class BlassBisHover(QObject):
    """Erledigte Bauplan-Karte blass (emm337, Nutzer: "die erledigten
    ausgrauen"); faehrt die Maus darueber, wird sie wieder voll sichtbar -
    sonst liessen sich Zahlen und Knoepfe schlecht lesen. Haengt als
    Kind am Widget und stirbt mit ihm."""
    BLASS = 0.5

    def __init__(self, widget):
        super().__init__(widget)
        from PySide6.QtWidgets import QGraphicsOpacityEffect
        self.effekt = QGraphicsOpacityEffect(widget)
        self.effekt.setOpacity(self.BLASS)
        widget.setGraphicsEffect(self.effekt)
        widget.setAttribute(Qt.WA_Hover, True)
        widget.installEventFilter(self)

    def eventFilter(self, obj, ev):
        try:
            if ev.type() in (QEvent.Enter, QEvent.HoverEnter):
                self.effekt.setOpacity(1.0)
            elif ev.type() in (QEvent.Leave, QEvent.HoverLeave):
                self.effekt.setOpacity(self.BLASS)
        except RuntimeError:
            pass
        return False


class FlashHinweis(QFrame):
    """Kurzer Hinweis an der Maus als EIGENES kleines Fenster (03.10.2026,
    Nutzer: "das Tooltip nach Klick auf Market scan haelt gerade mal eine
    Sekunde, keine Zeit zum Lesen"). Vorher QToolTip: Qt hat nur EINEN
    Tooltip - der eigene Tooltip des Knopfs unter der Maus ersetzte den
    Hinweis nach ~0,7 s. Dieses Fenster gehoert niemandem sonst und bleibt
    genau so lange, wie verlangt (mindestens FLASH_MIN_MS)."""

    def __init__(self, parent):
        super().__init__(parent, Qt.ToolTip | Qt.FramelessWindowHint)
        self.setAttribute(Qt.WA_ShowWithoutActivating)
        self.setAttribute(Qt.WA_TransparentForMouseEvents)
        self.setObjectName("FlashHinweis")
        lay = QVBoxLayout(self)
        lay.setContentsMargins(10, 7, 10, 7)
        self.lbl = QLabel("")
        self.lbl.setWordWrap(True)
        self.lbl.setMaximumWidth(460)
        lay.addWidget(self.lbl)
        self.setStyleSheet(
            f"QFrame#FlashHinweis{{background:{theme.PANEL2}; border:1px solid {theme.CYAN}; "
            f"border-radius:6px;}} QLabel{{color:{theme.TEXT}; font-size:{theme.FS_BASE}; "
            f"background:transparent;}}")
        self.uhr = QTimer(self)
        self.uhr.setSingleShot(True)
        self.uhr.timeout.connect(self.hide)

    def zeige(self, pos, text, ms):
        self.lbl.setText(str(text))
        self.adjustSize()
        self.move(pos.x() - 24, pos.y() - self.height() - 14)
        self.show()
        self.raise_()
        self.uhr.start(int(ms))


class ElideLabel(QLabel):
    """Ein Label, das zu langen Text mit "\u2026" kuerzt statt ihn hart
    abzuschneiden (Gewinn-Uebersicht, Nutzer 18.09.2026: "die Auflistung
    darf ersichtlicher sein" - "Medium Capacitor Control Circuit II \u00d7"
    stand halb da). Der volle Text bleibt in text() und im Tooltip."""

    def paintEvent(self, ev):
        from PySide6.QtGui import QPainter as _QP
        p = _QP(self)
        r = self.contentsRect()
        txt = self.fontMetrics().elidedText(self.text(), Qt.ElideRight, r.width())
        p.drawText(r, int(self.alignment()) | Qt.TextSingleLine, txt)
        p.end()

    def minimumSizeHint(self):
        from PySide6.QtCore import QSize as _QS
        return _QS(0, super().minimumSizeHint().height())


class KpiLabel(QLabel):
    """Kennzahl, die sich auf Knopfdruck verdecken laesst.

    NUTZER-WUNSCH (Sitzung 20): "wenn man jemandem etwas an dem Tool zeigen
    will, online oder on Stream, dann kann man diese heiklen Daten einfach
    zensieren."

    WARUM ALS EIGENE KLASSE und nicht als Umweg ueber die Aufrufer: die
    Kennzahlen werden an vielen Stellen mit `setText()` gefuellt (Render-
    Laeufe, ESI-Rueckmeldungen, Filterwechsel). Jede dieser Stellen anzufassen
    hiesse, dass eine vergessene die Zahl wieder preisgibt - genau dann, wenn
    der Stream laeuft. So bleibt `setText()` ueberall unveraendert; die Klasse
    merkt sich den ECHTEN Wert und zeigt ihn nur, wenn nicht verdeckt ist.
    """

    _MASKE = "\u2022\u2022\u2022\u2022\u2022\u2022"

    def __init__(self, text=""):
        super().__init__(text)
        self._echt = text
        self._zensiert = False

    def setText(self, text):
        self._echt = text
        super().setText(self._MASKE if self._zensiert else text)

    def zensur_setzen(self, an):
        self._zensiert = bool(an)
        super().setText(self._MASKE if self._zensiert else self._echt)

    def ist_zensiert(self):
        return self._zensiert


def kpi_card(title, schluessel=None, fenster=None, amber=False):
    """Kennzahl-Karte. Mit `schluessel` bekommt sie ein Auge zum Verdecken.

    `fenster` ist das Hauptfenster - es haelt die Zuordnung Schluessel ->
    Label und merkt sich, was verdeckt ist. Ohne beides verhaelt sich die
    Karte wie frueher.
    """
    card = QFrame()
    card.setObjectName("Card")
    lay = QVBoxLayout(card)
    lay.setContentsMargins(14, 12, 14, 12)
    lay.setSpacing(4)
    kopf = QHBoxLayout()
    kopf.setContentsMargins(0, 0, 0, 0)
    titel_lbl = QLabel(title)
    titel_lbl.setObjectName("Muted")
    kopf.addWidget(titel_lbl)
    kopf.addStretch()
    v = KpiLabel("\u2014")
    v.setObjectName("KpiValue")
    if amber:
        # LEITZAHL HERVORHEBEN (Nutzer, Sitzung 20: "die Zahl in fettem Amber").
        # UEBER DIE SCHRIFT, nicht ueber das Stylesheet: die Render-Laeufe
        # setzen spaeter ihr eigenes setStyleSheet und wuerfen alles weg, was
        # hier stuende (genau das ist passiert). Eine gesetzte Schrift
        # ueberlebt das.
        _f = v.font()
        _f.setPointSize(max(_f.pointSize() + 4, 14))
        _f.setBold(True)
        v.setFont(_f)
    if schluessel and fenster is not None:
        from PySide6.QtWidgets import QToolButton as _QTB
        aug = _QTB()
        aug.setIcon(icons.icon("eye", theme.MUTED))
        aug.setAutoRaise(True)
        aug.setCursor(Qt.PointingHandCursor)
        aug.setToolTip(t("Hide this number \u2013 for screenshots and streams. "
                         "Only the display changes, nothing is calculated "
                         "differently."))
        aug.clicked.connect(
            lambda *_a, k=schluessel: fenster._kpi_zensur_umschalten(k))
        kopf.addWidget(aug)
        fenster._kpi_labels[schluessel] = (v, aug)
    lay.addLayout(kopf)
    lay.addWidget(v)
    return card, v



# EMOJI-PRAEFIX -> GEZEICHNETES SYMBOL (Auftrag B, Sitzung 9). Die
# Auswahllisten (Modus/Preset in Daytrade und Swing Trade) trugen ihre
# Emoji IM TEXT - Qt kann dort aber ein echtes Icon setzen. Diese Karte
# uebersetzt einmal zentral; _combo_item zieht das Zeichen aus dem Text
# und haengt stattdessen das Symbol an den Eintrag.
_EMOJI_ZU_SYMBOL = {
    "\u26a1": "play",          # Aktiv am PC - schnelle Flips
    "\U0001F319": "clock",     # Wenig Zeit
    "\U0001F50D": "search",    # Geheimtipps / Suchen
    "\U0001F48E": "coins",     # Viel Kapital / teure Brocken
    "\U0001F6E1": "check",     # Kleine sichere Dips
    "\u23f3": "clock",         # Tiefe Dips - Geduld
    "\U0001F4E6": "package",   # Massenware
    "\U0001F512": "lock",      # Sicherer Exit
    "\u2696": "chart",         # Ausgewogen
}


# SCHLUESSEL DES NEUTRALEN PRESET-EINTRAGS. Er steht in mehreren
# KLASSEN-KONSTANTEN (_DEAL_PRESETS usw.), und dort darf KEIN t() stehen:
# Klassenrumpf laeuft beim IMPORT, also bevor die Sprache gesetzt ist -
# der Eintrag blieb dadurch englisch (Nutzer-Fund: "— Custom —" mitten in
# der deutschen Oberflaeche). Uebersetzt wird beim EINFUEGEN.
_CUSTOM_KEY = "\u2014 Custom \u2014"


def _combo_item(combo, text, data=None, symbol=None):
    """Eintrag mit gezeichnetem Symbol statt Emoji-Praefix.

    Der Text bleibt sauber lesbar (wichtig fuer Suche und Prueftexte),
    das Symbol kommt aus dem eigenen Set. Steht kein bekanntes Emoji
    vorn, wandert der Text unveraendert und ohne Symbol hinein - die
    Liste bleibt also in jedem Fall vollstaendig.

    `symbol` benennt das Symbol AUSDRUECKLICH und geht dem Emoji-Marker
    vor (Nutzer-Befund Sitzung 11: "da fehlen teilweise einfach noch
    Icons - auf keinen Fall Emojis einfuegen"). Eintraege ohne Marker
    blieben vorher symbollos; einen Marker nachzutragen hiesse, ein Emoji
    in den Quelltext zu schreiben, das bei fehlender Zuordnung auch
    ANGEZEIGT wuerde. Mit dem ausdruecklichen Namen kann das nicht
    passieren.
    """
    # UEBERSETZEN BEIM EINFUEGEN, nicht in der Klassen-Konstante: die
    # Preset-Listen werden beim IMPORT ausgewertet, dort waere jedes t()
    # wirkungslos (aa236). Ein Emoji-Marker vorn gehoert NICHT zum
    # Schluessel - er wird abgetrennt, der Rest uebersetzt, dann wieder
    # vorangestellt.
    _marker = ""
    if text and text[0] in _EMOJI_ZU_SYMBOL:
        _marker, text = text[0] + " ", text[1:].lstrip()
    text = _marker + t(text)
    if symbol:
        try:
            combo.addItem(icons.icon(symbol), text, data)
            return
        except Exception:
            pass
    _sym = _EMOJI_ZU_SYMBOL.get(text[:1])
    if _sym:
        text = text[1:].lstrip()
        try:
            combo.addItem(icons.icon(_sym), text, data)
            return
        except Exception:
            pass
    combo.addItem(text, data)


def _such_feld(le):
    """Suchfeld mit GEZEICHNETEM Lupensymbol statt Emoji im Platzhalter.

    Gleiche Bauweise wie `_btn_icon` und `_combo_item`: der Platzhaltertext
    bleibt sauber lesbar ("Suchen ..."), das Symbol sitzt als echtes Bild
    links im Feld. Faellt es aus, bleibt das Feld voll benutzbar - es hat
    dann eben keins.
    """
    le.setPlaceholderText(t("Search \u2026"))
    try:
        le.addAction(icons.icon("search"), QLineEdit.LeadingPosition)
    except Exception:
        pass
    return le


def _btn_icon(btn, name):
    """Knopf mit GEZEICHNETEM Symbol statt Emoji (Auftrag B, Sitzung 9).

    Der Text bleibt sauber lesbar (wichtig fuer Suche, Screenreader und
    die Prueftexte), das Symbol kommt aus dem eigenen 24x24-Set - damit
    sehen alle Knoepfe gleich aus, statt je nach Betriebssystem-Emojifont
    zu variieren. Faellt das Symbol aus, bleibt der Knopf voll bedienbar.
    """
    try:
        btn.setIcon(icons.icon(name))
    except Exception:
        pass
    return btn


class _NoEscDialog(MinimizableDialog):
    """A QDialog that does NOT close on Escape. Used for the Gold-Suche window,
    where Escape should do nothing (Escape is reserved for returning from the
    chart view to the previous tab)."""
    def keyPressEvent(self, e):
        if e.key() == Qt.Key_Escape:
            e.ignore()
            return
        super().keyPressEvent(e)


class TabNav(QWidget):
    """A thin QStackedWidget wrapper exposing the slice of the QTabWidget API the
    app uses, so the existing self.tabs.* calls keep working while navigation is
    driven by an external sidebar (common tabs) and top bar (paid tabs)."""
    currentChanged = Signal(int)

    class _TabBarStub:
        def setMovable(self, _b):
            pass

    def __init__(self):
        super().__init__()
        self._stack = QStackedWidget()
        self._titles = []
        lay = QVBoxLayout(self)
        lay.setContentsMargins(0, 0, 0, 0)
        lay.addWidget(self._stack)
        self._stack.currentChanged.connect(self.currentChanged.emit)
        # RUECKFRAGE VOR DEM VERLASSEN (Nutzer, 15.09.2026): "wenn man in
        # Einstellungen etwas einstellt und nicht speichert, bekommt man
        # keine Meldung, wenn man irgendwo anders im Tool klickt ... diese
        # Warnung muss kommen, sobald wir versuchen ungespeichert den
        # Einstellungs-Tab zu verlassen, EGAL WOHIN."
        #
        # WARUM HIER UND NICHT IN `_on_tab_changed`: das Signal kommt erst,
        # wenn der Wechsel schon passiert ist - dort liesse sich nur noch
        # zurueckspringen, was flackert. Jeder Weg durchs Programm
        # (Seitenleiste, obere Leiste, Sprung aus dem Code) laeuft durch
        # setCurrentIndex/setCurrentWidget, also greift ein Riegel hier
        # ausnahmslos - genau sein "egal wohin".
        self.vor_wechsel = None      # optional: callable(alt, neu) -> bool

    def _darf_wechseln(self, i):
        """Darf von der aktuellen Seite auf Seite `i` gewechselt werden?"""
        f = self.vor_wechsel
        alt = self._stack.currentIndex()
        if f is None or i == alt or i < 0:
            return True
        try:
            return bool(f(alt, i))
        except Exception:
            # EINE RUECKFRAGE DARF DIE NAVIGATION NIE SPERREN. Faellt sie
            # aus, ist der Wechsel erlaubt - ein Programm, in dem man
            # wegen eines Anzeigefehlers festsitzt, waere schlimmer als
            # eine verlorene Einstellung.
            return True

    def addTab(self, widget, title):
        self._titles.append(title)
        return self._stack.addWidget(widget)

    def setCurrentWidget(self, w):
        if not self._darf_wechseln(self._stack.indexOf(w)):
            return
        self._stack.setCurrentWidget(w)

    def setCurrentIndex(self, i):
        if not self._darf_wechseln(i):
            return
        self._stack.setCurrentIndex(i)

    def currentWidget(self):
        return self._stack.currentWidget()

    def currentIndex(self):
        return self._stack.currentIndex()

    def widget(self, i):
        return self._stack.widget(i)

    def indexOf(self, w):
        return self._stack.indexOf(w)

    def count(self):
        return self._stack.count()

    def title(self, i):
        return self._titles[i] if 0 <= i < len(self._titles) else ""

    def setMovable(self, _b):
        pass

    def tabBar(self):
        return TabNav._TabBarStub()


class MainWindow(BauplanFenster, BauplanTabs, Optimizer, MultiBauplan,
                 MainWindowHelpers, QMainWindow):
    # Beschriftung des EVE-Daten-Knopfes oben rechts - AN EINER STELLE.
    # Er steht direkt neben dem Programm-Version-Knopf; hiesse er weiter
    # bloss "Updates", waere das nebeneinander eine Etikettenluege.
    # KEIN t() HIER: eine Klassen-Konstante wird beim IMPORT ausgewertet,
    # also bevor die Sprache aus den Einstellungen gesetzt ist. Der Text
    # entsteht deshalb erst beim Bauen des Fensters (s. _eve_update_text).
    # Kein Emoji mehr (Sitzung 16) - der Knopf traegt sein Symbol ueber
    # `_btn_icon(..., "refresh")`, der Text bleibt sauber.
    EVE_UPDATE_ICON = ""

    # Alle Plan-Schluessel, die MENGEN je type_id enthalten. Wer Namen oder
    # Icons fuer die Items eines Plans braucht, muss ALLE davon abgrasen.
    # Es gab diese Liste zweimal an verschiedenen Stellen - beim Nachtragen
    # der Invention-Schluessel wurde nur eine erwischt, und die Datacores
    # standen wieder als "#16648" da (Nutzer-Fund). Jetzt eine Quelle.
    PLAN_QTY_KEYS = ("buy", "build_runs", "stock_used", "surplus",
                     "inv_buy", "inv_stock_used")

    # Ab diesem Anteil (%) der Baukosten aus dem Adjusted-Price-Rückfall wird
    # eine Bau-Trefferzeile markiert. Bewusst eine sichtbare Konstante und kein
    # im Code verstreuter Zahlenwert: das ist eine Ermessensschwelle, die der
    # Nutzer beim Nachjustieren finden können muss. NICHT ausblenden - markieren.
    BAU_FALLBACK_WARN_PCT = 20.0

    # BEWERTUNG STATT ZAHLENWAND (Nutzer: "keine unnoetigen Zahlen mehr,
    # Uebersichtlichkeit hat hoechste Prioritaet"). Die Trefferliste zeigt
    # nur noch Item, Marge, Gewinn/Stk und einen Balken mit einer AUSSAGE.
    # Die Schwellen stehen hier sichtbar beieinander - es sind Ermessens-
    # werte, die der Nutzer finden koennen muss, keine im Code verstreuten
    # Zahlen. Alle uebrigen Kennzahlen sind nicht weg, sie stehen im
    # Zeilen-Tooltip: minimalistisch, ohne fachliche Tiefe zu verlieren.
    BAU_MARGE_GUT = 30.0      # ab hier "lohnt sich klar"
    BAU_MARGE_OK = 15.0       # ab hier "solide"
    BAU_VOL_DUENN = 5.0       # Ø Tagesvolumen darunter: Markt zu duenn

    @classmethod
    def _bau_bewertung(cls, d, fallback_pct=None):
        """(Balken-%, Text, Farbe) fuer eine Bau-Trefferzeile.

        EINE Stelle fuer die Aussage - Liste und Capital-Liste lesen
        dieselbe Regel (Arbeitsregel 9). Reihenfolge ist Absicht: ein
        Vorbehalt schlaegt eine gute Marge. Wer eine unsichere Kostenbasis
        oder einen toten Markt hat, soll NICHT "lohnt sich klar" lesen.
        """
        _m = float(d.get("under_pct", 0) or 0)
        _vol = float(d.get("daily_vol", 0) or 0)
        if d.get("no_price"):
            # Capital-Zeile ohne Contract-Referenz: es gibt schlicht keinen
            # Marktpreis zum Vergleichen - ehrlich sagen statt eine Marge
            # aus nichts zu behaupten (Nutzer-Liste Punkt 3, Regel 6).
            return 0, t("no contract price"), theme.MUTED
        # Balkenlaenge = Marge im Verhaeltnis zur "gut"-Schwelle, gedeckelt.
        _pct = int(max(0, min(100, round(_m / max(1.0, cls.BAU_MARGE_GUT) * 100))))
        if fallback_pct is not None and fallback_pct >= cls.BAU_FALLBACK_WARN_PCT:
            return _pct, t("cost uncertain"), theme.VIOLET
        if d.get("vol_unknown"):
            # Historie (noch) nicht geladen - der Absatz ist UNBEKANNT, nicht
            # null. Ersetzt das "Erstlauf"-Preset: Treffer erscheinen sofort,
            # der Vorbehalt steht ehrlich am Balken, und sobald die Historie
            # im Hintergrund da ist, bewertet der naechste Scan normal.
            return _pct, t("demand unknown"), theme.AMBER
        if _vol and _vol < cls.BAU_VOL_DUENN:
            return _pct, t("thin market"), theme.AMBER
        if _m >= cls.BAU_MARGE_GUT:
            return _pct, t("clearly worth it"), theme.GREEN
        if _m >= cls.BAU_MARGE_OK:
            return _pct, t("solid"), theme.CYAN
        return _pct, t("tight"), theme.MUTED

    def __init__(self):
        super().__init__()
        # Kennzahl -> (Label, Auge). MUSS vor dem ersten `kpi_card` stehen:
        # die Reiter werden nicht in der Reihenfolge gebaut, in der sie
        # spaeter erscheinen (Sitzung 20 - erst am leeren Fenster gemerkt).
