        chead.addStretch()
        from PySide6.QtWidgets import QCheckBox
        self.cont_hide_all = QCheckBox(t("Hide all containers"))
        self.cont_hide_all.setToolTip(t("Excludes all containers from trading \u2013 their contents do not count "
                                        "towards stock, signals or profit."))
        self.cont_hide_all.stateChanged.connect(self._toggle_all_containers)
        chead.addWidget(self.cont_hide_all)
        # DAUERHINWEIS ENTFERNT (Nutzer-Wunsch Sitzung 12: "ich hasse
