    def _apply_deal_filters(self):
        mode = "flip"                       # Daytrade filters are the flip set
        vis = self._DEAL_FILTERS[mode]
        if "margin" in vis:
            self._deal_row_w["margin"][0].setText(t(self._DEAL_MARGIN_LABEL[mode]))
        g = self._deal_grid
        # detach all, then re-add only the visible ones, packed 4 per row
        for lab, wdg in self._deal_row_w.values():
            g.removeWidget(lab); g.removeWidget(wdg)
            lab.setVisible(False); wdg.setVisible(False)
        order = [k for (k, _l, _w) in self._deal_rows if k in vis]
        # always lay the visible filters out in exactly two rows
        cols = max(1, (len(order) + 1) // 2)
        for i, key in enumerate(order):
            lab, wdg = self._deal_row_w[key]
            wdg.setMaximumWidth(180); wdg.setMinimumWidth(90)
            r, c = i // cols * 2, i % cols
            g.addWidget(lab, r, c)
            g.addWidget(wdg, r + 1, c)
            lab.setVisible(True); wdg.setVisible(True)
            self._install_tip(wdg, lab)  # re-anchor tooltip to current label
        g.setColumnStretch(cols, 1)

    def _preset_to_custom(self, *args):
        """User changed mode/a filter by hand → the active preset no longer
        describes the settings, so show „Eigene Einstellung“."""
        if getattr(self, "_applying_preset", False):
            return
        if self.d_preset.currentIndex() != 0:
            self.d_preset.blockSignals(True)
            self.d_preset.setCurrentIndex(0)
            self.d_preset.blockSignals(False)

