    def _decryptor_list(self):
        """[(name, (prob, runs, me, te, type_id))] – primär aus der SDE, sonst Fallback."""
        try:
            sde = industry.load_decryptors()
        except Exception:
            sde = []
        if sde:
            out = [(KEIN_DECRYPTOR, (1.0, 0, 0, 0, None))]
            for d in sde:
                out.append((d["name"], (d["prob_mult"], int(d["run_mod"]),
                                        int(d["me_mod"]), int(d["te_mod"]), d["type_id"])))
            return out
        return list(self._DECRYPTORS)

    def _bau_decryptor_opts(self):
        """{inv_prob_mult, inv_run_mod, inv_me_mod, inv_te_mod, inv_decryptor_id}
        für den global gewählten Decryptor (Bau-Setup) - Fallback für Items ohne
        eigenen Decryptor im Invention-Tab (s. _resolve_inv_decryptor_map)."""
        key = self.settings.get("bau_decryptor", KEIN_DECRYPTOR)
        for nm, (pm, rm, me_mod, te_mod, tid) in self._decryptor_list():
            if nm == key:
                return {"inv_prob_mult": pm, "inv_run_mod": rm, "inv_me_mod": me_mod,
                       "inv_te_mod": te_mod, "inv_decryptor_id": tid}
        return {"inv_prob_mult": 1.0, "inv_run_mod": 0, "inv_me_mod": 0,
               "inv_te_mod": 0, "inv_decryptor_id": None}

    def _resolve_inv_decryptor_map(self):
        """bp_id -> Decryptor-Tupel, abgeleitet aus self._bd_decryptor_map
        (bp_id -> Decryptor-Name, wird beim Öffnen/Speichern eines Bauplans
        gesetzt/geladen). Einzige Quelle der Wahrheit für die per-Item-
        Decryptor-Wahl im Invention-Tab, damit Header-Kosten und Invention-Tab
        nie auseinanderlaufen und es kein Warten auf Combo-Change-Signale
        braucht (wichtig direkt nach dem Laden eines gespeicherten Plans)."""
        dm = getattr(self, "_bd_decryptor_map", None) or {}
        if not dm:
            return {}
        dlist = dict(self._decryptor_list())
        out = {}
        for bp_id, name in dm.items():
            v = dlist.get(name)
            if v is not None:
                out[bp_id] = v
        return out

    def _bd_inv_confidence(self):
        """Geplante Invention-Sicherheit als 0..1. EINE Quelle fuer die
        Kostenrechnung UND fuer die Decryptor-Wahl - sonst wuerde der
        Optimierer mit 75 % rechnen, waehrend der Plan 90 % einkauft, und
        empfiehlt den falschen Decryptor (Arbeitsregel 9)."""
        _v = getattr(self, "_bd_inv_conf", None)
        if _v is None:
            _v = industry.DEFAULT_INVENTION_CONFIDENCE
        return max(0.5, min(0.99, float(_v)))

    def _resolve_inv_manual_attempts(self):
        """bp_id -> manuell vorgegebene Versuchszahl (nur Items, wo „Versuche
        manuell“ im Invention-Tab angehakt ist). self._bd_manual_attempts wird
        vom Invention-Tab live gepflegt und persistiert (Bauplan speichern/
        laden), damit Kopfzeile und Invention-Tab dieselbe Zahl nutzen.

        SEIT 26.09.2026 AUSGEBAUT (Nutzer: "Attempts manually nehmen wir raus,
        ist nur verwirrend"): der Haken ist weg, und ein in einem ALTEN Plan
        gespeicherter Handwert darf nicht unsichtbar weiterrechnen - sonst
        stuenden Kopfzeile und Invention-Karte auf verschiedenen Zahlen."""
        return {}

    def _resolve_inv_owned_runs(self):
        """bp_id (T2-Blueprint) -> bereits per ESI geladene, eigene BPC-Runs
        (aus "Blaupausen laden" im Endprodukt-Block) - reduziert, wie viele
        NEUE Invention-Erfolge im Invention-Tab noch nötig sind. Besitzt du
        eine BPO (unbegrenzt), taucht der Eintrag hier NICHT auf, sondern das
        Item wird direkt wie "Eigene BPC" behandelt (kein Invention-Posten)."""
        out = {}
        owned = getattr(self, "_bd_end_bpc_esi", None)
        recipes = getattr(self, "_bd_recipes", None)
        type_id = getattr(self, "_bd_bp_type", None)
        if owned and recipes and type_id:
            bp = recipes.product_to_bp.get(type_id)
            if bp and not owned.get("bpo") and owned.get("total_runs_owned"):
                out[bp[0]] = int(owned["total_runs_owned"])
        # "Eigene BPCs für alle Items laden" (Invention-Tab) - deckt auch
        # Komponenten ab, die selbst Invention brauchen, nicht nur das
        # Endprodukt. Überschreibt/ergänzt den obigen Wert, falls beide
        # dasselbe Item treffen (sollte eigentlich gleich sein).
        out.update(getattr(self, "_bd_owned_bpc_by_id", None) or {})
        return out

    def _resolve_inv_skill_modifiers(self):
        """bp_id (T2-Blueprint) -> SkillModifier für dessen Invention-
        Erfolgschance, für ALLE Items, die im aktuellen Bauplan über Invention
        entstehen könnten - damit die Kopfzeile (_inv_cost) denselben Bonus
        nutzt wie der Invention-Tab, unabhängig davon, ob die Karte gerade
        sichtbar/aufgebaut wurde."""
        recipes = getattr(self, "_bd_recipes", None)
        if not recipes:
            return {}
        out = {}
        for bp_id, inv in (getattr(recipes, "invention_for_bpc", None) or {}).items():
            t1_bp = inv[0]
            mod = self._bau_invention_skill_modifier(t1_bp)
            if mod != 1.0:
                out[bp_id] = mod
        return out

    def _reload_bau_char(self):
        if not hasattr(self, "bs_char"):
            return
        chars = store.list_characters()
        for combo, key in ((self.bs_char, "bau_character"),
                           (getattr(self, "bs_react_char", None), "bau_react_character")):
            if combo is None:
                continue
            cur = self.settings.get(key, 0)
            combo.blockSignals(True)
            combo.clear()
            combo.addItem(t("\u2014 none (ignore skills) \u2014"), 0)
            for c in chars:
                nm = c.get("character_name") or c.get("name") or str(c["character_id"])
                combo.addItem(nm, c["character_id"])
            combo.blockSignals(False)
            self._combo_select(combo, cur)




    def _bau_skill_time_factor(self):
        """Zeit-Faktor (<1) aus Fertigungs-Skills des Bau-Charakters. %/Level aus
        der SDE (industry.skill_time_bonus_pct), verifizierter Fallback -4/-3."""
        sk = self.settings.get("bau_skills", {}) or {}
        ind = int(sk.get("3380", 0))   # Industry (Fertigungszeit)
        adv = int(sk.get("3388", 0))   # Advanced Industry
        pct_ind = industry.skill_time_bonus_pct(3380, 4.0) / 100.0
        pct_adv = industry.skill_time_bonus_pct(3388, 3.0) / 100.0
        return (1 - pct_ind * ind) * (1 - pct_adv * adv)

    def _bau_react_skill_time_factor(self):
        """Zeit-Faktor (<1) aus Reaktions-Skills. NUR der Reactions-Skill wirkt auf
        Reaktionen; Advanced Industry und andere Industry-Skills wirken laut CCP
        NICHT auf Reaktionen. %/Level aus der SDE, verifizierter Fallback -4."""
        sk = self.settings.get("bau_react_skills", {}) or {}
        rea = int(sk.get("45746", 0))  # Reactions (Reaktionszeit)
        pct_rea = industry.skill_time_bonus_pct(45746, 4.0) / 100.0
        return (1 - pct_rea * rea)

    def _bau_invention_skill_modifier(self, t1_bp_id):
        """Offizielle Invention-SkillModifier-Formel (1 + Encryption/40 +
        (Datacore1+Datacore2)/30), mit dem BESTEN unter allen im
        Baucharaktere-Tab als "Für Invention" markierten Charakteren
        (self.settings['bau_invention_chars']) - deren Skills kommen aus
        self.settings['bau_char_skills'] (per "Job-Slots laden" geholt).
        1.0 (kein Bonus), wenn keine passenden Skill-Daten vorhanden sind -
        dann rechnet das Tool konservativ ohne zu raten, wer die Invention
        wirklich macht (echte Charakter-Zuteilung kommt erst mit dem
        Runplaner-Ausbau, Punkt 8/9)."""
        return self._bau_invention_skill_modifier_with_char(t1_bp_id)[0]

    def _char_namen_kurz(self):
        """{character_id: Name} fuer Anzeigen, 30 s gemerkt (Ladezeit-Messung
        des Nutzers 27.09.2026: die Invention-Skill-Rechnung fragte die
        Datenbank bei JEDEM Aufruf - 23'000 Mal beim Laden der Plan-Karten,
        80 s). Nur der NAME kommt daher, gerechnet wird mit den Skills aus
        den Einstellungen; ein neu verknuepfter Charakter erscheint nach
        spaetestens 30 s mit Namen statt Nummer."""
        import time as _t
        _c = getattr(self, "_char_namen_cache", None)
        if _c is not None and _t.monotonic() - _c[0] < 30:
            return _c[1]
        namen = {c["character_id"]: (c.get("character_name") or c.get("name")
                                     or str(c["character_id"]))
                 for c in store.list_characters()}
        self._char_namen_cache = (_t.monotonic(), namen)
        return namen

    def _bau_invention_skill_modifier_with_char(self, t1_bp_id, fixed_cid=None,
                                                inv_skills_map=None):
        """Wie _bau_invention_skill_modifier, gibt aber zusätzlich zurück,
        WESSEN Skills den Wert geliefert haben (Name, oder None wenn
        1.0/kein Bonus) - rein zur Anzeige, keine Job-Zuteilung. Ist im
        Invention-Tab ein bestimmter Charakter fixiert (self._bd_invention_char
        != 0), zählen NUR dessen Skills, statt automatisch den besten unter
        allen "Für Invention"-markierten Charakteren zu suchen.
        fixed_cid/inv_skills_map: optionale Overrides (z.B. von der "Meine
        Baupläne"-Liste, die PRO gespeichertem Plan einen eigenen fixierten
        Charakter nutzen kann, unabhängig vom gerade offenen Bauplan-Dialog)."""
        inv_map = inv_skills_map if inv_skills_map is not None else \
            getattr(self, "_bd_invention_skills_map", None)
        if not inv_map:
            return 1.0, None
        all_skills = self.settings.get("bau_char_skills", {}) or {}
        char_names = self._char_namen_kurz()
        # NUR DIE SKILLS, DIE DIE FORMEL BRAUCHT (zweite Ladezeit-Messung des
        # Nutzers 27.09.2026: 18'000 Aufrufe, 4,7 s reine Rechenzeit - jeder
        # Aufruf wandelte die GANZE Skill-Liste jedes Charakters, einige
        # hundert Eintraege, in Zahlen-Schluessel um, gebraucht werden hoechstens
        # drei: Encryption + zwei Science-Skills dieses Blueprints).
        # Gleiches Ergebnis wie vorher: Schluessel als Text ODER Zahl,
        # unbrauchbare Skill-Daten -> None (vorher der TypeError/ValueError-Weg).
        _info = inv_map.get(t1_bp_id) if hasattr(inv_map, "get") else None
        if not isinstance(_info, dict):
            _info = {}
        _ids = [_x for _x in ([_info.get("encryption")]
                              + list(_info.get("science") or []))
                if isinstance(_x, int)]

        def _nur_invention_skills(sk):
            if not isinstance(sk, dict):
                return None
            out = {}
            for _sid in _ids:
                if str(_sid) in sk:
                    out[_sid] = sk[str(_sid)]
                elif _sid in sk:
                    out[_sid] = sk[_sid]
            return out
        _fixed = fixed_cid if fixed_cid is not None else \
            (getattr(self, "_bd_invention_char", 0) or 0)
        if _fixed:
            sk = all_skills.get(str(_fixed))
            if not sk:
                return 1.0, char_names.get(_fixed, str(_fixed))
            sk_int = _nur_invention_skills(sk)
            if sk_int is None:
                return 1.0, char_names.get(_fixed, str(_fixed))
            mod = industry.invention_skill_modifier(t1_bp_id, sk_int, inv_map)
            return mod, char_names.get(_fixed, str(_fixed))
        chars = self.settings.get("bau_invention_chars", []) or []
        best, best_name = 1.0, None
        for cid in chars:
            sk = all_skills.get(str(cid))
            if not sk:
                continue
            sk_int = _nur_invention_skills(sk)
            if sk_int is None:
                continue
            mod = industry.invention_skill_modifier(t1_bp_id, sk_int, inv_map)
            if mod > best:
                best, best_name = mod, char_names.get(cid, str(cid))
        return best, best_name

    def _inv_zeit_skills(self, char_name=None):
        """(Advanced Industry, Science) des Invention-Charakters (emm325):
        gepinnt (`_bd_invention_char`), sonst der Charakter, den die Karte als
        besten nennt (`char_name`), sonst der beste unter "For invention".
        Fehlen Skills: (0, 0) - lieber zu lang als zu kurz."""
        _alle = self.settings.get("bau_char_skills", {}) or {}
        _cid = getattr(self, "_bd_invention_char", 0) or 0
        if not _cid and char_name:
            for _c in (store.list_characters() or []):
                if _c.get("character_name") == char_name:
                    _cid = _c.get("character_id")
                    break
        _kand = ([_cid] if _cid else
                 list(self.settings.get("bau_invention_chars", []) or []))
        _best = (0, 0)
        for _k in _kand:
            _sk = _alle.get(str(_k)) or {}
            try:
                _w = (int(_sk.get("3388") or 0), int(_sk.get("3402") or 0))
            except (TypeError, ValueError):
                continue
            _best = max(_best, _w)
        return _best

    def _bau_te_factor(self):
        """Fertigungs-Zeitfaktor OHNE Skills: Endprodukt-TE aus dem offenen
        Bauplan-Dialog (_bd_te, sonst globale Vorgabe) MAL dem eingebauten
        Struktur-Rollen-Zeitbonus (Raitaru −15 %, Azbel −20 %, Sotiyo −30 %). Die
        Skill-Zeit kommt PRO CHARAKTER im Runplaner (schedule_build) – deshalb hier
        keine Skills, sonst würden sie doppelt zählen."""
        bp_te = getattr(self, "_bd_te", None)
        if bp_te is None:
            bp_te = self.settings.get("bau_te", 0)
        te_factor = max(0.02, (1 - float(bp_te or 0) / 100.0))
        return te_factor * self._bau_role_time_factor_mfg()

    def _bau_te_factor_reaction(self):
        """Reaktions-Zeitfaktor (0..1, kleiner = schneller) OHNE Skills (die kommen
        pro Char im Runplaner). Kombiniert den eingebauten Struktur-Rollen-Bonus
        (z.B. Tatara −25 % Reaktionszeit) mit dem Reactor-Rig-Zeitbonus – beides
        wurde vorher ignoriert (Faktor 1.0), weshalb Reaktionszeiten deutlich zu
        lang berechnet wurden. In EVE wirken die Boni multiplikativ."""
        react = self._struct_for_activity("reaction")
        if not react:
            return 1.0
        role_pct = self._STRUCT_ROLE_TIME.get(
            react.get("type", ""), {}).get("react", 0.0)
        rig_pct = self._struct_rig_pct(react, "rte")   # Reactor-Zeit-Rig (meist 0)
        factor = (1.0 - role_pct / 100.0) * (1.0 - float(rig_pct or 0.0) / 100.0)
        return max(0.05, factor)

    def _bau_role_time_factor_mfg(self):
        """Fertigungs-Zeitfaktor aus dem Struktur-Rollen-Bonus (Sotiyo −30 %,
        Azbel −20 %). Multiplikativ mit dem TE-Rig, das _bau_te_factor() liefert."""
        mfg = self._struct_for_activity("manufacturing")
        if not mfg:
            return 1.0
        role_pct = self._STRUCT_ROLE_TIME.get(
            mfg.get("type", ""), {}).get("mfg", 0.0)
        return max(0.05, 1.0 - role_pct / 100.0)

