    # de_scan2: an

    def _bd_material_gruppe(self, tid, recipes=None, groups=None,
                            stage_map=None, react_products=None,
                            catmap=None, inv_ids=None):
        """Anzeige-Gruppe EINES Items - dieselbe Einteilung wie der
        Materialien-Reiter.

        Herausgezogen in Sitzung 20: die Einteilung lag als geschachtelte
        Funktion `_category_for` im Materialien-Reiter. Die Gruppen-Blacklist
        braucht sie ebenfalls, und zwei Kopien derselben Einteilung waeren
        zwei Wahrheiten.

        "Datacores and decryptors" bleibt BEWUSST draussen, wenn `inv_ids`
        nicht uebergeben wird - fuer die Blacklist waere die Gruppe unsinnig
        (Invention-Material haengt an der Erfolgschance, nicht am Einkauf).
        """
        _react = react_products or set()
        if tid in _react:
            return ("Intermediate Reactions"
                    if (stage_map or {}).get(tid, 1) == 1
                    else "Composite Reactions")
        _cm = catmap if catmap is not None else (industry.item_category_map() or {})
        _inf = _cm.get(tid)
        try:
            _k = self._category_key(tid, (groups or {}).get(tid, ""), False,
                                    _inf[0] if _inf else None,
                                    _inf[2] if _inf else None)
        except Exception:
            _k = None
        if _k == "t1_hulls":
            # de_scan2: aus  (Kategorie-SCHLUESSEL, Anzeige via _kategorie_anzeige)
            return "H\u00fcllen"
            # de_scan2: an
        if _k == "fuel_blocks":
            return "Fuel"
        if _k == "tools":
            return "Tools"
        # Kategorie 41 = Planetary Resources, 43 = Planetary Commodities.
        if _inf and _inf[0] in (41, 43):
            return "PI"
        if inv_ids and tid in inv_ids:
            return t("Datacores and decryptors")
        # KOMPRIMIERTES ERZ (1.0.9, Weg B; Nutzer 19.09.2026: "Materials-Tab
        # hat keine Eintragsmoeglichkeit fuer Ore"): Kategorie 25 (Asteroid)
        # ist eine eigene Gruppe - vorher stand es unter "noch nicht
        # aufgeloest", weil die Erz-Gruppennamen erst spaet dazukommen.
        if _inf and _inf[0] == 25:
            # de_scan4: aus - interner SCHLUESSEL (Kategorie/Stufe/Dict), Anzeige uebersetzt woanders
            return "Erz"
            # de_scan4: an
        if recipes and tid in getattr(recipes, "product_to_bp", {}):
            # de_scan4: aus - interner SCHLUESSEL (Kategorie/Stufe/Dict), Anzeige uebersetzt woanders
            return "Komponenten"
            # de_scan4: an
        return self._bd_rohstoff_gruppe((groups or {}).get(tid, ""))

    @staticmethod
    def _bd_rohstoff_gruppe(group_name):
        """Gruppenname aus der SDE -> "Mineralien" | "Mond-Materialien" |
        "Rohstoffe". Mineralien (Tritanium ... Morphite) und rohe
        Mond-Materialien (Hafnium, Evaporite Deposits, Atmospheric Gases ...)
        lagen bisher in einem Topf und waren dadurch nicht auseinanderzuhalten
        (Nutzer: "die sind so vermischt").
        Entschieden wird am GRUPPENNAMEN, nicht an einer gepflegten Item-Liste:
        eine Liste veraltet mit jedem Patch, der Gruppenname kommt aus der SDE.
        Alles Uebrige (Eis, Gase, Salvage) bleibt "Rohstoffe" - bewusst als
        Sammelposten, statt Gruppen zu erfinden, die der Nutzer nicht kennt.
        FEHLT der Gruppenname (Item nicht in der Gruppen-Map), wird das
        MARKIERT statt behauptet (Arbeitsregel 6): "Rohstoffe" fuer ein Item,
        dessen Gruppe schlicht unbekannt ist, machte aus "weiss ich nicht"
        eine Aussage - so standen Vanadium/Caesium/Hafnium (Mond-Materialien)
        als "#16642" unter "Rohstoffe"."""
        _g = (group_name or "").strip().lower()
        if not _g:
            return MainWindow.GRUPPE_UNBEKANNT
        if _g == "mineral":
            # de_scan4: aus - interner SCHLUESSEL (Kategorie/Stufe/Dict), Anzeige uebersetzt woanders
            return "Mineralien"
            # de_scan4: an
        if "moon" in _g or "mond" in _g:
            # de_scan4: aus - interner SCHLUESSEL (Kategorie/Stufe/Dict), Anzeige uebersetzt woanders
            return "Mond-Materialien"
        return "Rohstoffe"
            # de_scan4: an

    def _category_key(self, tid, group, is_reaction, category_id=None, meta=None):
        g = group or ""
        if not g:
            # NUTZER-FALL (Stork-Plan): Ferrogel stand trotz "immer bauen"
            # auf "kaufen", die Geschwister-Composites bauten. Ursache: die
            # Gruppen-Karte der UI kannte Ferrogel nicht (nie im Markt-Scan
            # gewesen) -> leerer Gruppenname -> der Schluessel fiel auf das
            # generische "reactions", das in KEINEM Panel vorkommt -> nie
            # "besessen" -> stilles kaufen. Rueckfall: Gruppennamen aus der
            # SDE (group_name-Tabelle) nachschlagen - EINE Quelle, die jedes
            # Item kennt, unabhaengig vom Markt-Scan.
            _gn = getattr(self, "_sde_group_name_cache", None)
            if _gn is None:
                _gn = self._sde_group_name_cache = {}
            if tid not in _gn:
                _gn.update(industry.group_names([tid]) or {tid: ""})
            g = _gn.get(tid, "") or ""
        if is_reaction:
            # Match auf die ECHTEN SDE-Gruppennamen (aus der DB-Diagnose bestätigt),
            # nicht auf die Markt-Fenster-Namen (die abweichen). Reihenfolge:
            # spezifisch vor allgemein.
            if "Biochemical" in g:
                return "biochemical_reactions"
            if "Hybrid Polymer" in g:
                return "hybrid_reactions"
            if "Molecular-Forged" in g or "Molecular Forged" in g:
                return "molecular_reactions"
            if "Unrefined" in g:
                return "unrefined_reactions"
            if "Composite" in g:
                return "composite_reactions"
            if "Intermediate" in g:
                return "intermediate_reactions"
            return "reactions"
        # T1-BASIS: HUELLE, DROHNE ODER FIGHTER (Sitzung 17, Nutzer:
        # "Einherji I ist kein Component, das gehoert unter Hulls - auch bei
        # Drohnen und sonstigen T1-Versionen, wenn wir T2 daraus bauen").
        # WARUM ES ZAEHLT: wer den Haken abwaehlt, kauft die T1-Basis fertig
        # und muss keine voluminoesen Mineralien schleppen. Vorher galt nur
        # Kategorie 6 (Schiffe); Drohnen (18) und Fighter (87) fielen in den
        # Sammeltopf t1_components - und DER hat gar keinen Haken, wurde also
        # IMMER gebaut, egal was der Nutzer ankreuzte.
        if category_id in (6, 18, 87) and (meta in (0, 1, None)):
            return "t1_hulls"
        if "Fuel Block" in g:
            return "fuel_blocks"
        if "Tool" in g:
            return "tools"
        if "Advanced Capital" in g:
            return "advanced_capital_components"
        if "Capital Construction" in g or "Capital Component" in g:
            return "capital_components"
        if "Hybrid" in g:
            return "hybrid_components"
        if "Construction Component" in g:
            return "advanced_components"
        return "t1_components"

    def _bau_category_me_map(self, ids, groups, reaction_products, type_id,
                             use_dialog_me=True, recipes=None):
        """Basis-ME (%) je Item, NUR aus der Blaupausen-Kategorie (Komponenten/
        T1-H\u00fcllen/Fuel Blocks/Tools), noch OHNE Rig-Bonus \u2013 der kommt separat
        in _bau_me_maps dazu. Endprodukt (type_id) und Reaktionen sind absichtlich
        NICHT enthalten: Endprodukt nutzt die Blueprint-ME-Eingabe oben im Dialog,
        Reaktionen sind in EVE grunds\u00e4tzlich nicht erforschbar (immer 0 %)."""
        catmap = industry.item_category_map() or {}
        out = {}
        _enden = self._bd_enden(type_id, recipes)   # Buendel: jedes Ende ist "Endprodukt"
        for tid in ids:
            if tid in _enden or tid in (reaction_products or set()):
                continue
            info = catmap.get(tid)
            cat = info[0] if info else None
            meta = info[2] if info else None
            key = self._category_key(tid, groups.get(tid, ""), False, cat, meta)
            # use_dialog_me=False: NUR die gespeicherten Einstellungen, keine
            # `_bd_*`-Eingaben des zuletzt geoeffneten Bauplan-Dialogs. Der
            # Scanner muss das so aufrufen - sonst faerbt eine dort einmal
            # getippte ME still auf JEDEN gescannten Kandidaten ab, und der
            # Scan haette wieder eine andere Wahrheit als die Einstellungen.
            def _me_of(attr, skey):
                if use_dialog_me:
                    return getattr(self, attr, self.settings.get(skey, 10))
                return self.settings.get(skey, 10)
            # ECHTES ME DER EIGENEN BLAUPAUSE SCHLAEGT DIE KATEGORIE-ANNAHME
            # (Sitzung 16). Nur wenn die Kategorie auf ESI steht UND fuer
            # dieses Bauteil wirklich eine Blaupause im Cache liegt - sonst
            # faellt die Rechnung stillschweigend auf ME 0 und kauft absurd
            # viel Material ein.
            if self._bd_esi_me_aktiv(key):
                _esi = self._bd_esi_me_te_for_item(tid)
                if _esi is not None and _esi[0] is not None:
                    out[tid] = _esi[0]
                    continue
            if key == "t1_hulls":
                out[tid] = _me_of("_bd_me_t1hull", "bau_me_t1hull")
            elif key == "fuel_blocks":
                out[tid] = _me_of("_bd_me_fuel", "bau_me_fuel")
            elif key == "tools":
                out[tid] = _me_of("_bd_me_tools", "bau_me_tools")
            else:
                out[tid] = _me_of("_bd_me_component", "bau_me_component")
        return out

    def _bd_esi_me_te_for_item(self, type_id):
        """ME/TE aus den ECHTEN Blaupausen des Nutzers fuer EIN Bauteil -
        SCHLECHTESTE Kopie gewinnt. Gibt (me, te) zurueck oder None, wenn
        keine eigene Blaupause dafuer im Cache liegt.

        NUTZER (Sitzung 16): "Ich habe festgestellt, dass wir im Bauplan nicht
        alle meine Blueprints traecken. Da ist es teilweise so eingestellt,
        dass wir einfach von voll geforschten Blueprints ausgehen. Jetzt habe
        ich aber gemerkt, dass man nicht immer alle T1-Huellen voll
        ausgeforscht hat, deswegen hatte ich jetzt zu wenig Material
        eingekauft gehabt."

        BIS SITZUNG 16 kam das ME fuer Komponenten/Huellen/Fuel Blocks/Tools
        AUSSCHLIESSLICH aus den vier Drehfeldern der Karte "Other blueprints
        (ME/TE)" - Vorgabe 10 %/20 %, also voll ausgeforschtes BPO. Die
        eigenen Blaupausen wurden nie gefragt, obwohl ESI ihr
        `material_efficiency`/`time_efficiency` laengst mitliefert und die
        Daten im gemeinsamen Cache `_bd_owned_bp_cache` liegen. Es braucht
        also KEINEN zusaetzlichen Abruf.

        SCHLECHTESTE KOPIE, NICHT DURCHSCHNITT (Regel 3): welche Kopie er im
        Spiel einlegt, weiss das Werkzeug nicht. Zu wenig Material gekauft zu
        haben ist teurer als zu viel - und genau das ist ihm passiert.

        JE BAUTEIL, NICHT JE KATEGORIE - ausdrueckliche Wahl des Nutzers
        ("Je Item (genau): jedes Bauteil bekommt das ME seiner eigenen
        schlechtesten Kopie").
        """
        recipes = getattr(self, "_bd_recipes", None)
        cache = getattr(self, "_bd_owned_bp_cache", None)
        if not recipes or not cache:
            return None
        bp = recipes.product_to_bp.get(type_id)
        if not bp:
            return None
        treffer = [b for b in cache if b.get("type_id") == bp[0]]
        if not treffer:
            return None
        me_werte = [b.get("material_efficiency") for b in treffer
                    if b.get("material_efficiency") is not None]
        te_werte = [b.get("time_efficiency") for b in treffer
                    if b.get("time_efficiency") is not None]
        if not me_werte and not te_werte:
            return None
        return (float(min(me_werte)) if me_werte else None,
                float(min(te_werte)) if te_werte else None)

    @staticmethod
    def _bd_esi_kat_key(key):
        """Bildet die feinen Schluessel aus _category_key auf die VIER
        Karten der Oberflaeche ab.

        NOETIG, WEIL ES BEIM ERSTEN VERSUCH DANEBENGING: _category_key
        liefert fuer Bauteile nicht "components", sondern je nach Gruppe
        "t1_components", "advanced_components", "hybrid_components",
        "capital_components" oder "advanced_capital_components". Der
        Schalter haette also nie gegriffen - im Test blieb ME bei 4 %,
        obwohl "aus ESI" abgehakt war. Die Karte "Komponenten" ist der
        Sammelposten fuer alles, was NICHT Huelle/Fuel/Tool ist - genau wie
        im else-Zweig von _bau_category_me_map.
        """
        return key if key in ("t1_hulls", "fuel_blocks", "tools") else "components"

    def _bd_esi_me_aktiv(self, kategorie_key):
        """Ist fuer diese Kategorie die ESI-Verfolgung an (statt Handeingabe)?

        VORGABE AN: der Nutzer hat den Fall gemeldet, in dem die Annahme
        "voll ausgeforscht" ihn Geld gekostet hat. Wer eigene Zahlen setzen
        will, schaltet die Kategorie auf "manuell" - dann gilt wieder das
        Drehfeld.
        """
        schalter = self.settings.get("bau_me_aus_esi")
        if not isinstance(schalter, dict):
            return True
        return bool(schalter.get(self._bd_esi_kat_key(kategorie_key), True))

    def _bd_lookup_owned_bp_for_item(self, type_id):
        """Echte ESI-Blaupausendaten für EIN Item aus dem gemeinsamen Cache
        (nicht-blockierend - nutzt nur, was schon geladen ist, holt NICHTS
        neu nach). Gibt {"copies","runs","bpo"} zurück, oder None wenn der
        Cache noch leer ist oder keine eigene Blaupause gefunden wurde."""
        recipes = getattr(self, "_bd_recipes", None)
        cache = getattr(self, "_bd_owned_bp_cache", None)
        if not recipes or cache is None:
            return None
        bp = recipes.product_to_bp.get(type_id)
        if not bp:
            return None
        target_bp_id = bp[0]
        matches = [b for b in cache if b.get("type_id") == target_bp_id]
        if not matches:
            return None
        # ME/TE DER ECHTEN BLAUPAUSEN MITGEBEN (Sitzung 19). ESI liefert sie
        # je Blaupause; bisher wurden sie hier weggeworfen. Sie werden
        # gebraucht, sobald "Eigene BPC statt Invention" gilt: dann sind die
        # Werte der ERFUNDENEN Blaupause (2 %/4 %) fiktiv.
        #
        # IMMER DER SCHLECHTESTE WERT (Nutzer-Ansage, Sitzung 19: "dann
        # nehmen wir immer die am schlechtesten gefundene ME wert per ESI").
        # Wer mehrere Kopien mit verschiedener Forschung hat, weiss beim
        # Planen nicht, welche im Job landet. Der niedrigste Wert heisst:
        # eher zu viel Material und zu lange Zeit - die sichere Richtung.
        def _schlechteste(_liste, _feld):
            _w = [int(m.get(_feld, 0) or 0) for m in _liste]
            return min(_w) if _w else 0

        is_bpo = any(m.get("is_bpo") for m in matches)
        if is_bpo:
            _bpos = [m for m in matches if m.get("is_bpo")]
            copies = sum(int(m.get("quantity", 1) or 1) for m in _bpos)
            return {"copies": copies, "runs": 1, "bpo": True,
                    "me": _schlechteste(_bpos, "material_efficiency"),
                    "te": _schlechteste(_bpos, "time_efficiency")}
        copies = sum(int(m.get("quantity", 1) or 1) for m in matches)
        rep_runs = min(int(m.get("runs", 1) or 1) for m in matches)
        # runs_known: rep_runs ist die KLEINSTE eigene Kopie - der Runplaner
        # deckelt damit die Runs je Job (Regel 3, kleinste Kopie zaehlt).
        return {"copies": copies, "runs": rep_runs, "bpo": False, "runs_known": True,
                "me": _schlechteste(matches, "material_efficiency"),
                "te": _schlechteste(matches, "time_efficiency")}

    def _bd_own_bpc_me_te(self, type_id):
        """ME/TE fuer "Eigene BPC": die echten Werte der schlechtesten
        eigenen Blaupause, sonst 0/0.

        0/0 ist die bewusste Notbremse (Nutzer, Sitzung 19: "falls ein nutzer
        es uebersieht oder ignoriert, muss der ME/TE 0/0 zaehlen"). Sie greift,
        wenn der Blaupausen-Cache noch leer ist oder keine eigene Kopie
        gefunden wurde - dann weiss das Werkzeug nichts, und Nichtwissen darf
        keine guenstige Zahl erzeugen.
        """
        _d = self._bd_lookup_owned_bp_for_item(type_id) or {}
        return int(_d.get("me", 0) or 0), int(_d.get("te", 0) or 0)

    def _bd_refresh_bp_stage_info(self):
        """Aktualisiert die reinen Anzeige-Labels im "BLAUPAUSEN JE STUFE"-Panel
        (werden nur EINMAL beim Öffnen des Bauplan-Dialogs gebaut, NICHT bei
        jedem rebuild() neu erzeugt). Keine Eingabefelder mehr - alles
        automatisch: Endprodukt kommt aus der Invention-Erfolgschance (falls
        nötig) oder wird als eigene Blaupause angenommen; Komponenten/
        Reaktionen kommen aus "Alles aus ESI laden", nicht abgedeckte Items
        werden als unbegrenzt verfügbar angenommen statt den Plan zu
        blockieren."""
        widgets = getattr(self, "_bd_bp_widgets", None) or {}
        bp = getattr(self, "_bd_bp", None) or {}
        end_w = widgets.get("end")
        if end_w and end_w.get("info_lbl"):
            d = bp.get("end") or {}
            # MULTI-BAUPLAN (Schritt 4b): die Stufe "Endprodukt" hat hier
            # MEHRERE Produkte mit verschiedenen Kopien und Runs. EINE Zeile
            # koennte nur eines davon beschreiben - also sagen wir, wo die
            # echten Zahlen stehen, statt eine davon stellvertretend zu
            # zeigen (Regel: lieber verweisen als etwas Falsches behaupten).
            if getattr(self, "_bd_buendel_enden", None):
                end_w["info_lbl"].setText(t(
                    "Several end products \u2013 copies and runs per product are "
                    "in the \u201eEnd products\u201c card above."))
            elif d.get("bpo"):
                end_w["info_lbl"].setText(
                    t(
                        "Assumed: you own the blueprint (unlimited) – no invention "
                          "needed for this item."))
            else:
                end_w["info_lbl"].setText(t(
                    "{copies} copies \u00d7 {runs} runs - derived automatically from "
                    "the invention success chance (Invention tab)."
                ).format(copies=d.get('copies', 1), runs=d.get('runs', 1)))
        for stage in ("component", "reaction"):
            w = widgets.get(stage)
            if not w or not w.get("info_lbl"):
                continue
            per_item = (getattr(self, "_bd_stage_bp_esi", None) or {}).get(stage)
            _has_esi = bool(self.settings.get("client_id") and store.list_characters())
            if per_item:
                w["info_lbl"].setText(t(
                    "{n} item(s) loaded from ESI - exact values per item (incl. "
                    "BPO/BPC) in the Blueprints tab.").format(n=len(per_item)))
                w["status_lbl"].setText(
                    t(
                        "ESI data active – the run planner uses it directly for "
                          "scheduling."))
            elif _has_esi:
                w["info_lbl"].setText(
                    t(
                        "Items without your own blueprint are assumed to be "
                          "unlimited (you buy or copy them)."))
                w["status_lbl"].setText(
                    t("Being loaded automatically from ESI \u2026"))
            else:
                w["info_lbl"].setText(
                    t(
                        "Items without your own blueprint are assumed to be "
                          "unlimited (you buy or copy them)."))
                w["status_lbl"].setText(
                    t(
                        "No character linked – link one under „Characters“, then "
                          "real blueprints load automatically."))
            w["status_lbl"].setStyleSheet(
                f"color:{theme.GREEN if per_item else theme.MUTED}; font-size:11px; "
                f"line-height:150%; padding:2px 0;")

    def _bd_fetch_all_owned_blueprints(self, force=False):
        """EIN einziger ESI-Abruf pro Charakter für ALLE eigenen Blaupausen
        (BPO+BPC), gecached für die Dauer der Bauplan-Sitzung. Alle anderen
        ESI-Blaupausen-Funktionen (Endprodukt/Komponenten/Reaktionen/
        Invention/Blueprints-Tab) nutzen DIESEN gemeinsamen Cache, statt
        jede für sich dieselben Daten nochmal einzeln abzufragen - vorher
        liefen bei "Alles aus ESI laden" bis zu 5 komplette Abrufe pro
        Charakter für praktisch dieselbe Information. force=True erzwingt
        einen frischen Abruf (z.B. beim expliziten Knopf-Klick)."""
        if not force and getattr(self, "_bd_owned_bp_cache", None) is not None:
            return self._bd_owned_bp_cache
        client_id = self.settings.get("client_id")
        chars = store.list_characters()
        all_bp = []
        if client_id and chars:
            for c in chars:
                try:
                    for b in esi.fetch_blueprints(client_id, c["character_id"]):
                        all_bp.append(b)
                except Exception:
                    continue
            # CORP-BLAUPAUSEN (1.1.0, Discord: "Blueprints im Corp-Hangar"):
            # auch ohne "Subtract assets" - vorher kamen sie NUR ueber den
            # Bestands-Worker, der mit diesem Schalter laeuft. Schalter
            # use_corp, Divisions und Rollen prueft _corp_blaupausen selbst.
            try:
                all_bp.extend(self._corp_blaupausen(client_id, chars)
                              .get("blueprints") or [])
            except Exception as _cbe:
                self._log_exception("Corp: Blaupausen (Bauplan)", str(_cbe))
        self._bd_owned_bp_cache = all_bp
        return all_bp

    def _scan_owned_bpc_opts(self):
        """Eigene Blaupausen als build_opts-Teilmenge für den Bau-Scan -
        OHNE jeden Bauplan-Dialog-Zustand:
            {"inv_owned_runs": {bp_id: Runs}, "inv_manual_override": {bp_id: True}}

        WARUM ES DAS GIBT: `_resolve_inv_owned_runs()` liest `_bd_end_bpc_esi`
        und `_bd_owned_bpc_by_id` - beides gibt es nur, solange ein Bauplan
        offen ist. Im Scan war der Schlüssel deshalb nie gesetzt, und
        `build_cost()` stellte JEDEM T2-Item die vollen Invention-Kosten in
        Rechnung, auch für Items, von denen der Nutzer 112 BPC-Runs im Hangar
        hat. Der Bauplan zeigte für dieselben Items 0 ISK Invention.

        KEINE ZWEITE ABLEITUNG: die Blaupausenliste kommt aus dem GEMEINSAMEN
        Cache (`_bd_fetch_all_owned_blueprints`, ein ESI-Abruf je Charakter),
        die Auswertung aus `industry.owned_bp_runs()` - genau der Funktion,
        die auch der Invention-Tab benutzt. Ohne ESI-Zugang oder verknüpfte
        Charaktere liefert der Cache eine leere Liste und damit leere Maps;
        dann rechnet der Scan wie bisher.

        BPO = unbegrenzt: die landen als `inv_manual_override` (kein
        Invention-Posten), nicht als Run-Zahl - eine Zahl wäre dort gelogen.
        """
        runs, bpo_ids = industry.owned_bp_runs(
            self._bd_fetch_all_owned_blueprints())
        return {"inv_owned_runs": runs,
                "inv_manual_override": {bp_id: True for bp_id in bpo_ids}}

    def _load_all_esi_for_plan_core(self, type_id):
        """Reine Berechnung/ESI-Abrufe ohne UI-Seiteneffekte (kein Rebuild, kein
        Toast) - läuft im Hintergrund-Thread, damit die App w\u00e4hrend der ESI-
        Abrufe nicht einfriert. Gibt (summary_list, error_msg, owned_bp) zur\u00fcck
        - owned_bp ist die EINE gemeinsam geholte Blaupausen-Liste, die auch
        f\u00fcr die Blueprints-Tab-Tabelle weiterverwendet wird (kein zweiter,
        paralleler ESI-Abruf mehr n\u00f6tig).
        WICHTIG: erzeugt NIE ein QWidget hier (auch keine Platzhalter!) - Qt-
        Widgets d\u00fcrfen nur im Hauptthread erzeugt werden, das war der
        eigentliche Grund f\u00fcr das Einfrieren (kein Absturz, nur ein stiller
        Deadlock in Qt's internen Sperren). Die drei Lade-Funktionen bekommen
        deshalb None statt Widgets - im silent=True-Pfad greifen sie eh nie
        darauf zu."""
        client_id = self.settings.get("client_id")
        chars = store.list_characters()
        if not client_id or not chars:
            return None, t("No ESI access, or no characters linked."), []
        recipes = getattr(self, "_bd_recipes", None)
        plan = (getattr(self, "_bd_plan_ref", None) or {}).get("plan")
        if not recipes or not plan:
            return None, t("Build plan not fully calculated yet - click "
                           "\u201eRecalculate\u201c first."), []
        owned_bp = self._bd_fetch_all_owned_blueprints(force=True)
        summary = []
        # Endprodukt läuft NICHT mehr über ESI - kommt automatisch aus der
        # Invention-Erfolgschance (falls nötig) oder wird als eigene
        # Blaupause angenommen (siehe _bd_bp["end"]-Defaults).
        # 1) Komponenten + Reaktionen (pro Item)
        for stage, label in (("component", t("Components")), ("reaction", t("Reactions"))):
            n_cov, n_tot = self._load_stage_bp_from_esi(
                stage, plan, recipes, None, silent=True, owned_bp=owned_bp)
            if n_cov:
                summary.append(t("{label}: {cov}/{tot} items covered").format(
                    label=label, cov=n_cov, tot=n_tot))
        # 3) Invention (alle T2-Items)
        items = []
        for tid, runs in (plan.get("build_runs") or {}).items():
            if runs < 1:
                continue
            bp = recipes.product_to_bp.get(tid)
            if not bp:
                continue
            bp_id, activity, _oq = bp
            if activity != industry.MANUFACTURING:
                continue
            inv = recipes.invention_for_bpc.get(bp_id)
            if not inv:
                continue
            items.append((tid, bp_id, runs, inv))
        if items:
            n_inv = self._load_all_invention_bpc_from_esi(items, None, silent=True,
                                                           owned_bp=owned_bp)
            if n_inv:
                summary.append(t("Invention: {n} item(s) with own BPCs").format(n=n_inv))
        return summary, None, owned_bp

    def _load_all_invention_bpc_from_esi(self, items, undo_btn, silent=False, owned_bp=None):
        """Prüft für JEDES T2-Item im Invention-Tab (nicht nur das Endprodukt),
        ob eigene BPCs/BPOs existieren, und reduziert die nötigen Invention-
        Versuche entsprechend. Nutzt owned_bp (gemeinsamer ESI-Cache, s.
        _bd_fetch_all_owned_blueprints) statt selbst nochmal abzufragen, wenn
        übergeben - sonst holt es sich die Daten selbst (Einzelaufruf).
        silent=True: keine eigenen Popups/Toasts (für den zentralen "Alles
        aus ESI laden"-Knopf, der am Ende eine einzige Zusammenfassung
        zeigt) - gibt stattdessen die Trefferzahl zurück (0 bei Fehler/
        nichts gefunden)."""
        target_bp_ids = {bp_id for _tid, bp_id, _runs, _inv in items}
        if not target_bp_ids:
            return 0
        if owned_bp is None:
            client_id = self.settings.get("client_id")
            chars = store.list_characters()
            if not client_id or not chars:
                if not silent:
                    QMessageBox.warning(self, t("Load own BPCs"),
                                       t("No ESI access, or no characters linked."))
                return 0
            owned_bp = self._bd_fetch_all_owned_blueprints()
        # Aggregation liegt in industry.owned_bp_runs() - DIESELBE Funktion
        # nutzt der Bau-Scan (_scan_owned_bpc_opts), damit "eigene BPCs" dort
        # nicht ein zweites Mal, womoeglich anders, abgeleitet wird.
        owned, bpo_ids = industry.owned_bp_runs(owned_bp, target_bp_ids)
        if not owned and not bpo_ids:
            if not silent:
                QMessageBox.information(
                    self, t("Load own BPCs"),
                    t("No blueprints (BPO/BPC) of your own found for the items here."))
            return 0
        self._bd_owned_bpc_by_id = owned
        self._bd_owned_bpc_bpo_ids = bpo_ids
        for bp_id in bpo_ids:
            self._bd_opts.setdefault("inv_manual_override", {})[bp_id] = True
        n = len(owned) + len(bpo_ids)
        if not silent:
            undo_btn.setVisible(True)
            self._flash_tip(t("{n} item(s) with own blueprints found \u2713").format(n=n))
            cb = getattr(self, "_bd_full_rebuild", None)
            if cb:
                cb()
        return n

    def _undo_all_invention_bpc_esi(self, undo_btn):
        """Macht das ESI-Laden für alle Items rückgängig."""
        self._bd_owned_bpc_by_id = None
        for bp_id in (getattr(self, "_bd_owned_bpc_bpo_ids", None) or set()):
            (self._bd_opts.get("inv_manual_override") or {}).pop(bp_id, None)
        self._bd_owned_bpc_bpo_ids = None
        undo_btn.setVisible(False)
        cb = getattr(self, "_bd_full_rebuild", None)
        if cb:
            cb()



    def _load_stage_bp_from_esi(self, stage, plan, recipes, status_lbl, silent=False,
                                owned_bp=None):
        from ..sprache import t as _txt   # `t` ist hier lokal belegt
        """Wie beim Endprodukt, aber f\u00fcr Komponenten/Reaktionen: holt die echten
        Blaupausen ALLER Items dieser Stufe (pro Item einzeln, nicht als eine
        einzige Zahl) und speist sie als per-Item-Obergrenze in den Runplaner
        ein - ein Item mit 5 eigenen Blaupausen darf dann auf 5 Charakteren
        gleichzeitig laufen, eins mit nur 1 BPC eben nur auf einem.
        "Kopien"/"Runs" bleiben bewusst UNANGETASTET (keine Aggregation) -
        eine einzige Zahl kann die tats\u00e4chliche Verteilung \u00fcber viele
        verschiedene Items ohnehin nicht ehrlich abbilden. F\u00fcr "wie viele
        Blaupausen hab ich von was" gibt's den Blueprints-Tab (pro Item,
        keine Aggregation n\u00f6tig); f\u00fcr "wer baut was wie lange" den
        Runplaner, der die genauen Pro-Item-Daten direkt nutzt.
        silent=True: keine eigenen Popups/Toasts/Rebuild (f\u00fcr den zentralen
        "Alles aus ESI laden"-Knopf) - gibt (n_covered, n_total) zur\u00fcck."""
        if owned_bp is None:
            client_id = self.settings.get("client_id")
            chars = store.list_characters()
            if not client_id or not chars:
                if not silent:
                    QMessageBox.warning(self, _txt("Load blueprints"),
                                       _txt("No ESI access or no linked characters."))
                return 0, 0
            owned_bp = self._bd_fetch_all_owned_blueprints()
        top_tid = getattr(self, "_bd_bp_type", None)
        _enden = self._bd_enden(top_tid, recipes)   # Buendel: alle Enden
        target_ids = []          # (type_id, bp_id) Paare dieser Stufe
        for t, runs in (plan.get("build_runs") or {}).items():
            if runs < 1:
                continue
            bp = recipes.product_to_bp.get(t)
            if not bp:
                continue
            bp_id, activity, _oq = bp
            is_end = (t in _enden)
            st = ("reaction" if activity == industry.REACTION
                 else "end" if is_end else "component")
            if st != stage:
                continue
            target_ids.append((t, bp_id))
        if not target_ids:
            if not silent:
                QMessageBox.information(self, _txt("Load blueprints"),
                                        _txt("No items at this stage."))
            return 0, 0
        bp_to_tid = {}
        for t, bp_id in target_ids:
            bp_to_tid.setdefault(bp_id, []).append(t)
        target_bp_ids = set(bp_to_tid)
        all_matches = {bp_id: [] for bp_id in target_bp_ids}
        for b in owned_bp:
            bid = b.get("type_id")
            if bid in target_bp_ids:
                all_matches[bid].append(b)
        per_item = {}
        n_bpo = 0
        for bp_id, matches in all_matches.items():
            if not matches:
                continue
            is_bpo = any(m.get("is_bpo") for m in matches)
            # WICHTIG: "BPO = unbegrenzt Runs PRO Kopie" heißt NICHT "unbegrenzt
            # viele Kopien" - jede physische BPO belegt trotzdem genau einen
            # Job-Slot gleichzeitig, exakt wie eine BPC. Für "wie viele Slots
            # gleichzeitig" zählt IMMER die tatsächlich besessene Stückzahl,
            # BPO wie BPC gleich - sonst nimmt der Runplaner fälschlich an, ein
            # Item könnte auf beliebig vielen Charakteren gleichzeitig laufen,
            # nur weil man zufällig mindestens eine BPO davon besitzt.
            copies = sum(int(m.get("quantity", 1) or 1) for m in matches)
            if is_bpo:
                n_bpo += 1
            for t in bp_to_tid[bp_id]:
                per_item[t] = copies
        if not per_item:
            if not silent:
                QMessageBox.information(
                    self, _txt("Load blueprints"),
                    _txt("No blueprints of your own found for items at this stage."))
            return 0, len(target_ids)
        stage_map = getattr(self, "_bd_stage_bp_esi", None) or {}
        stage_map[stage] = per_item
        self._bd_stage_bp_esi = stage_map
        n_total = len(target_ids)
        n_covered = len(per_item)
        if not silent:
            status_lbl.setText(
                _txt("{a} of {b} items covered").format(a=n_covered, b=n_total)
                + (_txt(" ({n} as BPO)").format(n=n_bpo) if n_bpo else "")
                + _txt(" - exact values per item in the Blueprints tab, the run "
                       "planner uses them directly for scheduling."))
            status_lbl.setStyleSheet(
                f"color:{theme.GREEN}; font-size:11px; line-height:150%; padding:2px 0;")
            self._flash_tip(_txt("{a}/{b} items covered by ESI blueprints \u2713").format(
                a=n_covered, b=n_total))
            refill_cb_ = getattr(self, "_bd_full_rebuild", None)
            if refill_cb_:
                refill_cb_()
        return n_covered, n_total





    def _bau_item_invention_te_pct(self, tid, recipes=None, opts=None):
        """Echte TE (4% Basis + Decryptor-Bonus) eines Items, das über
        Invention entsteht - None, wenn Invention nicht zutrifft/aktiv ist
        oder "Eigene BPC" für dieses Item gesetzt ist (dann bleibt der
        normale, manuelle TE-Pfad aktiv). Wird von _bau_category_te_factor
        für JEDES Item genutzt (nicht nur das Endprodukt), damit auch
        Unterkomponenten, die selbst Invention brauchen, ihre echte TE für
        die Bauzeit-Planung bekommen - analog zur ME-Anbindung.
        recipes/opts: optionale Overrides (z.B. vom Hintergrund-Recompute
        für gespeicherte Pläne) - sonst self._bd_recipes/self._bd_opts vom
        gerade offenen Bauplan-Dialog. WICHTIG: NIE self._bd_* mutieren, um
        einen offenen Dialog nicht zu stören (war früher ein echter Bug -
        der Hintergrund-Recompute lief in einem eigenen Thread und hat
        self._bd_te& Co. kurzzeitig überschrieben, während ein Dialog offen
        war, was dessen Nachfüll-Plan-Berechnung durcheinanderbrachte)."""
        if recipes is None:
            recipes = getattr(self, "_bd_recipes", None)
        if opts is None:
            opts = getattr(self, "_bd_opts", None) or {}
        if not recipes or not opts.get("invention", True):
            return None
        bp = recipes.product_to_bp.get(tid)
        if not bp:
            return None
        bp_id = bp[0]
        if bp_id in (opts.get("inv_manual_override") or {}):
            return None
        inv = recipes.invention_for_bpc.get(bp_id)
        if not inv:
            return None
        _t1_bp, base_runs, base_prob, _dc = inv
        dv = (opts.get("inv_decryptor_map") or {}).get(bp_id)
        if dv is None:
            dv = (opts.get("inv_prob_mult", 1.0), opts.get("inv_run_mod", 0),
                 opts.get("inv_me_mod", 0), opts.get("inv_te_mod", 0),
                 opts.get("inv_decryptor_id"))
        return industry.invention_outcome(base_runs, base_prob, dv)["te_pct"]

    def _bau_category_te_factor(self, tid, groups, reaction_products, type_id,
                                mfg_struct=None, react_struct=None,
                                te_attrs=None, recipes=None, opts=None):
        """Zeit-Faktor (0..1, kleiner = schneller) f\u00fcr EIN Item: Kategorie-Basis-TE
        (Blueprint-Forschung, sofern m\u00f6glich) MAL passender Struktur-Rig-TE
        (Item-Dom\u00e4ne) MAL eingebautem Struktur-Rollen-Zeitbonus (Tatara \u221225 %
        Reaktion, Sotiyo \u221230 % / Azbel \u221220 % / Raitaru \u221215 % Fertigung).
        Endprodukt nutzt die Blueprint-TE-Eingabe oben im Dialog. Reaktionen haben
        KEINE Forschungs-TE, aber Reaktions-Rig UND Tatara-Rollen-Bonus gelten \u2013
        letzterer wurde hier vorher \u00fcbersehen (Reaktionszeiten zu lang)."""
        is_reac = tid in (reaction_products or set())
        catmap = industry.item_category_map() or {}
        info = catmap.get(tid)
        cat = info[0] if info else None
        meta = info[2] if info else None
        doms = industry.item_domains(cat, groups.get(tid, ""), meta, is_reaction=is_reac)
        if is_reac:
            base_factor = 1.0                  # keine BP-Forschung m\u00f6glich
            # KORRIGIERT (Sitzung 13, EVE ZEIGT ES SELBER): hier stand
            # `rig_te = 0.0` mit der Begruendung, der Reactor-Efficiency-Rig
            # wirke nicht auf die Reaktions-Job-Zeit. Beleg damals: Sylramic
            # und Platinum Technite liefen in derselben Tatara bei 19 Runs
            # gleich lang. Dieser Vergleich taugte nicht - zwei Items in
            # DERSELBEN Struktur mit DEMSELBEN Rig laufen auch dann gleich
            # lang, wenn der Rig sehr wohl wirkt.
            # NEUER BELEG, eindeutig: das Tooltip "JOB DURATION MODIFIERS" im
            # Industry-Fenster (Nonlinear Metamaterials, R&R Yard) listet
            # einzeln auf:
            #     Skills and Implants   -20.0 %
            #     Installed Rig         -22.0 %   <-- genau dieser Rig
            #     Structure Role Bonus  -25.0 %
            # Nachgerechnet: Grundzeit 3 h (aus dem Info-Fenster), 10 Runs
            # = 108'000 s. 108'000 x 0.80 x 0.78 x 0.75 = 50'544 s
            # = 14:02:24 - exakt die angezeigte JOB DURATION. Ohne den Rig
            # waeren es 64'800 s = 18:00:00, also 28 % zu lang.
            # Der Material-Bonus des Rigs war davon nie betroffen.
            rig_te = self._bau_rig_te_for_item(react_struct, doms, reaction=True)
            role_pct = self._STRUCT_ROLE_TIME.get(
                (react_struct or {}).get("type", ""), {}).get("react", 0.0)
        else:
            _inv_te = self._bau_item_invention_te_pct(tid, recipes=recipes, opts=opts)
            if _inv_te is not None:
                te = _inv_te
            elif industry.ist_ende(tid, type_id, recipes):
                # Buendel (1.0.9): jedes Ende hat die TE seines Einzelplans
                # (`_bd_te_je_ende`); der Einzelplan nimmt die Eingabe oben.
                _je = ((te_attrs or {}).get("_bd_te_je_ende") if te_attrs is not None
                       else getattr(self, "_bd_te_je_ende", None)) or {}
                te = _je.get(tid)
                if te is None:
                    te = (te_attrs or {}).get("_bd_te") if te_attrs is not None \
                        else getattr(self, "_bd_te", None)
                if te is None:
                    te = self.settings.get("bau_te", 0)
            else:
                key = self._category_key(tid, groups.get(tid, ""), False, cat, meta)
                _ta = te_attrs if te_attrs is not None else None
                # ECHTES TE DER EIGENEN BLAUPAUSE ZUERST (Sitzung 16) -
                # dieselbe Quelle und dieselbe Regel wie beim ME, sonst
                # rechnete das Werkzeug mit dem echten Materialbedarf, aber
                # der Zeit eines voll ausgeforschten BPOs.
                _esi_te = (self._bd_esi_me_te_for_item(tid)
                           if self._bd_esi_me_aktiv(key) else None)
                if _esi_te is not None and _esi_te[1] is not None:
                    te = _esi_te[1]
                elif key == "t1_hulls":
                    te = (_ta.get("_bd_te_t1hull") if _ta is not None else
                         getattr(self, "_bd_te_t1hull", self.settings.get("bau_te_t1hull", 20)))
                elif key == "fuel_blocks":
                    te = (_ta.get("_bd_te_fuel") if _ta is not None else
                         getattr(self, "_bd_te_fuel", self.settings.get("bau_te_fuel", 20)))
                elif key == "tools":
                    te = (_ta.get("_bd_te_tools") if _ta is not None else
                         getattr(self, "_bd_te_tools", self.settings.get("bau_te_tools", 20)))
                else:
                    te = (_ta.get("_bd_te_component") if _ta is not None else
                         getattr(self, "_bd_te_component",
                                self.settings.get("bau_te_component", 20)))
            base_factor = 1 - float(te or 0) / 100.0
            # KORRIGIERT (Ingame-Beleg Crystalline Carbonide Armor Plate, 6658 Runs):
            # Der Manufacturing-Rig-ZEITbonus WIRKT auf die Job-Zeit, wenn die
            # Rig-Domäne zum Item passt (z.B. "Advanced Component Manufacturing
            # Efficiency" ↔ Advanced-Component-Items). Ingame-Job-Duration-Panel zeigte
            # exakt: BP-TE -20% · Skills -34.7% · Installed Rig -42.0% (= -20% Rig-Basis
            # × Sicherheitsmultiplikator ×2.1 Null/WH) · Structure Role Bonus -20% →
            # Gesamtzeit 11:12:14, rechnerisch exakt reproduziert (25s base × 0.80 ×
            # 0.6528 × 0.58 × 0.80 × 6658 = 40334.06s = 11h 12m 14s). Die alte Annahme
            # "kein Rig-Zeitbonus bei Fertigung" war falsch (vermutlich Domain-Mismatch
            # beim damaligen Testitem). Fuer REAKTIONEN gilt dasselbe - siehe
            # den Reaktionszweig oben (Sitzung 13, EVEs eigenes
            # "JOB DURATION MODIFIERS"-Tooltip). Hier stand frueher, das sei
            # "separat verifiziert, CCP-Devblog bestaetigt" - beides trug nicht.
            rig_te = self._bau_rig_te_for_item(mfg_struct, doms, reaction=False)
            role_pct = self._STRUCT_ROLE_TIME.get(
                (mfg_struct or {}).get("type", ""), {}).get("mfg", 0.0)
        role_factor = 1 - role_pct / 100.0
        return max(0.02, base_factor * (1 - rig_te / 100.0) * role_factor)

    @staticmethod
    def _bl_clean_name(s):
        """Blacklist-Zeile auf den reinen Itemnamen reduzieren.

        Wer aus dem Spiel oder aus diesem Tool kopiert, bekommt
        "Gravimetric Sensor Cluster  1455" - Name plus Menge. Der Abgleich
        lief ueber exakte Namensgleichheit und schlug still fehl.
        Abgeschnitten werden Tabulator/Mehrfach-Leerzeichen und eine
        ABSCHLIESSENDE Zahl; Ziffern IM Namen bleiben ("R.A.M.- Starship
        Tech").
        """
        import re as _re_bl
        s = str(s or "").strip()
        s = _re_bl.split(r"\t|\s{2,}", s)[0]
        s = _re_bl.sub(r"[\s\u00a0]+[\d'.,]+$", "", s)
        return s.strip().lower()

    def _bau_plan_struct_ids(self):
        """Struktur-IDs, in denen DIESER Plan baut (je Aktivitaet die gewaehlte
        Struktur). Leere Menge = keine verknuepfte Struktur, dann laesst sich
        \"anderswo\" nicht sagen und die Anzeige bleibt wie bisher.

        NUTZER-AUFTRAG (Punkt C, Sitzung 20): `esi.fetch_blueprints` holt die
        Blaupausen ausdruecklich \"egal wo sie liegen\"; die `location_id` kam
        zwar mit, wurde aber nirgends ausgewertet. Der Blueprints-Reiter sagte
        deshalb \"enough\", auch wenn die Kopie 30 Spruenge entfernt liegt.
        NICHT hart filtern und NICHT rot faerben (Nutzer-Entscheid) - sonst
        wird der Reiter bei vielen komplett rot, weil BPO woanders liegen als
        kopiert wird. Nur dazuschreiben.
        """
        return {int(_s["link_structure_id"]) for _s in self._bau_plan_structs()
                if _s.get("link_structure_id")}

    def _bau_plan_structs(self):
        """Die Strukturen, in denen DIESER Plan wirklich baut - als Liste
        der Struktur-Eintraege, je Stufe hoechstens einer.

        NUTZER-BEFUND (Sitzung 20): "bei Only build structures werden meine
        Materialien richtig getrackt, bei Only where this plan builds nicht."
        GEMESSEN im Quelltext: es gab ZWEI Antworten auf "wo baut der Plan".
        Der Plan und der Runplaner nehmen `_bau_best_struct` - im Auto-Modus
        die Struktur mit dem groessten ME-Nutzen fuer GENAU die Items der
        Stufe. Der Bestandsbereich nahm `_struct_for_activity` - im
        Auto-Modus die mit dem besten PAUSCHALEN Rig-Prozent, ohne die Items
        anzusehen. Fallen die beiden auseinander, baut der Runplaner in
        Struktur A, der Bereich zaehlt aber Struktur B - und das Material in
        A ist unsichtbar.
        DESHALB: zuerst die Stufen-Strukturen, die der Plan beim Rechnen
        gewaehlt hat (`_bd_stage_structs`, dieselbe Quelle wie der
        Runplaner). Nur Stufen, die dort nicht vorkommen (Invention,
        Kopieren), fallen auf `_struct_for_activity` zurueck.
        """
        out = []
        seen = set()
        stufen = getattr(self, "_bd_stage_structs", None) or {}
        for _k, _s in stufen.items():
            if _s and id(_s) not in seen:
                seen.add(id(_s))
                out.append(_s)
        for _akey, _lab in self._STRUCT_ACTIVITIES:
            if _akey in stufen:
                continue                 # Plan hat fuer diese Stufe entschieden
            _s = self._struct_for_activity(_akey)
            if _s and id(_s) not in seen:
                seen.add(id(_s))
                out.append(_s)
        return out

    def _bau_rollen_netz(self):
        """NETZ BEIM OEFFNEN EINES BAUPLANS: ist GAR KEINE Rolle gesetzt,
        obwohl Charaktere verknuepft sind, werden alle vier Rollen fuer alle
        Charaktere gesetzt.

        NUTZER-ANSAGE (Sitzung 20): *"es soll sich schon merken was man
        angehackt hat ... aber beim Erstoeffnen muss da etwas angehackt sein,
        sonst sehen wir keine blueprints"*.

        Die Einmal-Migration in `config.py` deckt das nur EINMAL ab (sie setzt
        danach ihren Marker). Wer danach in einen leeren Zustand geraet - alle
        Haken entfernt, Charaktere neu verknuepft, Einstellungen zurueckgesetzt
        - saehe einen leeren Runplaner UND einen leeren Blueprints-Reiter, weil
        `_fill_bauplan_schedule` bei leerer Auswahl sofort aussteigt.

        BEWUSST NUR IM VOLLSTAENDIG LEEREN ZUSTAND. Sobald auch nur ein Haken
        irgendwo sitzt, wird NICHTS angefasst - eine bewusste Abwahl darf das
        Werkzeug nicht ueberschreiben (Regel 4: der Nutzer entscheidet). Der
        Zustand "gar nichts" ist dagegen nie gewollt: er macht Runplaner und
        Blueprints-Tabelle unbenutzbar.
        """
        try:
            cids = [int(c["character_id"]) for c in store.list_characters()]
        except Exception:
            return False
        if not cids:
            return False
        keys = [k for k, _l in self._ROSTER_ROLES]
        if any(self.settings.get(k) for k in keys):
            return False
        for k in keys:
            self.settings[k] = list(cids)
        config.save_settings(self.settings)
        return True

    def _bau_rollen_alle_anhaken(self):
        """Alle vier Rollen fuer alle verknuepften Charaktere setzen - der
        Knopf neben dem Hinweis, wenn jemand ohne Rolle dasteht."""
        try:
            cids = [int(c["character_id"]) for c in store.list_characters()]
        except Exception:
            cids = []
        if not cids:
            return
        for _key, _l in self._ROSTER_ROLES:
            self.settings[_key] = list(cids)
        config.save_settings(self.settings)
        self._char_roles_dirty = True
        self._reload_char_roles()
        self._apply_build_chars()

    def _bau_rollen_vorbelegen(self, character_id):
        """Ein frisch verknuepfter Charakter bekommt ALLE Rollen-Haken.

        WARUM (Nutzer-Meldung, Sitzung 19): ein Nutzer hatte Charaktere
        verknuepft, Strukturen angelegt, und unter "My blueprints" standen
        alle Blaupausen - im Bauplan blieb der Blueprints-Reiter trotzdem
        LEER. Grund: `_fill_bauplan_schedule` steigt sofort aus, wenn weder
        `bau_build_chars` noch `bau_reaction_chars` gesetzt sind. Diese eine
        Funktion fuellt BEIDES, den Runplaner und die Blueprints-Tabelle.
        Verknuepfen allein reichte also nicht - man musste die Charaktere
        zusaetzlich als Bau- bzw. Reaktions-Charakter zuweisen, ohne dass
        irgendwo stand, dass das noetig ist.

        Voll angehakt ist die richtige Voreinstellung: wer einen Charakter
        verknuepft, will ihn benutzen. Abwaehlen kann man ihn jederzeit -
        und ein bereits ABGEWAEHLTER Charakter wird hier nie wieder
        angehakt, weil nur der neu hinzugekommene eingetragen wird.
        """
        _cid = int(character_id)
        for _key in ("bau_build_chars", "bau_reaction_chars",
                     "bau_invention_chars", "bau_copy_chars"):
            _liste = list(self.settings.get(_key) or [])
            if _cid not in _liste:
                _liste.append(_cid)
                self.settings[_key] = _liste
        config.save_settings(self.settings)

    def _bau_never_build(self, ids, groups, reaction_products, names=None):
        """Set der Type-IDs, die komplett aus dem Plan genommen werden (weder bauen
        noch kaufen) \u2013 aus der Einzel-Item-Blacklist (Clipboard-Namen). Diese
        Items verschwinden aus Rezept-Struktur, Bau-Reihenfolge und Runplaner."""
        # MENGEN ABSCHNEIDEN. Wer aus dem Spiel oder aus diesem Tool kopiert,
        # bekommt "Gravimetric Sensor Cluster  1455" - also Name + Menge.
        # Der Abgleich lief ueber exakte Namensgleichheit und schlug damit
        # still fehl (Nutzer: "Kategorien abgehakt, trotzdem wird gebaut").
        _bl_clean = self._bl_clean_name
        bl_names = set(_bl_clean(n)
                       for n in (self.settings.get("bau_blacklist_names", []) or [])
                       if _bl_clean(n))
        # GANZE GRUPPEN (Nutzer-Wunsch, Sitzung 20): "komplette Gruppierungen
        # blacklisten - PI, Minerals, Hulls, Components". Bisher ging es nur
        # ueber Itemnamen; fuer PI haette man jedes einzelne Planetenprodukt
        # eintippen muessen.
        # DIESELBE Einteilung wie der Materialien-Reiter (`_bd_material_gruppe`),
        # damit das Haekchen genau die Gruppe trifft, die dort steht.
        bl_gruppen = set(self.settings.get("bau_blacklist_gruppen", []) or [])
        if not bl_names and not bl_gruppen:
            return set()
        names = names or {}
        never = set()
        _rec = getattr(self, "_bd_recipes", None)
        _stufen = None
        if bl_gruppen:
            try:
                _stufen = industry.reaction_stage_map(_rec) if _rec else {}
            except Exception:
                _stufen = {}
            _catmap_bl = industry.item_category_map() or {}
        for tid in ids:
            nm = (names.get(tid) or "").strip().lower()
            if nm and nm in bl_names:
                never.add(tid)
                continue
            if bl_gruppen:
                try:
                    _g = self._bd_material_gruppe(
                        tid, recipes=_rec, groups=groups,
                        stage_map=_stufen,
                        react_products=(reaction_products or set()),
                        catmap=_catmap_bl)
                except Exception:
                    _g = None
                if _g and _g in bl_gruppen:
                    never.add(tid)
        return never


    def _build_blacklist_compact(self):
        """Schmale, vertikale Blacklist für die rechte Spalte im Bauplan (neben
        „Meine Blueprints“). Nur ein Clipboard-Textfeld für einzelne Items \u2013
        keine Kategorien mehr (die gehören in „Meine Blueprints“)."""
        from PySide6.QtWidgets import QTextEdit as _TE
        w = QWidget()
        v = QVBoxLayout(w); v.setContentsMargins(6, 4, 6, 4); v.setSpacing(4)
        self.bl_notice_lbl = QLabel("")
        self.bl_notice_lbl.setWordWrap(True)
        self.bl_notice_lbl.setStyleSheet(
            f"color:{theme.AMBER}; font-weight:700; padding:2px 0;")
        self.bl_notice_lbl.setVisible(False)
        v.addWidget(self.bl_notice_lbl)
        # GANZE GRUPPEN AUSNEHMEN (Nutzer-Wunsch, Sitzung 20: "komplette
        # Gruppierungen blacklisten - PI, Minerals, Hulls, Components").
        # Ueber dem Clipboard-Feld, weil es dieselbe Zusage ist, nur grober:
        # weder bauen noch kaufen. Die Namen sind GENAU die Gruppen des
        # Materialien-Reiters (`_MATERIAL_GRUPPEN`) - eine zweite Einteilung
        # zu erfinden hiesse, dass Haekchen und Reiter Verschiedenes meinen.
        _gr_cap = QLabel(t("Never buy and never build these groups:"))
        _gr_cap.setObjectName("Muted")
        _gr_cap.setWordWrap(True)
        v.addWidget(_gr_cap)
        self._bl_gruppen_boxes = {}
        _gesetzt = set(self.settings.get("bau_blacklist_gruppen", []) or [])
        for _gk in self._MATERIAL_GRUPPEN:
            _cb = QCheckBox(self._kategorie_anzeige(_gk))
            _cb.setChecked(_gk in _gesetzt)
            _cb.setToolTip(t(
                "Everything in this group is taken out of the plan completely "
                "\u2013 not built, not bought, and it disappears from the "
                "shopping list and the run planner. What it would have been "
                "made of falls away with it."))
            _cb.toggled.connect(self._save_blacklist_gruppen)
            self._bl_gruppen_boxes[_gk] = _cb
            v.addWidget(_cb)
        self.bl_items = _TE()
        self._bl_widgets = [w for w in (getattr(self, "_bl_widgets", None) or [])
                            ] + [self.bl_items]
        # de_scan3: aus  (Beispiel-Itemnamen aus EVE, sprachneutral)
        self.bl_items.setPlaceholderText("Nanoelectrical Microprocessor\nMorphite\n\u2026")
        # de_scan3: an
        self.bl_items.setPlainText("\n".join(self.settings.get("bau_blacklist_names", [])))
        self.bl_items.setToolTip(
            t("Remove individual items completely from the build plan \u2013 copy the names "
              "from the game, one item per line. They disappear from the recipe "
              "structure, build order and run planner \u2013 automatically, a moment "
              "after you stop typing."))
        self.bl_items.textChanged.connect(self._blacklist_verzoegert)
        v.addWidget(self.bl_items, 1)
        return w

    def _save_blacklist_gruppen(self, *_a):
        """Haekchen der Gruppen-Blacklist speichern und sofort neu rechnen.

        DERSELBE Auffrischer wie bei "Meine Blueprints" und beim
        Clipboard-Feld (`_bau_refresh_exclusions_and_rebuild`) - sonst wirkte
        das Haekchen erst nach Schliessen und Neuoeffnen des Bauplans, genau
        der Fehler aus Sitzung 19 (aa321).
        """
        boxes = getattr(self, "_bl_gruppen_boxes", None) or {}
        self.settings["bau_blacklist_gruppen"] = [
            k for k, cb in boxes.items() if cb.isChecked()]
        config.save_settings(self.settings)
        self._bau_refresh_exclusions_and_rebuild()

    def _push_blacklist_to_ui(self):
        """Blacklist speichern UND das Textfeld nachziehen.

        Ohne das haette der Rechtsklick die Einstellung geaendert, das
        sichtbare Feld aber nicht - und beim naechsten Tippen darin waere
        alles wieder ueberschrieben worden.
        """
        config.save_settings(self.settings)
        _w = getattr(self, "bl_items", None)
        if _w is not None:
            try:
                _w.blockSignals(True)
                _w.setPlainText("\n".join(
                    self.settings.get("bau_blacklist_names", []) or []))
            finally:
                _w.blockSignals(False)

    def _blacklist_verzoegert(self):
        """Speichern ERST, wenn eine halbe Sekunde nicht getippt wurde.

        WARUM (Nutzer, Sitzung 19): "ich kann da sachen eintippen aber mit
        jedem buchstabe den ich eingebe rechnet das tool irgendwas und ich
        kann kaum tippen weil alles so langsam wird". `textChanged` feuert je
        Tastendruck, und `_save_blacklist_items` schreibt jedes Mal die
        KOMPLETTE Einstellungsdatei auf die Platte und befuellt ausserdem das
        zweite Blacklist-Feld neu. Bei einem Itemnamen wie "Nanoelectrical
        Microprocessor" sind das 28 Schreibvorgaenge.

        Der Timer sammelt die Tastendruecke ein; gespeichert wird einmal.
        Am Speichern selbst aendert sich nichts - nur am WANN.
        """
        _tm = getattr(self, "_bl_save_timer", None)
        if _tm is None:
            _tm = QTimer(self)
            _tm.setSingleShot(True)
            _tm.timeout.connect(self._save_blacklist_items)
            self._bl_save_timer = _tm
        # Wer gerade tippt, muss beim Ausloesen bekannt sein - `sender()` ist
        # dann der Timer, nicht das Textfeld.
        _w = self.sender()
        if _w is not None and hasattr(_w, "toPlainText"):
            self._bl_last_widget = _w
        _hint = getattr(self, "bl_notice_lbl", None)
        if _hint is not None:
            _hint.setText(t("Changed \u2013 applying it to the build plan \u2026"))
            # Farbe mitsetzen: dasselbe Label traegt nach einer Neuberechnung
            # andere Meldungen mit eigener Farbe (mw_bauplan_fenster).
            _hint.setStyleSheet(f"color:{theme.AMBER}; font-weight:700; "
                                f"padding:2px 0;")
            _hint.setVisible(True)
        _tm.start(500)

    def _save_blacklist_items(self):
        """Blacklist aus dem Feld speichern, das GERADE bearbeitet wurde.

        ES GIBT ZWEI Blacklist-Felder (Einstellungen + Seitenleiste im
        Bauplan), und beide setzen `self.bl_items` - das zuletzt gebaute
        gewinnt. Vorher las diese Methode IMMER `self.bl_items`: wer im
        Bauplan etwas herausnahm, sah die \u00c4nderung im Feld, gespeichert
        wurde aber der ALTE Inhalt des anderen Feldes. Der Nutzer entfernte
        zwei Items und die Warnung blieb trotzdem stehen.
        Dieselbe Fehlerklasse wie `_build_to_chart`, das immer `self.b_table`
        las - jetzt geht der Sender vor.
        """
        w = self.sender()
        if w is None or not hasattr(w, "toPlainText"):
            # Ueber den Timer gerufen (s. _blacklist_verzoegert): dann ist
            # der Sender der Timer. Das zuletzt bearbeitete Feld hat er
            # gemerkt.
            w = getattr(self, "_bl_last_widget", None) or getattr(
                self, "bl_items", None)
        if w is None:
            return
        names = [ln.strip() for ln in w.toPlainText().splitlines() if ln.strip()]
        self.settings["bau_blacklist_names"] = names
        config.save_settings(self.settings)
        # Das jeweils ANDERE Feld nachziehen, damit beide dasselbe zeigen.
        for _other in (getattr(self, "_bl_widgets", None) or []):
            if _other is w:
                continue
            try:
                _other.blockSignals(True)
                _other.setPlainText("\n".join(names))
            except RuntimeError:
                pass
            finally:
                try:
                    _other.blockSignals(False)
                except RuntimeError:
                    pass
        # AUSSCHLUESSE NEU RECHNEN UND NEU AUFBAUEN (Sitzung 19).
        #
        # DAS WAR DIE EIGENTLICHE URSACHE. `rebuild()` - also der Knopf "Neu
        # berechnen" - rechnet `excluded`/`never_build` NICHT neu, es nutzt
        # nur das gecachte `self._bd_opts`. Fuer die Checkboxen in "Meine
        # Blueprints" gibt es deshalb `_bau_refresh_exclusions_and_rebuild`;
        # das Blacklist-TEXTFELD rief sie nie. Folge: eine Blacklist-Zeile
        # wirkte erst nach Schliessen und Neuoeffnen des Bauplans.
        #
        # Das erklaert BEIDE Beobachtungen des Nutzers (Sitzung 19): dass
        # drei von vier Namen "nicht matchen" (sie kamen nach dem Oeffnen
        # dazu, nur der vierte stand beim Oeffnen schon drin), und dass ein
        # geleertes Feld nichts aendert ("es scheint nur beim neuoeffnen des
        # plans oder esi abruf zu wechseln").
        #
        # Sicher an dieser Stelle, weil das Speichern seit dieser Sitzung
        # verzoegert laeuft: der Rebuild kommt einmal, 500 ms nach dem
        # letzten Tastendruck - nicht je Buchstabe.
        self._bau_refresh_exclusions_and_rebuild()

    def _bau_cant_build(self, ids, groups, reaction_products, names=None, type_id=None,
                        recipes=None):
        """Items, deren Blaupausen-Kategorie du NICHT besitzt → müssen gekauft werden
        (kann ich nicht bauen). Populiert opts['never_build']. Nicht-baubare
        Kategorien (z. B. Unrefined Minerals) werden IMMER gekauft, egal was in
        „Meine Blueprints“ steht -- Minerals baut man nicht, die miniert/kauft man."""
        allkeys = set(k for k, _ in self._BLACKLIST_CATS)
        # Pro-Bauplan (self._bd_owned_bp), nicht mehr global - siehe
        # _build_bp_ownership_panel/_save_owned_bp für denselben Wechsel.
        owned = getattr(self, "_bd_owned_bp", None)
        owned = set(owned) if owned is not None else set(
            k for k, _ in self._OWNED_BP_CATS)
        catmap = industry.item_category_map() or {}
        # REAKTIONEN NACH REZEPTSTUFE, NICHT NACH KATEGORIENAME (Nutzer,
        # Sitzung 14: "der runplaner zeigt immer dasselbe egal was man in der
        # Fertigungsschleife ankreuzt").
        #
        # WARUM: die Kategorien MISCHEN Rezeptstufen - mit seinen echten
        # Daten gemessen (`pruefe_stufen_vs_kategorien.py`):
        #   intermediate_reactions  24 x Stufe 1 / 17 x Stufe 2
        #   biochemical_reactions   16 / 16
        #   molecular_reactions      4 / 8
        # Ausgerechnet die Kategorie, die "Intermediate" heisst, liegt selbst
        # nicht auf einer Stufe. Ein Kategorie-Haken kann deshalb NIE "ab
        # Stufe X baue ich selbst" bedeuten - egal wie man die Tiefenstufen
        # zusammenstellt. Gemessene Folge: bei 27 von 36 baubaren Boostern
        # baute "Ab Composite" trotzdem Stufe-1-Reaktionen (76 Faelle), bei
        # Schiffen/Modulen 32 weitere.
        #
        # DIE REGEL: `reaction_stage_map` leitet die Stufe aus der ECHTEN
        # Rezeptkette ab (Stufe 1 = das Produkt wird selbst wieder in einer
        # Reaktion verbraucht, Stufe 2 = es geht direkt in den Bau). Genau so
        # bildet der Runplaner auch seine Stufen - damit sagen Filter und
        # Anzeige endlich dasselbe.
        #
        # NUR FUER REAKTIONSPRODUKTE. Komponenten, Tools und Fuel Blocks
        # laufen unveraendert ueber die Kategorien - insbesondere bleibt die
        # bewusste Fuel-Block-Setzung unangetastet (Nutzer: "wir haben damals
        # fuel blocks extra auf stufe 1 gemacht weil man die fuer reactions
        # braucht"). Sie sind gar keine Reaktionen und tauchen in der
        # Stufenkarte nicht auf.
        #
        # AN 550 ECHTEN PLAENEN GEMESSEN (36 Booster, 114 Implantate, 400
        # Schiffe/Module): alle 108 Fehlfaelle verschwinden, die
        # Stufe-2-Reaktionen bleiben vollstaendig erhalten (19 bzw. 623), und
        # KEIN Plan baut etwas zusaetzlich, das vorher gekauft wurde.
        try:
            _stufen_map = industry.reaction_stage_map(recipes) if recipes else {}
        except Exception as _st_err:
            # Faellt die Stufenkarte aus, gilt die alte Kategorie-Regel
            # weiter - lieber ungenau als gar kein Filter. Aber NICHT still:
            # ein `except: pass` hat in dieser Sitzung schon einmal verdeckt,
            # dass eine Liste unvollstaendig blieb.
            # de_scan4: aus - Beschriftung fuer fehler.log, nicht Oberflaeche
            self._log_exception("Fertigungstiefe: Reaktionsstufen", str(_st_err))
            # de_scan4: an
            _stufen_map = {}
        cant = set()
        _enden = self._bd_enden(type_id, recipes)   # Buendel: Enden nie ausschliessen
        for tid in ids:
            if tid in _enden:
                continue
            info = catmap.get(tid)
            cat = info[0] if info else None
            meta = info[2] if info else None
            # "ist das eine Reaktion?" NICHT nur über reaction_products prüfen
            # (kann bei manchen Items eine Lücke haben, z.B. tiefer verschachtelte
            # Composite-/Intermediate-Materialien wie "Phenolic Composites") -
            # zusätzlich über product_to_bp's Aktivität gegenchecken, sonst
            # rutscht so ein Item an der Kategorisierung vorbei und bleibt
            # trotz abgehakter "Meine Blueprints"-Reaktionskategorien "besessen".
            is_react = tid in reaction_products
            if not is_react and recipes is not None:
                bp = recipes.product_to_bp.get(tid)
                if bp and bp[1] == industry.REACTION:
                    is_react = True
            key = self._category_key(tid, groups.get(tid, ""), is_react, cat, meta)
            # Nicht-baubare Kategorie -> immer kaufen. Sonst: kaufen, wenn nicht besessen.
            if key in self._NON_BUILDABLE_CATS:
                cant.add(tid)
                continue
            _st = _stufen_map.get(tid)
            if _st is not None:
                # REAKTIONSPRODUKT: die REZEPTSTUFE bestimmt, welches
                # Haekchen zustaendig ist - Stufe 1 (Produkt geht in eine
                # weitere Reaktion) haengt an "intermediate_reactions",
                # Stufe 2 (geht direkt in den Bau) an
                # "composite_reactions". Das deckt jede
                # Haekchen-Kombination ab, nicht nur die vier
                # Voreinstellungen der Fertigungstiefe.
                _schl = ("intermediate_reactions" if _st == 1
                         else "composite_reactions")
                if _schl not in owned:
                    cant.add(tid)
            elif key in allkeys and key not in owned:
                cant.add(tid)
        return cant

    def _build_invention_purchase_panel(self):
        """Zwei Checkboxen im selben Stil wie 'Meine Blueprints': steuern, ob
        die im Invention-Tab ermittelten Datacores/Decryptoren beim Klick auf
        'Einkaufswagen' mit in die Einkaufsliste wandern. Menge kommt aus der
        aktuell angezeigten Versuchszahl je Item (self._bd_invention_needs,
        von _fill_invention_tab live gepflegt)."""
        from PySide6.QtWidgets import QCheckBox
        panel = QWidget()
        # SEIT 26.09.2026 (Nutzer) EINMAL in der Seitenleiste des Invention-
        # Reiters, Karte "Buy or not?" ganz oben - nicht mehr je Karte.
        pv = QVBoxLayout(panel); pv.setContentsMargins(4, 2, 4, 2); pv.setSpacing(4)
        # ETWAS GROESSER (Nutzer, Sitzung 20) - sie stehen jetzt mitten im
        # Invention-Reiter und sollen nicht wie eine Fussnote wirken.
        _kb_stil = "QCheckBox{font-size:13px; font-weight:700;}"
        dc_cb = QCheckBox(t("Buy datacores"))
        dc_cb.setStyleSheet(_kb_stil)
        dc_cb.setChecked(bool(self.settings.get("bau_buy_datacores", True)))
        dc_cb.setToolTip(
            t("Ticked = the datacore quantities worked out in the Invention tab (at "
              "the number of attempts shown there) go into the shopping list when you "
              "click \u201eShopping list\u201c below."))

        def _save_dc(v):
            self.settings["bau_buy_datacores"] = bool(v)
            config.save_settings(self.settings)
        dc_cb.toggled.connect(_save_dc)
        pv.addWidget(dc_cb)
        dcy_cb = QCheckBox(t("Buy decryptors"))
        dcy_cb.setStyleSheet(_kb_stil)
        dcy_cb.setChecked(bool(self.settings.get("bau_buy_decryptors", True)))
        dcy_cb.setToolTip(
            t("Ticked = the decryptor quantities worked out in the Invention tab go "
              "into the shopping list when you click \u201eShopping list\u201c below (not with "
              "\u201eNo decryptor\u201c)."))

        def _save_dcy(v):
            self.settings["bau_buy_decryptors"] = bool(v)
            config.save_settings(self.settings)
        dcy_cb.toggled.connect(_save_dcy)
        pv.addWidget(dcy_cb)
        # KEIN addStretch mehr: in der Seitenleiste zog er die Karte "Buy or
        # not?" in die Hoehe (Leerraum bis zum naechsten Knopf, gerendert).
        return panel

    # Repräsentative Item-Namen je Kategorie, um ein echtes, großes EVE-Icon
    # zu zeigen (statt nur Text) - kein exakter Vertreter, nur ein bekanntes
    # Beispiel-Item aus der jeweiligen SDE-Gruppe. Wird per Name nachgeschlagen
    # (industry.type_id_for_name) - falls nicht gefunden (z.B. Name-Mismatch,
    # noch nie gescannt), fällt die Karte auf ein großes Emoji zurück.
    _OWNED_BP_CAT_ICON_NAME = {
        "intermediate_reactions": "Titanium Chromide",
        "composite_reactions": "Crystalline Carbonide",
        "hybrid_reactions": "Fulleroferrocene",
        "biochemical_reactions": "Crash Booster",
        "molecular_reactions": "Meta-Operant Neurolink Enhancer",
        "reactions": "Mechanical Parts",
        "advanced_components": "Nanoelectrical Microprocessor",
        "capital_components": "Capital Armor Plate",
        "advanced_capital_components": "Capital Nanoelectrical Microprocessor",
        "hybrid_components": "Hybrid Polymer Nanotube Composite",
        "t1_hulls": "Rifter",
        "fuel_blocks": "Nitrogen Fuel Block",
        "tools": "R.A.M.- Robotics",
    }
    # RUECKFALL-SYMBOL je Kategorie, wenn kein Item-Bild vorliegt. Seit
    # Sitzung 16 aus dem eigenen Set statt Emoji - sonst sieht die Liste je
    # nach Betriebssystem-Font anders aus.
    _OWNED_BP_CAT_SYMBOL = {
        "intermediate_reactions": "flask", "composite_reactions": "flask",
        "hybrid_reactions": "flask", "biochemical_reactions": "flask",
        "molecular_reactions": "flask", "reactions": "flask",
        "advanced_components": "wrench", "capital_components": "wrench",
        "advanced_capital_components": "wrench", "hybrid_components": "wrench",
        "t1_hulls": "factory", "fuel_blocks": "package", "tools": "hammer",
    }

    # FERTIGUNGSTIEFE (Nutzer): "ab wann will ich bauen?". Die 14
    # Kategorie-Haken SIND der Tiefenschalter - hier nur die Uebersetzung in
    # die Frage, die man tatsaechlich stellt. KEINE zweite Rechenlogik.
    # ENGLISCH als Schluessel, t() beim Anzeigen (Sitzung 16).
    _DEPTH_LEVELS = [
        ("nur_endprodukt", "End product only",
         set(),
         "All components AND reactions are bought. Little effort, smallest "
         "margin."),
        ("ab_komponenten", "From components",
         {"advanced_components", "capital_components",
          "advanced_capital_components", "hybrid_components", "t1_hulls",
          "tools"},
         "You build components and tools (incl. R.A.M.) yourself, you buy all "
         "reactions and fuel blocks."),
        ("ab_composite", "From composite reactions",
         {"advanced_components", "capital_components",
          "advanced_capital_components", "hybrid_components", "t1_hulls",
          "tools", "fuel_blocks", "composite_reactions", "hybrid_reactions",
          "biochemical_reactions", "molecular_reactions",
          "unrefined_reactions", "reactions"},
         "Composite reactions and fuel blocks yourself as well. You only buy "
         "the intermediate reactions."),
        # NAME (Nutzer 26.09.2026: "'Everything yourself' ist eigentlich
        # die falsche Namensgebung, es muesste heissen From intermediate
        # Reactions"). Nachgemessen: diese Stufe unterscheidet sich von
        # "From composite reactions" genau um intermediate_reactions - der
        # Name sagt jetzt, AB WELCHER Stufe gebaut wird, wie die anderen.
        ("alles_selbst", "From intermediate reactions",
         None,                       # None = ALLE Kategorien
         "The complete chain from the intermediate reactions to the end "
         "product. Largest margin, most work."),
    ]

    def _depth_keys(self, level_key):
        """Kategorie-Schluessel einer Tiefenstufe (None = alle)."""
        _all = {k for k, _ in self._OWNED_BP_CATS}
        for key, _lbl, keys, _tip in self._DEPTH_LEVELS:
            if key == level_key:
                return set(_all) if keys is None else (set(keys) & _all)
        return set(_all)

    def _depth_of(self, owned):
        """Welche Stufe entspricht dieser Haken-Menge? None = eigene Auswahl."""
        _o = set(owned or ())
        for key, _lbl, _keys, _tip in self._DEPTH_LEVELS:
            if self._depth_keys(key) == _o:
                return key
        return None

    def _build_depth_panel(self):
        """Panel \u201eFertigungstiefe\u201c \u2013 setzt die vorhandenen Kategorie-Haken."""
        from PySide6.QtWidgets import QRadioButton, QButtonGroup
        w = QWidget()
        v = QVBoxLayout(w); v.setContentsMargins(8, 6, 8, 6); v.setSpacing(4)
        hint = QLabel(t("From which stage do you build yourself?"))
        hint.setObjectName("Muted"); hint.setWordWrap(True)
        v.addWidget(hint)
        self._depth_group = QButtonGroup(w)
        self._depth_btns = {}
        _cur = self._depth_of(getattr(self, "_bd_owned_bp", None)
                              if getattr(self, "_bd_owned_bp", None) is not None
                              else {k for k, _ in self._OWNED_BP_CATS})
        # SICHTBARKEIT: der ausgewaehlte Knopf ging im dunklen Hintergrund
        # unter - man sah nicht, welche Stufe aktiv ist (Nutzer-Meldung).
        # Deshalb ein eigener Indikator mit Rahmen, gefuellt in Cyan, plus
        # farbige Beschriftung fuer die aktive Stufe.
        _rb_css = (
            "QRadioButton{padding:2px 0;}"
            f"QRadioButton::indicator{{width:13px; height:13px; "
            f"border-radius:7px; border:2px solid {theme.MUTED};}}"
            f"QRadioButton::indicator:checked{{border:2px solid {theme.CYAN}; "
            f"background:{theme.CYAN};}}"
            f"QRadioButton:checked{{color:{theme.CYAN}; font-weight:700;}}")
        for key, lbl, _keys, tip in self._DEPTH_LEVELS:
            rb = QRadioButton(t(lbl))
            rb.setStyleSheet(_rb_css)
            rb.setToolTip(t(tip))
            rb.setChecked(key == _cur)
            self._depth_group.addButton(rb)
            self._depth_btns[key] = rb
            v.addWidget(rb)
            rb.toggled.connect(
                lambda checked, _k=key: self._apply_depth(_k) if checked else None)
        self._depth_custom_lbl = QLabel(t("\u2022 Own selection"))
        self._depth_custom_lbl.setStyleSheet(f"color:{theme.AMBER};")
        self._depth_custom_lbl.setVisible(_cur is None)
        v.addWidget(self._depth_custom_lbl)
        # KOSTEN JE STUFE: gefuellt, sobald eine Stufe einmal gerechnet wurde.
        # Bewusst KEIN Vorab-Durchrechnen aller vier Stufen - das waere vier
        # volle Plan-Laeufe bei jedem Oeffnen. Wer durchklickt, sieht die
        # Zahlen nebeneinander wachsen, und die guenstigste wird markiert.
        self._depth_cost_lbl = QLabel("")
        self._depth_cost_lbl.setObjectName("Muted")
        self._depth_cost_lbl.setWordWrap(True)
        self._depth_cost_lbl.setStyleSheet("font-size:11px;")
        v.addWidget(self._depth_cost_lbl)
        self._depth_costs = getattr(self, "_depth_costs", {})
        self._render_depth_costs()
        return w

    def _render_depth_costs(self):
        """Bisher gerechnete Baukosten je Stufe anzeigen, guenstigste fett."""
        lbl = getattr(self, "_depth_cost_lbl", None)
        if lbl is None:
            return
        costs = getattr(self, "_depth_costs", {}) or {}
        if not costs:
            lbl.setText(t("Build cost per stage appears here once you have "
                          "calculated a stage."))
            return
        best = min(costs.values())
        rows = []
        # Buendel: Menge 1 -> "je Stueck" ist die Summe aller Enden (Nutzer
        # 26.09.2026, dieselbe Frage wie bei der Karte "Build cost").
        _einheit = (t(" ISK, bundle total")
                    if int(getattr(self, "_bd_type", 0) or 0) == industry.BUENDEL_ID
                    else t(" ISK/unit"))
        if len(costs) == 1:
            lbl.setText(t("Only this stage is calculated \u2013 click the others "
                          "to compare.<br>")
                        + next(iter(
                            f"<b style='color:{theme.GREEN}'>"
                            f"{[n for k, n, _a, _b in self._DEPTH_LEVELS if k == _k][0]}: "
                            + f"{_v:,.0f}".replace(",", "'") + _einheit + "</b>"
                            for _k, _v in costs.items())))
            return
        for key, name, _k, _t in self._DEPTH_LEVELS:
            if key not in costs:
                continue
            _v = costs[key]
            _txt = f"{_v:,.0f}".replace(",", "'") + _einheit
            _d = _v - best
            _extra = ("" if _d <= 0 else
                      "  (+" + f"{_d:,.0f}".replace(",", "'") + ")")
            rows.append(
                (f"<b style='color:{theme.GREEN}'>{name}: {_txt}</b>"
                 if _v == best else f"{name}: {_txt}{_extra}"))
        lbl.setText("<br>".join(rows))

    def _depth_fingerprint(self):
        """Alles, was die Baukosten AUSSER der Fertigungstiefe beeinflusst.

        Ohne diesen Abgleich stehen in der Liste Äpfel neben Birnen: der
        Nutzer sah „Nur das Endprodukt: 41'087'474“ und später
        „33'688'400“ fuer DIESELBE Stufe - dazwischen hatte er zwei Items
        auf die Blacklist gesetzt. Die alten Werte blieben stehen und liessen
        die Stufen falsch aussehen.
        """
        return (
            int(getattr(self, "_bd_qty", 0) or 0),
            tuple(sorted(str(x).strip().lower() for x in
                         (self.settings.get("bau_blacklist_names", []) or []))),
            bool(getattr(self, "_bd_force", False)),
            bool(getattr(self, "_bd_prefer_owned", False)),
            bool(getattr(self, "_bd_frozen", False)),
            str(getattr(self, "_bd_sell_hub", "")),
            int(getattr(self, "_bd_me", 0) or 0),
            int(getattr(self, "_bd_te", 0) or 0),
        )

    def _note_depth_cost(self, cost_per_unit):
        """Baukosten der AKTUELL eingestellten Stufe merken.

        Verwirft alle bisherigen Werte, sobald sich SONST etwas geaendert hat
        (s. _depth_fingerprint) - sonst vergleicht man Zahlen aus
        verschiedenen Welten.
        """
        _cur = self._depth_of(getattr(self, "_bd_owned_bp", None))
        if _cur is None or not cost_per_unit or cost_per_unit <= 0:
            return
        _fp = self._depth_fingerprint()
        if getattr(self, "_depth_fp", None) != _fp:
            self._depth_costs = {}
            self._depth_fp = _fp
        if not hasattr(self, "_depth_costs"):
            self._depth_costs = {}
        self._depth_costs[_cur] = float(cost_per_unit)
        self._render_depth_costs()

    def _apply_depth(self, level_key):
        """Stufe auf die vorhandenen Kategorie-Haken uebertragen."""
        want = self._depth_keys(level_key)
        boxes = getattr(self, "_bp_own_boxes", None) or {}
        if not boxes:
            return
        for k, cb in boxes.items():
            cb.blockSignals(True)
            cb.setChecked(k in want)
            cb.blockSignals(False)
        self._save_owned_bp()
        if getattr(self, "_depth_custom_lbl", None) is not None:
            self._depth_custom_lbl.setVisible(False)
        _fn = getattr(self, "_bd_full_rebuild", None)
        if _fn is not None:
            _fn()

    def _sync_depth_panel(self):
        """Nach einer Einzelhaken-\u00c4nderung die Stufe nachziehen (oder
        \u201eEigene Auswahl\u201c zeigen)."""
        _cur = self._depth_of(getattr(self, "_bd_owned_bp", None))
        for k, rb in (getattr(self, "_depth_btns", None) or {}).items():
            rb.blockSignals(True)
            rb.setChecked(k == _cur)
            rb.blockSignals(False)
        if getattr(self, "_depth_custom_lbl", None) is not None:
            self._depth_custom_lbl.setVisible(_cur is None)

    def _build_bp_ownership_panel(self, with_head=True):
        from PySide6.QtWidgets import QCheckBox
        panel = QWidget()
        pv = QVBoxLayout(panel); pv.setContentsMargins(10, 4, 6, 4); pv.setSpacing(3)
        if with_head:
            head = QLabel(" " + t("Build or buy?"))
            head.setStyleSheet(f"color:{theme.CYAN}; font-weight:600;")
            pv.addWidget(head)
        allkeys = [k for k, _ in self._OWNED_BP_CATS]
        # Pro-Bauplan gespeichert (self._bd_owned_bp), NICHT mehr global -
        # sonst hätte ein Abhaken in EINEM Bauplan alle anderen (auch zukünftige)
        # Baupläne mit betroffen. Standard = alles angehakt ("ich besitze/baue
        # alles"), sofern für DIESEN Bauplan noch nichts abweichend gespeichert
        # wurde (frischer Bauplan oder alter Spielstand ohne per-Plan-Daten).
        owned = getattr(self, "_bd_owned_bp", None)
        owned = set(owned) if owned is not None else set(allkeys)
        self._bp_own_boxes = {}
        for key, label in self._OWNED_BP_CATS:
            row = QHBoxLayout(); row.setSpacing(6)
            icon_lbl = QLabel(); icon_lbl.setFixedSize(20, 20)
            icon_lbl.setAlignment(Qt.AlignCenter)
            _icon_name = self._OWNED_BP_CAT_ICON_NAME.get(key)
            _pix = None
            if _icon_name:
                _tid = industry.type_id_for_name(_icon_name)
                if _tid:
                    _pix = self._item_pixmap(_tid, size=20)
            if _pix and not _pix.isNull():
                icon_lbl.setPixmap(self._pixmap_im_rahmen(_pix, 20))
            else:
                icon_lbl.setPixmap(icons.pixmap(
                    self._OWNED_BP_CAT_SYMBOL.get(key, "package"), groesse=18))
            row.addWidget(icon_lbl)
            cb = QCheckBox(t(label)); cb.setChecked(key in owned)
            cb.setToolTip(
                t("Ticked = I have it (can build). Not ticked = will be bought "
                  "(no blueprint). Then \u201eRecalculate\u201c.\n"
                  "Do I have this blueprint(s)? ") + t(self._BLACKLIST_TIPS.get(key, "")))
            cb.toggled.connect(self._save_owned_bp)
            # Stufe nachziehen: wer ein Einzelhaken aendert, bekommt
            # "Eigene Auswahl" statt einer falsch angezeigten Stufe.
            cb.toggled.connect(lambda *_a: self._sync_depth_panel())
            self._bp_own_boxes[key] = cb
            row.addWidget(cb, 1)
            pv.addLayout(row)
        pv.addStretch()
        return panel

    def _bau_refresh_exclusions_and_rebuild(self):
        """Berechnet never_build/excluded (aus "Meine Blueprints"/Blacklist) neu
        und stößt einen Rebuild an - für den Fall, dass diese Checkboxen
        innerhalb eines BEREITS offenen Bauplan-Dialogs geändert werden.
        rebuild() (bei "Neu berechnen") berechnet diese Ausschlüsse NICHT neu,
        nutzt nur das gecachte self._bd_opts - ohne diesen Schritt hätte ein
        Checkbox-Klick erst nach Schließen+Neuöffnen des Dialogs eine Wirkung
        gehabt (weder auf Rezept-Struktur noch auf den Runplaner)."""
        recipes = getattr(self, "_bd_recipes", None)
        ids = getattr(self, "_bd_all_ids", None)
        groups = getattr(self, "_bd_groups_cache", None)
        bl_names = getattr(self, "_bd_bl_names_cache", None)
        opts = getattr(self, "_bd_opts", None)
        type_id = getattr(self, "_bd_bp_type", None)
        if not (recipes and ids and groups is not None and bl_names is not None
               and opts is not None):
            return   # Bauplan noch nicht (fertig) berechnet - nichts zu tun
        opts["excluded"] = self._bau_never_build(list(ids), groups,
                                                 recipes.reaction_products, bl_names)
        # AUCH HIER MERKEN (Nutzer-Befund, Sitzung 20: nach einem
        # Gruppen-Haekchen stand in der Rezept-Struktur weiter "vorhanden").
        # Von den drei Stellen, die `excluded` setzen, fuellte nur EINE
        # `_bd_excluded_ids` - und genau dieser Weg laeuft, wenn man ein
        # Haekchen setzt. Die Rechnung stimmte, die Zeile log.
        self._bd_excluded_ids = set(opts["excluded"])
        opts["never_build"] = self._bau_cant_build(list(ids), groups,
                                                    recipes.reaction_products, bl_names,
                                                    type_id, recipes=recipes)
        cb = getattr(self, "_bd_full_rebuild", None)
        if cb:
            cb()

    def _save_owned_bp(self):
        if not hasattr(self, "_bp_own_boxes"):
            return
        self._bd_owned_bp = [k for k, cb in self._bp_own_boxes.items()
                             if cb.isChecked()]
        self._bau_refresh_exclusions_and_rebuild()


    def _char_implant_mfg_mult(self, cid):
        """Fertigungszeit-Multiplikator (<1) aus dem gewählten/erkannten
        Implantat dieses Charakters (Zainou 'Beancounter' Industry BX-80X).
        1.0 (kein Effekt), wenn kein Implantat gesetzt ist oder die SDE die
        Boni (noch) nicht kennt."""
        tid = (self.settings.get("bau_char_implant", {}) or {}).get(str(cid))
        if not tid:
            return 1.0
        bonuses = getattr(self, "_implant_bonus_cache", None)
        if bonuses is None:
            bonuses = self._implant_bonus_cache = industry.load_implant_time_bonuses()
        try:
            info = bonuses.get(int(tid))
        except (TypeError, ValueError):
            info = None
        if not info or info.get("activity") != "manufacturing":
            return 1.0
        return max(0.5, 1.0 - abs(float(info.get("pct", 0) or 0)) / 100.0)

    def _build_char_roles_widget(self):
        w = QWidget()
        self._char_roles_layout = QVBoxLayout(w)
        self._char_roles_layout.setContentsMargins(6, 4, 6, 4)
        self._char_roles_layout.setSpacing(6)
        self._populate_char_roles()
        return w

    @staticmethod
    def _leere_layout(lay):
        """Ein Layout VOLLSTAENDIG leeren - Widgets UND Unter-Layouts.

        Qt gibt bei `takeAt` ein QLayoutItem zurueck; `item.widget()` ist nur
        dann gesetzt, wenn das Element ein Widget ist. Bei einem
        eingehaengten Unter-Layout (`addLayout(...)`) ist es None - wer nur
        auf `widget()` prueft, nimmt das Unter-Layout zwar aus der
        Anordnung, laesst dessen Knoepfe aber als Kinder des Panels stehen.
        Sie bleiben sichtbar, reagieren aber auf nichts mehr, weil der Code
        laengst mit den neu gebauten Knoepfen arbeitet.
        """
        # Iterativ statt rekursiv: kein `MainWindow.`-Selbstbezug, damit der
        # Block bei einem spaeteren Zerlegungs-Schnitt woertlich umziehen
        # kann (Erfahrung Auftrag E, Sitzung 10).
        stapel = [lay]
        while stapel:
            akt = stapel.pop()
            while akt.count():
                it = akt.takeAt(0)
                wd = it.widget()
                if wd is not None:
                    wd.setParent(None)
                    wd.deleteLater()
                    continue
                sub = it.layout()
                if sub is not None:
                    stapel.append(sub)

    def _reload_char_roles(self):
        """Roster neu aufbauen – z. B. wenn ein Charakter dazukommt/entfernt wird.
        Der Roster lebt jetzt im Bauplan-Dialog (transient); wenn er zu ist, no-op."""
        lay = getattr(self, "_char_roles_layout", None)
        if lay is None:
            return
        try:
            if lay.parent() is None:      # Widget bereits zerstört (Dialog zu)
                self._char_roles_layout = None
                return
            # AUCH UNTER-LAYOUTS LEEREN (Nutzer-Befund Sitzung 11:
            # "ich kann nur 1x Uebernehmen klicken"). Die Knopfzeile haengt
            # als LAYOUT im Panel (`lay.addLayout(btn_row)`), nicht als
            # Widget. `it.widget()` liefert dafuer None - die drei Knoepfe
            # wurden also NIE geloescht, blieben Kinder des Panels und
            # standen nach dem Neuaufbau ein zweites Mal da. Der alte,
            # ausgegraute "Uebernehmen" blieb genau dort liegen, wo der
            # neue hingehoert, und reagierte auf nichts mehr: die Haken
            # schalteten den NEUEN Knopf frei, der Nutzer sah den ALTEN.
            self._leere_layout(lay)
            self._populate_char_roles()
        except RuntimeError:              # C++-Objekt weg
            self._char_roles_layout = None

    # ENGLISCHE KURZNAMEN, t() beim Anzeigen (Sitzung 17).
    _ROSTER_ROLES = [
        ("bau_build_chars", "Build"),
        ("bau_reaction_chars", "React"),
        ("bau_invention_chars", "Inv"),
        ("bau_copy_chars", "Copy"),
    ]
    _ROSTER_ROLE_TIPS = {
        "bau_build_chars": "For building (manufacturing)",
        "bau_reaction_chars": "For reactions",
        "bau_invention_chars": "For invention",
        "bau_copy_chars": "For copying",
    }

    def _populate_char_roles(self):
        from PySide6.QtWidgets import QCheckBox
        lay = self._char_roles_layout
        # GEMERKTEN KNOPF ZUERST VERGESSEN. Sonst zeigt `_char_roles_apply_btn`
        # waehrend des Neuaufbaus auf einen geloeschten Knopf - und wenn die
        # Liste unten leer ist ("Keine Charaktere verknuepft"), bleibt er es
        # dauerhaft, weil die Knopfzeile in dem Zweig gar nicht erst gebaut
        # wird. `_save_build_chars` prueft auf None und laesst ihn dann in
        # Ruhe, statt an einem toten C++-Objekt zu scheitern.
        self._char_roles_apply_btn = None
        # DAUERHINWEIS ENTFERNT (Nutzer-Wunsch Sitzung 12: "ich hasse
        # Infos, die das Tool ueberladen aussehen lassen").
        info = QLabel("")
        info.setVisible(False)
        info.setObjectName("Muted"); info.setWordWrap(True)
        lay.addWidget(info)
        gw = QWidget()
        g = QGridLayout(gw)
        g.setContentsMargins(0, 0, 0, 0)
        g.setHorizontalSpacing(6); g.setVerticalSpacing(4)
        for c, (_key, label) in enumerate(self._ROSTER_ROLES):
            h = QLabel(t(label)); h.setObjectName("Muted"); h.setAlignment(Qt.AlignCenter)
            h.setToolTip(t(self._ROSTER_ROLE_TIPS.get(_key, label)))
            g.addWidget(h, 0, c + 1)
        # SLOT-SPALTE ENTFAELLT (Nutzer: "die Anzahl Slots muss ich nicht
        # sehen, das darf ESI im Hintergrund machen"). Die Zahlen werden
        # weiterhin per ESI geholt und vom Runplaner benutzt - sie brauchen
        # nur keine eigene Spalte, die die Tabelle so breit macht, dass man
        # scrollen muss. Der Wert steht jetzt im Tooltip des Charakternamens,
        # ist also nicht verloren (Arbeitsregel 6).
        col_implant = len(self._ROSTER_ROLES) + 1
        hi = QLabel(t("Implant")); hi.setObjectName("Muted")
        hi.setToolTip(t("Manufacturing time implant (Zainou 'Beancounter' Industry BX-80X). "
                        "Detected automatically via ESI (button below) or chosen by hand."))
        g.addWidget(hi, 0, col_implant)
        chars = store.list_characters()
        slots_map = self.settings.get("bau_char_slots", {}) or {}

        def _slot_sum(ch):
            sl = slots_map.get(str(ch["character_id"]))
            return sum(sl) if sl else -1
        chars = sorted(chars, key=lambda c: (-_slot_sum(c),
                                             (c.get("character_name") or "").lower()))
        sels = {key: set(self.settings.get(key, []) or []) for key, _l in self._ROSTER_ROLES}
        # HINWEIS NUR, WENN ETWAS FEHLT (Nutzer, Sitzung 12: "ich hasse Infos,
        # die das Tool ueberladen aussehen lassen"). Ein Charakter ohne jede
        # Rolle baut nichts, seine Slots zaehlen nicht - und im Bild sieht er
        # aus wie die anderen. Deshalb wird er BENANNT statt still uebergangen.
        _ohne_rolle = [c for c in chars
                       if not any(int(c["character_id"]) in sels[_k]
                                  for _k, _l in self._ROSTER_ROLES)]
        if _ohne_rolle:
            info.setText(t("{n} linked character(s) have no role at all \u2013 they "
                           "build nothing and their slots do not count.")
                         .format(n=len(_ohne_rolle)))
            info.setObjectName("")
            info.setStyleSheet(f"color:{theme.AMBER};")
            info.setVisible(True)
        self._char_role_boxes = {}     # (cid, role_key) -> checkbox
        self._char_slot_labels = {}
        self._char_implant_combos = {}     # cid -> QComboBox
        implant_options = industry.load_implant_time_bonuses()   # {type_id: {...}}
        implant_by_activity = [(tid, info) for tid, info in implant_options.items()
                               if info.get("activity") == "manufacturing"]
        if not chars:
            g.addWidget(QLabel(t(
                "No characters linked – add them in the Characters tab.")), 1, 0, 1, col_implant + 1)
            lay.addWidget(gw)
            return
        char_implants = self.settings.get("bau_char_implant", {}) or {}
        for r, ch in enumerate(chars):
            cid = ch["character_id"]
            nm = ch.get("character_name") or ch.get("name") or str(cid)
            nm_lbl = QLabel(nm); nm_lbl.setMaximumWidth(140)
            nm_lbl.setToolTip(nm)
            # NAME ANKLICKBAR (Nutzer-Wunsch Sitzung 11: "wenn man auf den
            # Charakternamen klickt, dass sich alle Haken setzen oder
            # entfernen von diesem Charakter"). Ein QLabel hat kein
            # clicked-Signal - statt einer eigenen Klasse haengen wir den
            # Klick direkt an dieses eine Etikett. Der Zeigefinger-Cursor
            # macht sichtbar, dass da etwas geht.
            nm_lbl.setCursor(Qt.PointingHandCursor)
            nm_lbl.mousePressEvent = (
                lambda _ev, _cid=cid: self._toggle_char_alle_rollen(_cid))
            g.addWidget(nm_lbl, r + 1, 0)
            for c, (key, _l) in enumerate(self._ROSTER_ROLES):
                cb = QCheckBox(); cb.setChecked(cid in sels[key])
                cb.toggled.connect(self._save_build_chars)
                self._char_role_boxes[(cid, key)] = cb
                g.addWidget(cb, r + 1, c + 1, alignment=Qt.AlignCenter)
            # Label bleibt bestehen (der ESI-Ladevorgang schreibt hinein,
            # _char_slot_labels wird an mehreren Stellen benutzt) - es haengt
            # nur nicht mehr im Raster. Stattdessen wandert der Text in den
            # Tooltip der Namenszelle: sichtbar auf Nachfrage, kostet aber
            # keine Spaltenbreite.
            sl = QLabel(self._slot_text(cid)); sl.setObjectName("Muted")
            sl.setStyleSheet("font-size:11px;")
            sl.setVisible(False)
            self._char_slot_labels[cid] = sl
            nm_lbl.setToolTip(
                t("{name}\nCLICK the name: set all four roles of this character "
                  "at once \u2013 and remove them again on the next click.\n"
                  "Parallel job slots from the skills: {slots}\n"
                  "(Mfg. = manufacturing / Mass Production, "
                  "React. = reactions / Mass Reactions)").format(
                    name=nm, slots=self._slot_text(cid)))
            # REPROCESSING-SKILLS NUR IM TOOLTIP (1.0.9, Nutzer 17.09.2026:
            # "das reprocessen macht man mit einem Klick nur mit einem
            # Charakter" - keine Spalte, keine Rolle; der Runplaner waehlt
            # spaeter selbst). Sichtbar erst, wenn Skills geladen sind UND
            # die SDE die Skill-IDs geliefert hat - sonst keine Zeile.
            _rz = self._reproc_skill_zeile(cid)
            if _rz:
                nm_lbl.setToolTip(nm_lbl.toolTip() + "\n" + _rz)
            imp_combo = QComboBox()
            imp_combo.setMaximumWidth(260)
            imp_combo.addItem(t("No implant"), None)
            for tid, info in sorted(implant_by_activity, key=lambda x: x[1].get("pct", 0)):
                imp_combo.addItem(f"{info.get('name', tid)} (\u2212{abs(info.get('pct', 0)):.0f}%)",
                                  tid)
            cur_tid = char_implants.get(str(cid))
            self._combo_select(imp_combo, cur_tid) if cur_tid else None
            imp_combo.currentIndexChanged.connect(self._save_char_implants)
            self._char_implant_combos[cid] = imp_combo
            g.addWidget(imp_combo, r + 1, col_implant)
        lay.addWidget(gw)
        from PySide6.QtWidgets import QPushButton
        btn = QPushButton(" " + t("Load skills"))
        btn.setToolTip(t("Fetches the manufacturing/reaction skills of every character from ESI "
                         "and shows the parallel job slots (for the run planner)."))
        btn.clicked.connect(self._load_char_slots)
        # Kompakter (Nutzer: "die Buttons unten etwas kleiner machen") - beide
        # nur so breit wie ihr Text, damit die Zeile nicht die Panelbreite
        # bestimmt. "→ Job-Slots" bzw. "(ESI)" stehen jetzt im Tooltip.
        for _b in (btn,):
            _b.setStyleSheet("padding:4px 10px; font-size:11px;")
        btn_row = QHBoxLayout()
        btn_row.setSpacing(6)
        btn_row.addWidget(btn)
        imp_btn = QPushButton(" " + t("Load implants"))
        imp_btn.setIcon(icons.icon("trend_up"))
        imp_btn.setToolTip(t("Detects automatically which of the plugged-in implants are "
                             "manufacturing time bonus implants (Zainou 'Beancounter' Industry "
                             "BX-80X). Needs the implant scope (Settings \u2192 'Implant manufacturing "
                             "bonus' \u2192 On + relink)."))
        imp_btn.clicked.connect(self._load_char_implants)
        imp_btn.setStyleSheet("padding:4px 10px; font-size:11px;")
        btn_row.addWidget(imp_btn)
        # UEBERNEHMEN (Nutzer-Ansage Sitzung 10): erst hier wird gerechnet.
        # Ausgegraut, solange es nichts zu uebernehmen gibt - so ist auf
        # einen Blick sichtbar, ob noch eine Aenderung aussteht, statt dass
        # man raten muss, ob der Runplaner schon die neue Auswahl zeigt.
        _app_btn = QPushButton(t("✓ Apply"))
        _app_btn.setIcon(icons.icon("check"))
        _app_btn.setToolTip(t("Recalculates the run planner with the changed character selection.\n"
                              "The selection itself is already saved \u2013 the calculation only happens "
                              "here, so the tool does not recalculate on every click while you change "
                              "several ticks."))
        _app_btn.setStyleSheet("padding:4px 10px; font-size:11px;")
        _app_btn.clicked.connect(self._apply_build_chars)
        _app_btn.setEnabled(bool(getattr(self, "_char_roles_dirty", False)))
        self._char_roles_apply_btn = _app_btn
        if _ohne_rolle:
            _all_btn = QPushButton(t("Tick all"))
            _all_btn.setIcon(icons.icon("check"))
            _all_btn.setToolTip(t("Sets all four roles for every linked character. "
                                  "You can untick individual ones again afterwards."))
            _all_btn.setStyleSheet("padding:4px 10px; font-size:11px;")
            _all_btn.clicked.connect(self._bau_rollen_alle_anhaken)
            btn_row.addWidget(_all_btn)
        btn_row.addWidget(_app_btn)
        btn_row.addStretch()
        lay.addLayout(btn_row)

    def _reproc_skill_zeile(self, cid):
        """Tooltip-Zeile "Reprocessing skills: R / Efficiency E" fuer einen
        Charakter - oder "" wenn seine Skills nie geladen wurden oder die
        SDE die Skill-IDs (noch) nicht kennt. Nichts wird geraten: ohne ID
        keine Zeile."""
        ids = industry.reprocess_skill_ids()
        rid, eid = ids.get("Reprocessing"), ids.get("Reprocessing Efficiency")
        sk = (self.settings.get("bau_char_skills", {}) or {}).get(str(cid))
        if not sk or not rid or not eid:
            return ""
        try:
            sk = {int(k): int(v) for k, v in sk.items()}   # nach JSON sind Schluessel str
        except (TypeError, ValueError):
            return ""
        return t("Reprocessing skills: {r} / Efficiency {e}").format(
            r=sk.get(int(rid), 0), e=sk.get(int(eid), 0))

    def _save_char_implants(self):
        combos = getattr(self, "_char_implant_combos", None)
        if not combos:
            return
        out = {}
        for cid, combo in combos.items():
            tid = combo.currentData()
            if tid:
                out[str(cid)] = tid
        self.settings["bau_char_implant"] = out
        self._implant_bonus_cache = None   # Cache invalidieren
        config.save_settings(self.settings)
        cb = getattr(self, "_char_roles_on_change", None)
        if cb:
            try:
                cb()
            except Exception:
                pass

    def _load_char_implants(self):
        """Holt per ESI die eingesteckten Implantate aller Bau-/Reaktions-
        Charaktere und wählt automatisch das erkannte Fertigungszeit-Implantat
        (Zainou 'Beancounter' Industry BX-80X) im jeweiligen Dropdown aus.
        Andere Implantate (Kampf, Skill-Training etc.) werden ignoriert -
        wir kennen nur die Fertigungszeit-Bonus-Serie aus der SDE."""
        client_id = self.settings.get("client_id")
        chars = store.list_characters()
        combos = getattr(self, "_char_implant_combos", None) or {}
        if not client_id or not chars or not combos:
            self._flash_tip(t("No characters/client ID linked."))
            return
        implant_bonuses = industry.load_implant_time_bonuses()
        if not implant_bonuses:
            QMessageBox.information(
                self, t("Implant data missing"),
                t("The SDE does not know any implant bonuses yet.\n\nPlease click "
                  "\u201eLoad recipes\u201c at the top once and confirm the fresh download "
                  "with \u201eYes\u201c when asked (once, approx. 140\u2009MB). Then reopen "
                  "this dialog."))
            return

        def job():
            out = {}
            errors = []
            for ch in chars:
                cid = ch["character_id"]
                if cid not in combos:
                    continue
                try:
                    implants = esi.fetch_character_implants(client_id, cid)
                except Exception as e:
                    errors.append(f"{ch.get('character_name', cid)}: {e}")
                    continue
                for tid in implants:
                    if tid in implant_bonuses:
                        out[cid] = tid
                        break
            return out, errors

        def done(res):
            out, errors = res
            for cid, combo in combos.items():
                if cid in out:
                    self._combo_select(combo, out[cid])
                else:
                    self._combo_select(combo, None)
            self._save_char_implants()
            n = len(out)
            msg = t("{n} implant(s) detected \u2713").format(n=n)
            if errors:
                msg += "  \u00b7  " + t("{n} error(s) (missing scope? re-link)").format(
                    n=len(errors))
            self._flash_tip(msg)
        self._run(Worker(job), done, label=t("Implants \u2026"), overlay=False)


    def _toggle_char_alle_rollen(self, cid):
        """Klick auf den Charakternamen: alle vier Rollen an oder aus.

        REGEL (Nutzer-Wunsch Sitzung 11): steht bei diesem Charakter noch
        NICHT ueberall ein Haken, werden alle gesetzt; steht ueberall einer,
        werden alle entfernt. So macht derselbe Klick immer das, was man von
        ihm erwartet, und man landet nie in einem Halbzustand.

        EIN Speichervorgang, nicht vier: die Kreuze werden mit
        blockierten Signalen umgelegt und danach EINMAL uebernommen. Ohne das
        liefe `_save_build_chars` viermal - genau die Haeufung, gegen die die
        Beschleunigung gebaut ist.
        """
        boxen = [(key, self._char_role_boxes.get((cid, key)))
                 for key, _l in self._ROSTER_ROLES]
        boxen = [(key, cb) for key, cb in boxen if cb is not None]
        if not boxen:
            return
        neuer_stand = not all(cb.isChecked() for _key, cb in boxen)
        for _key, cb in boxen:
            if cb.isChecked() == neuer_stand:
                continue
            cb.blockSignals(True)
            cb.setChecked(neuer_stand)
            cb.blockSignals(False)
        self._save_build_chars()

    def _save_build_chars(self):
        if not hasattr(self, "_char_role_boxes"):
            return
        for key, _l in self._ROSTER_ROLES:
            self.settings[key] = [cid for (cid, k), cb in self._char_role_boxes.items()
                                  if k == key and cb.isChecked()]
        # NICHTS GEAENDERT -> NICHT SCHREIBEN. Ein Haken hin und wieder zurueck
        # (oder das Sammel-Setzen ueber den Namen, das am Ende denselben Stand
        # herstellt) kostet so gar keine Platte mehr.
        _stand = tuple(tuple(sorted(self.settings.get(key) or []))
                       for key, _l in self._ROSTER_ROLES)
        if _stand == getattr(self, "_char_roles_last_saved", None):
            return
        self._char_roles_last_saved = _stand
        # ENTPRELLT UND IM HINTERGRUND SCHREIBEN (Nutzer-Messung Sitzung 10:
        # "es dauert ca. 3 Sekunden bis der Haken da ist", Sitzung 11:
        # "beschleunige das Haken-Setzen"). Das Rechnen war schon raus - was
        # blieb, ist `config.save_settings`: es schreibt die KOMPLETTE
        # settings.json synchron inkl. fsync. Seit dem Auto-Einfrieren traegt
        # jeder gespeicherte Plan einen Plan-Schnappschuss, die Datei ist
        # damit ein Vielfaches groesser geworden - wir haben das
        # mitverursacht. Gemessen bei 10 Plaenen: ~4,6 MB je Klick, auf
        # echter Platte mit Virenscanner entsprechend langsam.
        # Die AUSWAHL steht sofort in self.settings (kann also nicht
        # verlorengehen); auf die Platte geht sie gebuendelt 400 ms nach dem
        # letzten Klick, und dort wartet die Oberflaeche nicht mehr mit
        # (save_settings_async). Wer zehn Kreuze setzt, schreibt einmal statt
        # zehnmal - und merkt auch von diesem einen Mal nichts.
        _t = getattr(self, "_char_roles_save_timer", None)
        if _t is None:
            _t = QTimer(self)
            _t.setSingleShot(True)
            _t.setInterval(400)
            _t.timeout.connect(lambda: config.save_settings_async(self.settings))
            self._char_roles_save_timer = _t
        _t.start()
        # NICHT MEHR SOFORT RECHNEN (Nutzer-Ansage Sitzung 10: "wenn ich da
        # mehrere Sachen und Charaktere austauschen und anhaken will, dauert
        # es sehr lange, teilweise friert mir das Tool fast ein"). Jedes
        # Kreuz stiess vorher einen kompletten Runplaner-Neuaufbau an - bei
        # zehn Charakteren x vier Rollen also bis zu 40 Neuberechnungen fuer
        # EINE Umstellung. Gerechnet wird erst auf Knopfdruck.
        self._char_roles_dirty = True
        _btn = getattr(self, "_char_roles_apply_btn", None)
        if _btn is not None:
            _btn.setEnabled(True)

    def _apply_build_chars(self):
        """"Übernehmen" unter den Bau-Charakteren: JETZT neu rechnen."""
        # Eine noch laufende Entprellung sofort ausloesen - der Nutzer
        # erwartet, dass mit dem Klick alles steht, nicht 400 ms spaeter.
        _t = getattr(self, "_char_roles_save_timer", None)
        if _t is not None and _t.isActive():
            _t.stop()
            config.save_settings(self.settings)
        self._char_roles_dirty = False
        _btn = getattr(self, "_char_roles_apply_btn", None)
        if _btn is not None:
            _btn.setEnabled(False)
        cb = getattr(self, "_char_roles_on_change", None)   # Runplaner neu füllen
        if cb:
            try:
                cb()
            except Exception:
                pass


    def _slot_text(self, cid):
        mx = (self.settings.get("bau_char_slots") or {}).get(str(cid))
        if mx:
            # Fertigung · Reaktionen. Science-Slots (Invention/Kopieren) hier
            # bewusst NICHT mehr angezeigt - irrelevant, solange keine Invention
            # gemacht wird (auf Wunsch entfernt; die Rohdaten/Checkboxen bleiben
            # für später bestehen, falls doch mal gebraucht).
            return t("Mfg. {mfg} \u00b7 React. {react}").format(
                mfg=mx[0], react=mx[1])
        return t("\u2014 (load skills)")

    def _load_char_slots(self, silent=False):
        """`silent=True`: ohne Lade-Overlay und ohne Erfolgs-Meldung - fuer
        das automatische Nachziehen beim Oeffnen eines Bauplans (Nutzer,
        Sitzung 9). Der Knopf im Setup ruft weiter mit Overlay auf, damit
        ein bewusster Klick sichtbar quittiert wird."""
        client_id = self.settings.get("client_id")
        chars = store.list_characters()
        if not client_id or not chars:
            self._flash_tip(t("No characters / client ID"))
            return

        def job():
            out = {}
            for ch in chars:
                cid = ch["character_id"]
                try:
                    sk = esi.fetch_skills(client_id, cid)
                    mx = industry.job_slots(sk)   # (mfg, reaction, science)
                    try:
                        used = esi.fetch_industry_jobs(client_id, cid)
                        free = [max(0, mx[0] - used["manufacturing"]),
                                max(0, mx[1] - used["reaction"]),
                                max(0, mx[2] - used.get("science", 0))]
                    except Exception:
                        free = None
                    out[cid] = (sk, list(mx), free)
                except Exception:
                    out[cid] = (None, None, None)
            return out

        def done(out):
            slots_store = dict(self.settings.get("bau_char_slots") or {})
            free_store = dict(self.settings.get("bau_char_free") or {})
            skills_store = dict(self.settings.get("bau_char_skills") or {})
            for cid, (sk, mx, free) in out.items():
                if mx:
                    slots_store[str(cid)] = mx
                    skills_store[str(cid)] = sk
                    if free is not None:
                        free_store[str(cid)] = free
            self.settings["bau_char_slots"] = slots_store
            self.settings["bau_char_free"] = free_store
            # ZEITSTEMPEL (Sitzung 9, Peanut Motor): die freien Slots sind ein
            # SCHNAPPSCHUSS (max minus damals laufende Jobs) und veralten
            # still - laeuft ingame ein Job aus, sieht das Tool den freien
            # Slot erst nach erneutem "Skills laden". Ohne Datum konnte
            # niemand erkennen, wie alt der Stand ist.
            import time as _time9
            self.settings["bau_char_free_ts"] = _time9.time()
            self.settings["bau_char_skills"] = skills_store
            config.save_settings(self.settings)
            if not silent:
                self._flash_tip(t("Job slots loaded \u2713"))
            self._reload_char_roles()          # neu nach Skills sortieren + Labels
            cb = getattr(self, "_char_roles_on_change", None)
            if cb:
                try:
                    cb()                       # Runplaner mit neuen Slots neu füllen
                except Exception:
                    pass

        self._run(Worker(job), done,
                  label=None if silent else t("Loading skills \u2026"),
                  overlay=not silent)


    def _bau_default_struct(self):
        """Standard-Struktur für Optimierer/Scanner/Job-Kosten: die der Fertigung
        zugewiesene, sonst die erste. None, wenn keine angelegt."""
        structs = self.settings.get("bau_structures", []) or []
        if not structs:
            return None
        sid = (self.settings.get("bau_activity_struct", {}) or {}).get("manufacturing")
        if sid:
            s = next((x for x in structs if x["id"] == sid), None)
            if s:
                return s
        return structs[0]

    def _bau_jobcost_opts(self):
        """Parameter der Job-Kosten-Formel. Index, Steuer und Rollenbonus
        kommen aus der Struktur, die fuer die JEWEILIGE Aktivitaet gewaehlt
        wurde (Fertigung/Reaktion koennen verschiedene sein); Rueckfall sind
        die zuletzt gespeicherten Werte.
        Frueher kam alles aus der "Standard-Struktur" - und die ist, wenn
        nichts fest zugewiesen ist, einfach die ERSTE der Liste. Beim Nutzer
        war das eine Struktur ohne EVE-Verknuepfung, wodurch weder ihre
        Steuer noch der System-Index je ankamen."""
        idx_mfg = float(self.settings.get("bau_mfg_index", 0.0))
        # PUNKT D: bei JEDEM Lauf leeren - sonst behauptet die Warnzeile eine
        # Leihgabe, die aus einer frueheren Rechnung stammt.
        self._bd_index_geliehen = {}
        idx_rea = float(self.settings.get("bau_reaction_index", 0.0))
        ftax = float(self.settings.get("bau_facility_tax", 0.25))
        s = self._bau_default_struct()
        cache = getattr(self, "_bau_cost_idx", None)
        # Die Indizes holen, sobald IRGENDEINE Struktur ein System kennt -
        # nicht nur wenn ausgerechnet die erste der Liste verknuepft ist.
        _any_sys = next((x for x in (self.settings.get("bau_structures") or [])
                         if x.get("system_id")), None)
        if (s and s.get("system_id")) or _any_sys:
            s = s if (s and s.get("system_id")) else _any_sys
            if cache is None:
                try:
                    self._bau_cost_idx = esi.system_cost_indices()
                    cache = self._bau_cost_idx
                except Exception:
                    cache = {}
            ci = (cache or {}).get(int(s["system_id"]), {}) or {}
            if ci:
                idx_mfg = float(ci.get("manufacturing", idx_mfg) or idx_mfg)
                idx_rea = float(ci.get("reaction", idx_rea) or idx_rea)
            ftax = float(s.get("facility_tax", ftax))
        # STEUER AUS DER TATSAECHLICH GEWAEHLTEN STRUKTUR (Nutzer: "Facility
        # Tax soll aus der gewaehlten Baustruktur genommen werden - die
        # Struktur, die die App selber erwaehlt"). Vorher kam sie IMMER aus
        # der Standard-Struktur: wer seine 0,50 % bei Dockside Innovations
        # eintrug, aber eine andere Standard-Struktur hatte, sah davon nichts.
        # Fertigung und Reaktion laufen in verschiedenen Strukturen - also
        # auch verschiedene Steuern.
        # SYSTEM-INDEX EBENFALLS AUS DER GEWAEHLTEN STRUKTUR. Bisher kam er
        # nur aus der "Standard-Struktur" - und das ist, wenn nichts fest
        # zugewiesen ist (bei Nutzern der Normalfall), einfach die ERSTE in
        # der Liste. Steht dort eine Struktur ohne EVE-Verknuepfung (kein
        # system_id, z.B. "Capslock"), wurde der ganze ESI-Block uebersprungen
        # und der Index blieb auf dem zuletzt gespeicherten Wert - womoeglich
        # 0. Die Job-Kosten waeren dann massiv zu niedrig gewesen.
        def _sys_id_of(_st):
            """System-ID einer Struktur - notfalls ueber den SYSTEMNAMEN von
            einer Schwesterstruktur geliehen. Grund (Nutzer): verknuepfen
            kann man nur Strukturen, in denen man ASSETS liegen hat. Eine
            frisch gebaute oder leere Struktur bleibt also dauerhaft ohne
            `system_id` - und haette dann nie einen System-Index bekommen,
            obwohl ihr System bekannt ist und im selben System eine
            verknuepfte Struktur steht. Der Index gilt pro SYSTEM, nicht pro
            Struktur; das Ausleihen ist also keine Schaetzung, sondern
            derselbe Wert."""
            _sid = (_st or {}).get("system_id")
            if _sid:
                return _sid
            _name = ((_st or {}).get("system") or "").strip().lower()
            if not _name:
                return None
            for _o in (self.settings.get("bau_structures") or []):
                if (_o.get("system_id")
                        and (_o.get("system") or "").strip().lower() == _name):
                    return _o["system_id"]
            return None

        def _idx_of(_act, _fallback):
            """Systemkostenindex fuer eine Aktivitaet.

            PUNKT D (Nutzer-Auftrag, Sitzung 20): fehlt die Struktur einer
            Stufe, nahm diese Funktion die STANDARD-Struktur - also die ERSTE
            der Liste. Die Warnzeile sagte dann \"Index 0\", obwohl in Wahrheit
            ein Index aus einem ANDEREN System gerechnet wurde. Plausible
            Zahl, falsche Herkunft.

            ZWEI AENDERUNGEN:
            1. Geliehen wird der HOECHSTE bekannte Index, nicht der erste
               beliebige (Nutzer: \"lieber mehr einkaufen als zu wenig\" - hier:
               lieber zu hohe Job-Kosten annehmen als zu niedrige, sonst sieht
               ein Plan gewinnbringender aus als er ist).
            2. Die Herkunft wird gemerkt (`_bd_index_geliehen`), damit die
               Warnzeile ueber den Tabs zwischen \"Index 0\" und \"geliehener
               Index\" unterscheiden kann statt beides gleich zu nennen.
            """
            _key = "reaction" if _act == "reaction" else "manufacturing"
            _zug = self._struct_for_activity(_act)
            if _zug is not None:
                _sid = _sys_id_of(_zug)
                _ci = ((cache or {}).get(int(_sid), {}) or {}) if _sid else {}
                if not _ci:
                    return _fallback
                return float(_ci.get(_key, _fallback) or _fallback)
            # Keine zugewiesene Struktur -> der Index wird GELIEHEN.
            _kand = []
            for _o in (self.settings.get("bau_structures") or []):
                _osid = _sys_id_of(_o)
                if not _osid:
                    continue
                _oci = (cache or {}).get(int(_osid), {}) or {}
                _v = _oci.get(_key)
                if _v is None:
                    continue
                _kand.append((float(_v), _o.get("system") or str(_osid)))
            if not _kand:
                return _fallback
            _v, _sysname = max(_kand)
            if not hasattr(self, "_bd_index_geliehen"):
                self._bd_index_geliehen = {}
            self._bd_index_geliehen[_act] = (_v, _sysname)
            return _v

        def _ftax_of(_act):
            _st = self._struct_for_activity(_act)
            if _st and _st.get("facility_tax") is not None:
                return float(_st.get("facility_tax") or 0.0)
            return ftax
        # ROLLENBONUS AUS DEM STRUKTURTYP statt aus einer Einstellung, die
        # niemand setzen konnte: ein Engineering Complex (Raitaru/Azbel/
        # Sotiyo) senkt den Index-Anteil der Job-Kosten um 4 %, eine Refinery
        # (Athanor/Tatara) nicht. EVE weist das als "Structure Role Bonus"
        # aus. Damit kommen Rigs, ME, TE, Steuer UND Job-Bonus aus DERSELBEN
        # Struktur - vorher waren es zwei verschiedene Quellen.
        def _rbonus_of(_act):
            _st = self._struct_for_activity(_act)
            _typ = ((_st or {}).get("type") or "").lower()
            return self._STRUCT_ROLE_JOBCOST.get(_typ, 0.0) / 100.0
        return {
            "system_index_mfg": _idx_of("manufacturing", idx_mfg),
            "system_index_reaction": _idx_of("reaction", idx_rea),
            "facility_tax": _ftax_of("manufacturing") / 100.0,
            "facility_tax_reaction": _ftax_of("reaction") / 100.0,
            "role_bonus": _rbonus_of("manufacturing"),
            "role_bonus_reaction": _rbonus_of("reaction"),
            "scc_surcharge": float(self.settings.get("bau_scc", 0.04)),
            # SCIENCE-INDIZES fuer die Jobgebuehren Kopieren/Invention
            # (Sitzung 9, Formel in industry.science_job_fee verifiziert).
            # v1: dasselbe System wie die Fertigung - eine eigene
            # Science-Struktur-Wahl kennt das Tool (noch) nicht.
            "sci_index_invention": _idx_of("invention", 0.0),
            "sci_index_copying": _idx_of("copying", 0.0),
        }


    def _bau_rig_me(self):
        """Material-Rig-Bonus ohne Struktur = 0 %. Der Rig-Bonus kommt jetzt aus der
        zugewiesenen Struktur (kategorie-spezifisch, im Bauplan)."""
        return 0.0

    def _bau_effective_me(self):
        """ME ohne Struktur = nur Blueprint-ME (Rig kommt aus der Struktur)."""
        return float(self.settings.get("bau_me", 10))

    def _bau_struct_te_factor(self, s):
        """Zeitfaktor aus TE-Rig der Struktur (× Sicherheit) + Endprodukt-TE, OHNE
        Skills. Die Skill-Zeit kommt pro Charakter im Runplaner (sonst doppelt)."""
        rig_te = self._struct_te_rig_pct(s)          # schon × Sicherheit
        bp_te = getattr(self, "_bd_te", None)
        if bp_te is None:
            bp_te = self.settings.get("bau_te", 0)
        return max(0.02, (1 - float(bp_te or 0) / 100.0) * (1 - rig_te / 100.0))


    def _bau_rig_me_for_item(self, s, item_doms, reaction=False):
        """Bester passender Rig-ME (in %) einer Struktur für eine Item-Domäne,
        inkl. Sicherheits-Multiplikator.

        KEIN RUECKFALL AUF EIN T1-RIG (seit dem Falcon-Vorfall, Sitzung 8):
        findet sich in der Struktur kein Rig, das auf diese Item-Domäne wirkt,
        sind es 0 %. Vorher wurde hier ein T1-Rig unterstellt (2 % mal
        Sicherheits-Multiplikator) - das rechnete den Materialbedarf um bis zu
        4,2 % zu NIEDRIG, und im Spiel fehlte dem Nutzer genau dieser Anteil.
        Der Schalter `_RIG_FALLBACK_T1` schaltet das alte Verhalten wieder ein,
        steht aber bewusst auf False: lieber Material uebrig als ein Job, der
        nicht startet.
        KORRIGIERT (Sitzung 8, NUTZER-MESSUNG ingame): frueher galt hier
        "Reactor-Efficiency wirkt nur auf Composite/Hybrid/Biochemical, NICHT
        auf Intermediate". Das war FALSCH. Beweis aus zwei Industry-Fenstern
        des Nutzers, beide R&R Yard (Tatara, Standup L-Set Reactor Efficiency I,
        Null/WH):
          * Vanadium Hafnite (INTERMEDIATE): Eingang 98 + 98 statt 100 + 100
          * Tungsten Carbide (COMPOSITE):    Eingang 98 + 98 statt 100 + 100
        Beide zeigen denselben Materialabzug, und beide Jobs laufen exakt
        gleich lang (01:24:14) - der generische Reactor-Efficiency-Rig wirkt
        also auf BEIDE Reaktionsarten. Die alte Ausnahme liess Intermediate-
        Reaktionen 2 % zu viel Material einplanen (harmlos in der Richtung -
        Material blieb uebrig - aber falsch).
        HINWEIS: EVE kennt daneben spezialisierte Reaktions-Rigs (Composite/
        Hybrid/Biochemical Reactor Efficiency). Sobald eines davon in den
        Katalog kommt, braucht ES eine Domaenen-Einschraenkung - der
        generische bekommt keine.
        """
        if not s or not item_doms:
            return 0.0
        _, bonus = self._rig_catalog()
        best = 0.0
        for key in (s.get("rigs") or []):
            b = bonus.get(key)
            if b and (b.get("domains") or set()) & item_doms:
                best = max(best, b.get("me", 0.0))
        if not best and self._RIG_FALLBACK_T1 and not reaction:
            # NUR FERTIGUNG. Reaktionen haben in EVE eigene Reactor-Efficiency-
            # Rigs; fuer eine Struktur ohne solches Rig einen T1-Reaktor zu
            # unterstellen waere eine deutlich staerkere Annahme - und wuerde
            # die gerade verifizierten Bauplan-Zahlen des Nutzers still
            # verschieben. Bleibt bewusst offen, bis er es entscheidet.
            best = self._ME_RIG_PCT.get(1, 2.0)
        secmult = float(s.get("security", 1.0))
        if reaction:
            secmult = 1.1 if secmult >= 2.0 else 1.0
        return best * secmult

    def _bau_rig_te_for_item(self, s, item_doms, reaction=False):
        """Bester passender Rig-TE (in %) einer Struktur für eine Item-Domäne,
        inkl. Sicherheits-Multiplikator. 0, wenn kein Rig passt. Pendant zu
        _bau_rig_me_for_item, nur für die Zeit-Komponente des Rig-Bonus.
        KORRIGIERT wie beim ME-Pendant (Nutzer-Messung, Sitzung 8): der
        generische Reactor-Efficiency-Rig wirkt auch auf INTERMEDIATE.
        Beleg: Vanadium Hafnite (intermediate) und Tungsten Carbide
        (composite) laufen im selben Tatara exakt gleich lang (01:24:14) -
        haette der Rig nur auf composite gewirkt, muesste die Intermediate-
        Reaktion laenger dauern."""
        if not s or not item_doms:
            return 0.0
        # Intermediate-Reaktion? Dann greifen die Reactor-Efficiency-Rigs nicht.
        _, bonus = self._rig_catalog()
        best = 0.0
        for key in (s.get("rigs") or []):
            b = bonus.get(key)
            if b and (b.get("domains") or set()) & item_doms:
                best = max(best, b.get("te", 0.0))
        secmult = float(s.get("security", 1.0))
        if reaction:
            secmult = 1.1 if secmult >= 2.0 else 1.0
        return best * secmult

    def _bau_best_struct(self, activity, ids, groups, reaction_products,
                         stage_map=None, endprodukt=None):
        """Struktur für eine Bau-STUFE. Explizit zugewiesen → respektieren.
        Sonst „Auto": die Struktur mit dem größten ME-Gesamtnutzen für GENAU
        die Bauteile dieser Stufe (nicht nach pauschalem Prozent) - NUR unter
        Strukturen, die diese Aktivität überhaupt können (Refineries z.B. nie
        Fertigung). None, wenn keine Strukturen angelegt oder keine geeignete
        dabei ist.

        Seit Sitzung 8 wird nach STUFE gefiltert (components/endproduct/
        reaction_1/reaction_2), nicht mehr nur nach „ist Reaktion". Vorher
        floss der Nutzen ALLER Fertigungs-Items in eine einzige Wahl - die
        Komponenten haben das Endprodukt dabei regelmäßig überstimmt, weil es
        viel mehr davon gibt."""
        structs = self.settings.get("bau_structures", []) or []
        if not structs:
            return None
        _amap = self.settings.get("bau_activity_struct", {}) or {}
        sid = _amap.get(activity) or _amap.get(
            self._STUFE_LEGACY.get(activity, ""), "")
        # Fest zugewiesen schlaegt die Automatik - aber NICHT die Diagnose.
        # Vorher kehrte die Funktion hier sofort um, ohne Einordnung und
        # Rangliste aufzuzeichnen: fest zugewiesene Stufen zeigten im
        # Runplaner dauerhaft "Rig: keine Einordnung", als laege ein Fehler
        # vor. Jetzt wird die Zuweisung gemerkt und erst NACH der
        # Aufzeichnung zurueckgegeben.
        _fest = None
        if sid:
            _fest = next((x for x in structs if x["id"] == sid), None)
            # Auch hier gilt: unmoegliche Zuweisung schlaegt NICHTS (Sitzung 19).
            if _fest is not None and not self._struct_kann(_fest, activity):
                _fest = None
        fit_key = self._STUFE_FIT.get(activity, activity)
        structs = [s for s in structs if fit_key in
                  self._STRUCT_TYPE_FIT.get(s.get("type", ""), (set(), ""))[0]]
        if not structs and _fest is None:
            return None
        reaction = (fit_key == "react")
        # Wird noch mit einem ALTEN, groben Schluessel gerufen ("manufacturing"/
        # "reaction"), deckt der alle Stufen ab, die auf ihn zurueckfallen -
        # sonst faende der Filter unten kein einziges Item und die Auswahl
        # kippte still auf "erstbeste Struktur".
        zielstufen = {k for k, v in self._STUFE_LEGACY.items()
                      if v == activity} or {activity}
        catmap = industry.item_category_map() or {}
        rel = []
        _diag = []
        for tid in ids:
            if self._bau_stufe_fuer_item(tid, reaction_products, stage_map,
                                         endprodukt) not in zielstufen:
                continue
            is_reac = tid in (reaction_products or set())
            info = catmap.get(tid)
            doms = industry.item_domains(info[0] if info else None,
                                         groups.get(tid, ""),
                                         info[2] if info else None,
                                         is_reaction=is_reac)
            if doms:
                rel.append(doms)
                # WELCHE Einordnung hat das Item bekommen? Das ist die
                # entscheidende Zahl bei "warum gewinnt Struktur X?" - ohne
                # sie raet man (Nutzer-Fall Simurgh: Capital-Rig oder
                # Large-Ship-Rig?). Gruppenname MIT ausgeben, denn genau
                # daran haengt die Zuordnung.
                _diag.append((groups.get(tid, "") or "?", sorted(doms)))

        def benefit(s):
            return sum(self._bau_rig_me_for_item(s, d, reaction) for d in rel)
        ranked = sorted(structs, key=benefit, reverse=True)
        # NACHVOLLZIEHBAR MACHEN (Nutzer-Frage, Sitzung 8: "theoretisch
        # muesste das Tool fuer ein Capital-Schiff den Bauort auf Capslock
        # aendern"). Die Wahl war bisher eine Blackbox - man sah das
        # Ergebnis, nie den Grund. Jetzt wird die Rangliste mit dem
        # jeweiligen Rig-Nutzen gemerkt und im Runplaner als Tooltip
        # gezeigt. Bei GLEICHEM Nutzen (oft 0 zu 0, weil kein Rig auf die
        # Item-Art passt) gewinnt schlicht die erste Struktur - genau das
        # sieht man dann auch.
        try:
            if not hasattr(self, "_bd_struct_choice"):
                self._bd_struct_choice = {}
            if not hasattr(self, "_bd_struct_diag"):
                self._bd_struct_diag = {}
            self._bd_struct_choice[activity] = (
                ([(t("{name} (fixed assignment)").format(
                       name=_fest.get('name', '?')),
                   round(benefit(_fest), 2))] if _fest is not None else [])
                + [(x.get("name", "?"), round(benefit(x), 2))
                   for x in ranked
                   if _fest is None or x.get("id") != _fest.get("id")])
            # Einordnung der Items mitgeben (max. 4, sonst wird der Tooltip
            # zur Wand) - daran sieht man SOFORT, warum ein Rig nicht greift.
            _u = []
            for _g, _d in _diag:
                if (_g, tuple(_d)) not in [(a, tuple(b)) for a, b in _u]:
                    _u.append((_g, _d))
            self._bd_struct_diag[activity] = _u[:4]
        except Exception:
            pass
        if _fest is not None:
            return _fest
        return ranked[0] if ranked else None

    # Eingebauter Struktur-ME-Bonus (KEIN Rig!) je Typ, in % - NUR Engineering
    # Complexes bekommen den, Refineries nicht (CCP: "You get a 1% ME bonus in
    # an engineering complex - does not apply in other structures"). Wirkt
    # multiplikativ zusätzlich zu Blueprint-ME UND Rig-ME - wurde vorher
    # komplett ignoriert (Faktor 1.0), wodurch jeder Materialbedarf bei
    # zugewiesener Engineering-Complex-Struktur ca. 1 % zu hoch berechnet
    # wurde (derselbe Bug, den es beim Zeitfaktor schon mal gab, s.
    # _STRUCT_ROLE_TIME oben - dort längst gefixt, hier nicht).
    # Rollenbonus auf die JOB-KOSTEN (Index-Anteil) je Strukturtyp - in EVE
    # die Zeile "Structure Role Bonus". Engineering Complexes geben ihn,
    # Refineries nicht. Katalog statt Einstellung: der Nutzer waehlt die
    # Struktur, nicht den Bonus (Nutzer: "das App erkennt automatisch").
    # GEMESSEN am Info-Fenster (Nutzer-Screenshots): Azbel "4% reduction in
    # ISK requirements", Sotiyo "5%" (19.09.2026), Raitaru "3% reduction in
    # ISK requirements for manufacturing and science jobs" (25.09.2026).
    # DER RAITARU STAND HIER MIT 4 % - geraten, nie gemessen, und damit ein
    # Prozentpunkt zu guenstig: Plaene in einem Raitaru haben ihre Jobkosten
    # zu NIEDRIG geschaetzt. Dass daneben Material (1 %) und Zeit (15 %)
    # stimmten, hat den falschen Wert lange gedeckt.
    _STRUCT_ROLE_JOBCOST = {
        "raitaru": 3.0, "azbel": 4.0, "sotiyo": 5.0,
        "athanor": 0.0, "tatara": 0.0,
    }

    _STRUCT_ROLE_ME = {
        "raitaru": 1.0, "azbel": 1.0, "sotiyo": 1.0,
        "athanor": 0.0, "tatara": 0.0,
    }

    def _bau_me_maps(self, ids, groups, reaction_products, cat_me_map=None,
                     type_id=None, use_dialog_me=True, recipes=None):
        """Pro Item die effektive ME% (Kategorie-Basis-ME + passender Struktur-Rig).
        Endprodukt (type_id) nutzt weiterhin die Blueprint-ME-Eingabe oben im
        Dialog; alle anderen Items ihre Kategorie-Basis aus cat_me_map (Komponenten/
        T1-H\u00fcllen/Fuel Blocks/Tools \u2013 s. _bau_category_me_map). Auto w\u00e4hlt je
        Aktivit\u00e4t die f\u00fcr DIESEN Bau beste Struktur. Returns
        (me_map, me_map_reaction, rig_me_map, used, ec_me_map) \u2013 used =
        {activity: struct|None}; ec_me_map = {tid: Rollenbonus-ME % der Struktur
        seiner Stufe} fuer den invented-Pfad in industry (me_invented_pct) -
        dort ersetzt die Invention-ME die me_map, der 1-%-Bonus des
        Engineering Complexes fiel deshalb weg (Viator-Befund 19.09.2026)."""
        structs = self.settings.get("bau_structures", []) or []
        # s. _bau_category_me_map: der Scanner ruft mit use_dialog_me=False auf,
        # damit die ME-Eingabe des letzten Bauplan-Dialogs nicht durchschlaegt.
        bp_me = float(self._bd_me if (use_dialog_me and
                                      getattr(self, "_bd_me", None) is not None)
                      else self.settings.get("bau_me", 10))
        cat_me_map = cat_me_map or {}
        catmap = industry.item_category_map() or {}
        # STUFEN-KARTE: 1 = Intermediate, 2 = Composite. Dieselbe Quelle, die
        # der Runplaner benutzt - nicht danebengerechnet.
        # REIHENFOLGE-FALLE (Nutzer-Screenshot, Sitzung 9: Composite-Stufe
        # "keine Einordnung", Intermediate direkt darueber voll): der
        # Oeffnen-Job ruft diese Funktion, BEVOR er self._bd_recipes setzt.
        # Beim ERSTEN Bauplan nach dem Start war _bd_recipes also None, die
        # Stufen-Karte leer - und JEDE Reaktion galt als Stufe 1: reaction_2
        # bekam null Items (leere Diagnose, Strukturwahl ohne Item-Nutzen).
        # Deshalb reichen die Aufrufer ihr recipes jetzt DIREKT herein;
        # _bd_recipes bleibt nur als Rueckfall fuer Alt-Aufrufer.
        try:
            _rec9 = recipes if recipes is not None \
                else getattr(self, "_bd_recipes", None)
            stage_map = industry.reaction_stage_map(_rec9) if _rec9 else {}
        except Exception:
            stage_map = {}
        # JE STUFE EINE STRUKTUR (Nutzer-Wunsch, Sitzung 8). Vorher gab es
        # genau zwei: eine fuer alles Gefertigte, eine fuer alles Reagierte.
        stufen = ("components", "endproduct", "reaction_1", "reaction_2")
        # Diagnose-Speicher VOR der Stufenwahl leeren - sonst ueberleben
        # Eintraege der letzten Berechnung (anderer Bauplan, andere
        # Strukturen) und der Runplaner zeigt veraltete Ranglisten. Nur im
        # Dialog-Kontext: der Scanner (use_dialog_me=False) darf die Anzeige
        # des offenen Bauplans nicht ueberschreiben.
        if use_dialog_me:
            self._bd_struct_choice = {}
            self._bd_struct_diag = {}
        st_map = {}
        for _stufe in stufen:
            st_map[_stufe] = self._bau_best_struct(
                _stufe, ids, groups, reaction_products,
                stage_map=stage_map,
                endprodukt=self._bd_enden(type_id, _rec9) if type_id is not None else None
            ) if structs else None
        ec_me = {k: (self._STRUCT_ROLE_ME.get((v or {}).get("type", ""), 0.0)
                     if v else 0.0)
                 for k, v in st_map.items()}

        me_map = {}; me_map_reaction = {}; rig_me_map = {}; ec_me_map = {}
        # BUENDEL (1.0.9): jedes Ende ist "Endprodukt" und bringt die ME
        # seines Einzelplans mit (`_bd_me_je_ende`, Schritt 4); fehlt der
        # Eintrag, gilt die Eingabe oben wie beim Einzelplan.
        _enden = self._bd_enden(type_id, _rec9) if type_id is not None else set()
        _me_je_ende = (getattr(self, "_bd_me_je_ende", None) or {}) if use_dialog_me else {}
        for tid in ids:
            is_reac = tid in (reaction_products or set())
            stufe = self._bau_stufe_fuer_item(tid, reaction_products,
                                              stage_map, _enden)
            if ec_me.get(stufe, 0.0):
                ec_me_map[tid] = ec_me.get(stufe, 0.0)
            s_used = st_map.get(stufe)
            info = catmap.get(tid)
            doms = industry.item_domains(info[0] if info else None,
                                         groups.get(tid, ""),
                                         info[2] if info else None, is_reaction=is_reac)
            if is_reac:
                rm = self._bau_rig_me_for_item(s_used, doms, reaction=True)
                me_map_reaction[tid] = (1 - (1 - rm / 100.0) *
                                        (1 - ec_me.get(stufe, 0.0) / 100.0)) * 100.0
            else:
                rm = self._bau_rig_me_for_item(s_used, doms)
                if tid in _enden:
                    _bme = _me_je_ende.get(tid)
                    base = float(_bme) if _bme is not None else bp_me
                else:
                    base = cat_me_map.get(tid, bp_me)
                me_map[tid] = (1 - (1 - base / 100.0) * (1 - rm / 100.0) *
                              (1 - ec_me.get(stufe, 0.0) / 100.0)) * 100.0
            if rm:
                rig_me_map[tid] = rm
        # `used` behaelt die alten Schluessel BEI und ergaenzt die feinen -
        # sonst braechen alle Anzeigen, die "manufacturing"/"reaction" lesen.
        used = dict(st_map)
        used["manufacturing"] = st_map.get("components")
        used["reaction"] = st_map.get("reaction_2") or st_map.get("reaction_1")
        return me_map, me_map_reaction, rig_me_map, used, ec_me_map

    def _combo_select(self, combo, data):
        for i in range(combo.count()):
            if combo.itemData(i) == data:
                combo.setCurrentIndex(i)
                return

    def _bau_profile_snapshot(self):
        # NUR EINSTELLUNGEN (03.10.2026): nie die Plaene - siehe
        # config.BAU_PROFIL_OHNE.
        return config.bau_profil_bereinigen(self.settings)

    def _reload_bau_profiles(self):
        if not hasattr(self, "bs_profile"):
            return
        self.bs_profile.blockSignals(True)
        self.bs_profile.clear()
        self.bs_profile.addItem(t("— Choose profile —"), None)
        for name in sorted((self.settings.get("bau_profiles") or {}).keys()):
            self.bs_profile.addItem(name, name)
        self.bs_profile.blockSignals(False)

    def _save_bau_profile(self):
        from PySide6.QtWidgets import QInputDialog
        name, ok = QInputDialog.getText(
            self, t("Save profile"),
            t("Name of the profile (e.g. \u201eAzbel null \u00b7 own reactions\u201c):"))
        name = (name or "").strip()
        if not ok or not name:
            return
        profs = self.settings.setdefault("bau_profiles", {})
        profs[name] = self._bau_profile_snapshot()
        config.save_settings(self.settings)
        self._reload_bau_profiles()
        self._combo_select(self.bs_profile, name)
        self._flash_tip(t("Profile \u201e{name}\u201c saved \u2713").format(name=name))

    def _load_bau_profile(self):
        name = self.bs_profile.currentData()
        if not name:
            self._flash_tip(t("No profile selected"))
            return
        snap = (self.settings.get("bau_profiles") or {}).get(name)
        if not snap:
            return
        # Auch ein ALTES Profil (mit Plaenen darin) ueberschreibt nie mehr
        # die aktuellen Plaene, Jobs oder Skills.
        self.settings.update(config.bau_profil_bereinigen(snap))
        config.save_settings(self.settings)
        self._apply_bau_settings_to_fields()
        self._flash_tip(t("Profile \u201e{name}\u201c loaded \u2713").format(name=name))

    def _delete_bau_profile(self):
        name = self.bs_profile.currentData()
        if not name:
            return
        profs = self.settings.get("bau_profiles") or {}
        if name in profs:
            del profs[name]
            config.save_settings(self.settings)
            self._reload_bau_profiles()
            self._flash_tip(t("Profile \u201e{name}\u201c deleted").format(name=name))

    def _apply_bau_settings_to_fields(self):
        """Setzt alle Bau-Setup-Widgets aus self.settings (nach Profil-Laden)."""
        s = self.settings
        widgets = [self.bs_sec, self.bs_ftax,
                   self.bs_bpme, self.bs_bpte, self.bs_react, self.bs_inv,
                   self.bs_decry]
        for w in widgets:
            w.blockSignals(True)
        try:
            self._combo_select(self.bs_sec, float(s.get("bau_security", 1.0)))
            self.bs_ftax.setValue(float(s.get("bau_facility_tax", 0.25)))
            self.bs_bpme.setValue(int(s.get("bau_me", 10)))
            self.bs_bpte.setValue(int(s.get("bau_te", 0)))
            self.bs_react.setCurrentIndex(0 if s.get("bau_reactions", True) else 1)
            self.bs_inv.setCurrentIndex(0 if s.get("bau_invention", False) else 1)
            self._combo_select(self.bs_decry, s.get("bau_decryptor", KEIN_DECRYPTOR))
        finally:
            for w in widgets:
                w.blockSignals(False)
        if hasattr(self, "bs_syspick") and s.get("bau_system_name"):
            self.bs_syspick.blockSignals(True)
            self.bs_syspick.setEditText(s.get("bau_system_name"))
            self.bs_syspick.blockSignals(False)
        if hasattr(self, "_reload_bau_loc"):
            self._reload_bau_loc()
        self._update_bau_eff()
        self._update_bau_sys()

    def _save_bau_setup(self, *_a):
        self.settings["bau_security"] = self.bs_sec.currentData()
        self.settings["bau_facility_tax"] = self.bs_ftax.value()
        self.settings["bau_me"] = int(self.bs_bpme.value())
        self.settings["bau_te"] = int(self.bs_bpte.value())
        self.settings["bau_reactions"] = bool(self.bs_react.currentData())
        self.settings["bau_invention"] = bool(self.bs_inv.currentData())
        self.settings["bau_decryptor"] = self.bs_decry.currentData()
        config.save_settings(self.settings)
        self._update_bau_eff()
        self._update_bau_sys()

    def _update_bau_sys(self):
        if not hasattr(self, "bs_sys"):
            return
        sysn = self.settings.get("bau_system_name", "")
        if not sysn:
            # Beispiel neutral halten (Sitzung 11): hier stand das
            # Heimatsystem des Entwicklers. Jita kennt jeder.
            self.bs_sys.setText(t(
                "No system selected – search for a build system above "
                  "(e.g. „Jita“) for the live cost index."))
            return
        idx = float(self.settings.get("bau_mfg_index", 0.0))
        ftax = float(self.settings.get("bau_facility_tax", 0.25))
        parts = []
        if self.settings.get("bau_character") and self.settings.get("bau_skills"):
            parts.append(t("Build \u2212{p} % time").format(
                p=f"{(1 - self._bau_skill_time_factor()) * 100:.0f}"))
        if self.settings.get("bau_react_character") and self.settings.get("bau_react_skills"):
            parts.append(t("Reaction \u2212{p} % time").format(
                p=f"{(1 - self._bau_react_skill_time_factor()) * 100:.0f}"))
        skill_txt = ("   \u00b7   " + t("Skills: ") + ", ".join(parts)) if parts else ""
        self.bs_sys.setText(
            t("System: {sys}  \u00b7  manufacturing cost index: {idx} %  "
              "(live from ESI)  \u00b7  facility tax: {ftax} %  \u00b7  "
              "+ 4 % SCC (fixed)").format(
                sys=sysn, idx=f"{idx * 100:.2f}", ftax=f"{ftax:.2f}")
            + skill_txt)

    def _detect_bau_system(self, structure_id):
        """System der Struktur auflösen + Fertigungs-Kosten-Index aus ESI holen."""
        fav = next((f for f in store.list_favorites()
                    if f.get("structure_id") == structure_id), None)
        cid = fav.get("character_id") if fav else None
        if not cid:
            chars = store.list_characters()
            cid = chars[0]["character_id"] if chars else None
        if not cid:
            return
        client_id = self.settings.get("client_id")
        self.bs_sys.setText(t("Fetching system index from ESI \u2026"))

        def job():
            info = esi.resolve_structure(client_id, cid, structure_id)
            sysid = info.get("solar_system_id")
            sinfo = esi.system_info(sysid) if sysid else {"name": "", "security": 1.0}
            idxs = esi.system_cost_indices()
            d = (idxs.get(int(sysid), {}) or {}) if sysid else {}
            return {"sysid": sysid or 0, "name": sinfo.get("name", ""),
                    "security": sinfo.get("security", 1.0),
                    "mfg": d.get("manufacturing", 0.0) or 0.0,
                    "reaction": d.get("reaction", 0.0) or 0.0}

        def done(r):
            sec = r["security"]
            mult = 1.0 if sec >= 0.45 else (1.9 if sec > 0.0 else 2.1)
            self.settings["bau_system_id"] = r["sysid"]
            self.settings["bau_system_name"] = r["name"]
            self.settings["bau_mfg_index"] = r["mfg"]
            self.settings["bau_reaction_index"] = r["reaction"]
            self.settings["bau_security"] = mult
            config.save_settings(self.settings)
            self._combo_select(self.bs_sec, mult)     # Sicherheit → Rig-Bonus skaliert
            self._update_bau_eff()
            self._update_bau_sys()

        def fail(msg):
            self.bs_sys.setText(t("System index error (structure access?): ") + msg)
        self._run(Worker(job), done, fail_cb=fail, overlay=False)

    def _reload_system_picker(self):
        """Lädt alle Systemnamen (einmalig, im Hintergrund) für die System-Suche."""
        if not hasattr(self, "bs_syspick") or getattr(self, "_sysname2id", None):
            return

        def job():
            return esi.all_system_names()      # {id: name}

        def done(names):
            self._sysname2id = {v.lower(): k for k, v in names.items()}
            self.bs_syspick.blockSignals(True)
            self.bs_syspick.clear()
            for nm in sorted(names.values()):
                self.bs_syspick.addItem(nm, self._sysname2id.get(nm.lower()))
            self.bs_syspick.setCurrentIndex(-1)
            self.bs_syspick.setEditText(self.settings.get("bau_system_name", ""))
            self.bs_syspick.blockSignals(False)
        self._run(Worker(job), done, overlay=False)

    def _on_bau_syspick(self, *_a):
        txt = self.bs_syspick.currentText().strip()
        sid = (getattr(self, "_sysname2id", {}) or {}).get(txt.lower())
        if not sid:
            return
        self.bs_sys.setText(t("Fetching system index + security from ESI \u2026"))

        def job():
            info = esi.system_info(sid)
            idxs = esi.system_cost_indices()
            d = idxs.get(int(sid), {}) or {}
            return {"info": info, "mfg": d.get("manufacturing", 0.0) or 0.0,
                    "reaction": d.get("reaction", 0.0) or 0.0}

        def done(r):
            sec = r["info"]["security"]
            mult = 1.0 if sec >= 0.45 else (1.9 if sec > 0.0 else 2.1)
            self.settings["bau_system_id"] = sid
            self.settings["bau_system_name"] = r["info"]["name"]
            self.settings["bau_mfg_index"] = r["mfg"]
            self.settings["bau_reaction_index"] = r["reaction"]
            self.settings["bau_security"] = mult
            config.save_settings(self.settings)
            self._combo_select(self.bs_sec, mult)     # Sicherheit automatisch
            self._update_bau_eff()
            self._update_bau_sys()

        def fail(msg):
            self.bs_sys.setText(t("System index error: ") + msg)
        self._run(Worker(job), done, fail_cb=fail, overlay=False)

    def _reload_bau_loc(self):
        """Füllt den Bau-Ort-Wähler: NPC + deine Struktur-Favoriten + „hinzufügen“."""
        if not hasattr(self, "bs_loc"):
            return
        cur = self.settings.get("bau_location", "npc")
        self.bs_loc.blockSignals(True)
        self.bs_loc.clear()
        self.bs_loc.addItem(t("NPC station (no rigs)"), "npc")
        for f in store.list_favorites():
            if f.get("kind") == "structure" and f.get("structure_id"):
                self.bs_loc.addItem("★ " + f["name"], f["structure_id"])
        self.bs_loc.addItem(t("＋ Add structure …"), "__add__")
        self.bs_loc.blockSignals(False)
        self._combo_select(self.bs_loc, cur)

    def _on_bau_loc_change(self, *_a):
        data = self.bs_loc.currentData()
        if data == "__add__":
            self._bau_pick_structure()     # Dropdown deiner Strukturen (+ manuelle ID)
            self._reload_bau_loc()
            return
        self.settings["bau_location"] = data
        if data == "npc":
            self.settings["bau_system_id"] = 0
            self.settings["bau_system_name"] = ""
            self.settings["bau_mfg_index"] = 0.0
            config.save_settings(self.settings)
            self._update_bau_sys()
            return
        config.save_settings(self.settings)
        self._detect_bau_system(int(data))    # System + Kosten-Index aus ESI holen

    def _update_bau_eff(self):
        if not hasattr(self, "bs_eff"):
            return
        self.bs_eff.setText(t(
            "\u2192 Blueprint material efficiency: {me} %   \u00b7   Rig bonuses (ME/TE) "
            "now come from the assigned structure (in the \u201eStructure fitting\u201c, "
            "category-specific per build plan).").format(
            me=int(self.settings.get('bau_me', 10))))

    def _reload_build_picker(self):
        """Laedt die Suchliste aller baubaren Items (Namen im Hintergrund).

        Das Tippfeld im Scanner ist ENTFERNT (Nutzer: "kann weg, es gibt
        Rechtsklick und Neuer Bauplan") - die Liste wird aber weiterhin
        gebraucht: der "Neuer Bauplan"-Dialog sucht darin. Deshalb pflegt
        diese Funktion nur noch `_build_picker_pairs` und fasst kein
        Widget mehr an.
        """
        if not industry.sde_ready():
            return
        def job():
            # Wiederverwendet statt jedes Mal neu eingelesen (gemessen: 310 ms
            # je Oeffnen). Die Kopie wird verworfen, sobald die SDE neu
            # geladen wurde - s. industry.recipes_cached.
            recipes = industry.recipes_cached()
            ids = list(recipes.product_to_bp.keys())
            names = esi.resolve_names(ids)
            # Laufvariable NICHT `t` nennen - das ueberdeckt den Uebersetzer.
            return sorted(((names.get(_i, f"#{_i}"), _i) for _i in ids),
                          key=lambda x: x[0])
        def done(pairs):
            self._build_picker_pairs = pairs        # für „Neuer Bauplan“-Dialog
        self._run(Worker(job), done, overlay=False)

    def _open_build_picker_dialog(self):
        from ..sprache import t as _txt   # `t` ist hier lokal belegt
        """„Neuer Bauplan“: kleiner Dialog mit eigener Blaupausen-Suche (wie im Scanner)."""
        if not industry.sde_ready():
            self.build_status.setText(t("Run \u201eLoad recipes\u201c first."))
            return
        from PySide6.QtWidgets import (QDialog, QVBoxLayout, QHBoxLayout, QComboBox,
                                       QLabel, QPushButton, QCompleter)
        pairs = getattr(self, "_build_picker_pairs", None)
        dlg = MinimizableDialog(self); dlg.setWindowTitle(t("New build plan"))
        dlg.setMinimumWidth(440)
        v = QVBoxLayout(dlg); v.setContentsMargins(18, 16, 18, 16); v.setSpacing(10)
        v.addWidget(QLabel(t("Search blueprint / item:")))
        cb = QComboBox(); cb.setEditable(True); cb.setMinimumHeight(34)
        cb.setInsertPolicy(QComboBox.NoInsert)
        if pairs:
            for nm, _tid in pairs:          # NICHT `t` - ueberdeckt den Uebersetzer
                cb.addItem(nm, _tid)
        else:
            cb.addItem(t("(load recipes first)"), None)
        cb.setCurrentIndex(-1); cb.setEditText("")
        comp = cb.completer()
        if comp:
            comp.setCompletionMode(QCompleter.PopupCompletion)
            comp.setFilterMode(Qt.MatchContains)
            comp.setCaseSensitivity(Qt.CaseInsensitive)
        v.addWidget(cb)
        row = QHBoxLayout(); row.addStretch()
        cancel = QPushButton(_txt("Cancel")); cancel.clicked.connect(dlg.reject)
        cancel.setIcon(icons.icon("close"))
        # AN self MERKEN (Sitzung 17): das Tutorial laesst ihn mitblinken.
        openb = self._picker_open_btn = QPushButton(" " + _txt("Open"))
        openb.setIcon(icons.icon("eye"))
        openb.setStyleSheet(f"QPushButton{{background:{theme.CYAN_FILL}; color:{theme.CYAN}; "
                            f"border:none; border-radius:7px; padding:9px 18px; font-weight:700;}}")
        row.addWidget(cancel); row.addWidget(openb)
        v.addLayout(row)

        def _open():
            txt = cb.currentText().strip()
            tid = None; name = txt
            for i in range(cb.count()):
                if cb.itemText(i).lower() == txt.lower():
                    tid = cb.itemData(i); name = cb.itemText(i); break
            if tid is None and cb.currentIndex() >= 0:
                tid = cb.itemData(cb.currentIndex()); name = cb.currentText()
            if tid is None:
                return
            dlg.accept()
            self.open_build_detail(int(tid), name, fresh=True)
        openb.clicked.connect(_open)
        cb.lineEdit().returnPressed.connect(_open)
        dlg.exec()

    def _ladezeit_warten(self):
        """Die Oberflaechen-Messung endet, sobald kein Hintergrund-Job mehr
        laeuft und die Oberflaeche zweimal in Folge ruhig war (alle 500 ms
        geprueft), spaetestens nach 20 Minuten."""
        import time
        t0 = time.time()
        ruhig = [0]
        tm = QTimer(self)
        tm.setInterval(500)

        def _pruefen():
            if not ladezeit.ui_laeuft():
                tm.stop(); tm.deleteLater()
                return
            if time.time() - t0 > 1200:
                ruhig[0] = 99
            elif time.time() - t0 > 2 and not getattr(self, "_workers", None):
                ruhig[0] += 1
            else:
                ruhig[0] = 0
            if ruhig[0] >= 2:
                tm.stop(); tm.deleteLater()
                ladezeit.ui_stop()
        tm.timeout.connect(_pruefen)
        tm.start()

    def open_build_detail(self, type_id, name, fresh=False):
        """fresh=True: ausdruecklich ein NEUER Bauplan (Scanner-Rechtsklick,
        "Neuer Bauplan", Bauen-Tab). Dann wird IMMER auf Standard
        zurueckgesetzt - Menge 1, ME/TE-Standard, kein Einfrieren, kein
        eingefuegter Bestand, keine Plan-Bindung.

        BUG, den das behebt (Nutzer-Meldung): der Zuruecksetz-Zweig haengte
        allein an "anderes Item als zuletzt" (`_bd_bp_type != type_id`).
        Wer denselben Artikel erneut oeffnete - etwa nachdem er den
        gespeicherten Plan geloescht hatte - bekam den kompletten alten
        Zustand zurueck (Menge 20, bearbeitete Werte, Einfrier-Stand), weil
        der lebt in den `_bd_*`-Attributen des Fensters und nicht im
        gespeicherten Plan. Loeschen konnte das gar nicht aufraeumen.
        """
        # LADEZEIT-MESSUNG (nur mit EMM_LADEZEIT=1): vom Klick bis alles ruhig.
        if ladezeit.AN:
            ladezeit.ui_start(f"open build plan: {name}")
            self._ladezeit_warten()
        if not industry.sde_ready():
            self.build_status.setText(t("Run \u201eLoad recipes\u201c first."))
            return
        # NETZ: ohne eine einzige Rollen-Zuweisung bleiben Runplaner UND
        # Blueprints-Reiter leer (Nutzer, Sitzung 20: "beim Erstoeffnen muss
        # da etwas angehackt sein sonst sehen wir keine blueprints"). Greift
        # nur im vollstaendig leeren Zustand - eine bewusste Abwahl bleibt.
        try:
            self._bau_rollen_netz()
        except Exception:
            pass
        # Gelegenheit nutzen: hier interessiert der Bestand, also im
        # Hintergrund pruefen, ob neue Asset-Orte dazugekommen sind.
        # Drosselung und Bedingungen stecken in der Methode selbst.
        try:
            self._maybe_autodiscover_structures()
        except Exception:
            pass
        if fresh:
            # Pending-Payloads eines zuvor geladenen GESPEICHERTEN Plans
            # verwerfen - sonst sickern sie in den frischen Plan.
            self._bd_bp_pending = None
            self._bd_frozen_pending = None
            self._bd_manual_pending = None
            self._bd_manual_meta_pending = None
            # erzwingt unten den Zuruecksetz-Zweig, auch bei GLEICHEM Item
            self._bd_bp_type = None
        # Blaupausen-Einstellungen sind pro Bauplan → bei Item-Wechsel zurücksetzen
        # (bei „Neu berechnen“ desselben Items bleiben sie erhalten). Ein neuer
        # Bauplan (anderes Item, kein geladener gespeicherter Plan) startet IMMER
        # bei den Standardwerten – Menge 1, ME/TE 0, Puffer/Frachtraum/Transport
        # zurückgesetzt, Blaupausen je Stufe 1×1 (Komponenten/Reaktionen als BPO).
        # EIN NEUER BAUPLAN HAT KEINE KOSTEN - Punkt. Das hing frueher am
        # ITEM-Wechsel, also blieben die Werte stehen, wenn man zweimal
        # hintereinander einen neuen Plan fuer DASSELBE Item aufmachte.
        # `fresh=True` setzen genau die Wege, die einen neuen Plan oeffnen
        # (Scanner, "Neuer Bauplan", Endprodukt bauen); der Loader eines
        # gespeicherten Plans ruft OHNE fresh und bringt seine eigenen Werte
        # mit. "Neu berechnen" laeuft hier gar nicht durch - eingetippte Werte
        # bleiben also waehrend der Arbeit erhalten.
        if fresh:
            self.settings["bau_transport_rate"] = 0.0
            self.settings["bau_transport_trip_cost"] = 0.0
            self.settings["bau_extra_cost"] = 0.0
            # Sicherheit ist eine Entscheidung PRO PLAN - ein neuer Plan
            # startet bei der Vorgabe, nicht beim Wert des letzten.
            self._bd_inv_conf = industry.DEFAULT_INVENTION_CONFIDENCE
            config.save_settings(self.settings)
            # ME/TE DES ENDPRODUKTS EBENFALLS AUF 0 (Nutzer: "wenn ein Bauplan
            # neu aufgeht soll ME und TE im Invention-Tab auf 0 sein, aktuell
            # uebernimmt es die letzte Einstellung"). Das hing bisher am
            # ITEM-Wechsel - genau dieselbe Falle wie bei den Kosten. Und der
            # Ausgangswert ist bewusst 0, nicht `bau_me`: eine frisch
            # erfundene T2-Blaupause ist unerforscht. Die KATEGORIE-ME/TE
            # (Komponenten, Fuel, ...) bleiben davon unberuehrt - die sind
            # Erfahrungswerte des Nutzers und gelten weiter als Standard.
            self._bd_me = 0
            self._bd_te = 0
        # WIRD GERADE EIN GESPEICHERTER PLAN GELADEN? Das muss AUSDRUECKLICH
        # bekannt sein. Frueher diente `_bd_bp_pending is not None` als
        # Ersatz-Erkennung - und genau das war der Bug (Nutzer: "selbst
        # eingegebene ME wird nicht richtig abgespeichert, beim naechsten
        # Oeffnen steht MANCHMAL wieder 0"): ein Plan, der beim Speichern
        # keine Blaupausen-Nutzlast hatte (`"bp": None`), sah beim Laden aus
        # wie ein NEUER Plan. Der Zuruecksetz-Zweig unten hat dann alles
        # ueberschrieben, was `_open_saved_plan` gerade geladen hatte - ME,
        # TE, "Eigene BPC", Decryptoren, manuelle Versuche. "Manchmal", weil
        # es allein davon abhing, ob der Plan zufaellig eine bp-Nutzlast
        # hatte. `fresh` gewinnt immer (ein neuer Plan ist ein neuer Plan),
        # und die Marke wird hier verbraucht, damit sie nicht stehenbleibt.
        _loading_saved = bool(getattr(self, "_bd_loading_saved", False)) and not fresh
        self._bd_loading_saved = False
        if getattr(self, "_bd_bp_type", None) != type_id:
            if getattr(self, "_bd_bp_pending", None) is not None:
                self._bd_bp = self._bd_bp_pending      # aus gespeichertem Bauplan
                self._bd_bp_pending = None
            elif _loading_saved:
                # Gespeicherter Plan OHNE Blaupausen-Nutzlast: nur die
                # Blaupausen-Stufen leeren. Alles andere hat der Loader
                # soeben gesetzt und ist die Absicht des Nutzers.
                self._bd_bp = None
            else:
                self._bd_bp = None
                self._bd_qty = 1
                self._bd_me = 0
                self._bd_te = 0
                # Nutzer-Wunsch: die zuletzt eingestellten Kategorie-ME/TE
                # gelten als STANDARD fuer jeden neuen Plan. Vorher stand hier
                # hart 10/20 - wer z.B. T1-Huellen auf 8 % stellte, hatte das
                # beim naechsten neuen Bauplan wieder verloren.
                for _ca, _cv in self._cat_me_te_defaults(self.settings).items():
                    setattr(self, _ca, _cv)
                self._bd_decryptor_map = {}   # neuer Plan -> keine alten Decryptoren
                self._bd_dec_bestaetigt = set()  # neuer Plan -> Decryptor-Warnung scharf
                self._bd_manual_attempts = {}   # neuer Plan -> keine alte manuelle Versuchszahl
                self._bd_own_bpc = False        # neuer Plan -> Invention-Tab wieder aktiv
                self._bd_own_bpc_runs = 0       # neuer Plan -> Runs/BPC-Feld zurückgesetzt
                self._bd_invention_char = 0     # neuer Plan -> wieder "Bester automatisch"
                self._bd_inv_split = {}         # neuer Plan -> Invention-Regler ganz links (emm328)
                self._bd_end_bpc_esi = None      # neuer Plan -> ESI-Blaupausen-Ladestand weg
                self._bd_me_manuell = False      # neuer Plan -> ME/TE wieder aus ESI vorbelegen
                # NEUER PLAN = STANDARDEINSTELLUNG (Nutzer, Sitzung 20).
                # Blacklist und die zwei Invention-Haken sind Sache DIESES
                # Plans, nicht des Programms. Vorher blieben sie global
                # stehen: was man in einem Plan eintrug, galt beim naechsten
                # weiter - auch wenn man gar nicht gespeichert hatte.
                # Ein GESPEICHERTER Plan bringt seine eigenen Werte mit
                # (s. _open_saved_plan) und ueberschreibt diese Vorgaben
                # danach wieder.
                # Dazu seit 19.09.2026 die zwei Reprocessing-Haken (Nutzer:
                # "bei einem neuen ungespeicherten Bauplan bitte beide
                # immer OFF").
                _std = config.DEFAULT_SETTINGS
                for _sk in ("bau_blacklist_names", "bau_blacklist_gruppen",
                            "bau_buy_datacores", "bau_buy_decryptors",
                            "bau_reprocess_on", "bau_unrefined_on"):
                    _v = _std.get(_sk)
                    self.settings[_sk] = (list(_v) if isinstance(_v, list)
                                          else _v)
                self._bd_owned_bpc_by_id = None
                self._bd_owned_bpc_bpo_ids = None
                self._bd_stage_bp_esi = None
                self._bd_owned_bp = None        # neuer Plan -> Standard "besitze alles"
                # Automatisch prüfen, was laut ESI schon vorhanden ist, statt
                # das Häkchen "📦 Assets abziehen" jedes Mal manuell zu setzen -
                # gilt auch für frische (nicht gespeicherte) Pläne, nicht nur
                # beim Wiederöffnen eines gespeicherten Plans.
                self._bd_restore_assets_toggle = True
                self._bd_force = False
                self._bd_prefer_owned = True    # neuer Plan -> Standard AN (auf Wunsch)
                self._bd_ladder_result = None
                self._bd_ladder_pending = False
                self._bd_open_plan_id = None    # neuer Plan -> keine Auto-Speicherung
                self._bd_frozen = None          # neuer Plan -> nicht eingefroren
                # Verkaufscharakter: bester (guenstigste Gesamtgebuehr).
                self._bd_sell_hub = "jita"     # Standard-Verkaufsort
                self._bd_hub_sell_price = None
                self._bd_contract_sell = None   # neuer Plan -> Contract-Preis-Wahl weg
                self._bd_sell_char = self._best_sell_char(
                    self.settings.get("char_fees") or {})
                self._bd_manual_stock = {}      # neuer Plan -> kein Fremd-Bestand
                self._bd_manual_ts = None       # ... und kein Einfüge-Zeitstempel
                # Dauerhaft-Haeckchen STANDARD AN (Nutzer): wer von Hand
                # einfuegt, tut das gerade weil ESI es nicht sieht. Ohne den
                # Haken faellt der Wert beim naechsten Abruf still auf 0.
                self._bd_manual_perm = True
                self._bd_manual_only = False    # ... ESI-Lagerbestand normal an
                self._bd_manual_unknown = []    # ... keine alte Trefferbilanz
                self._bd_manual_legacy = False
                self._bd_stock_src = {}         # ... keine alte Herkunfts-Karte
                self._bd_esi_stock_base = None  # ... kein alter Lager-Baustein
                self._bd_virt_stock = {}        # ... keine alte Pipeline
                self._bd_esi_stock_ts = None    # ... kein altes ESI-Datenalter
                self._bd_runplan_delivered_sicher = {}   # ... und keine alte Liefer-Karte
                self._bd_runplan_checked = set()  # neuer Plan -> keine alten Runplaner-Häkchen
                self._bd_runplan_ts = {}        # ... und keine alten Haken-Zeitstempel
                # ... und KEINE erledigten Runs des vorigen Plans (Nutzer
                # 29.09.2026: "neuen Multiplan erstellt und gespeichert, der
                # Runplaner hat gruene Haken gesetzt, die ich nie gemacht
                # habe"). Aus ihnen setzt `haken_nachtragen` Haken auf
                # gleiche Items - und Speichern schrieb sie fest.
                self._bd_runplan_erledigt = {}
                self._bd_runplan_erledigt_ts = {}
                self._bd_active_jobs_map = {}   # neuer Plan -> keine alten "läuft schon"-Marker
                self._bd_active_jobs_alle = {}  # ... auch nicht ungefiltert
                self._bd_active_unzugeordnet = {}
                self._bd_delivered_jobs = []    # ... und keine alten Fortschritts-Jobs
                # ... und KEINE geerbte "war gedeckt"-Erinnerung: sonst
                # meldete ein frischer Plan Verluste, die zum vorherigen
                # gehoerten.
                self._bd_covered_once = set()
                self.settings["bau_buy_surplus"] = 0
                self.settings["bau_transport_m3"] = 350000
                # "bau_transport_mode" ist Geschichte (beide Kostenarten
                # zaehlen jetzt gleichzeitig) - nur noch als Migrationsmarker
                # in config.load_settings relevant.
                self.settings["bau_transport_rate"] = 0.0
                self.settings["bau_transport_trip_cost"] = 0.0
                self.settings["bau_extra_cost"] = 0.0
                config.save_settings(self.settings)
            self._bd_bp_type = type_id
        # MULTI-BAUPLAN (1.0.9): das Buendel bringt seine Enden und die
        # ME/TE je Ende als Pending mit (mw_multi_bauplan._multi_plan_oeffnen)
        # - NACH dem Zuruecksetz-Zweig verbraucht, damit es ihn ueberlebt.
        # Ein normaler Plan leert die Felder, sonst saehe er die Enden des
        # letzten Buendels. "Neu berechnen" desselben Buendels (kein
        # Pending) behaelt sie.
        _bp_multi = getattr(self, "_bd_buendel_pending", None)
        self._bd_buendel_pending = None
        if type_id == industry.BUENDEL_ID and _bp_multi:
            self._bd_buendel_enden = list(_bp_multi.get("enden") or [])
            self._bd_buendel_quellen = list(_bp_multi.get("quellen") or [])
            self._bd_me_je_ende = dict(_bp_multi.get("me") or {})
            self._bd_te_je_ende = dict(_bp_multi.get("te") or {})
            self._bd_own_bpc_je_ende = dict(_bp_multi.get("own_bpc") or {})
            self._bd_own_bpc_runs_je_ende = dict(_bp_multi.get("own_bpc_runs") or {})
            self._bd_qty = 1
        elif type_id != industry.BUENDEL_ID:
            self._bd_buendel_enden = None
            self._bd_buendel_quellen = []
            self._bd_me_je_ende = {}
            self._bd_te_je_ende = {}
            self._bd_own_bpc_je_ende = {}
            self._bd_own_bpc_runs_je_ende = {}
        elif not getattr(self, "_bd_buendel_enden", None):
            QMessageBox.information(self, t("Multi build plan"),
                                    t("This multi build plan has no end products."))
            return
        # Eingefrorenen Zustand übernehmen (aus gespeichertem Plan) bzw. bei
        # frischem Item-Wechsel zurücksetzen. Sentinel-Muster wie _bd_bp_pending:
        # der Plan-Loader legt das Payload in _bd_frozen_pending ({} = Plan war
        # ausdrücklich NICHT eingefroren).
        _fp = getattr(self, "_bd_frozen_pending", None)
        if _fp is not None:
            self._bd_frozen = _fp or None
            self._bd_frozen_pending = None
            self._bd_frozen_plan_cache = None   # anderer Plan -> anderer Snapshot
            # ... UND DIE ORDERBUCH-LADDER DES VORIGEN PLANS WEG. Sie wurde
            # nur beim NEUEN Plan zurueckgesetzt, nicht beim Oeffnen eines
            # gespeicherten: wer einmal "Neu berechnen" gedrueckt hatte, trug
            # die gecachten Orderbuecher in JEDEN danach geoeffneten Plan
            # mit - dessen Materialkosten wurden dann gegen die Buecher eines
            # ANDEREN Bauplans gerechnet. Genau dieselbe Fehlerklasse wie
            # "eine Liste verliert ihre Einschraenkung" (Sitzung 22).
            self._bd_ladder_result = None
            self._bd_ladder_pending = False
        _mp = getattr(self, "_bd_manual_pending", None)
        if _mp is not None:
            self._bd_manual_stock = {int(k): int(v) for k, v in (_mp or {}).items()}
            _meta = getattr(self, "_bd_manual_meta_pending", None) or {}
            _ts = _meta.get("ts")
            self._bd_manual_perm = bool(_meta.get("perm", False))
            self._bd_manual_only = bool(_meta.get("only", False))
            self._bd_manual_unknown = []
            # MIGRATION: Pläne, die VOR der Zeitstempel-Automatik gespeichert
            # wurden, haben eine Einfügung ohne Datum. Altes Verhalten war
            # „gilt immer" - das bilden wir 1:1 ab (ts=0 + permanent), damit
            # niemandem still Bestand verschwindet. Der Legacy-Marker sorgt
            # dafür, dass das Panel es SAGT, statt es zu verstecken; beim
            # nächsten „Übernehmen" ist der Sonderfall weg.
            if self._bd_manual_stock and _ts is None:
                self._bd_manual_ts = 0.0
                self._bd_manual_perm = True
                self._bd_manual_legacy = True
            else:
                self._bd_manual_ts = float(_ts) if _ts else None
                self._bd_manual_legacy = False
            self._bd_manual_pending = None
            self._bd_manual_meta_pending = None
        # BAU-ODER-KAUF-WAHL eines neu aufgebauten Buendels (emm317, s.
        # _multi_plan_oeffnen) - NACH dem Zuruecksetzen einsetzen.
        _bw = getattr(self, "_bd_wahl_pending", None)
        self._bd_wahl_pending = None
        if _bw:
            self._bd_owned_bp = (list(_bw["owned_bp"])
                                 if _bw.get("owned_bp") is not None else None)
            self._bd_force = bool(_bw.get("force"))
            self._bd_prefer_owned = bool(_bw.get("prefer"))
        # MITGENOMMENER BESTAND (emm308): das Fenster oeffnet an Stelle eines
        # offenen neu (Ende anhaengen u. a.) - dessen Lager gilt, bis der
        # eigene Assets-Abruf (unten angestossen) ihn ersetzt. Nicht bei
        # eingefrorenem Plan: dort zaehlt der Einfrier-Stand.
        _bm = getattr(self, "_bd_bestand_pending", None)
        self._bd_bestand_pending = None
        _bm_stock = None
        if _bm and not getattr(self, "_bd_frozen", None):
            self._bd_esi_stock_base = dict(_bm.get("base") or {})
            self._bd_virt_stock = dict(_bm.get("virt") or {})
            self._bd_esi_stock_ts = _bm.get("ts")
            _bm_stock, _ = self._recompute_bd_stock()
        # FIX (U1): "Assets abziehen" bei JEDEM Öffnen automatisch anstoßen -
        # nicht nur beim Item-Wechsel. Vorher startete das Häkchen beim
        # Wiederöffnen DESSELBEN Items aus (Einmal-Flag war verbraucht), der
        # Plan rechnete dann ohne Lagerbestand -> scheinbar zufällig mal mehr,
        # mal weniger Materialien/Reaktions-Runs/Volumen, je nach Öffnungsweg.
        # AUCH für eingefrorene Pläne: der Live-Abruf läuft mit, wird dort
        # aber per max(eingefroren, live) GEMISCHT statt zu ersetzen (s.
        # _merge_frozen_stock) - sonst wurden seit dem Einfrieren gebaute
        # Zwischenprodukte nie gutgeschrieben und der Runplaner plante sie
        # tagelang immer wieder neu (Nutzer-Fall).
        self._bd_restore_assets_toggle = True
        snapshot = store.get_snapshot()
        if not snapshot:
            QMessageBox.information(self, t("Build plan"),
                                   t("Run \u201eMarket scan\u201c first - the market prices are missing."))
            return
        me_bp = getattr(self, "_bd_me", None)
        if me_bp is None:
            me_bp = int(self.settings.get("bau_me", 10))
        rig = self._bau_rig_me()
        eff_me = (1 - (1 - me_bp / 100.0) * (1 - rig / 100.0)) * 100.0
        opts = {
            "me": eff_me,
            "job_pct": self.settings.get("bau_job_pct", 3),
            "build_reactions": True,   # immer einrechnen – Tool entscheidet Bau/Kauf per Menge
            "invention": bool(self.settings.get("bau_invention", False)),
            "force_build": bool(getattr(self, "_bd_force", False)),
            "prefer_build_if_owned": bool(getattr(self, "_bd_prefer_owned", False)),
            "tree_depth": 6,
        }
        if _bm_stock:
            opts["stock"] = dict(_bm_stock)   # emm308, s. oben
        opts.update(self._bau_decryptor_opts())
        opts["inv_decryptor_map"] = self._resolve_inv_decryptor_map()
        opts["inv_manual_attempts"] = self._resolve_inv_manual_attempts()
        # INVENTION-SICHERHEIT (Nutzer einstellbar, Vorgabe 75 %): wie
        # wahrscheinlich die geplanten Versuche wirklich reichen. Sie aendert
        # NICHT die Erfolgschance je Versuch, sondern nur, fuer wieviel Pech
        # man Material einkauft. `_inv_cost` liest den Schluessel seit jeher -
        # er wurde bloss nie gesetzt, also galt immer die Konstante.
        opts["inv_confidence"] = self._bd_inv_confidence()
        opts["inv_skill_modifier"] = self._resolve_inv_skill_modifiers()
        opts["inv_owned_runs"] = self._resolve_inv_owned_runs()
        opts.update(self._bau_jobcost_opts())
        opts["te_factor"] = self._bau_te_factor()            # Zeit: BP-TE × Rig
        opts["te_factor_reaction"] = self._bau_te_factor_reaction()
        self.build_status.setText(t("Calculating build plan for {name} \u2026").format(name=name))

        def job():
            if getattr(self, "_adj_prices", None) is None:
                try:
                    # BEIDE Preisarten in EINEM Abruf (Sitzung 14): `adjusted`
                    # fuer die Job-Kosten wie bisher, `average` als
                    # Rueckfall-Preis fuer Material, das gerade NIRGENDS im
                    # Orderbuch steht. Ohne den fiel so ein Material still auf
                    # 0 ISK - der Bauplan sah dadurch doppelt so guenstig aus,
                    # wie er ist (Nutzer: "es ist nicht moeglich dass eine
                    # Ametat II nur 10 mio kostet").
                    _mp = esi.market_prices()
                    self._adj_prices = _mp["adjusted"]
                    self._avg_prices = _mp["average"]
                except Exception:
                    self._adj_prices = {}
                    self._avg_prices = {}
            recipes = industry.recipes_cached()
            pm = {s["type_id"]: s["sell_min"] for s in snapshot if s["sell_min"] > 0}
            adj = dict(self._adj_prices or {})
            # MULTI-BAUPLAN: Rezept-Kopie mit dem Buendel; sein "Verkaufspreis"
            # ist die Summe der Enden x Menge (fehlt einem Ende der Preis,
            # zaehlt es 0 - der Dialog zeigt es in der Enden-Karte als "-").
            _enden_mb = (list(getattr(self, "_bd_buendel_enden", None) or [])
                         if type_id == industry.BUENDEL_ID else [])
            if _enden_mb:
                recipes = industry.buendel_rezepte(recipes, _enden_mb)
                pm[industry.BUENDEL_ID] = self._multi_buendel_verkauf(pm, _enden_mb)
                # SCHRITT 4: "Eigene BPC" je Ende -> inv_manual_override je
                # Blaupause. MUSS hier stehen, VOR dem ersten build_tree:
                # sonst rechnet der erste Baum noch mit der Invention-ME.
                #
                # KEINE ZUWEISUNG AN `opts` (Nutzer-Befund 20.09.2026: "Open
                # build plan" oeffnete kein Fenster, Statuszeile sagte
                # "cannot access local variable 'opts'"). `opts` gehoert der
                # AEUSSEREN Funktion; ein `opts = ...` hier drin macht daraus
                # eine lokale Variable von job() - und dann ist JEDER Zugriff
                # auf opts in job() unbelegt, auch dieser. Die Methode
                # aendert das Woerterbuch ohnehin an Ort und Stelle.
                self._multi_opts_je_ende(opts, recipes)
            _frozen = getattr(self, "_bd_frozen", None)
            if _frozen:
                # "Alle Materialien gekauft": Kostenseite komplett auf dem Stand
                # des Einfrier-Zeitpunkts festnageln - Materialpreise, Adjusted-
                # Preise (EIV/Jobkosten), System-Kostenindizes und Lagerbestand.
                # NUR der Verkaufspreis des ENDPRODUKTS bleibt live, damit man
                # Wochen später sieht: "damals für X gekauft -> heute für Y
                # verkaufbar = Gewinn Z". (JSON macht aus Dict-Keys Strings ->
                # beim Lesen zurück auf int.)
                _live_sell = pm.get(type_id)
                pm = {int(k): v for k, v in (_frozen.get("prices") or {}).items()}
                if _enden_mb:
                    _live_sell = self._multi_buendel_verkauf(pm, _enden_mb)
                if _live_sell and _live_sell > 0:
                    pm[type_id] = _live_sell
                _fadj = {int(k): v for k, v in (_frozen.get("adjusted") or {}).items()}
                if _fadj:
                    adj = _fadj
                if _frozen.get("cost_idx"):
                    self._bau_cost_idx = {int(k): v for k, v
                                          in _frozen["cost_idx"].items()}
                # "Neu berechnen" darf die Herkunfts-Auflösung nicht umgehen -
                # sonst wären eingefügte Mengen bei eingefrorenen Plänen bis
                # zum nächsten Assets-Abruf wieder weg (dieselbe Fehlerklasse
                # wie damals bei _bd_live_stock).
                _fz_base = self._merge_frozen_stock(
                    _frozen.get("stock") or {},
                    getattr(self, "_bd_live_stock", None) or {})
                _fz_stock, _fz_src = self._resolve_stock_sources(
                    _fz_base, {},
                    getattr(self, "_bd_manual_stock", None) or {},
                    manual_ts=getattr(self, "_bd_manual_ts", None),
                    esi_ts=getattr(self, "_bd_esi_stock_ts", None),
                    manual_permanent=bool(getattr(self, "_bd_manual_perm", False)),
                    manual_only=bool(getattr(self, "_bd_manual_only", False)))
                # DIESELBE Reservierungs-Regel wie der Live-Weg (Sitzung 20).
                self._reservierungen_anwenden(_fz_stock)
                opts["stock"] = _fz_stock
                self._bd_stock_src = _fz_src
            if not adj:                        # ESI-Adjusted leer → Markt als EIV-Basis
                adj = dict(pm)
            opts["adjusted_prices"] = adj
            opts["average_prices"] = dict(getattr(self, "_avg_prices", None)
                                          or {})
            # REPROCESSING (1.0.9, Weg B): nur mit Schalter - sonst fehlt der
            # Schluessel und der Plan rechnet exakt wie bisher.
            _ro = self._reprocess_opts()
            if _ro:
                opts["reprocess"] = _ro
            # Schritt 3: Struktur-Boni. Nur wenn Strukturen angelegt sind; sonst
            # bleibt das alte Setup-Verhalten. Die Auswahl der besten Struktur je
            # Aktivität ist item-abhängig → passiert unten (nach groups).
            struct_on = bool(self.settings.get("bau_structures"))
            if struct_on and getattr(self, "_bau_cost_idx", None) is None:
                try:
                    self._bau_cost_idx = esi.system_cost_indices()
                except Exception:
                    self._bau_cost_idx = {}
            tree = industry.build_tree(type_id, pm.get, recipes, opts)
            ids = set([type_id])

            def walk(n):
                if not n:
                    return
                for c in n["components"]:
                    ids.add(c["type_id"])
                    walk(c.get("subtree"))
            walk(tree)
            # WICHTIG: obiger Baum ist auf tree_depth=4 begrenzt (nur fürs
            # Anzeigen gedacht) - production_plan() geht dagegen bis
            # max_depth=12. Ohne diesen zweiten, voll aufgeklappten Discovery-
            # Lauf fehlten tief verschachtelte Reaktionen (z.B. Composite-
            # Reactions wie Nonlinear Metamaterials, mehrere Stufen unter
            # einem Capital-/T3-Bauteil versteckt) im "ids"-Set - und damit
            # auch in me_map/me_map_reaction weiter unten. Die bekamen dadurch
            # STILLSCHWEIGEND 0% Struktur-ME statt des echten Rig-Bonus (genau
            # das gemeldete 1200-statt-1174-Problem bei Nonlinear Metamaterials).
            try:
                _deep_opts = dict(opts); _deep_opts["tree_depth"] = 99
                _deep_tree = industry.build_tree(type_id, pm.get, recipes, _deep_opts)
                walk(_deep_tree)
            except Exception as _deep_err:
                # NICHT MEHR STILL VERSCHLUCKEN (Sitzung 14): hier stand
                # `except Exception: pass`. Scheitert der Lauf, fehlen genau
                # die tief verschachtelten Items, gegen die er gebaut wurde -
                # und niemand erfaehrt es. Ein Fehler darf den Bauplan nicht
                # aufhalten, aber er gehoert ins Protokoll.
                # de_scan4: aus - Beschriftung fuer fehler.log, nicht Oberflaeche
                self._log_exception("Tiefen-Discovery fuer ids", str(_deep_err))
                # de_scan4: an
            # ITEM-LISTE UNABHAENGIG VON DER KAUF/BAU-ENTSCHEIDUNG (Nutzer,
            # Sitzung 14: "der runplaner zeigt immer dasselbe egal was man in
            # der Fertigungsschleife ankreuzt").
            #
            # `walk()` oben laeuft ueber `build_tree` - und dort haengt der
            # Teilbaum an der Entscheidung (`subtree` ist None, sobald ein
            # Item gekauft wird). Aus DIESER Liste wird `never_build`
            # gebildet. Der Kreis: Item wird gekauft -> kein Teilbaum -> seine
            # Materialien fehlen in `ids` -> werden nie geprueft -> koennen
            # nie abgewaehlt werden -> werden gebaut, egal was angekreuzt ist.
            # Im Container gemessen: Kette 100 -> 201 -> 301 -> 401 ergab bei
            # "bauen" {201,301,401}, bei "kaufen" nur {201}.
            #
            # Die Struktur-Frage "was kommt in dieser Kette vor" darf nicht
            # vom Ergebnis abhaengen, das sie mitbestimmt. Deshalb hier
            # zusaetzlich die reine Rezept-Kette - sie bewertet nichts.
            try:
                ids |= industry.alle_items_der_kette(type_id, recipes)
            except Exception as _kette_err:
                # de_scan4: aus - Beschriftung fuer fehler.log, nicht Oberflaeche
                self._log_exception("Rezeptkette fuer ids", str(_kette_err))
                # de_scan4: an
            qty0 = 1 if _enden_mb else int(getattr(self, "_bd_qty", 1) or 1)
            groups = industry.group_names(list(ids))
            # WICHTIG: "Meine Blueprints"-Ausschlüsse (excluded/never_build) HIER
            # berechnen und setzen - VOR dem finalen (angezeigten) Baum-Aufbau
            # weiter unten. Früher passierte das erst NACH dem zweiten
            # build_tree()-Aufruf, wodurch der angezeigte Rezept-Struktur-Baum
            # "Meine Blueprints" ignorierte (nur reine Kostenvergleiche zeigte),
            # während production_plan() (danach aufgerufen) die Ausschlüsse
            # korrekt anwendete - der Runplaner zeigte dadurch andere Bau/Kauf-
            # Entscheidungen als der Baum. Jetzt sehen beide dieselben Daten.
            bl_names = esi.resolve_names(list(ids))
            # Für "Meine Blueprints"/Blacklist-Checkbox-Handler gecacht (siehe
            # _save_owned_bp/_save_blacklist) - sonst müsste man den ganzen
            # Bauplan-Dialog schließen+neu öffnen, damit ein Checkbox-Klick
            # überhaupt eine Wirkung hat (rebuild() beim "Neu berechnen"-Knopf
            # berechnet never_build/excluded NICHT neu, nutzt nur self._bd_opts).
            self._bd_all_ids = set(ids)
            self._bd_groups_cache = groups
            self._bd_bl_names_cache = bl_names
            opts["excluded"] = self._bau_never_build(list(ids), groups,
                                                        recipes.reaction_products, bl_names)
            # Fuer die Anzeige merken: der Rezept-Baum soll Blacklist-Items
            # als solche benennen statt nur "vorhanden" zu schreiben.
            self._bd_excluded_ids = set(opts["excluded"])
            opts["never_build"] = self._bau_cant_build(list(ids), groups,
                                                       recipes.reaction_products, bl_names,
                                                       type_id, recipes=recipes)
            # Kategorie-Basis-ME (Komponenten/T1-Hüllen/Fuel Blocks/Tools) – IMMER,
            # auch ohne konfigurierte Strukturen. Vorher galt ohne Struktur pauschal
            # die Endprodukt-Blueprint-ME für alles, was zu viel Materialbedarf
            # vorgaukelte (T1-Sachen sind i. d. R. voll ausgeforscht, T2 selten).
            cat_me_map = self._bau_category_me_map(list(ids), groups,
                                                    recipes.reaction_products, type_id,
                                                    recipes=recipes)
            # REPROCESSING WEG A (1.0.9): Unrefined-Reaktionen. Die Wahl
            # faellt HIER, mit den Basis-Rezepten und vor den Rig-ME-Karten
            # (die Reaktions-ME wirkt auf beide Wege gleich); danach laeuft
            # alles Weitere - Rig-Karten, Stufen, Baum, Plan, Runplaner -
            # ueber die Rezept-Kopie, in der X ueber seine Unrefined-Formel
            # gebaut wird. Ohne Schalter: dieselben Rezepte wie bisher.
            self._bd_recipes_basis = recipes
            _uo_opts = dict(opts); _uo_opts.setdefault("me_map", cat_me_map)
            _uo_fest = None
            if _frozen:
                _uo_fz = self._frozen_snapshot_plan()
                if _uo_fz is not None:
                    _uo_fest = (_uo_fz.get("unrefined") or {})
            recipes, _u_wahl = self._unrefined_overlay(type_id, recipes, pm.get,
                                                       _uo_opts, kredit_pfn=pm.get,
                                                       fest=_uo_fest)
            if _u_wahl:
                _u_neu = set()
                for _ux, _uk in _u_wahl.items():
                    _u_neu.add(int(_uk["u"]))
                    _u_neu |= {int(_m) for _m, _q in _uk["mats"]}
                    _u_neu |= {int(_m) for _m in (_uk.get("zurueck_je_run") or {})}
                _u_neu -= ids
                if _u_neu:
                    ids |= _u_neu
                    groups.update(industry.group_names(list(_u_neu)))
            # Kategorie-spezifische Rig-ME pro Item + Auto-Strukturwahl (nur mit Strukturen)
            self._bd_rig_me_map = {}
            self._bd_struct_used = {}
            self._bd_mfg_struct = None
            self._bd_react_struct = None
            if struct_on:
                me_map, me_map_reaction, rig_me_map, used, ec_me_map = self._bau_me_maps(
                    list(ids), groups, recipes.reaction_products, cat_me_map,
                    type_id, recipes=recipes)
                opts["me_map"] = me_map
                opts["me_map_reaction"] = me_map_reaction
                opts["me"] = me_bp                     # Fallback: nur Blueprint-ME
                opts["me_reaction"] = 0
                self._bd_rig_me_map = rig_me_map
                opts["rig_me_map"] = rig_me_map
                opts["ec_me_map"] = ec_me_map          # EC-Rollenbonus fuer invented Items
                # TE / System-Index / Cost-Rig aus den gewählten Strukturen
                cidx = self._bau_cost_idx or {}
                mfg_s = used.get("manufacturing"); rea_s = used.get("reaction")
                self._bd_mfg_struct = mfg_s     # für Kategorie-TE pro Item im Runplaner
                self._bd_react_struct = rea_s
                # JE STUFE die wirklich gewaehlte Struktur merken. _bd_mfg_struct
                # ist die KOMPONENTEN-Struktur (used["manufacturing"] =
                # st_map["components"]) - wer sie fuer "1. Treibstoff" oder
                # "5. Endprodukt" anzeigt, schreibt dort einen falschen Namen
                # hin. Genau daran hing die Simurgh-Frage: der Runplaner zeigte
                # dreimal "Dockside", obwohl fuers Endprodukt intern eine
                # andere Struktur gewaehlt sein kann.
                self._bd_stage_structs = {
                    k: used.get(k) for k in
                    ("components", "endproduct", "reaction_1", "reaction_2")}

                def _sys_idx(s, act):
                    sid = (s or {}).get("system_id")
                    return float((cidx.get(int(sid), {}) or {}).get(act, 0.0) or 0.0) \
                        if sid else 0.0
                if mfg_s:
                    opts["te_factor"] = self._bau_struct_te_factor(mfg_s)
                    opts["cost_rig_mfg"] = self._struct_cost_rig_pct(mfg_s)
                    opts["system_index_mfg"] = _sys_idx(mfg_s, "manufacturing")
                if rea_s:
                    opts["cost_rig_reaction"] = self._struct_cost_rig_pct(rea_s)
                    opts["system_index_reaction"] = _sys_idx(rea_s, "reaction")
                if mfg_s:
                    # Science-Indizes aus dem System der Fertigungs-Struktur
                    # (v1, s. industry.science_job_fee) - Invention und
                    # Kopieren haben im selben System EIGENE Indizes.
                    opts["sci_index_invention"] = _sys_idx(mfg_s, "invention")
                    opts["sci_index_copying"] = _sys_idx(mfg_s, "copying")
                # JE-ITEM-WERTE an die Rechnung durchreichen (Sitzung 9,
                # Simurgh): te_factor/system_index/cost_rig/role_bonus/
                # facility_tax oben sind je AKTIVITAET pauschal und stammen
                # auf der Fertigungsseite aus mfg_s - also aus der
                # KOMPONENTEN-Struktur. Wird das Endprodukt in einer anderen
                # Struktur gebaut, waren Zeit und Jobkosten dort falsch.
                # Die MATERIAL-Rechnung war nie betroffen (rig_me_map lief
                # schon je Item ueber die richtige Stufen-Struktur).
                try:
                    _sm9 = industry.reaction_stage_map(recipes)
                except Exception:
                    _sm9 = {}
                _jc_by_tid = {}
                _te_by_tid = {}
                for _t9 in ids:
                    _s9 = self._bau_struct_fuer_item(
                        _t9, recipes.reaction_products, _sm9, type_id)
                    if not _s9:
                        continue
                    _is_re9 = _t9 in recipes.reaction_products
                    _act9 = "reaction" if _is_re9 else "manufacturing"
                    _typ9 = (_s9.get("type") or "").lower()
                    _jc_by_tid[_t9] = {
                        "system_index": _sys_idx(_s9, _act9),
                        "cost_rig": self._struct_cost_rig_pct(_s9),
                        "role_bonus": self._STRUCT_ROLE_JOBCOST.get(
                            _typ9, 0.0) / 100.0,
                        "facility_tax": float(
                            _s9.get("facility_tax")
                            if _s9.get("facility_tax") is not None
                            else self.settings.get("bau_facility_tax", 0.25)
                        ) / 100.0,
                    }
                    _te_by_tid[_t9] = self._bau_category_te_factor(
                        _t9, groups, recipes.reaction_products, type_id,
                        mfg_struct=_s9, react_struct=_s9, recipes=recipes,
                        opts=opts)
                opts["jobcost_by_tid"] = _jc_by_tid
                opts["te_by_tid"] = _te_by_tid
                assigned = self.settings.get("bau_activity_struct", {}) or {}
                self._bd_struct_used = {
                    "manufacturing": ((mfg_s or {}).get("name"),
                                      bool(assigned.get("manufacturing"))),
                    "reaction": ((rea_s or {}).get("name"),
                                 bool(assigned.get("reaction"))),
                }
                tree = industry.build_tree(type_id, pm.get, recipes, opts)  # Baum m. me_map
            else:
                opts["me_map"] = cat_me_map            # NEU: Kategorie-ME auch ohne Struktur
                tree = industry.build_tree(type_id, pm.get, recipes, opts)
            # EINGEFROREN = auch der PLAN ist eingefroren (Nutzer-Spez):
            # Entscheidungen, Mengen und Runplaner kommen aus dem Schnappschuss
            # vom Einfrier-Zeitpunkt - production_plan wird NICHT aufgerufen
            # (genau der Rechenlauf, der beim Nutzer nach 3 Tagen 2'665 -> 2'789
            # GSC-Runs machte). Alt-Payloads ohne plan_snapshot rechnen weiter
            # wie bisher (nur Preise fest).
            _frozen_plan = self._frozen_snapshot_plan() if _frozen else None
            if _frozen_plan is not None:
                plan = _frozen_plan
            else:
                plan = industry.production_plan(type_id, qty0, pm.get, recipes, opts)
            # ALLE Mengen-Felder des Plans abgrasen, nicht nur buy/build_runs.
            # Der Materialien-Tab zeigt auch `stock_used` und `surplus` an -
            # Items, die vollstaendig aus dem BESTAND gedeckt sind, tauchten
            # dort deshalb als "#16642" auf (Nutzer-Fund, zweite Stelle
            # derselben Fehlerklasse nach dem Rezept-Baum).
            for _pk in self.PLAN_QTY_KEYS:
                ids |= set(plan.get(_pk, {}) or {})
            # AUCH den Baum abgrasen: er geht tiefer als Einkaufs- und
            # Bauliste. Items, die nur dort vorkommen (z.B. Reaktions-
            # Eingaenge, die vollstaendig aus dem Bestand gedeckt sind),
            # standen sonst als "#17888" statt mit Namen da (Nutzer-Fund).
            def _tree_ids(_node, _acc):
                if not isinstance(_node, dict):
                    return
                if _node.get("type_id"):
                    _acc.add(int(_node["type_id"]))
                for _c in (_node.get("components") or []):
                    if isinstance(_c, dict):
                        if _c.get("type_id"):
                            _acc.add(int(_c["type_id"]))
                        _tree_ids(_c.get("subtree"), _acc)
            _tree_ids(tree, ids)
            # Auch alles, was der Plan sonst noch nennt: der BAUM ist
            # tiefenbegrenzt (`tree_depth`), Materialien darunter tauchten
            # sonst als "#16666" auf (Nutzer-Screenshot).
            # "inv_buy"/"inv_stock_used" MUESSEN hier mit rein: die Datacores
            # und Decryptoren standen sonst als "#20411" statt mit Namen da
            # (Nutzer-Screenshot). Sie sind neu im Plan - diese Liste kannte
            # nur die alten Schluessel und hat sie schlicht nie aufgeloest.
            for _k in self.PLAN_QTY_KEYS:
                _d = plan.get(_k) or {}
                if isinstance(_d, dict):
                    ids |= {int(x) for x in _d}
            # Kandidaten-Erze VOR der Namensaufloesung dazu: `kandidaten()`
            # erkennt komprimierte Erze am Namen.
            if opts.get("reprocess"):
                ids |= self._reprocess_erz_ids(pm.get)
            names = esi.resolve_names(list(ids))
            if _enden_mb:
                names[industry.BUENDEL_ID] = name     # das Buendel heisst wie der Plan
            if opts.get("reprocess") and _frozen_plan is None:
                plan = self._reprocess_anwenden(plan, pm.get, names, opts["reprocess"],
                                                kredit_pfn=pm.get)
            # GRUPPEN NACHZIEHEN - dieselbe Logik wie bei den Namen: `groups`
            # wurde oben auf dem FRUEHEN ids-Set berechnet, danach kamen
            # Plan-Schluessel und Baum-Ids dazu (drei Erweiterungen). Die
            # Namen wurden ueber das erweiterte Set aufgeloest, die Gruppen
            # NICHT - genau deshalb standen spaet entdeckte Items (Vanadium,
            # Caesium, Hafnium aus tiefen Reaktionsketten) ohne Gruppe da und
            # wurden frueher als "Rohstoffe" einsortiert. group_names() liest
            # nur die lokale SDE-Datenbank - der Nachzug kostet kein ESI.
            _g_miss = [i for i in ids if i not in groups]
            if _g_miss:
                groups.update(industry.group_names(_g_miss))
            # Kontext für schnelle Neuberechnung bei Mengen-Änderung merken
            self._bd_recipes = recipes
            self._bd_invention_skills_map = industry.bp_invention_skills_map()
            self._bd_pricemap = pm
            self._bd_opts = dict(opts)
            # Plan-Cache verwerfen: der Fingerabdruck deckt nur type_id/qty/
            # opts ab, NICHT die Preise. Werden die ersetzt, muss der Plan neu.
            self._bd_plan_cache = None
            self._bd_type = type_id
            self._bd_name = name
            self._bd_groups = groups
            self._bd_reaction_stages = None   # pro Bauplan neu (Stufen-Kategorie)
            # Orderbuch-genaue Material-Ladder NUR wenn gerade per "Neu berechnen"
            # angefordert (one-shot) - sonst würde jede Mengenänderung im Spinner
            # ungefragt Live-ESI-Abrufe auslösen.
            if getattr(self, "_bd_ladder_pending", False):
                # Aktiver Hub (oben gewählt) – gilt für alle Reiter.
                _l_region, _l_station, _l_struct = self._active_hub()
                if True:
                    try:
                        def _ladder_plan_fn(n):
                            return industry.production_plan(type_id, n, pm.get,
                                                             recipes, opts)

                        def _ladder_orderbook_fn(mtid):
                            try:
                                ob = self._hub_orders(int(mtid), _l_region,
                                                      _l_station, _l_struct)
                                return ob.get("sell", [])
                            except Exception:
                                return []
                        ladder_rows = industry.ladder_cost_curve(
                            [qty0], _ladder_plan_fn, _ladder_orderbook_fn,
                            price_fn=pm.get)
                        self._bd_ladder_result = ladder_rows[0] if ladder_rows else None
                    except Exception:
                        self._bd_ladder_result = None
                self._bd_ladder_pending = False
            sell_val = pm.get(type_id)
            sell_is_contract = False
            if not sell_val:
                try:
                    # DIESELBE REIHENFOLGE WIE DIE CAPITAL-TABELLE
                    # (_compute_capital_costs): erst der regionale Stand,
                    # dann NEW EDEN darueber - der gewinnt.
                    # BIS SITZUNG 22 STAND HIER NUR DIE REGION. Der
                    # Capital-Scan speichert aber nach ALL_REGIONS. Wer im
                    # Capital-Modus Contract-Preise geladen hatte, bekam beim
                    # Oeffnen des Bauplans trotzdem keinen Preis - und ohne
                    # Preis stuerzte der Bauplan ab (Nutzer "buyenne",
                    # 15.09.2026; der Absturz selbst ist mit aa355/b7d
                    # abgefangen). Zwei Ablagen fuer dieselbe Frage.
                    cp = dict(store.get_contract_prices(
                        store.get_scan_region()) or {})
                    cp.update(store.get_contract_prices(
                        store.ALL_REGIONS) or {})
                    cp = cp.get(type_id)
                except Exception:
                    cp = None
                if cp:
                    sell_val = cp["median"]
                    sell_is_contract = True
            return {"tree": tree, "names": names, "sell": sell_val,
                   "sell_is_contract": sell_is_contract, "plan": plan}

        def done(res):
            self.build_status.setText("")
            if not res["tree"]:
                QMessageBox.information(self, t("Build plan"),
                    t("{name} cannot be built, or a material cannot be priced "
                      "(market scan current?).").format(name=name))
                return
            self._show_build_detail(type_id, name, res)

        def fail(msg):
            self.build_status.setText(t("Build plan error: ") + msg)
        self._run(Worker(job), done, fail_cb=fail,
                  label=t("Build plan {name} \u2026").format(name=name))

    def _bd_ladder_ctx(self, qty):
        """EINE Wahrheit darueber, ob die Orderbuch-Ladder fuer `qty` gilt.

        Die gecachten Orderbuecher (`_orderbooks`) gelten fuer JEDE Menge:
        ladder_detail_for_buy() rechnet die Bedarfsliste des AKTUELLEN Plans
        gegen dieselben Buecher neu, ohne Live-Abruf. Nur der eingefrorene
        Skalar `mat_cost_ladder` gehoert zu genau EINER Menge - fehlen die
        Buecher, bleibt es deshalb bei der alten Mengen-Gleichheit.

        Vorher war die Ladder an `ladder["qty"] == qty` gebunden. Folge: eine
        Mengenaenderung im Spinner fiel auf den Flachpreis-Zweig zurueck, der
        den Bestand doppelt zaehlte - dieselbe Kette kostete bei Menge 1
        rund 74 Mio/Stk statt 44,6 Mio/Stk, bis man "Neu berechnen" drueckte.

        Rueckgabe: None (keine gueltige Ladder) oder
        {"ladder", "obs", "qty" (Menge des Abrufs), "same_qty" (bool)}.
        """
        ladder = getattr(self, "_bd_ladder_result", None)
        if not ladder:
            return None
        # EINGEFROREN SCHLAEGT LADDER (Nutzer-Befund 25.09.2026): sein
        # Small Nanobot Accelerator II x160 zeigte im Dialog 3'894'389/Stk,
        # auf der Karte 4'767'285 - und im eingefrorenen Schnappschuss steht
        # 4'767'285. Die Ladder hatte die MATERIALKOSTEN des eingefrorenen
        # Plans mit gecachten Orderbuechern neu bepreist (670'396'800 ->
        # 530'733'296) und damit genau das ueberschrieben, was "eingefroren"
        # zusagt: der Einkauf steht fest. Der Kopf sagt "purchase
        # 15.08.2026", die Zahl darunter kam von heute. Ein eingefrorener
        # Plan rechnet nicht mehr - auch nicht ueber diesen Weg.
        if (getattr(self, "_bd_frozen", None) or {}).get("plan_snapshot"):
            return None
        obs = ladder.get("_orderbooks")
        same_qty = int(ladder.get("qty", -1)) == int(qty or 0)
        if obs is None and not same_qty:
            return None
        return {"ladder": ladder, "obs": obs,
                "qty": int(ladder.get("qty", -1)), "same_qty": same_qty}

    def _bd_update_esi_stand(self, stand=None):
        """Kopfzeile "Bestand (ESI)" im Bauplan neu beschriften.

        Robust gegen einen fehlenden Bauplan-Dialog: adone() laeuft auch,
        wenn der Bauplan gar nicht offen ist - dann gibt es das Label nicht,
        und das darf keinen Fehler werfen.
        """
        lbl = getattr(self, "_bd_esi_stand_lbl", None)
        if lbl is None:
            return
        try:
            if stand is None:
                stand = store.asset_snapshot_info()
            lbl.setText(self.bestand_stand_text(stand))
        except Exception as _st_err:
            # Die Anzeige darf den Bauplan NIE aufhalten - lieber leer als tot.
            self._log_exception("Bestands-Zeitstempel", str(_st_err))
            lbl.setText(t("Stock (ESI): state unknown"))


    @staticmethod
    def _absatz_region(hub_key=None):
        """Region des Verkaufs-Hubs (NPC-Hub-Schluessel), sonst die Scan-Region."""
        for _k, _l, _rid, _sid in hubs.NPC_HUBS:
            if hub_key and _k == hub_key:
                return _rid
        try:
            return store.get_scan_region() or config.FORGE_REGION
        except Exception:
            return config.FORGE_REGION

    def _absatz_je_typ(self, tids, region=None):
        """{type_id: Ø verkaufte Stueck/Tag oder None} aus der LOKALEN Markt-
        Historie (emm349) - kein Netz, darf im Hintergrund laufen."""
        from .mw_helpers import tagesvolumen
        region = region or self._absatz_region()
        ids = sorted({int(t) for t in (tids or []) if t})
        try:
            h = store.get_histories(ids, region) if ids else {}
        except Exception:
            h = {}
        return {t: tagesvolumen(h.get(t)) for t in ids}

    def _absatz_nachladen(self, tids, region=None, fertig=None):
        """Fehlende Historien im Hintergrund per ESI holen - je Typ und Region
        nur EINMAL je Sitzung (kein Kreisverkehr), hoechstens 400 je Lauf.
        `fertig()` danach (Anzeige neu). -> True, wenn ein Abruf startet."""
        region = region or self._absatz_region()
        versucht = getattr(self, "_absatz_versucht", None)
        if versucht is None:
            versucht = self._absatz_versucht = set()
        neu = [int(t) for t in (tids or []) if t and (region, int(t)) not in versucht]
        if not neu:
            return False
        for _t in neu:
            versucht.add((region, _t))

        def job():
            from .. import scanner as _sc
            n = 0
            for _t in neu[:400]:
                try:
                    _sc.history_cached(_t, region)
                except Exception:
                    break                    # Rate-Limit o. ae.: spaeter wieder
                n += 1
            return n

        def done(_n):
            if fertig is not None:
                try:
                    fertig()
                except Exception as _fe:
                    self._log_exception("Absatz nachladen", str(_fe))
        self._run(Worker(job), done, overlay=False)
        return True

    def _item_volumes_with_esi_fix(self, type_ids):
        """Volumen-Map (type_id -> m³) für eine Einkaufsliste, mit ESI-Korrektur
        für Schiffe/Strukturen ohne gepacktes Volumen in der lokalen SDE (manche
        SDE-Konvertierungen haben invVolumes nicht/unvollständig -> item_volume_map
        fällt dann auf die AS-FIT-Größe zurück, die für Fracht massiv zu groß ist,
        z.B. Cormorant ~47'000 statt ~2'500 m³ gepackt). esi.resolve_volumes nutzt
        packaged_volume direkt von CCP, braucht keine Auth, cached lokal.
        Rückgabe: (vols_dict, unresolved_ships) - unresolved_ships sind Schiffe,
        die auch nach dem ESI-Versuch noch die AS-FIT-Größe nutzen (z.B. weil
        ESI gerade nicht erreichbar war)."""
        ids = list(type_ids or [])
        vols = industry.item_volume_map(ids) if ids else {}
        unpkg_ships = industry.ships_with_unpackaged_volume(ids) if ids else set()
        if unpkg_ships:
            try:
                esi_vols = esi.resolve_volumes(unpkg_ships)
                for tid, v in esi_vols.items():
                    if v:
                        vols[tid] = v
                        unpkg_ships.discard(tid)
            except Exception:
                pass
        return vols, unpkg_ships

    def _buy_surplus_qty(self, qty):
        """Menge inkl. Material-Überschuss (bau_buy_surplus %), immer aufgerundet."""
        import math
        s = float(self.settings.get("bau_buy_surplus", 0) or 0)
        return max(1, int(math.ceil(qty * (1 + s / 100.0))))

    def _plan_to_cart(self, plan, names):
        if not plan or not plan.get("buy"):
            self._flash_tip(t("Nothing to buy"))
            return
        buy = plan["buy"]
        items = [(tid, names.get(tid, f"#{tid}")) for tid in buy]
        # Mengen mitgeben: erst damit kann der Dialog Benoetigt/Besitze/Fehlt
        # mit Ampelfarben zeigen statt nur „ist schon da".
        # WARNUNG, bevor etwas in den Wagen wandert: passt die Einkaufsliste
        # ueberhaupt in eine Fahrt? Diese Pruefung stand vorher NUR in der
        # Transportzeile des Dialogs - wer die ausblendet, verliert sie.
        _ti = getattr(self, "_bd_transport", None) or {}
        if _ti.get("over_capacity"):
            from PySide6.QtWidgets import QMessageBox as _QMB
            _v = _ti.get("volume", 0) or 0
            _cap = _ti.get("capacity", 0) or 0
            _n = _ti.get("trips", 0) or 0
            if _QMB.question(
                    self._tool_parent(), t("Does not fit in one trip"),
                    t("The shopping list has {vol} m\u00b3, your cargo hold {cap} m\u00b3.\n"
                      "That is {n} trips.\n\nAdd anyway?").format(
                        vol=f"{_v:,.0f}".replace(",", "'"),
                        cap=f"{_cap:,.0f}".replace(",", "'"), n=_n),
                    _QMB.Yes | _QMB.Cancel, _QMB.Yes) != _QMB.Yes:
                return
        _cart_qty = {}
        keep = {_tid for _tid, _n in self._cart_conflict_filter(
            items, needed=buy, qty_out=_cart_qty, show_all=True,
            plan_stock=(getattr(self, "_bd_opts", None) or {}).get("stock"))}
        cart = self._cart_ids()
        added = 0
        for tid, qty in buy.items():
            if tid not in keep or tid in cart:
                continue
            # Die im Dialog gezeigte FEHLMENGE ist auch die, die gekauft wird.
            # Vorher landete hier die volle Plan-Menge, obwohl der Dialog
            # "es fehlen N" anzeigte (Nutzer-Meldung).
            qty = _cart_qty.get(tid, qty)
            if qty <= 0:
                continue
            store.add_shopping(tid, names.get(tid, f"#{tid}"),
                               self._buy_surplus_qty(qty), 0, 0, source="build")
            added += 1
        # Datacores/Decryptoren aus dem Invention-Tab mit einkaufen, falls die
        # entsprechenden Checkboxen ("🧪 Inventions miteinbeziehen") an sind.
        want_dc = bool(self.settings.get("bau_buy_datacores", True))
        want_dcy = bool(self.settings.get("bau_buy_decryptors", True))
        added_inv = 0
        covered_by_stock = 0
        if want_dc or want_dcy:
            from collections import defaultdict
            need = defaultdict(float)
            for info in (getattr(self, "_bd_invention_needs", None) or {}).values():
                if want_dc:
                    for d, q in (info.get("datacores") or []):
                        if q > 0:
                            need[d] += q
                if want_dcy and info.get("decryptor_id") and info.get("decryptor_qty", 0) > 0:
                    need[info["decryptor_id"]] += info["decryptor_qty"]
            # Schon vorhandene Menge (aus "📦 Assets abziehen", falls genutzt)
            # abziehen - vorher wurde IMMER der volle Brutto-Bedarf gekauft,
            # egal was schon im Hangar lag.
            stock = (getattr(self, "_bd_opts", None) or {}).get("stock") or {}
            for tid in list(need):
                owned = stock.get(tid, 0) or 0
                if owned > 0:
                    reduced = max(0.0, need[tid] - owned)
                    covered_by_stock += need[tid] - reduced
                    need[tid] = reduced
                if need[tid] <= 0:
                    del need[tid]
            if need:
                try:
                    inv_names = esi.resolve_names(list(need))
                except Exception:
                    inv_names = {}
                cart = self._cart_ids()   # neu holen, Materialien oben schon drin
                for tid, qty in need.items():
                    if tid in cart:
                        continue
                    store.add_shopping(tid, inv_names.get(tid, f"#{tid}"),
                                       max(1, int(round(qty))), 0, 0, source="build")
                    added_inv += 1
        if hasattr(self, "_render_shopping"):
            self._render_shopping()
        s = float(self.settings.get("bau_buy_surplus", 0) or 0)
        extra = t(" (+{s}% surplus)").format(s=f"{s:g}") if s > 0 else ""
        inv_txt = t(" + {n} invention items").format(n=added_inv) if added_inv else ""
        if covered_by_stock:
            inv_txt += t(" ({n} already in the hangar, not bought)").format(
                n=int(round(covered_by_stock)))
        warn_txt = ""
        if (not want_dc or not want_dcy) and getattr(self, "_bd_invention_needs", None):
            missing = []
            if not want_dc:
                missing.append("Datacores")
            if not want_dcy:
                missing.append(t("Decryptors"))
            warn_txt = t("  \u26a0 {what} NOT bought along - tick at \u201eInclude "
                         "inventions\u201c missing").format(what='/'.join(missing))
        self._flash_tip(t("{n} materials{inv} \u2192 shopping list{extra} \u2713{warn}").format(
            n=added, inv=inv_txt, extra=extra, warn=warn_txt))








    def _sidebar_breite_anpassen(self):
        """Das Logo auf die WIRKLICHE Sidebar-Breite bringen.

        Frueher stand hier das Gegenteil: die Sidebar wurde so breit
        gemacht, dass der Schriftzug "MOTOR MARKET" hineinpasste. Das ging
        zweimal schief ("da steht nur MOTOR MARKE"), weil die noetige Breite
        an der Schrift des Zielrechners haengt und feste Zahlen das nicht
        loesen koennen.

        Seit Sitzung 11 traegt das Logo den Schriftzug selbst - der
        Text daneben ist weg, und damit auch das Problem. Jetzt laeuft es
        andersherum: die Sidebar gibt die Breite vor, das Bild richtet sich
        danach. Ein Bild laesst sich beliebig skalieren, eine Schrift nicht.
        """
        try:
            sb = getattr(self, "_sidebar_widget", None)
            logo = getattr(self, "_brand_logo", None)
            if sb is None or logo is None:
                return
            # Innenbreite = Sidebar minus ihre Raender (2x10). Nach unten
            # begrenzt, damit es bei einer schmalen Sidebar nicht zu einem
            # Briefmarken-Logo wird; nach oben, damit es die Werkzeugliste
            # nicht aus dem Fenster schiebt.
            breite = max(96, min(sb.width() - 20, 240))
            if logo.pixmap().isNull() or logo.pixmap().width() != breite:
                logo.setPixmap(icons.logo_pixmap(breite))
        except Exception:
            pass    # reine Optik - darf den Start nie verhindern

    @staticmethod
    def _bp_name_fuer(item_name, activity):
        """Blaupausen-Name aus Itemname + Aktivitaet.

        EINE Stelle (Sitzung 20): dieselbe Regel, die das Rechtsklick-Menue
        des Runplaners schon benutzt - Reaktionen heissen "... Reaction
        Formula", alles andere "... Blueprint". Zwei Schreibweisen desselben
        Namens waeren im Spiel nicht auffindbar.
        """
        base = str(item_name or "").strip()
        if not base:
            return ""
        if activity == industry.REACTION:
            return f"{base} Reaction Formula"
        return f"{base} Blueprint"

    def _copy_bp_name_value(self, name):
        """Blaupausen-Name ins Clipboard (Nutzer, Sitzung 20) - zum Suchen
        im Spiel. Bewusst NUR der Name, ohne Zusatz."""
