        b_myblue = page_btn(t("My blueprints"), 1, icon="blueprint")

        header(t("PRODUCTION"), theme.GREEN)
        # Nutzer-Wunsch: "Neuer Bauplan" gehört zu PRODUKTION, nicht zu
