        self.bp_refresh_btn.setMinimumHeight(34)
        self.bp_refresh_btn.setStyleSheet("font-size:13px; font-weight:800; padding:6px 18px;")
        self.bp_refresh_btn.clicked.connect(self._reload_my_blueprints)
        row.addWidget(self.bp_refresh_btn)
        self.bp_status = QLabel(t("Not loaded yet – press „↻ Load blueprints“."))
        self.bp_status.setObjectName("Muted")
        row.addWidget(self.bp_status)
        row.addStretch()
        srch_lbl = QLabel(t("Search:"))
        srch_lbl.setStyleSheet(f"color:{theme.MUTED}; font-weight:700;")
        row.addWidget(srch_lbl)
        from PySide6.QtWidgets import QCompleter
        self.bp_search = QComboBox(); self.bp_search.setEditable(True)
        self.bp_search.setMinimumWidth(220)
        self.bp_search.setInsertPolicy(QComboBox.NoInsert)
        self.bp_search.lineEdit().setPlaceholderText(t("Blueprint name \u2026"))
        self.bp_search.completer().setCompletionMode(QCompleter.PopupCompletion)
        self.bp_search.completer().setFilterMode(Qt.MatchContains)
        self.bp_search.completer().setCaseSensitivity(Qt.CaseInsensitive)
        self.bp_search.setToolTip(
            t("Filter by blueprint name - suggestions appear while typing."))
        self.bp_search.editTextChanged.connect(self._apply_bp_filter)
        row.addWidget(self.bp_search)
        lay.addLayout(row)

        # Filter-Leiste: Kategorien per Checkbox (Mehrfachauswahl) + „nur
        # profitable“. Die Filter wirken rein lokal auf die schon geladenen Zeilen
        # (kein erneuter ESI-Abruf) -- deshalb nur _apply_bp_filter(), kein reload.
        frow = QHBoxLayout(); frow.setContentsMargins(0, 2, 0, 2); frow.setSpacing(14)
        flabel = QLabel(t("Show:"))
        flabel.setStyleSheet(f"color:{theme.MUTED}; font-weight:700;")
        frow.addWidget(flabel)
        self.bp_cb_end = QCheckBox(t("End products"))
        self.bp_cb_end.setIcon(icons.icon("target"))
        self.bp_cb_comp = QCheckBox(t("Components"))
