    def _bau_stufe_fuer_item(self, tid, reaction_products, stage_map,
                             endprodukt=None):
        """Bau-Stufe EINES Items -> Schluessel aus _STRUCT_ACTIVITIES.

        EINE Quelle fuer Runplaner UND Rechenweg (Arbeitsregel 9): die
        Stufen-Zuordnung darf nicht an zwei Stellen unterschiedlich
        entstehen, sonst zeigt der Plan einen anderen Bau-Ort an als er
        rechnet - und genau daran ist der Falcon gescheitert.

        Fuel Blocks fallen absichtlich unter "components" (Nutzer-Ansage).
        `endprodukt`: EIN Item ODER eine Menge (Buendel: alle Enden). Ist es
        das Buendel selbst (BUENDEL_ID), werden die Enden aus den offenen
        Rezepten aufgeloest - kein Aufrufer muss das Buendel kennen.
        """
        if tid in (reaction_products or set()):
            return ("reaction_2" if (stage_map or {}).get(tid, 1) == 2
                    else "reaction_1")
        if endprodukt is not None:
            if isinstance(endprodukt, (set, frozenset, dict, list, tuple)):
                if tid in endprodukt:
                    return "endproduct"
            elif endprodukt == industry.BUENDEL_ID:
                # ohne self-Zustand aufloesen (aa155 ruft mit einem nackten
                # Namespace) - die Enden stehen in den offenen Rezepten
                if tid in industry.buendel_enden(getattr(self, "_bd_recipes", None)):
                    return "endproduct"
            elif tid == endprodukt:
                return "endproduct"
        return "components"

    def _bau_struct_fuer_item(self, tid, reaction_products, stage_map=None,
                              endprodukt=None):
        """Die Struktur, in der DIESES Item gebaut/reagiert wird - ueber
        seine STUFE nachgeschlagen (Sitzung 9, Simurgh). Vorher griffen alle
        Verbraucher auf die zwei Sammelvariablen zu; die Fertigungs-Seite
        lieferte dabei IMMER die Komponenten-Struktur, auch fuers Endprodukt.
        Rueckfall auf die Sammelvariablen, wenn die Stufen-Karte fehlt
        (eingefrorene Alt-Plaene)."""
        stufe = self._bau_stufe_fuer_item(tid, reaction_products, stage_map,
                                          endprodukt)
        st = (getattr(self, "_bd_stage_structs", {}) or {}).get(stufe)
        if st is not None:
            return st
        if tid in (reaction_products or set()):
            return getattr(self, "_bd_react_struct", None)
        return getattr(self, "_bd_mfg_struct", None)

    # Rig-Kategorien (Fertigung) – jede wirkt nur auf ihre Item-Gruppe.
    # Fertigungs-Rig-Kategorien (echte EVE-Namen) – jede wirkt nur auf ihre Item-Gruppe.
    _RIG_MFG_CATS = [
        "Equipment", "Advanced Component", "Basic Capital Component",
        "Advanced Capital Component", "Ammunition", "Drone and Fighter", "Structure",
        "Basic Small Ship", "Basic Medium Ship", "Basic Large Ship",
        "Advanced Small Ship", "Advanced Medium Ship", "Advanced Large Ship",
        "Capital Ship",
    ]
    # Rig-Kategorie-Name (Fallback ohne SDE-Effekte) -> Domänen-Tags.
    _CAT_DOMAINS = {
        "Equipment": {"equipment"},
        "Advanced Component": {"advanced_component"},
        "Basic Capital Component": {"capital_component"},
        "Advanced Capital Component": {"advanced_capital_component"},
        "Ammunition": {"ammo"},
        "Drone and Fighter": {"drone"},
        "Structure": {"structure"},
        "Basic Small Ship": {"basic_small_ship"},
        "Basic Medium Ship": {"basic_medium_ship"},
        "Basic Large Ship": {"basic_large_ship"},
        "Advanced Small Ship": {"advanced_small_ship"},
        "Advanced Medium Ship": {"advanced_medium_ship"},
        "Advanced Large Ship": {"advanced_large_ship"},
        "Capital Ship": {"capital_ship"},
        "Reactor": {"reaction"},
    }

    def _domains_from_name(self, name):
        """Domänen aus dem Rig-Namen ableiten (Fallback, wenn keine SDE-Effekte da
        sind). Längere Tokens zuerst, damit 'Advanced Component' vor 'Component' greift."""
        nm = name or ""
        doms = set()
        for tok in sorted(self._CAT_DOMAINS, key=len, reverse=True):
            if tok in nm:
                doms |= self._CAT_DOMAINS[tok]
        return doms

    def _rig_catalog(self):
        """(rigs, bonus): rigs=[(key,label)]; bonus={key:{me,te,cost,cat,set,grp}}.
        Primär aus der SDE (industry.load_rigs); sonst verifizierter Fallback."""
        cache = getattr(self, "_rig_cat_cache", None)
        if cache:
            return cache
        rigs = [("", "\u2013 leerer Slot \u2013")]
        bonus = {}
        sde = []
        try:
            sde = industry.load_rigs()
        except Exception:
            sde = []
        if sde:
            seen_names = set()
            for r in sde:
                nm = r["name"] or ""
                low = nm.lower()
                if low.endswith(" blueprint"):
                    continue                # das ist die Blaupause des Rigs, nicht das
                                             # Rig selbst → sonst Dubletten im Dropdown.
                                             # WICHTIG: nur am WORTENDE prüfen, sonst
                                             # fliegen echte Rigs wie "...Blueprint Copy
                                             # Accelerator II" fälschlich mit raus (deren
                                             # Eigenname "Blueprint" in der Mitte enthält).
                if low in seen_names:
                    continue                # Sicherheitsnetz gegen sonstige Namens-Dubletten
                seen_names.add(low)
                size = ("XL" if "xl-set" in low else "L" if "l-set" in low
                        else "M" if "m-set" in low else "?")
                # NUR industrie-relevante Rigs. Aktivität aus dem Namen; alles andere
                # (Kampf: E-War/Neut/Targeting/Missile/Multiplexing; Moon Drilling)
                # fliegt raus.
                if "reactor" in low:
                    grp = "react"
                elif "reprocessing" in low:
                    grp = "react"            # Reprocessing-Rigs sitzen auf denselben
                                             # Refinery-Strukturen (Athanor/Tatara)
                elif "invention" in low:
                    grp = "invention"
                elif "copy" in low:
                    grp = "copy"
                elif "research" in low or "laboratory" in low:
                    grp = "research"          # XL: „Laboratory Optimization“ = Science
                elif "manufacturing" in low or "thukker" in low:
                    grp = "mfg"
                else:
                    continue                 # kein Bau-Rig → nicht ins Dropdown
                key = f"sde:{r['type_id']}"
                doms = set(industry.rig_domains(r.get("effects") or []))
                if not doms:                     # SDE ohne Effekt-Daten → aus Name
                    doms = self._domains_from_name(nm)
                me = abs(r["material"]); te = abs(r["time"]); cost = abs(r["cost"])
                tier2 = nm.rstrip().endswith("II")
                # Boni ableiten, wo die SDE sie nicht auf 2593/2594/2595 führt:
                # „Accelerator“ = Zeit-Rig; „Optimization“ (auch ohne „Cost“) = Job-Kosten.
                if "accelerator" in low and te == 0:
                    te = 24.0 if tier2 else 20.0
                if "optimization" in low and cost == 0:
                    cost = 24.0 if tier2 else 20.0
                rigs.append((key, nm))
                bonus[key] = {"me": me, "te": te, "cost": cost, "cat": "*",
                              "set": size, "grp": grp, "domains": doms}
            self._rig_cat_cache = (rigs, bonus)
            return self._rig_cat_cache

        def add(key, label, me, te, cost, cat, size, grp):
            rigs.append((key, label))
            bonus[key] = {"me": me, "te": te, "cost": cost, "cat": cat,
                          "set": size, "grp": grp,
                          "domains": set(self._CAT_DOMAINS.get(cat, set()))}
        for cat in self._RIG_MFG_CATS:
            add(f"L|{cat}|eff|1", f"Standup L-Set {cat} Manufacturing Efficiency I",
                2.0, 20.0, 0.0, cat, "L", "mfg")
            add(f"L|{cat}|eff|2", f"Standup L-Set {cat} Manufacturing Efficiency II",
                2.4, 24.0, 0.0, cat, "L", "mfg")
            add(f"M|{cat}|me|1", f"Standup M-Set {cat} Manufacturing Material Efficiency I",
                2.0, 0.0, 0.0, cat, "M", "mfg")
            add(f"M|{cat}|me|2", f"Standup M-Set {cat} Manufacturing Material Efficiency II",
                2.4, 0.0, 0.0, cat, "M", "mfg")
            add(f"M|{cat}|te|1", f"Standup M-Set {cat} Manufacturing Time Efficiency I",
                0.0, 20.0, 0.0, cat, "M", "mfg")
            add(f"M|{cat}|te|2", f"Standup M-Set {cat} Manufacturing Time Efficiency II",
                0.0, 24.0, 0.0, cat, "M", "mfg")
        add("L|Reaction|eff|1", "Standup L-Set Reactor Efficiency I",
            2.0, 20.0, 0.0, "Reaction", "L", "react")
        add("L|Reaction|eff|2", "Standup L-Set Reactor Efficiency II",
            2.4, 24.0, 0.0, "Reaction", "L", "react")
        add("M|Reaction|me|1", "Standup M-Set Reactor Material Efficiency I",
            2.0, 0.0, 0.0, "Reaction", "M", "react")
        add("M|Reaction|me|2", "Standup M-Set Reactor Material Efficiency II",
            2.4, 0.0, 0.0, "Reaction", "M", "react")
        add("M|Reaction|te|1", "Standup M-Set Reactor Time Efficiency I",
            0.0, 20.0, 0.0, "Reaction", "M", "react")
        add("M|Reaction|te|2", "Standup M-Set Reactor Time Efficiency II",
            0.0, 24.0, 0.0, "Reaction", "M", "react")
        self._rig_cat_cache = (rigs, bonus)
        return self._rig_cat_cache

    # Struktur-Typ -> (erlaubte Rig-Gruppen, Set-Größe). Engineering Complexes können
    # Fertigung + Invention + Kopieren + Research; Refineries nur Reaktionen.
    _STRUCT_TYPE_FIT = {
        "raitaru": ({"mfg", "invention", "copy", "research"}, "M"),
        "azbel": ({"mfg", "invention", "copy", "research"}, "L"),
        "sotiyo": ({"mfg", "invention", "copy", "research"}, "XL"),
        "athanor": ({"react"}, "M"),
        "tatara": ({"react"}, "L"),
        # OHNE DIESEN EINTRAG WAERE DIE STATION TOT: `_bau_struct_for_activity`
        # waehlt Strukturen ueber genau diese Menge aus. Eine NPC-Station kann
        # fertigen, erfinden, kopieren und forschen - REAKTIONEN NICHT, die
        # brauchen in EVE eine Refinery mit Reactor-Modul. Die Groesse ist bei
        # 0 Rig-Slots ohne Wirkung.
        "npc": ({"mfg", "invention", "copy", "research"}, "L"),
    }
    # Rig-Domänen, die auf diesem Strukturtyp wirkungslos wären, obwohl Gruppe/Größe
    # passen würden – raus aus dem Dropdown. Nur der Raitaru betrifft das: laut EVE
    # kann ein Medium-Engineering-Complex KEINE Capital-Schiffshüllen bauen (das
    # „Capital Shipyard“-Servicemodul gibt's erst ab Azbel/L). Capital-KOMPONENTEN
    # (Materialien) baut ein Raitaru dagegen ganz normal – die bleiben nutzbar.
    _STRUCT_EXCLUDE_DOMAINS = {
        "raitaru": {"capital_ship"},
    }

    # Rig-Slots je Struktur-Typ: alle Upwell-Strukturen haben 3 Rig-Slots.
    _STRUCT_RIG_SLOTS = {
        "raitaru": 3, "azbel": 3, "sotiyo": 3, "athanor": 3, "tatara": 3,
        # NPC-Station: keine Rig-Slots. `_apply_slot_vis` blendet die drei
        # Zeilen damit von selbst aus, und `_save` schreibt eine leere
        # Rig-Liste - es gibt also keinen Weg, einer Station versehentlich
        # einen Rig-Bonus zu geben.
        "npc": 0,
    }

    def _rigs_for_type(self, stype):
        """Nur die Rigs, die in diese Struktur passen (Set-Größe + Aktivitäts-Gruppen)
        UND dort auch etwas bewirken (s. _STRUCT_EXCLUDE_DOMAINS), mit Bonus im Label,
        damit man sofort sieht was das Rig bringt."""
        rig_list, bonus = self._rig_catalog()
        groups, size = self._STRUCT_TYPE_FIT.get(stype, ({"mfg"}, "L"))
        exclude_doms = self._STRUCT_EXCLUDE_DOMAINS.get(stype, set())
        out = [("", "\u2013 leerer Slot \u2013")]
        for key, label in rig_list:
            if not key:
                continue
            b = bonus.get(key)
            if b and b["grp"] in groups and b["set"] == size:
                if exclude_doms and (b.get("domains") or set()) & exclude_doms:
                    continue
                tags = []
                if b.get("me"):
                    tags.append(f"\u2212{b['me']:g}% Mat")
                if b.get("te"):
                    tags.append(t("\u2212{v}% time").format(v=f"{b['te']:g}"))
                if b.get("cost"):
                    tags.append(f"\u2212{b['cost']:g}% Job")
                out.append((key, label + (f"   ({' · '.join(tags)})" if tags else "")))
        return out

    def _struct_extra_rig_pct(self, s, grp):
        """Zeit-/Kosten-Bonus (%) von Kopier-/Forschungs-/Invention-Rigs auf dieser
        Struktur \u2013 nur zur Anzeige. Wird noch NICHT in der Baurechnung verwendet
        (Kopieren/Forschung sind noch kein eigener Rechenschritt), sonst w\u00fcrde man
        sonst f\u00e4lschlich denken, diese Rigs bringen gar nichts."""
        _rigs, bonus = self._rig_catalog()
        best = 0.0
        for r in (s.get("rigs") or []):
            b = bonus.get(r)
            if b and b["grp"] == grp:
                v = b.get("te") or b.get("cost") or b.get("me") or 0.0
                best = max(best, v)
        return best

    def _struct_rig_pct(self, s, kind):
        """Bester Bonus einer Art × Sicherheit, in %.
        kind: me/te/cost (Fertigung) oder rme/rte/rcost (Reaktion).
        Reactor-Rigs nutzen einen anderen Sicherheits-Multiplikator (Null ×1,1)."""
        _rigs, bonus = self._rig_catalog()
        comp = {"me": "me", "te": "te", "cost": "cost",
                "rme": "me", "rte": "te", "rcost": "cost"}.get(kind, "me")
        want = "react" if kind in ("rme", "rte", "rcost") else "mfg"
        best = 0.0
        for r in (s.get("rigs") or []):
            b = bonus.get(r)
            if b and b["grp"] == want:
                best = max(best, b.get(comp, 0.0))
        secmult = float(s.get("security", 1.0))
        if want == "react":                       # Reactor: Low ×1,0 · Null/WH ×1,1
            secmult = 1.1 if secmult >= 2.0 else 1.0
        return best * secmult
    def _struct_me_rig_pct(self, s):
        return self._struct_rig_pct(s, "me")

    def _struct_te_rig_pct(self, s):
        return self._struct_rig_pct(s, "te")

    def _struct_reaction_rig_pct(self, s):
        return self._struct_rig_pct(s, "rme")

    def _struct_cost_rig_pct(self, s):
        return self._struct_rig_pct(s, "cost")

    def _struct_kann(self, s, activity):
        """Kann DIESE Struktur diese Stufe ueberhaupt? EINE Quelle fuer alle
        Stellen (Arbeitsregel 9).

        Hintergrund (Nutzer, Sitzung 19): er hatte alle fuenf Stufen auf eine
        NPC-Station gestellt, auch beide Reaktionsstufen. Das Werkzeug liess
        es zu, obwohl `_STRUCT_TYPE_FIT` die Regel kennt - die Dropdowns
        boten jede Struktur fuer jede Stufe an, und eine feste Zuweisung
        wurde ZURUECKGEGEBEN, BEVOR der Fit-Filter griff. In EVE laufen
        Reaktionen aber ausschliesslich in einer Refinery mit Reactor-Modul.
        """
        fit_key = self._STUFE_FIT.get(activity, activity)
        return fit_key in self._STRUCT_TYPE_FIT.get(
            (s or {}).get("type", ""), (set(), ""))[0]

    def _unmoegliche_zuweisungen(self):
        """Fest zugewiesene Stufen, die diese Struktur gar nicht kann.
        Liste von (stufe, strukturname) - fuer die Warnung im Struktur-Tab."""
        structs = self.settings.get("bau_structures", []) or []
        amap = self.settings.get("bau_activity_struct", {}) or {}
        raus = []
        for _akey, _lab in self._STRUCT_ACTIVITIES:
            _sid = amap.get(_akey)
            if not _sid:
                continue
            _s = next((x for x in structs if x["id"] == _sid), None)
            if _s is not None and not self._struct_kann(_s, _akey):
                raus.append((_akey, _s.get("name", "?")))
        return raus

    def _struct_for_activity(self, activity):
        """Struktur für eine Aktivität: zugewiesene, sonst (Auto) die mit bestem
        Bonus - NUR unter Strukturen, die diese Aktivität laut EVE überhaupt
        unterstützen. Refineries (Athanor/Tatara) können AUSSCHLIESSLICH
        Reaktionen - kein Invention, kein Kopieren, keine Forschung (siehe
        _STRUCT_TYPE_FIT). Vorher wurde das ignoriert: die Auto-Wahl hat für
        JEDE Aktivität außer Reaktion pauschal den besten ME-Rig-Wert genommen
        - dadurch konnte z.B. eine Refinery für Invention vorgeschlagen werden,
        obwohl dort technisch gar nicht invented werden kann."""
        structs = self.settings.get("bau_structures", []) or []
        if not structs:
            return None
        _amap = self.settings.get("bau_activity_struct", {}) or {}
        sid = _amap.get(activity)
        if not sid:
            # RUECKFALL auf den alten, groberen Schluessel - siehe
            # _STUFE_LEGACY. Nur wenn fuer die feine Stufe nichts gesetzt ist.
            sid = _amap.get(self._STUFE_LEGACY.get(activity, ""), "")
        if sid:
            s = next((x for x in structs if x["id"] == sid), None)
            # NUR WENN SIE ES AUCH KANN (Sitzung 19). Vorher kehrte die
            # Funktion hier bedingungslos um - eine alte, unmoegliche
            # Zuweisung (Reaktion auf eine NPC-Station) haette den Fit-Filter
            # darunter nie erreicht und still falsch gerechnet. Kann sie es
            # nicht, faellt es auf die Auto-Wahl zurueck, und die Warnung im
            # Struktur-Tab sagt es.
            if s and self._struct_kann(s, activity):
                return s
        fit_key = self._STUFE_FIT.get(activity, activity)
        capable = [s for s in structs if fit_key in
                  self._STRUCT_TYPE_FIT.get(s.get("type", ""), (set(), ""))[0]]
        if not capable:
            return None   # keine verlinkte Struktur kann das -> lieber keine
                          # Vorschlagen als eine, die's technisch nicht kann
        if fit_key == "react":
            key = self._struct_reaction_rig_pct
        elif fit_key == "mfg":
            key = self._struct_me_rig_pct
        else:
            key = lambda s: self._struct_extra_rig_pct(s, fit_key)
        return max(capable, key=key)

    def _fehlende_bau_strukturen(self, tree, endprodukt, reaction_products,
                                 stage_map=None, is_invented=False):
        """Welche Stufen baut DIESER Plan, ohne dass eine Struktur da ist?

        Rueckgabe: Liste von (stufe, kritisch). `kritisch` heisst: in EVE
        UNMOEGLICH, nicht nur unbekannt. Das trifft ausschliesslich
        Reaktionen - die brauchen zwingend eine Refinery mit Reactor-Modul.
        Fertigen, Forschen und Kopieren geht dagegen in jeder NPC-Station;
        dort fehlt dem Werkzeug nur der Ort.

        WOZU (Nutzer, Sitzung 19): ohne Struktur bleibt der Systemkostenindex
        auf 0, weil `_bau_jobcost_opts` den ESI-Block ueberspringt. Die
        Anlagegebuehr faellt damit fast komplett weg - uebrig bleiben 0,25 %
        Steuer und 4 % SCC. Der ausgewiesene Gewinn ist zu hoch, und nichts
        sagt es. Gerechnet wird trotzdem weiter: Plaene entstehen oft, BEVOR
        die Struktur eingerichtet ist, und das Rechnen zu verweigern naehme
        genau diesen Nutzen.

        Gezaehlt werden nur Stufen, die der Plan WIRKLICH baut. Wer nichts
        reagiert, soll keine Refinery-Warnung sehen.
        """
        gebaut = set()

        def _lauf(knoten, tiefe=0):
            if not isinstance(knoten, dict) or tiefe > 12:
                return
            _tid = knoten.get("type_id")
            if _tid is not None:
                gebaut.add(int(_tid))
            for _k in (knoten.get("components") or []):
                if (_k or {}).get("decision") == "build":
                    _lauf(_k.get("subtree") or {}, tiefe + 1)

        _lauf(tree or {})
        stufen = []
        for _tid in gebaut:
            _st = self._bau_stufe_fuer_item(_tid, reaction_products, stage_map,
                                            endprodukt)
            if _st not in stufen:
                stufen.append(_st)
        if is_invented and "invention" not in stufen:
            stufen.append("invention")
        _reihenfolge = [k for k, _l in self._STRUCT_ACTIVITIES]
        stufen.sort(key=lambda k: _reihenfolge.index(k)
                    if k in _reihenfolge else 99)
        fehlt = []
        for _st in stufen:
            if self._struct_for_activity(_st) is None:
                fehlt.append((_st, _st.startswith("reaction")))
        return fehlt

    def _build_structures_page(self):
        page = QWidget()
        self._struct_layout = QVBoxLayout(page)
        self._struct_layout.setContentsMargins(14, 8, 14, 8)
        self._struct_layout.setSpacing(7)
        self._reload_structures()
        return page

    @staticmethod
    def _best_sell_char(char_fees):
        """Charakter mit der NIEDRIGSTEN Gesamtgeb\u00fchr (Sales Tax + Broker
        Fee). Vorbelegung f\u00fcr neue Baupl\u00e4ne - bei d\u00fcnnen Margen macht
        ein halber Prozentpunkt mehr aus als jede Bau-Optimierung.
        R\u00fcckgabe: character_id (int) oder None."""
        best, best_v = None, None
        for cid, d in (char_fees or {}).items():
            try:
                v = float(d.get("combined"))
                c = int(cid)
            except (TypeError, ValueError):
                continue
            if best_v is None or v < best_v:
                best, best_v = c, v
        return best

    def _fetch_hub_sell_price(self, type_id):
        """Verkaufspreis EINES Items am gewaehlten Verkaufs-Hub holen.

        Bewusst nur EIN Item: ein kompletter Markt-Scan der anderen Region
        waere Minuten, hier reicht ein Request. Deshalb bleibt die
        Snapshot-Tabelle (die genau EINEN Hub haelt) unangetastet - der
        Einkauf rechnet weiter mit dem gescannten Hub.
        """
        key = getattr(self, "_bd_sell_hub", None)
        if not key or key == hubs.hub_key_for_region(store.get_scan_region()):
            self._bd_hub_sell_price = None      # gescannter Hub -> Snapshot
            self._bd_hub_sell_je_ende = {}
            _fn = getattr(self, "_bd_full_rebuild", None)
            if _fn is not None:
                _fn()
            return

        _enden_hs = (list(getattr(self, "_bd_buendel_enden", None) or [])
                     if type_id == industry.BUENDEL_ID else [])

        def job(progress=None):
            # MULTI-BAUPLAN: jedes Ende einzeln am Hub, Summe x Menge als
            # "Preis des Buendels"; je Ende gemerkt fuer die Enden-Karte.
            if _enden_hs:
                je = self._multi_hub_sell_job(_enden_hs, key)
                self._bd_hub_sell_je_ende = je
                return self._multi_buendel_verkauf(je, _enden_hs) or None
            if isinstance(key, tuple) and key and key[0] == "struct":
                sid = int(key[1])
                cid = None
                for f in self._market_structures():
                    if f.get("structure_id") == sid:
                        cid = f.get("character_id")
                        break
                if not cid:
                    return None
                d = esi.fetch_structure_orders(
                    self.settings.get("client_id", ""), int(cid), sid)
                row = (d or {}).get(int(type_id)) or {}
                return row.get("sell_min") or None
            for k, _lbl, region, station in hubs.NPC_HUBS:
                if k == key:
                    lad = esi.fetch_type_orders(int(type_id), station, region)
                    s = (lad or {}).get("sell") or []
                    return s[0][0] if s else None
            return None

        def done(price):
            self._bd_hub_sell_price = float(price) if price else None
            if not price:
                self._flash_tip(t("\u26a0 No sell order for this item at the chosen "
                                  "sales hub \u2013 the price stays from the scanned hub."))
            _fn = getattr(self, "_bd_full_rebuild", None)
            if _fn is not None:
                _fn()

        def fail(msg):
            self._bd_hub_sell_price = None
            self._flash_tip(t("\u26a0 Sale price at the chosen hub not loadable: ")
                            + str(msg)[:80])
        self._run(Worker(job), done, fail_cb=fail)

    @classmethod
    def _fees_for_hub(cls, settings, cid, hub_key):
        """(tax, broker, quelle) f\u00fcr Verkaufscharakter UND Verkaufs-Hub.

        Der Hub bestimmt die BROKER FEE mit: sie h\u00e4ngt an den Standings zum
        Stationsbesitzer, und die sind je Hub verschieden (`hub_standings`).
        Die SALES TAX h\u00e4ngt nur am Accounting-Skill, also nicht am Ort.
        Beides zusammen ist der gr\u00f6\u00dfte Hebel auf den Gewinn - bei d\u00fcnnen
        Margen gr\u00f6\u00dfer als jede Bau-Optimierung.

        SPIELERSTRUKTUREN: dort setzt der Besitzer die Broker Fee selbst,
        ESI liefert sie nicht. Dann bleibt es beim globalen Wert, und die
        Quelle wird als unsicher zur\u00fcckgegeben (hub_key None/unbekannt).
        """
        s = settings or {}
        cf = (s.get("char_fees") or {}).get(str(cid)) if cid else None
        st = (s.get("hub_standings", {}) or {}).get(hub_key or "") or {}
        if cf and hub_key and st:
            try:
                return (config.effective_sales_tax(int(cf["acc"])) / 100.0,
                        config.effective_broker_fee(
                            int(cf["br"]), float(st.get("faction", 0.0) or 0.0),
                            float(st.get("corp", 0.0) or 0.0)) / 100.0,
                        f"{cf.get('name', cid)} @ {hub_key}")
            except (KeyError, TypeError, ValueError):
                pass
        return cls._fees_for_sell_char(s, cid)

    @classmethod
    def _sell_hub_choices(cls, market_structures=None):
        """Auswahl f\u00fcr den Verkaufs-Hub: die f\u00fcnf NPC-Hubs + die bekannten
        Spielerstrukturen. R\u00fcckgabe [(label, key)] - key ist der Hub-Schl\u00fcssel
        ("jita") oder ("struct", structure_id)."""
        out = [(lbl, key) for key, lbl, _r, _s in hubs.NPC_HUBS]
        for f in (market_structures or []):
            sid = f.get("structure_id")
            # NUR Orte, an denen man auch HANDELN kann (Nutzer). Strukturen,
            # die nur \u00fcber die Asset-Suche bekannt wurden, haben meist gar
            # kein Markt-Modul - eine Azbel oder ein Tatara ist kein
            # Handelsplatz. Die kommen hier nicht rein.
            if f.get("discovered"):
                continue
            if sid:
                out.append((" " + str(f.get("name") or sid),
                            ("struct", int(sid))))
        return out

    @classmethod
    def _fees_for_sell_char(cls, settings, cid):
        """(tax, broker, quelle) f\u00fcr den gew\u00e4hlten Verkaufscharakter.

        Ohne Auswahl (oder wenn der Charakter keine gelesenen Skills hat)
        gelten die GLOBALEN Werte aus den Einstellungen - dasselbe Verhalten
        wie bisher, nur eben benannt. `quelle` ist der Name f\u00fcr die Anzeige
        bzw. None, wenn global gerechnet wird.
        """
        s = settings or {}
        cf = (s.get("char_fees") or {})
        d = cf.get(str(cid)) if cid else None
        if d:
            try:
                return (float(d["tax"]) / 100.0, float(d["broker"]) / 100.0,
                        d.get("name") or str(cid))
            except (KeyError, TypeError, ValueError):
                pass
        return (float(s.get("sales_tax_pct", 0) or 0) / 100.0,
                float(s.get("broker_fee_pct", 0) or 0) / 100.0, None)

    @staticmethod
    def _recommended_sell_price(total_cost, qty, tax_pct, broker_pct,
                                market_sell=None, transport_cost=0.0,
                                tick=0.01, extra_cost=0.0):
        """Zielpreis je Stück: den aktuellen Markt unterbieten, aber nie unter
        den eigenen Mindestpreis rutschen (Nutzer-Auftrag).

        MINDESTPREIS (break_even) ist der Preis, bei dem nach Gebühren und
        Transport genau NULL Gewinn bleibt:
            sell x qty x (1 - tax - broker) = Baukosten + Transport
        Die Gebühren müssen hier hinein, sonst verkauft man scheinbar mit
        Gewinn und zahlt real drauf - bei dünnen Margen sind sie der größte
        Posten überhaupt.

        UNTERBIETUNG: einen Tick unter der billigsten Sell-Order.

        ZIELPREIS = max(Mindestpreis, Unterbietung). Liegt die Unterbietung
        UNTER dem Mindestpreis, ist sie nicht möglich - dann meldet
        `can_undercut=False` und der Zielpreis bleibt der Mindestpreis
        (lieber nicht verkaufen als mit Verlust).

        Ohne Marktpreis (market_sell None) gibt es nur den Mindestpreis;
        `can_undercut` ist dann None = unbekannt.
        """
        q = max(1, int(qty or 1))
        net = 1.0 - (float(tax_pct or 0) + float(broker_pct or 0))
        if net <= 0:
            return None
        # ZUSATZKOSTEN GEHOEREN IN DIE SCHWELLE. Sie werden vom Gewinn
        # abgezogen - also muss der Verkaufspreis sie auch verdienen, sonst
        # meldet die Zeile "kein Verlust", waehrend der Gewinn negativ ist.
        # Nutzer-Fund: bei 20 Mio Zusatzkosten auf 20 Stueck lag die Schwelle
        # 1,05 Mio je Stueck zu niedrig.
        break_even = ((float(total_cost or 0) + float(transport_cost or 0)
                       + float(extra_cost or 0))
                      / (q * net))
        undercut = None
        if market_sell and float(market_sell) > 0:
            undercut = max(0.0, float(market_sell) - float(tick))
        if undercut is None:
            return {"break_even": break_even, "undercut": None,
                    "target": break_even, "can_undercut": None}
        return {"break_even": break_even, "undercut": undercut,
                "target": max(break_even, undercut),
                "can_undercut": undercut >= break_even}

    @staticmethod
    def _norm_struct_name(x):
        """Namen vergleichbar machen: Kleinschreibung, nur Buchstaben/Ziffern.
        ESI liefert „A-DDGY - Dockside Innovations“, im Bau-Setup steht
        Name und System getrennt - Bindestriche/Leerzeichen dürfen den
        Vergleich nicht kaputt machen."""
        import re as _re
        return _re.sub(r"[^a-z0-9]", "", str(x or "").lower())

    @classmethod
    def _match_eve_structure(cls, name, system, known):
        """Passende echte EVE-Struktur zu einer Bau-Struktur finden.

        Nutzer-Frage: „Warum macht das Tool das nicht automatisch?“ - es
        gab schlicht keinen Grund. ESI benennt Upwell-Strukturen als
        „<SYSTEM> - <Name>“, im Bau-Setup stehen beide Teile ohnehin
        getrennt da.

        Bewusst STRENG: es wird nur zugeordnet, wenn genau EINE Struktur
        passt. Zwei Kandidaten -> None, lieber nichts als das Falsche
        (ein falscher Ort zählt fremdes Material als vorhanden - genau der
        Cormorant-Fehler).
        Rueckgabe: structure_id oder None.
        """
        n_name = cls._norm_struct_name(name)
        n_sys = cls._norm_struct_name(system)
        if not n_name:
            return None
        hits = []
        for f in (known or []):
            sid = f.get("structure_id")
            if not sid:
                continue
            full = cls._norm_struct_name(f.get("name"))
            if not full:
                continue
            # (a) exakt "<System> - <Name>"  (b) Name enthalten UND System passt
            if full == n_sys + n_name or (n_name in full and
                                          (not n_sys or n_sys in full)):
                hits.append(sid)
        uniq = list(dict.fromkeys(hits))
        return uniq[0] if len(uniq) == 1 else None

    @classmethod
    def _autolink_bau_structures(cls, bau_structures, known, force=False):
        """Bau-Strukturen EINMALIG automatisch mit ihrer echten EVE-Struktur
        verknüpfen. Ändert nur Einträge ohne Verknüpfung, und nur solange
        noch kein Versuch gelaufen ist (`link_auto_done`) - eine bewusste
        Nutzer-Wahl „— keine —“ darf NICHT immer wieder überschrieben
        werden. Rückgabe: [(Struktur-Name, Ziel-Name), …] der neuen
        Verknüpfungen."""
        made = []
        by_id = {f.get("structure_id"): f for f in (known or [])}
        for s in (bau_structures or []):
            if s.get("link_structure_id"):
                continue
            # BUG (Nutzer): der Marker `link_auto_done` sollte eine bewusste
            # "- keine -"-Wahl schuetzen. Er blockierte aber auch das
            # Nachziehen, NACHDEM neue Orte gefunden wurden - also genau den
            # Fall, fuer den der Knopf "Orte finden und alle verknuepfen" da
            # ist. force=True kommt ausschliesslich von diesem Knopf: der
            # Nutzer hat ausdruecklich darum gebeten.
            # Nach einer echten Suche (`link_search_done`) wird bei JEDEM
            # Aufruf weiter versucht - kostet nichts (reiner Namensvergleich)
            # und sorgt dafuer, dass eine Struktur SOFORT greift, sobald sie
            # bekannt wird (Nutzer: "falls ich da in Zukunft etwas habe, soll
            # es sofort getrackt werden").
            if (s.get("link_auto_done") and not force
                    and not s.get("link_search_done")):
                continue
            s["link_auto_done"] = True
            sid = cls._match_eve_structure(s.get("name"), s.get("system"), known)
            if not sid:
                continue
            s["link_structure_id"] = sid
            s["link_character_id"] = (by_id.get(sid) or {}).get("character_id")
            s["link_auto"] = True
            made.append((s.get("name"), (by_id.get(sid) or {}).get("name")))
        return made

    def _struct_label(self, s):
        tname = dict(self._STRUCT_TYPES).get(s.get("type", ""), s.get("type", "?"))
        me = self._struct_me_rig_pct(s)
        te = self._struct_te_rig_pct(s)
        rr = self._struct_reaction_rig_pct(s)
        co = self._struct_cost_rig_pct(s)
        iv = self._struct_extra_rig_pct(s, "invention")
        bonuses = []
        if me:
            bonuses.append(f"ME {me:.1f}%")
        if te:
            bonuses.append(f"TE {te:.0f}%")
        if rr:
            bonuses.append(t("Reaction {v}%").format(v=f"{rr:.1f}"))
        if co:
            bonuses.append(t("Cost {v}%").format(v=f"{co:.0f}"))
        # Kopie-/Forschungs-Rigs stehen NICHT mehr im Label (Nutzer-
        # Entscheidung: "das Kopieren nehmen wir komplett raus, die Info
        # ist ueberfluessig" - ein Forschen&Kopieren-Rechenschritt wird
        # NICHT gebaut). Die Rigs bleiben im Editor eintragbar (sie bilden
        # die echte Struktur ab), aber eine Zeile "wirkt nirgends" ist
        # keine Information, sondern Rauschen.
        if iv:
            bonuses.append(t("Invention \u2212{v}% (job time, included in the "
                             "Invention tab)").format(v=f"{iv:.0f}"))
        btxt = "  \u00b7  ".join(bonuses) if bonuses else t("no rig bonuses")
        # VERKN\u00dcPFUNGS-STATUS (Nutzer-Fall: "Morphite liegt doch auf einer
        # Bau-Struktur"). Eine Bau-Struktur hier ist ein RECHENMODELL (Rigs,
        # Rolle, System-Index) - sie sagt dem Tool NICHT, welcher echte
        # EVE-Ort gemeint ist. Ohne die Verkn\u00fcpfung findet
        # "\U0001F4E6 Assets abziehen" im Scope "Nur Bau-Strukturen" NULL Orte
        # und z\u00e4hlt gar keinen Lagerbestand. Das stand bisher nur im
        # Bearbeiten-Dialog - in der Liste war es unsichtbar, und die Warnung
        # im Bauplan nannte keine Struktur beim Namen.
        _lid = s.get("link_structure_id")
        if _lid:
            _lname = None
            for _f in self._link_orte():
                if _f.get("structure_id") == _lid:
                    _lname = _f.get("name")
                    break
            _auto = t(" (automatic)") if s.get("link_auto") else ""
            _ltxt = (f"<span style='color:{theme.GREEN}'>"
                     + t("linked to {where}{auto} \u2013 material lying there "
                         "counts towards this plan").format(
                             where=_lname or _lid, auto=_auto) + "</span>")
        elif s.get("link_search_done"):
            # Es WURDE gesucht und nichts gefunden -> das ist eine Aussage
            # ueber den Bestand, kein Fehler des Nutzers. Entsprechend
            # neutral formuliert und nicht als Warnung eingefaerbt.
            # KLARSTELLUNG (Nutzer-Frage zur unverknuepften Capslock:
            # "trotzdem sollte getrackt werden alles andere wie facility
            # Tax usw"): die Verknuepfung betrifft NUR das Bestand-Zaehlen.
            # Rigs, ME/TE, Facility-Tax, Rollenbonus und System-Index kommen
            # aus DIESEM Eintrag und wirken immer - das stand nirgends, und
            # der Text las sich, als sei die Struktur komplett inaktiv.
            _ltxt = (f"<span style='color:{theme.MUTED}'>"
                     + t("Nothing here right now \u2013 ESI found neither assets "
                         "nor orders. As soon as you have material here it is detected "
                         "and counted automatically. Rigs, tax and system index of this "
                         "structure count regardless, already.") + "</span>")
        else:
            _ltxt = (f"<span style='color:{theme.AMBER}'>"
                     + t("Not searched yet \u2013 click \u201eFind locations and "
                         "link all\u201c above once, then the stock from here counts in "
                         "the build plan. Rigs, tax and system index count even WITHOUT "
                         "a link \u2013 only the hangar stock needs it.") + "</span>")
        return (f"<b>{s.get('name', '?')}</b>  \u00b7  {tname.split(' \u2013 ')[0]}"
                f"  \u00b7  {s.get('system', '?')}<br>"
                f"<span style='color:{theme.CYAN}'>{btxt}</span><br>{_ltxt}")

    def _reload_structures(self):
        from PySide6.QtWidgets import QFrame, QHBoxLayout, QComboBox
        lay = getattr(self, "_struct_layout", None)
        if lay is None:
            return
        # Automatisch verkn\u00fcpfen, was sich eindeutig zuordnen l\u00e4sst
        # (Nutzer-Frage: "warum macht das Tool das nicht selbst?").
        try:
            _made = self._autolink_bau_structures(
                self.settings.get("bau_structures", []) or [],
                self._link_orte())
            if _made:
                config.save_settings(self.settings)
                self._flash_tip(
                    t("{n} build structure(s) automatically linked to the "
                      "real EVE structure: ").format(n=len(_made))
                    + ", ".join(a or "?" for a, _b in _made[:3])
                    + ("\u2026" if len(_made) > 3 else ""))
        except Exception:
            pass
        while lay.count():
            it = lay.takeAt(0)
            w = it.widget()
            if w:
                w.setParent(None); w.deleteLater()
        MAXW = 760   # feste Breite für beide Karten-Bereiche -> zentriert statt

        def _centered(widget):
            """Zentriert `widget` (mit fester Maximalbreite) statt es über die
            ganze Fensterbreite zu strecken \u2013 Buttons bleiben nah am Inhalt."""
            row = QHBoxLayout(); row.setContentsMargins(0, 0, 0, 0)
            row.addStretch()
            row.addWidget(widget)
            row.addStretch()
            wrap = QWidget(); wrap.setLayout(row)
            return wrap
        title = QLabel(t("MY STRUCTURES"))
        title.setStyleSheet(f"color:{theme.CYAN}; font-size:15px; font-weight:800; "
                            f"letter-spacing:1px;")
        lay.addWidget(_centered(title))
        # DAUERHINWEIS ENTFERNT (Nutzer-Wunsch Sitzung 12: "ich hasse
        # Infos, die das Tool ueberladen aussehen lassen").
        head = QLabel("")
        head.setVisible(False)
        head.setObjectName("Muted"); head.setWordWrap(True)
        head.setMaximumWidth(MAXW)
        lay.addWidget(_centered(head))
        # AN self MERKEN (Sitzung 17): das Tutorial laesst diese zwei Knoepfe
        # mitblinken, wenn es die Strukturen erklaert.
        addbtn = self._struct_add_btn = QPushButton(t("+ Add structure"))
        addbtn.setIcon(icons.icon("plus"))
        addbtn.setMinimumHeight(34)
        addbtn.clicked.connect(lambda: self._open_structure_dialog())
        lay.addWidget(_centered(addbtn))
        # EIN Knopf statt Handarbeit (Nutzer: "ich will da nichts ausw\u00e4hlen").
        # Sucht die echten Orte aus Assets + Orders und ordnet sie anschlie\u00dfend
        # automatisch \u00fcber den Namen zu. Danach z\u00e4hlen die Best\u00e4nde ALLER
        # erkannten Bau-Strukturen im Bauplan.
        _unl = [x for x in (self.settings.get("bau_structures", []) or [])
                if not x.get("link_structure_id")]
        linkbtn = self._struct_link_btn = QPushButton(
            t("Find locations and link all")
            + (t("  ({n} open)").format(n=len(_unl)) if _unl else t("  \u2713 all linked")))
        linkbtn.setIcon(icons.icon("link"))
        linkbtn.setMinimumHeight(34)
        linkbtn.setToolTip(
            t("Searches your assets and orders for the real EVE structures and assigns "
              "them automatically to the build structures above \u2013 by name, without you "
              "having to pick anything.\n"
              "Only after that does \u201e Deduct assets\u201c in the build plan count the "
              "material lying at these structures.\n"
              "Takes 10\u201320 s (ESI). Assigned only on an UNAMBIGUOUS name match \u2013 a "
              "wrong place would count foreign material as available."))
        if _unl:
            linkbtn.setStyleSheet(
                f"QPushButton{{border:2px solid {theme.AMBER}; border-radius:6px; "
                f"padding:6px 14px; color:{theme.AMBER}; font-weight:700;}}")
        linkbtn.clicked.connect(lambda: self._bau_pick_structure())
        lay.addWidget(_centered(linkbtn))
        lay.addSpacing(6)
        structs = self.settings.get("bau_structures", []) or []
        if not structs:
            e = QLabel(t("No structures yet. Add your first one."))
            e.setObjectName("Muted"); lay.addWidget(_centered(e))
        for s in structs:
            card = QFrame(); card.setObjectName("Card"); card.setMaximumWidth(MAXW)
            row = QHBoxLayout(card); row.setContentsMargins(14, 10, 14, 10); row.setSpacing(10)
            lbl = QLabel(self._struct_label(s)); lbl.setWordWrap(True)
            row.addWidget(lbl, 1)
            eb = QPushButton(t("Edit"))
            eb.setIcon(icons.icon("menu"))
            eb.clicked.connect(lambda *_a, sid=s["id"]: self._open_structure_dialog(sid))
            row.addWidget(eb)
            db = QPushButton(t("Delete"))
            db.setIcon(icons.icon("trash"))
            db.clicked.connect(lambda *_a, sid=s["id"]: self._delete_structure(sid))
            row.addWidget(db)
            lay.addWidget(_centered(card))
        if structs:
            amap = self.settings.get("bau_activity_struct", {}) or {}
            abox = QFrame(); abox.setObjectName("Card"); abox.setMaximumWidth(MAXW)
            av = QVBoxLayout(abox); av.setContentsMargins(14, 12, 14, 12); av.setSpacing(6)
            ah = QLabel("\u2699\uFE0F  " + t("WHICH STRUCTURE FOR WHICH ACTIVITY?"))
            ah.setStyleSheet(f"color:{theme.AMBER}; font-size:15px; font-weight:800; "
                             f"letter-spacing:1px; padding-bottom:2px;")
            av.addWidget(ah)
            # DAUERHINWEIS ENTFERNT (Nutzer-Wunsch Sitzung 12: "ich hasse
            # Infos, die das Tool ueberladen aussehen lassen").
            ahint = QLabel("")
            ahint.setVisible(False)
            ahint.setObjectName("Muted"); ahint.setWordWrap(True)
            ahint.setStyleSheet("font-size:11px;")
            av.addWidget(ahint)
            # ALTE UNMOEGLICHE ZUWEISUNGEN BENENNEN (Sitzung 19). Die
            # Dropdowns bieten so etwas nicht mehr an, aber gespeicherte
            # Einstellungen liegen weiter in den Settings. Gerechnet wird
            # damit nicht mehr - stillschweigend darauf verzichten waere
            # aber genauso schlecht wie es vorher zu benutzen: der Nutzer
            # denkt, seine Zuweisung greife.
            _unmoeg = self._unmoegliche_zuweisungen()
            if _unmoeg:
                _lm = dict(self._STRUCT_ACTIVITIES)
                _uw = QLabel("\u26a0 " + t(
                    "These assignments are impossible in EVE and are being "
                    "ignored: {list}. Reactions only run in a refinery with a "
                    "reactor module; a refinery can do nothing else. The "
                    "automatic choice is used instead \u2013 pick a suitable "
                    "structure below to make it explicit."
                ).format(list="; ".join(
                    f"{t(_lm.get(_k, _k))} \u2192 {_n}" for _k, _n in _unmoeg)))
                _uw.setWordWrap(True)
                _uw.setStyleSheet(f"color:{theme.RED}; font-weight:700;")
                av.addWidget(_uw)
            self._struct_act_combos = {}
            for akey, alabel in self._STRUCT_ACTIVITIES:
                r = QHBoxLayout()
                r.addWidget(QLabel(t(alabel)))
                r.addStretch()
                cb = QComboBox(); cb.addItem(t("\u2013 auto (best per build plan) \u2013"), "")
                # NUR STRUKTUREN, DIE DIESE STUFE KOENNEN (Sitzung 19). Eine
                # Refinery kann nur Reaktionen, eine NPC-Station alles ausser
                # Reaktionen. Wer sie trotzdem anbietet, laedt zu einer
                # Einstellung ein, die es in EVE nicht gibt.
                for s in structs:
                    if self._struct_kann(s, akey):
                        cb.addItem(s.get("name", "?"), s["id"])
                cur = amap.get(akey) or amap.get(
                    self._STUFE_LEGACY.get(akey, ""), "")
                ix = cb.findData(cur)
                cb.setCurrentIndex(ix if ix >= 0 else 0)
                cb.currentIndexChanged.connect(self._save_activity_struct)
                self._struct_act_combos[akey] = cb
                r.addWidget(cb)
                wr = QWidget(); wr.setLayout(r); av.addWidget(wr)
            lay.addWidget(_centered(abox))
        # RESERVIERUNGS-UEBERSICHT ENTFERNT (Nutzer, Sitzung 20): "die
        # Bauplaene haben wir ja unter Meine Bauplaene schon". Die Karte
        # listete jeden gespeicherten Plan ein zweites Mal auf. Der
        # Schloss-Knopf bleibt dort, wo der Plan steht - derselbe Handler
        # (_toggle_plan_reserve), derselbe Zustand in den Settings. Die
        # Kurzzeile im Bauplan selbst bleibt ebenfalls: wo abgezogen wird,
        # muss der Abzug sichtbar sein.
        lay.addStretch()

    def _save_activity_struct(self):
        if not hasattr(self, "_struct_act_combos"):
            return
        amap = {}
        for akey, cb in self._struct_act_combos.items():
            d = cb.currentData()
            if d:
                amap[akey] = d
        self.settings["bau_activity_struct"] = amap
        config.save_settings(self.settings)

    def _system_names_cached(self):
        if getattr(self, "_all_sysnames", None) is None:
            try:
                self._all_sysnames = esi.all_system_names() or {}
            except Exception:
                self._all_sysnames = {}
        return self._all_sysnames

    def _open_structure_dialog(self, sid=None):
        from PySide6.QtWidgets import (QDialog, QVBoxLayout, QFormLayout, QLineEdit,
                                       QComboBox, QDoubleSpinBox, QPushButton, QHBoxLayout,
                                       QCompleter)
        structs = self.settings.get("bau_structures", []) or []
        s = next((x for x in structs if x["id"] == sid), None) if sid else None
        dlg = MinimizableDialog(self)
        dlg.setWindowTitle(t("Edit structure") if s else t("Add structure"))
        dlg.resize(460, 380)
        v = QVBoxLayout(dlg)
        form = QFormLayout(); v.addLayout(form)
        name = QLineEdit(s.get("name", "") if s else "")
        form.addRow(t("Name"), name)
        typ = QComboBox()
        for k, lab in self._STRUCT_TYPES:
            typ.addItem(lab, k)
        if s:
            ix = typ.findData(s.get("type")); typ.setCurrentIndex(max(0, ix))
        form.addRow(t("Type"), typ)
        system = QLineEdit(s.get("system", "") if s else "")
        system.setPlaceholderText(t("Type a system \u2026"))
        sysnames = self._system_names_cached()
        sys2id = {nm.lower(): sysid for sysid, nm in sysnames.items()}
        comp = QCompleter(sorted(sysnames.values()))
        comp.setCompletionMode(QCompleter.PopupCompletion)
        comp.setFilterMode(Qt.MatchContains)
        comp.setCaseSensitivity(Qt.CaseInsensitive)
        comp.setMaxVisibleItems(12)
        system.setCompleter(comp)
        form.addRow(t("System"), system)
        # STATIONSAUSWAHL (Sitzung 19). Nur fuer den Typ "NPC station"
        # sichtbar. Gefuellt wird sie, sobald das System feststeht - die
        # Stations-IDs stecken ohnehin in der Systemantwort. Wer hier waehlt,
        # bekommt Name UND Verknuepfung in einem Schritt: kein Abtippen einer
        # Nummer, kein Ingame-Link, und es funktioniert auch dann, wenn dort
        # noch gar nichts von einem liegt.
        _stat_row = form.rowCount()
        station_cb = QComboBox()
        station_cb.addItem(t("\u2014 choose a system first \u2014"), None)
        form.addRow(t("Station"), station_cb)
        _stat_gewaehlt = {"id": (s.get("link_structure_id") if s else None)}

        def _fuelle_stationen(paare):
            _vorher = _stat_gewaehlt["id"]
            station_cb.blockSignals(True)
            station_cb.clear()
            if paare:
                station_cb.addItem(t("\u2014 none \u2014"), None)
                for _sid2, _nm2 in paare:
                    station_cb.addItem(_nm2, _sid2)
                _ix2 = station_cb.findData(_vorher)
                station_cb.setCurrentIndex(_ix2 if _ix2 >= 0 else 0)
            else:
                station_cb.addItem(t("\u2014 no NPC station in this system \u2014"), None)
            station_cb.blockSignals(False)

        def _stat_gewaehlt_hat(*_a):
            _stat_gewaehlt["id"] = station_cb.currentData()
            # Den Namen gleich uebernehmen, solange der Nutzer keinen eigenen
            # eingetippt hat - sonst steht in der Liste spaeter "Structure".
            if station_cb.currentData() and not name.text().strip():
                name.setText(station_cb.currentText())
        station_cb.currentIndexChanged.connect(_stat_gewaehlt_hat)
        # Verknüpfung mit einer echten EVE-Struktur (für "Assets abziehen"): nur so
        # weiß das Tool, welche Assets tatsächlich HIER liegen. Quelle sind deine
        # bekannten Strukturen (Favoriten mit structure_id + character_id).
        link = QComboBox()
        link.addItem(t("\u2014 none (assets not location-bound) \u2014"), None)
        # STRUKTUREN UND NPC-STATIONEN (Sitzung 19) - siehe _link_orte.
        _known = self._link_orte()
        for f in _known:
            link.addItem(" " + (f.get("name") or str(f.get("structure_id"))),
                         {"structure_id": f.get("structure_id"),
                          "character_id": f.get("character_id"),
                          "name": f.get("name")})
        if s and s.get("link_structure_id"):
            for i in range(link.count()):
                d = link.itemData(i)
                if isinstance(d, dict) and d.get("structure_id") == s.get("link_structure_id"):
                    link.setCurrentIndex(i); break
        link.setToolTip(t("Link this build structure to its real EVE structure so that \u201eDeduct "
                          "assets\u201c only counts material that really lies HERE (not in Jita or "
                          "elsewhere). The list comes from your known structures \u2013 if one is "
                          "missing, add it in the hub/structure area at the top."))
        _link_row = form.rowCount()
        form.addRow(t("Real EVE structure"), link)
        sec = QComboBox()
        for val, lab in self._SEC_LEVELS:
            sec.addItem(lab, val)
        if s:
            ix = sec.findData(s.get("security", 1.0)); sec.setCurrentIndex(max(0, ix))
        form.addRow(t("Security (auto)"), sec)
        # FACILITY-TAX: die Job-Kosten-Formel LIEST diesen Wert seit jeher aus
        # der Struktur (`s.get("facility_tax", ...)` in _bau_jobcost_opts), es
        # gab dafuer nur nie ein Eingabefeld - man konnte ihn also gar nicht
        # setzen (Nutzer: "ich kann hier gar nichts facility Tax selber
        # setzen"). Ohne Eintrag greift die globale Vorgabe aus Setup, und die
        # ist ein GERATENER Wert (0,25 %), kein gemessener: ESI liefert den
        # System-Index, aber NICHT die Steuer des Strukturbesitzers.
        ftax_sp = QDoubleSpinBox()
        ftax_sp.setRange(0.0, 100.0)
        ftax_sp.setDecimals(2)
        ftax_sp.setSingleStep(0.25)
        ftax_sp.setSuffix(" %")
        ftax_sp.setValue(float((s or {}).get(
            "facility_tax", self.settings.get("bau_facility_tax", 0.25)) or 0.0))
        _ftax_tip = (
            t("Tax the OWNER of this structure charges on industry jobs.\n"
              "In game: Show Info on the structure.\n"
              "Own structure usually 0 %, foreign 1-5 %.\n"
              "Enters the job cost as EIV \u00d7 (facility tax + 4 % SCC) - does NOT come "
              "from ESI, so it has to be entered here. Left empty, the value from "
              "Setup applies."))
        ftax_sp.setToolTip(_ftax_tip)
        form.addRow(t("Facility tax (owner)"), ftax_sp)
        idx_store = {"mfg": (s.get("system_mfg_index") if s else None),
                     "reaction": (s.get("system_reaction_index") if s else None),
                     "sysid": (s.get("system_id") if s else None)}
        _rig_row0 = form.rowCount()
        rig_combos = []
        rig_list = self._rigs_for_type(typ.currentData())
        cur_rigs = list((s.get("rigs") if s else None) or [])
        while len(cur_rigs) < 3:
            cur_rigs.append("")
        for i in range(3):
            rc = QComboBox()
            for k, lab in rig_list:
                rc.addItem(lab, k)
            ix = rc.findData(cur_rigs[i]); rc.setCurrentIndex(max(0, ix))
            form.addRow(t("Rig slot {n}").format(n=i + 1), rc)
            rig_combos.append(rc)

        def _slot_count():
            return self._STRUCT_RIG_SLOTS.get(typ.currentData(), 3)

        def _apply_slot_vis():
            n = _slot_count()
            for i in range(3):
                try:
                    form.setRowVisible(_rig_row0 + i, i < n)
                except Exception:
                    rig_combos[i].setVisible(i < n)
        _apply_slot_vis()
        preview = QLabel(""); preview.setObjectName("Muted"); preview.setWordWrap(True)
        v.addWidget(preview)

        def _upd(*_a):
            n = _slot_count()
            secv = sec.currentData() or 1.0
            tmp = {"rigs": [rc.currentData() for rc in rig_combos[:n]], "security": secv}
            preview.setText(t(
                "\u2192 Effective (security \u00d7{sec}):  Material up to \u2212{me} %  \u00b7  "
                "Time \u2212{te} %  \u00b7  Reaction mat up to \u2212{rme} %  \u00b7  "
                "Job cost \u2212{cost} %\n(Material rigs only affect the matching item "
                "type \u2013 e.g. \u201eAdvanced Component\u201c not the ship hull.)"
            ).format(sec=f"{secv:g}",
                     me=f"{self._struct_rig_pct(tmp, 'me'):.1f}",
                     te=f"{self._struct_rig_pct(tmp, 'te'):.0f}",
                     rme=f"{self._struct_rig_pct(tmp, 'rme'):.1f}",
                     cost=f"{self._struct_rig_pct(tmp, 'cost'):.0f}"))
        for _c in [sec] + rig_combos:
            _c.currentIndexChanged.connect(_upd)

        def _refill_rigs(*_a):
            new_rigs = self._rigs_for_type(typ.currentData())
            for rc in rig_combos:
                cur = rc.currentData()
                rc.blockSignals(True); rc.clear()
                for k, lab in new_rigs:
                    rc.addItem(lab, k)
                ix = rc.findData(cur)
                rc.setCurrentIndex(ix if ix >= 0 else 0)
                rc.blockSignals(False)
            _apply_slot_vis()
            _upd()
        typ.currentIndexChanged.connect(_refill_rigs)

        def _apply_npc(*_a):
            """Facility Tax fuer NPC-Stationen festnageln.

            CCP hat sie mit Viridian auf 0,25 % gesetzt (davor 10 %). Bei
            Spielerstrukturen bestimmt sie der Besitzer, deshalb ist das Feld
            dort frei - bei einer NPC-Station waere jede andere Zahl schlicht
            falsch, und ein offenes Feld laedt zum Raten ein.
            """
            _ist_npc = (typ.currentData() == "npc")
            try:
                form.setRowVisible(_stat_row, _ist_npc)
                # ZWEI WEGE ZUM SELBEN ZIEL VERWIRREN (Sitzung 19). Bei einer
                # NPC-Station ist die gewaehlte Station schon der echte Ort -
                # die Verknuepfungszeile daneben stehen zu lassen sieht aus,
                # als muesse man dort noch etwas tun. Sie taugt dafuer auch
                # nicht: sie listet Orte, an denen man bereits etwas liegen
                # hat.
                form.setRowVisible(_link_row, not _ist_npc)
            except Exception:
                station_cb.setVisible(_ist_npc)
                link.setVisible(not _ist_npc)
            if _ist_npc:
                ftax_sp.setValue(0.25)
            ftax_sp.setEnabled(not _ist_npc)
            ftax_sp.setToolTip(
                t("Fixed at 0.25 % in NPC stations \u2013 CCP sets this rate, "
                  "it cannot be changed.") if _ist_npc else _ftax_tip)
            # Wer das System zuerst eingetippt und DANN auf NPC-Station
            # umgestellt hat, haette sonst eine leere Auswahl vor sich.
            if _ist_npc and station_cb.count() <= 1 and system.text().strip():
                _fetch_sys()
        typ.currentIndexChanged.connect(_apply_npc)
        # Der erste Aufruf steht ABSICHTLICH weiter unten, hinter _fetch_sys:
        # _apply_npc darf beim Umschalten nachladen, und beim Oeffnen eines
        # bestehenden Eintrags ist das System schon gefuellt - dann liefe es
        # hier in einen NameError.
        _upd()

        def _fetch_sys(*_a):
            nm = system.text().strip()
            sysid = sys2id.get(nm.lower())
            if not sysid:
                # STILLES NICHTS IST DIE SCHLECHTESTE ANTWORT (Sitzung 19):
                # vorher kehrte die Funktion bei einem Tippfehler wortlos um,
                # und die Stationsauswahl blieb auf "erst ein System waehlen"
                # stehen - als sei das Feld kaputt.
                if nm:
                    _fuelle_stationen([])
                    station_cb.setItemText(0, t("\u2014 system not found \u2014"))
                return
            idx_store["sysid"] = sysid

            def sjob():
                info = esi.system_info(sysid)
                idxs = esi.system_cost_indices()
                d = idxs.get(int(sysid), {}) or {}
                # STATIONEN DES SYSTEMS MIT NAMEN (Sitzung 19). Die IDs stehen
                # schon in derselben Antwort; nur die Namen kosten je einen
                # oeffentlichen Abruf. Ein System hat eine Handvoll Stationen,
                # das ist billig - und erspart dem Nutzer, eine Nummer
                # abzutippen oder einen Ingame-Link zu kopieren (Nutzer,
                # Sitzung 19: "ist es nicht einfach den exakten Struktur Namen
                # einzutippen?" - noch einfacher ist: gar nichts tippen).
                stationen = []
                # NUR WENN ES GEBRAUCHT WIRD (Sitzung 19). Jeder Stationsname
                # ist ein eigener Abruf. Wer eine Spielerstruktur eintraegt,
                # sieht die Auswahl gar nicht - dann waeren das mehrere
                # Abrufe, die das Systemfeld ohne Nutzen traege machen.
                for _stid in ((info.get("stations") or [])
                              if typ.currentData() == "npc" else []):
                    try:
                        _si = esi.resolve_station(_stid)
                    except Exception:
                        continue
                    stationen.append((int(_stid), _si.get("name") or str(_stid)))
                stationen.sort(key=lambda x: x[1])
                return {"sec": info.get("security", 1.0),
                        "mfg": d.get("manufacturing", 0.0) or 0.0,
                        "reaction": d.get("reaction", 0.0) or 0.0,
                        "stationen": stationen}

            def sdone(r):
                secv = r["sec"]
                mult = 1.0 if secv >= 0.45 else (1.9 if secv > 0.0 else 2.1)
                self._combo_select(sec, mult)
                idx_store["mfg"] = r["mfg"]; idx_store["reaction"] = r["reaction"]
                _fuelle_stationen(r.get("stationen") or [])
                _upd()
            self._run(Worker(sjob), sdone, overlay=False)
        _apply_npc()          # jetzt ist _fetch_sys bekannt
        system.editingFinished.connect(_fetch_sys)
        from PySide6.QtCore import QTimer as _QTimer
        comp.activated.connect(lambda *_a: _QTimer.singleShot(0, _fetch_sys))
        btns = QHBoxLayout(); btns.addStretch()
        save = QPushButton(t("Save")); btns.addWidget(save)
        save.setIcon(icons.icon("check"))
        cancel = QPushButton(t("Cancel")); cancel.clicked.connect(dlg.reject)
        cancel.setIcon(icons.icon("close"))
        btns.addWidget(cancel)
        v.addLayout(btns)

        def _save():
            import time as _t
            sys_name = system.text().strip()
            data = {"id": (s["id"] if s else int(_t.time() * 1000)),
                    "name": name.text().strip() or t("Structure"),
                    "type": typ.currentData(), "system": sys_name,
                    "system_id": idx_store.get("sysid") or sys2id.get(sys_name.lower()),
                    "security": sec.currentData(),
                    "rigs": [rc.currentData() for rc in rig_combos[:_slot_count()]
                             if rc.currentData()],
                    "system_mfg_index": idx_store.get("mfg"),
                    "system_reaction_index": idx_store.get("reaction"),
                    # Prozentwert wie im Feld - _bau_jobcost_opts teilt selbst
                    # durch 100. Genau der Schluessel, den die Rechnung liest.
                    "facility_tax": float(ftax_sp.value())}
            # Verknüpfung mit echter EVE-Struktur (für ortsgebundenes Assets-Abziehen).
            # Bei einer NPC-Station ist die gewaehlte Station zugleich der
            # echte Ort - eine zweite Verknuepfung waere doppelte Arbeit.
            if typ.currentData() == "npc" and _stat_gewaehlt["id"]:
                data["link_structure_id"] = int(_stat_gewaehlt["id"])
                data["link_character_id"] = 0
                data["link_search_done"] = True
                # AUCH ALS ORT MERKEN (Sitzung 19). Ohne diesen Eintrag kennt
                # `_link_orte` die Station nicht, und ueberall, wo der Name
                # nachgeschlagen wird, stuende die nackte Nummer - genau das
                # ist dem Nutzer aufgefallen: "was ist gemeint mit 60003883".
                try:
                    _sid_fav = int(_stat_gewaehlt["id"])
                    if not any(f.get("station_id") == _sid_fav
                               for f in store.list_favorites()):
                        store.add_favorite(
                            {"kind": "station",
                             "name": station_cb.currentText() or str(_sid_fav),
                             "structure_id": None, "character_id": 0,
                             "region_id": None, "station_id": _sid_fav})
                except Exception:
                    pass
            _linkd = link.currentData()
            if isinstance(_linkd, dict) and _linkd.get("structure_id"):
                data["link_structure_id"] = _linkd.get("structure_id")
                data["link_character_id"] = _linkd.get("character_id")
            lst = self.settings.get("bau_structures", []) or []
            if s:
                lst = [data if x["id"] == s["id"] else x for x in lst]
            else:
                lst.append(data)
            self.settings["bau_structures"] = lst
            config.save_settings(self.settings)
            self._reload_structures()
            dlg.accept()
        save.clicked.connect(_save)
        dlg.exec()

    @classmethod
    def _bau_eintraege_aus_funden(cls, funde, typnamen, systeme, indizes,
                                  vorhandene_links, facility_tax, basis_id):
        """Fertige Bau-Struktur-Eintraege aus gefundenen EVE-Strukturen.

        Sitzung 17 (Nutzer: "waere doch voll geil, wenn mir die Struktur-
        eintraege soweit es geht direkt fertiggestellt werden. Die Rigs muss
        ich dann selber eintragen"). Befuellt wird genau, was der Struktur-
        Dialog beim Speichern schreibt - ausser den Rigs.

        Der Typ kommt aus dem ESI-TYPNAMEN ("Raitaru" -> raitaru), nicht aus
        fest eingetragenen Typ-IDs. Uebersprungen (mit Grund): Strukturen, die
        schon mit einem Eintrag verknuepft sind, und alles ausser Engineering
        Complexes/Refineries (Citadels haben keinen Bau-Rollenbonus).
        Rueckgabe: (neue_eintraege, [(name, grund), ...]).
        """
        bekannt = {k for k, _l in cls._STRUCT_TYPES}
        neu, weg = [], []
        for i, f in enumerate(funde or []):
            nm = str(f.get("name") or f.get("structure_id") or "?")
            sid = f.get("structure_id")
            if sid in (vorhandene_links or set()):
                weg.append((nm, "already linked"))
                continue
            typ = str(typnamen.get(f.get("type_id")) or "").strip().lower()
            if typ not in bekannt:
                weg.append((nm, "not an engineering complex or refinery"))
                continue
            sysid = f.get("solar_system_id")
            sy = systeme.get(sysid) or {}
            secv = sy.get("security")
            if secv is None:
                mult = 1.0
            else:
                mult = 1.0 if secv >= 0.45 else (1.9 if secv > 0.0 else 2.1)
            ix = indizes.get(int(sysid)) if sysid else None
            ix = ix or {}
            neu.append({
                "id": int(basis_id) + i,
                # "Name" wie EVE ihn liefert: "System - Strukturname"
                "name": nm,
                "type": typ,
                "system": sy.get("name") or "",
                "system_id": sysid,
                "security": mult,
                "rigs": [],                      # traegt der Nutzer selbst ein
                "system_mfg_index": ix.get("manufacturing"),
                "system_reaction_index": ix.get("reaction"),
                "facility_tax": float(facility_tax),
                "link_structure_id": sid,
                "link_character_id": f.get("character_id"),
                "link_search_done": True,
            })
        return neu, weg

    def _bau_funde_frage(self, text):
        """Frage vor dem Anlegen - Vorgabe ANLEGEN (Nutzer-Wunsch). Eigene
        Methode, damit die Pruefung sie ersetzen kann (kein modales Fenster)."""
        _box = QMessageBox(self)
        _box.setIcon(QMessageBox.Question)
        _box.setWindowTitle(t("Structures added"))
        _box.setText(text)
        _ja = _box.addButton(t("Create entries"), QMessageBox.AcceptRole)
        _box.addButton(t("Only save as locations"), QMessageBox.RejectRole)
        _box.setDefaultButton(_ja)
        _box.exec()
        return _box.clickedButton() is _ja

    def _bau_funde_anbieten(self, added, funde):
        """Nach der Struktur-Suche: aus den Funden auf Wunsch fertige
        Bau-Struktur-Eintraege machen (nur Rigs fehlen dann noch)."""
        _links = {x.get("link_structure_id") for x in
                  (self.settings.get("bau_structures", []) or [])
                  if x.get("link_structure_id")}
        _bekannt = {k for k, _l in self._STRUCT_TYPES}
        _kand = [f for f in funde if f.get("structure_id") not in _links
                 and str(f.get("type_name") or "").strip().lower() in _bekannt]
        _liste = "\n".join("\u2022 " + n for n in added)
        if not _kand:
            QMessageBox.information(
                self, t("Structures added"),
                t("Found and saved:\n\n") + _liste
                + t("\n\nNow choose it in the \u201eBuild location\u201c dropdown above."))
            return
        _kliste = "\n".join(
            f"\u2022 {f.get('name')} ({f.get('type_name')})" for f in _kand)
        if not self._bau_funde_frage(
                (t("Found and saved:\n\n") + _liste + "\n\n" if added else "")
                + t("These can become build structures:") + "\n" + _kliste
                + t("\n\nCreate build-structure entries for them? Name, type, system, "
                    "security, cost index and the link are filled in \u2013 you only "
                    "add the rigs. (Only engineering complexes and refineries; "
                    "citadels are skipped.)")):
            return
        _tax = self.settings.get("bau_facility_tax", 0.25)

        def job():
            _tn = {f.get("type_id"): f.get("type_name") for f in _kand}
            _sy = {}
            for _sid in {f.get("solar_system_id") for f in _kand if f.get("solar_system_id")}:
                try:
                    _sy[_sid] = esi.system_info(_sid)
                except Exception:
                    _sy[_sid] = {}
            try:
                _ix = esi.system_cost_indices()
            except Exception:
                _ix = {}
            return _tn, _sy, _ix

        def done(res):
            import time as _t
            _tn, _sy, _ix = res
            neu, weg = self._bau_eintraege_aus_funden(
                _kand, _tn, _sy, _ix, _links, _tax, int(_t.time() * 1000))
            if neu:
                self.settings["bau_structures"] = (
                    (self.settings.get("bau_structures", []) or []) + neu)
                config.save_settings(self.settings)
                self._reload_structures()
            _txt_neu = "\n".join(
                f"\u2022 {e['name']} ({e['type'].capitalize()}, {e['system'] or '?'})"
                for e in neu) or t("(none)")
            _txt_weg = ("\n\n" + t("Skipped:") + "\n" + "\n".join(
                f"\u2022 {n} \u2013 {t(g)}" for n, g in weg)) if weg else ""
            QMessageBox.information(
                self, t("Build structures created"),
                t("Created:") + "\n" + _txt_neu + _txt_weg
                + (t("\n\nStill to do: enter the rigs \u2013 click \u201eEdit\u201c on "
                     "each structure.") if neu else ""))

        def fail(msg):
            QMessageBox.information(self, t("Structure search failed"),
                                    t("Could not load the structure details: ") + str(msg))
        self._run(Worker(job), done, fail_cb=fail, overlay=False)

    def _delete_structure(self, sid):
        lst = self.settings.get("bau_structures", []) or []
        self.settings["bau_structures"] = [x for x in lst if x["id"] != sid]
        amap = self.settings.get("bau_activity_struct", {}) or {}
        self.settings["bau_activity_struct"] = {k: v for k, v in amap.items() if v != sid}
        config.save_settings(self.settings)
        self._reload_structures()

    def _serial_plan_seconds(self, plan, type_id):
        """Serielle Bauzeit (ein Job nach dem anderen, keine Char-Parallelität) aus
        einem Plan – Fallback für den Kalender, wenn keine Bau-Charaktere gewählt
        sind. Nutzt pro Job den KORREKTEN Zeitfaktor (inkl. Struktur-Rollen-Bonus
        wie Tatara −25 %), damit der Kalender dieselbe Zeit wie der Runplaner zeigt."""
        recipes = getattr(self, "_bd_recipes", None)
        if not plan or not recipes:
            return 0
        _groups = getattr(self, "_bd_groups", {}) or {}
        _mfg_struct = getattr(self, "_bd_mfg_struct", None)
        _react_struct = getattr(self, "_bd_react_struct", None)
        # Stufen-Karte fuer die Je-Stufe-Struktur (Sitzung 9, Simurgh).
        try:
            _sm_sp = industry.reaction_stage_map(recipes)
        except Exception:
            _sm_sp = {}
        total = 0.0
        for t, runs in plan.get("build_runs", {}).items():
            if runs < 1:
                continue
            bp = recipes.product_to_bp.get(t)
            if not bp:
                continue
            bp_id, activity, _oq = bp
            base_t = recipes.activity_time.get((bp_id, activity), 0) or 0
            _s_item = self._bau_struct_fuer_item(
                t, recipes.reaction_products, _sm_sp, type_id)
            te = self._bau_category_te_factor(
                t, _groups, recipes.reaction_products, type_id,
                mfg_struct=_s_item or _mfg_struct,
                react_struct=_s_item or _react_struct)
            total += base_t * runs * te
        return int(total)

    def _icon_html_hero(self, type_id, size=44):
        """Wie _icon_html, aber bevorzugt das große 3D-'render'-Bild (nur für
        Schiffe verfügbar) statt des kleinen quadratischen Icons - für
        prominente Kopfzeilen (z.B. die Bauplan-Titelzeile). Fällt automatisch
        auf 'icon' zurück, wenn kein Render existiert (Module/Munition/
        Komponenten haben keins) - NIE ein kaputtes Bild."""
        if not type_id:
            return ""
        html = self._icon_html(type_id, size=size, kind="render")
        if html:
            return html
        return self._icon_html(type_id, size=size, kind="icon")

    def _icon_html(self, type_id, size=20, kind="icon"):
        """<img>-Tag für ein Item-Icon (lokal gecacht unter icon_cache/), zum
        Einbetten in Rich-Text-QLabels (setText mit HTML). Leerstring, wenn
        kein Icon verfügbar ist - dann bleibt der Text einfach ohne Icon,
        NIE ein kaputtes Platzhalter-Bild. kind='icon' für normale Items,
        kind='bp' für Blueprint-Originale (eigene Bild-Kategorie bei CCP -
        'icon' liefert für Blueprint-typeIDs ein 404)."""
        if not type_id:
            return ""
        pm = self._item_pixmap(type_id, size=size, kind=kind, allow_fetch=False)
        if not pm:
            return ""
        cache_path = os.path.join(config.app_data_dir(), "icon_cache",
                                  self._icon_cache_name(
                                      type_id, kind, self._icon_fetch_size(size)))
        if not os.path.exists(cache_path):
            return ""
        url = "file:///" + cache_path.replace("\\", "/")
        return (f'<img src="{url}" width="{size}" height="{size}" '
                f'style="vertical-align:middle;">&nbsp;')




    def _item_pixmap(self, type_id, size=64, kind="icon", allow_fetch=True):
        """Item-Icon/Schiffs-Render als QPixmap, mit Disk-Cache (damit wir nicht
        bei jedem Dialog-Öffnen neu von images.evetech.net laden). None, wenn
        kein Bild verfügbar (z.B. 404) - der Aufrufer zeigt dann Text-Fallback,
        NIE ein geratenes/Platzhalter-Bild als "echtes" Icon ausgeben.
        WICHTIG: CCPs Bilder-Server akzeptiert nur feste Größen (32/64/128/256/
        512) - andere Werte werden abgelehnt. Die ANGEFRAGTE Größe wird daher
        auf die nächstgrößere gültige CCP-Größe gerundet; die Darstellung im
        UI (z.B. per .scaled()) bleibt trotzdem frei wählbar."""
        if not type_id or int(type_id) <= 0:      # Buendel (-1): kein Bild
            return None
        from PySide6.QtGui import QPixmap
        fetch_size = self._icon_fetch_size(size)
        cache = getattr(self, "_icon_pixmap_cache", None)
        if cache is None:
            cache = self._icon_pixmap_cache = {}
        key = (int(type_id), fetch_size, kind)
        if key in cache:
            return cache[key]
        pm = None
        cache_dir = os.path.join(config.app_data_dir(), "icon_cache")
        cache_path = os.path.join(cache_dir, self._icon_cache_name(
            type_id, kind, fetch_size))
        try:
            if os.path.exists(cache_path):
                pm = QPixmap(cache_path)
                if pm.isNull():
                    pm = None
        except Exception:
            pm = None
        if pm is None and not allow_fetch:
            # CACHE-ONLY (Massen-Aufbau von Listen/Karten): NICHT synchron aus
            # dem Netz holen - genau das kostete beim Oeffnen des Bauplans
            # ~62 % der Zeit (hunderte HTTP-Abrufe im GUI-Thread, gemessen in
            # messung_invention_tab.py). Stattdessen vormerken; der
            # Hintergrund-Lauf holt sie und traegt sie EINMAL nach.
            _w = getattr(self, "_icon_wanted", None)
            if _w is None:
                _w = self._icon_wanted = set()
            _w.add(key)
            return None
        if pm is None:
            try:
                data = esi.fetch_type_image_bytes(type_id, size=fetch_size, kind=kind)
                pm = QPixmap()
                if not pm.loadFromData(data):
                    pm = None
                    # de_scan2: aus  (fehler.log, nie in der Oberflaeche)
                    self._log_icon_error(type_id, fetch_size, kind,
                                         f"Antwort war kein gültiges Bild "
                                         f"({len(data)} Bytes erhalten)")
                    # de_scan2: an
                elif not os.path.exists(cache_dir):
                    os.makedirs(cache_dir, exist_ok=True)
                    pm.save(cache_path, "PNG")
                elif not os.path.exists(cache_path):
                    pm.save(cache_path, "PNG")
            except Exception as e:
                pm = None
                self._log_icon_error(type_id, fetch_size, kind, repr(e))
        cache[key] = pm
        return pm


    def _icon_prefetch_pending(self, refresh_cb=None):
        """Vorgemerkte Icons EINMAL im Hintergrund holen, danach GENAU EINEN
        Nachtrag anstossen (Regel 13: entkoppelt ueber QTimer.singleShot,
        nie synchron aus dem Signal heraus - der Nachtrag baut Widgets neu,
        in denen das Signal entstehen koennte).

        Der Nachtrag laeuft nur, wenn wirklich neue Bilder ankamen, und jeder
        Schluessel wird nur EINMAL versucht (`_icon_tried`) - sonst dreht sich
        aufbauen -> vormerken -> holen -> aufbauen endlos, wenn ein Bild
        dauerhaft fehlt (404)."""
        if getattr(self, "_icon_prefetch_running", False):
            # NICHT verwerfen (Nutzer-Fund: Order-Update ohne ein einziges
            # Bild): vorher wurden die Wuensche GELEERT und dann bei
            # "laeuft schon" weggeworfen - wer als Zweiter kam (waehrend
            # Bauplan oder Wagen holten), verlor seine Icons fuer die ganze
            # Sitzung. Jetzt bleiben die Wuensche stehen, der Rueckruf wird
            # gemerkt, und der LAUFENDE Lauf haengt am Ende einen Folgelauf
            # an (s. _done/_fail).
            if refresh_cb is not None:
                self._icon_prefetch_followup = refresh_cb
            return False
        keys = self._icon_keys_to_fetch(getattr(self, "_icon_wanted", None),
                                        getattr(self, "_icon_tried", None))
        self._icon_wanted = set()
        if not keys:
            return False
        tried = getattr(self, "_icon_tried", None)
        if tried is None:
            tried = self._icon_tried = set()
        tried.update(keys)
        self._icon_prefetch_running = True
        cache_dir = os.path.join(config.app_data_dir(), "icon_cache")

        def _write(_dir, _name, _data):
            with open(os.path.join(_dir, _name), "wb") as fh:
                fh.write(_data)

        def _job(should_cancel=None):
            return self._icon_prefetch_job(
                keys, cache_dir, esi.fetch_type_image_bytes,
                lambda d: os.makedirs(d, exist_ok=True), _write,
                should_cancel=should_cancel)

        def _folgelauf():
            """Waehrend des Laufs aufgelaufene Wuensche abarbeiten - der
            gemerkte Rueckruf des wartenden Tabs kommt mit."""
            _cb = getattr(self, "_icon_prefetch_followup", None)
            self._icon_prefetch_followup = None
            if getattr(self, "_icon_wanted", None) or _cb:
                QTimer.singleShot(
                    0, lambda: self._icon_prefetch_pending(_cb))

        def _done(res):
            self._icon_prefetch_running = False
            n_ok = (res or (0, 0))[0]
            if n_ok:
                # Die None-Eintraege dieser Schluessel aus dem Speicher-
                # Cache werfen, damit sie beim Nachtrag frisch von der
                # Platte kommen.
                _mem = getattr(self, "_icon_pixmap_cache", None) or {}
                for k in keys:
                    _mem.pop(k, None)
                if refresh_cb:
                    QTimer.singleShot(0, refresh_cb)
            _folgelauf()

        def _fail(_msg):
            self._icon_prefetch_running = False
            _folgelauf()

        w = Worker(_job, with_cancel=True)
        self._icon_prefetch_worker = w      # Referenz halten (sonst GC)
        self._run(w, _done, fail_cb=_fail, overlay=False)
        return True

    def _log_icon_error(self, type_id, size, kind, msg):
        """Merkt sich Icon-Ladefehler sichtbar (statt sie stillschweigend zu
        verschlucken), damit sich per '\U0001F5BC Icon-Verbindung testen'
        nachvollziehen lässt, WARUM Bilder nicht laden (z.B. Firewall/Proxy
        blockiert images.evetech.net, obwohl esi.evetech.net erreichbar ist)."""
        errs = getattr(self, "_icon_fetch_errors", None)
        if errs is None:
            errs = self._icon_fetch_errors = []
        errs.append(f"type_id={type_id} size={size} kind={kind}: {msg}")
        if len(errs) > 20:
            del errs[:len(errs) - 20]


    def _character_pixmap(self, character_id, size=64):
        """Charakter-Portrait als QPixmap, mit Disk-Cache (analog zu
        _item_pixmap). None, wenn kein Bild verfügbar - der Aufrufer zeigt
        dann einfach keins, nie ein geratenes Platzhalter-Bild."""
        if not character_id:
            return None
        from PySide6.QtGui import QPixmap
        fetch_size = next((s for s in (32, 64, 128, 256, 512, 1024) if s >= size), 1024)
        cache = getattr(self, "_portrait_pixmap_cache", None)
        if cache is None:
            cache = self._portrait_pixmap_cache = {}
        key = (int(character_id), fetch_size)
        if key in cache:
            return cache[key]
        pm = None
        cache_dir = os.path.join(config.app_data_dir(), "icon_cache")
        cache_path = os.path.join(cache_dir, f"char_{key[0]}_{fetch_size}.png")
        try:
            if os.path.exists(cache_path):
                pm = QPixmap(cache_path)
                if pm.isNull():
                    pm = None
        except Exception:
            pm = None
        if pm is None:
            try:
                data = esi.fetch_character_portrait_bytes(character_id, size=fetch_size)
                pm = QPixmap()
                if not pm.loadFromData(data):
                    pm = None
                else:
                    os.makedirs(cache_dir, exist_ok=True)
                    pm.save(cache_path, "PNG")
            except Exception:
                pm = None
        cache[key] = pm
        return pm

    def _character_icon(self, character_id, size=32):
        """QIcon aus dem Charakter-Portrait, fürs Charaktere-Tab. None, wenn
        kein Bild verfügbar."""
        pm = self._character_pixmap(character_id, size=size)
        if not pm or pm.isNull():
            return None
        from PySide6.QtGui import QIcon
        return QIcon(pm)

    @staticmethod
    def _short_qty(n):
        """Grosse Stueckzahlen lesbar kuerzen (Nutzer: weniger Ziffernrauschen).
        21'957'687 -> 21.96M, 252'407 -> 252.4k, 4'108 -> 4'108.
        Unter 10'000 bleibt es exakt - dort zaehlt jede Einheit."""
        try:
            v = int(n)
        except (TypeError, ValueError):
            return str(n)
        a = abs(v)
        if a >= 1_000_000:
            return f"{v / 1_000_000:.2f}M"
        if a >= 10_000:
            return f"{v / 1_000:.1f}k"
        return f"{v:,}".replace(",", "'")

    def _table_icon(self, type_id, size=20, kind="icon"):
        """QIcon fürs Item-Icon in Tabellenzellen (Portfolio, Verkaufsliste,
        Meine Blueprints, Scanner, Einkaufswagen) - nutzt denselben gecachten
        Pixmap-Pfad wie _icon_html/_icon_label. None, wenn kein Bild verfügbar
        (dann bleibt die Zeile einfach ohne Icon, kein Platzhalter)."""
        pm = self._item_pixmap(type_id, size=size, kind=kind, allow_fetch=False)
        if not pm or pm.isNull():
            return None
        from PySide6.QtGui import QIcon
        return QIcon(pm)

    def _icon_label(self, type_id, size=40, kind="icon"):
        """QLabel mit dem Item-Icon, oder leer (kein Platzhalter-Bild), falls
        keins verfügbar ist."""
        lbl = QLabel()
        pm = self._item_pixmap(type_id, size=size, kind=kind, allow_fetch=False)
        if pm:
            lbl.setPixmap(pm.scaled(size, size, Qt.KeepAspectRatio,
                                    Qt.SmoothTransformation))
        lbl.setFixedSize(size, size)
        lbl.setAlignment(Qt.AlignCenter)
        return lbl

    def _bp_fehlende_kopieren(self):
        """Knopf "Buy Missing Blueprints" im Blueprints-Reiter: fehlende
        Blaupausen als EVE-Multibuy ("Name<TAB>Menge", wie die Einkaufsliste)
        in die Zwischenablage. Rueckmeldung im Reiter selbst - ein Flash-Tip
        erschiene im Hauptfenster HINTER dem Bauplan-Dialog."""
        from PySide6.QtWidgets import QApplication as _QA
        _liste = getattr(self, "_bd_bp_kaufliste", None)
        _lbl = getattr(self, "_bd_bp_kauf_lbl", None)

        def _sag(txt, farbe):
            if _lbl is not None:
                try:
                    _lbl.setText(txt)
                    _lbl.setStyleSheet(f"color:{farbe};")
                    _lbl.show()
                except RuntimeError:
                    pass
        if _liste is None:
            _sag(t("Load ESI ownership first \u2013 without it nobody knows which "
                   "blueprints are missing."), theme.AMBER)
            return 0
        if not _liste:
            _sag(t("No blueprint is missing \u2713 (invented T2 copies are not "
                   "bought)."), theme.GREEN)
            return 0
        _QA.clipboard().setText("\n".join(f"{_n}\t{_q}" for _n, _q in _liste))
        _sag(t("{n} blueprint(s) copied \u2713 \u2013 paste into the in-game "
               "multibuy window.").format(n=len(_liste)), theme.GREEN)
        return len(_liste)

    def _fill_blueprint_tab(self, jobs, sched_chars, recipes, tbl):
        """Füllt den 'Blueprints'-Tab: pro benötigtem Blueprint (Zwischenmaterial
        bis Endprodukt) die empfohlene Kopienzahl für minimale Wellenzahl
        (industry.recommended_bp_copies, gedeckelt auf die tatsächlich für diese
        Aktivität verfügbaren Job-Slots der eingeplanten Charaktere) + ESI-Besitz
        (BPO-Anzahl, falls schon per '\U0001F50C ESI-Besitz laden' geholt).
        Gibt (n_missing, n_low, n_missing_by_stage, n_low_by_stage) zurück - wie
        viele Items komplett fehlen bzw. zu wenig Kopien haben, aufgeschlüsselt
        nach Stufe (Endprodukt/Komponente/Reaktion), damit der Runplaner selbst
        gezielt warnen kann (z.B. "Endprodukt fehlt" ist meist normal - das
        T2-BPC hat man vor der Planung ja noch nicht erfunden - während
        fehlende Komponenten/Reaktionen echte Engpässe sind)."""
        from PySide6.QtWidgets import QTableWidgetItem
        tbl.setSortingEnabled(False)
        # Verfügbare Slots je Aktivität: Summe über alle dafür eingeplanten Chars.
        # VEREINFACHUNG (bewusst, transparent): das ist der GESAMTE Pool, den sich
        # alle Items dieser Aktivität teilen -- kein exaktes Bin-Packing pro Item
        # (das macht schon der Runplaner). Als Obergrenze für "wie viele Kopien
        # sind überhaupt sinnvoll" reicht das aber, um keine 500-Kopien-Empfehlung
        # für ein Item mit nur 3 Slots zu geben.
        slots_by_activity = {industry.MANUFACTURING: 0, industry.REACTION: 0}
        for c in sched_chars:
            if c.get("can_mfg"):
                slots_by_activity[industry.MANUFACTURING] += int(c.get("mfg_slots", 0) or 0)
            if c.get("can_react"):
                slots_by_activity[industry.REACTION] += int(c.get("reaction_slots", 0) or 0)
        owned = getattr(self, "_bd_bp_owned_counts", None)
        owned_bpc = getattr(self, "_bd_bp_owned_bpc_runs", None) or {}
        # Reaktionsstufen einmalig ermitteln (Stufe 1 -> geht in eine weitere
        # Reaktion, Stufe 2 -> geht in den Bau). Wird unten fuer Sortierung
        # und Beschriftung gebraucht.
        try:
            _bp_stage_map = industry.reaction_stage_map(recipes) if recipes else {}
        except Exception:
            _bp_stage_map = {}
        rows = []
        for j in jobs:
            # DAS BUENDEL IST KEINE BLAUPAUSE (Nutzer-Befund 21.09.2026:
            # "im Blueprint-Tab wird Multiplan als Blueprint gewertet, ist
            # aber keiner - nur eine Gruppierung"). Der Multi-Bauplan hat ein
            # PSEUDO-Rezept (BUENDEL_BP), damit `production_plan` ueber
            # mehrere Endprodukte rechnen kann; `full_build_chain` liefert es
            # deshalb wie jedes andere Item mit. Im Blueprints-Tab stand es
            # dann als Komponente mit "completely missing - you need 1" -
            # eine Blaupause, die es im Spiel gar nicht gibt und die niemand
            # je besitzen kann.
            if int(j.get("tid", 0) or 0) == industry.BUENDEL_ID:
                continue
            bp_id = j.get("bp_id")
            activity = j.get("activity")
            total_runs = int(j.get("runs", 0) or 0)
            max_runs = recipes.activity_max_runs.get((bp_id, activity), 0) if recipes else 0
            avail_slots = slots_by_activity.get(activity, 1)
            copies, jobs_needed, waves = industry.recommended_bp_copies(
                total_runs, max_runs, avail_slots)
            # REAKTIONEN NACH STUFE TRENNEN (Nutzer: "sortiere bitte von
            # Intermediate Reactions zu normalen Reactions"). Stufe 1 liefert
            # die Vorprodukte, Stufe 2 verarbeitet sie weiter - in genau der
            # Reihenfolge baut man auch. Vorher stand alles als "Reaktion"
            # zusammen und war nur alphabetisch geordnet.
            if activity == industry.REACTION:
                _rst = _bp_stage_map.get(j.get("tid"), 1)
                # de_scan4: aus - Stufen-SCHLUESSEL (Sortierung); Anzeige via _kategorie_anzeige
                stage = ("Reaktion \u00b7 Stufe 1" if _rst == 1
                         else "Reaktion \u00b7 Stufe 2")
                # de_scan4: an
            elif j.get("is_end"):
                # de_scan4: aus - interner SCHLUESSEL (Kategorie/Stufe/Dict), Anzeige uebersetzt woanders
                stage = "Endprodukt"
                # de_scan4: an
            else:
                # FUEL und TOOLS als eigene Stufen (Nutzer-Vorgabe) - dieselbe
                # Einteilung wie im Materialien-Baum und im Rezept-Baum. Ohne
                # das liefen hier drei verschiedene Schemata nebeneinander.
                _inf_bp = (industry.item_category_map() or {}).get(j.get("tid"))
                _gm_bp = (getattr(self, "_bd_groups", None)
                          or getattr(self, "_bd_groups_cache", None) or {})
                try:
                    _kbp = self._category_key(
                        j.get("tid"), _gm_bp.get(j.get("tid"), ""), False,
                        _inf_bp[0] if _inf_bp else None,
                        _inf_bp[2] if _inf_bp else None)
                except Exception:
                    _kbp = None
                # de_scan2: aus  (Kategorie-SCHLUESSEL, Anzeige via _kategorie_anzeige)
                stage = ("H\u00fcllen" if _kbp == "t1_hulls"
                # de_scan2: an
                         # de_scan6: aus  (Kategorie-SCHLUESSEL wie die
                         # Nachbarzeilen; Anzeige via _kategorie_anzeige)
                         else "Fuel" if _kbp == "fuel_blocks"
                         else "Tools" if _kbp == "tools"
                         # de_scan6: an
                         # de_scan4: aus - interner SCHLUESSEL (Kategorie/Stufe/Dict), Anzeige uebersetzt woanders
                         else "Komponente")
                         # de_scan4: an
            have = owned.get(bp_id, 0) if owned is not None else None
            bpc_runs = owned_bpc.get(bp_id, 0)
            # DER NAME IN DER SPALTE "BLUEPRINT" IST DER BLAUPAUSEN-NAME
            # (Nutzer 21.09.2026: "es steht nur das Item, nicht Blueprint
            # hintendran - Magpulse Thruster, muesste aber Magpulse Thruster
            # Blueprint heissen"). Die Spalte heisst Blueprint, also gehoert
            # der Name hinein, unter dem man das Ding im Spiel sucht.
            # `_bp_name_fuer` ist dieselbe EINE Regel wie im Runplaner-
            # Rechtsklick: Reaktionen heissen "... Reaction Formula".
            # Der BASISNAME bleibt daneben erhalten (`basis`) - Kopieren,
            # Suche und Sortierung haengen daran, und zwei Schreibweisen
            # desselben Namens waeren im Spiel nicht auffindbar.
            _basis_bp = self._bp_basisname(
                j.get("tid"), j.get("name", f"#{j.get('tid')}"))
            # WIRD ERFUNDEN (Nutzer 26.09.2026: "bei T2 ist die Anzeige falsch,
            # 'completely missing' in Rot - da muesste stehen 'wird erfunden',
            # bitte nicht rot, vielleicht amber"). Dieselbe Bedingung wie die
            # Rechnung (industry: Fertigung, Invention an, Blaupause erfindbar,
            # kein "Eigene BPC"-Override) - sonst saegte die Anzeige etwas
            # anderes als der Plan. Kaufbar ist so eine T2-Kopie ohnehin nicht.
            _opts_bp = getattr(self, "_bd_opts", None) or {}
            _inv_tab = getattr(recipes, "invention_for_bpc", None) or {}
            _erfindbar = bp_id in _inv_tab
            _erfunden = bool(
                _erfindbar and activity == industry.MANUFACTURING
                and _opts_bp.get("invention")
                and bp_id not in (_opts_bp.get("inv_manual_override") or {}))
            rows.append({"basis": _basis_bp, "invented": _erfunden,
                         "inventable": _erfindbar,
                         "name": self._bp_name_fuer(_basis_bp, activity),
                         "stage": stage,
                        "runs": total_runs, "max_runs": max_runs, "copies": copies,
                        "waves": waves, "have": have, "bpc_runs": bpc_runs,
                        "bp_id": bp_id, "tid": j.get("tid")})
        # T1-ORIGINALE DER INVENTION ALS SOLCHE BENENNEN (emm323, Nutzer
        # 01.10.2026: "die zu inventenden T1-Blueprint-Originale werden als
        # Component deklariert - aber es sind Blueprints ... suche ich im
        # Hangar, ist das schwierig"). Die T1-Blaupause, aus der die T2-Kopie
        # erfunden wird, steht hier, weil sie AUCH das T1-Item baut, das in
        # das T2-Produkt geht - die Zeile sagt jetzt beides.
        _inv_tab9 = getattr(recipes, "invention_for_bpc", None) or {}
        _quellen9 = set()
        for _r9 in rows:
            if _r9.get("invented"):
                try:
                    _quellen9.add(int((_inv_tab9.get(_r9["bp_id"]) or (0,))[0] or 0))
                except (TypeError, ValueError):
                    continue
        _quellen9.discard(0)
        for _r9 in rows:
            # de_scan2: aus  (Kategorie-SCHLUESSEL, Anzeige via _kategorie_anzeige)
            if _r9.get("bp_id") in _quellen9 and _r9["stage"] in ("Komponente", "H\u00fcllen"):
                _r9["stage"] = "Invention-Quelle"
            # de_scan2: an
                _r9["inv_quelle"] = True
        # Reihenfolge = Bau-Reihenfolge von unten nach oben innerhalb der
        # Reaktionen, danach Komponenten, zuletzt das Endprodukt oben.
        # de_scan2: aus  (Kategorie-SCHLUESSEL, Anzeige via _kategorie_anzeige)
        _stage_order = {"Endprodukt": 0, "Invention-Quelle": 0.5,
                        "Komponente": 1, "H\u00fcllen": 2,
        # de_scan2: an
                        "Fuel": 3, "Tools": 4,
                        # de_scan4: aus - Stufen-SCHLUESSEL der Sortierung
                        "Reaktion \u00b7 Stufe 1": 5, "Reaktion \u00b7 Stufe 2": 6,
                        # de_scan4: an
                        # de_scan4: aus - interner SCHLUESSEL (Kategorie/Stufe/Dict), Anzeige uebersetzt woanders
                        "Reaktion": 7}
                        # de_scan4: an
        rows.sort(key=lambda r: (_stage_order.get(r["stage"], 9),
                                 r["name"].lower()))
        # "BUY MISSING BLUEPRINTS" (Nutzer 26.09.2026): was komplett fehlt
        # (weder Original noch Kopie), EIN Original je Blaupause - Kopien fuer
        # parallele Jobs zieht man selbst daraus. T2-Kopien (erfindbar) sind
        # nicht kaufbar und fehlen hier IMMER, auch mit "Eigene BPC".
        # None = Besitz noch nicht geladen (dann weiss niemand, was fehlt).
        self._bd_bp_kaufliste = (None if owned is None else [
            (r["name"], 1) for r in rows
            if not r.get("inventable")
            and not (r.get("have") or 0) and not (r.get("bpc_runs") or 0)])
        tbl.setRowCount(len(rows))
        n_missing = 0
        n_low = 0
        n_missing_by_stage = {}
        n_low_by_stage = {}
        for i, r in enumerate(rows):
            have = r["have"]
            bpc_runs = r["bpc_runs"]
            if have is None:
                have_txt, status_txt, status_col = "?", t("Load ESI ownership"), theme.MUTED
            elif r.get("invented") and not have and bpc_runs < r["runs"]:
                # T2-Kopie, die der Plan ERFINDET: kein Fehlen, kein Rot.
                have_txt = (f"{bpc_runs} Runs (BPC)" if bpc_runs else "0")
                status_txt = t("will be invented \u2697")
                status_col = theme.AMBER
            elif have > 0:
                # BPO vorhanden -> unbegrenzt nutzbar, wie bisher gegen die
                # empfohlene Kopienzahl vergleichen.
                have_txt = str(have)
                if have < r["copies"]:
                    status_txt = t("too few \u2013 get {n} more").format(n=r['copies'] - have)
                    status_col = theme.AMBER
                    n_low += 1
                    n_low_by_stage[r["stage"]] = n_low_by_stage.get(r["stage"], 0) + 1
                else:
                    status_txt = t("enough \u2713")
                    status_col = theme.GREEN
            elif bpc_runs > 0:
                # KEINE BPO, aber eigene BPC(s) mit begrenzten Runs - zählt
                # trotzdem, sonst zeigt die Tabelle fälschlich "fehlt komplett"
                # für Items, die man tatsächlich (teilweise) bauen kann.
                have_txt = f"{bpc_runs} Runs (BPC)"
                if bpc_runs >= r["runs"]:
                    status_txt = t("enough \u2713 (via BPC)")
                    status_col = theme.GREEN
                else:
                    fehlen = r["runs"] - bpc_runs
                    status_txt = t("too few \u2013 {n} more runs (BPC) needed").format(n=fehlen)
                    status_col = theme.AMBER
                    n_low += 1
                    n_low_by_stage[r["stage"]] = n_low_by_stage.get(r["stage"], 0) + 1
            else:
                have_txt = "0"
                status_txt = t("completely missing \u2013 you need {n}").format(n=r['copies'])
                status_col = theme.RED
                n_missing += 1
                n_missing_by_stage[r["stage"]] = n_missing_by_stage.get(r["stage"], 0) + 1
            # PUNKT C (Sitzung 20): dazuschreiben, wieviele der eigenen Kopien
            # NICHT an einer Bau-Struktur dieses Plans liegen. Nur bei "genug" -
            # wo ohnehin etwas fehlt, sagt die Zeile schon das Wichtigere.
            _anderswo = (getattr(self, "_bd_bp_elsewhere", None) or {}).get(r["bp_id"], 0)
            if _anderswo and status_col == theme.GREEN:
                status_txt += t(" ({n} not at the build structure)").format(n=_anderswo)
            cells = [
                r["name"], self._kategorie_anzeige(r["stage"]), f"{r['runs']:,}".replace(",", "'"),
                (f"{r['max_runs']:,}".replace(",", "'") if r["max_runs"] else "\u2013"),
                str(r["copies"]), have_txt, status_txt,
            ]
            for col, text in enumerate(cells):
                it = QTableWidgetItem(text)
                if col >= 2:
                    it.setTextAlignment(Qt.AlignRight | Qt.AlignVCenter)
                if col == 6:
                    it.setForeground(QColor(status_col))
                if col == 0:
                    _bic = self._table_icon(r.get("tid") or r.get("bp_id"))
                    if _bic:
                        it.setIcon(_bic)
                    # Fuers Kontextmenue SORT-SICHER am Item ablegen: die
                    # Tabelle ist sortierbar, ein Zeilenindex in die rows-
                    # Liste zeigte nach einem Kopfzeilen-Klick aufs falsche
                    # Item (selbst gefangen vor dem Testlauf).
                    it.setData(Qt.UserRole + 8, r.get("basis") or r.get("name"))
                    it.setData(Qt.UserRole + 7, r.get("stage"))
                if col == 1 and r.get("inv_quelle"):
                    it.setToolTip(t(
                        "T1 original for the invention of the T2 copy - it also "
                        "builds the T1 item that goes into the T2 product."))
                tbl.setItem(i, col, it)
            # STATUS ALS FARBIGE PILLE (Nutzer-Wunsch): liest sich schneller
            # als eine Textspalte und macht die Tabelle weniger nach
            # Datenblatt aussehen. Das Item darunter bleibt fuers Sortieren.
            _pill = QLabel(status_txt)
            _pill.setAlignment(Qt.AlignCenter)
            _pill.setStyleSheet(
                f"QLabel{{color:{status_col}; "
                f"background:rgba(255,255,255,0.06); "
                f"border:1px solid {status_col}; border-radius:9px; "
                f"padding:2px 10px; font-size:11px; font-weight:700;}}")
            _pw = QWidget(); _pl = QHBoxLayout(_pw)
            _pl.setContentsMargins(4, 2, 4, 2); _pl.addWidget(_pill)
            _pl.addStretch()
            # Das Item darunter bleibt FUERS SORTIEREN erhalten, sein TEXT
            # muss aber weg: die Pille hat einen halbtransparenten
            # Hintergrund, dadurch schien der Item-Text durch und stand
            # doppelt in der Zeile (Nutzer-Screenshot). Sortiert wird ueber
            # die Sortier-Rolle, nicht ueber den sichtbaren Text.
            _bi = tbl.item(i, 6)
            if _bi is not None:
                _bi.setText("")
            tbl.setCellWidget(i, 6, _pw)
        tbl.setSortingEnabled(True)
        # KONTEXTMENUE ZUM KOPIEREN (Nutzer, Sitzung 9: "diese Option
        # gefaellt mir - fuege das auch beim Tab Blueprints ein"). Gleiche
        # Namenskonvention wie im Runplaner: Produktname + " Blueprint",
        # Reaktionen als " Reaction Formula" (erkennbar an der Stufen-
        # Beschriftung). Quelle sind die ROWS-Daten, nicht der Anzeigetext.
        def _bp_such_name(r9):
            # BASIS, NICHT ANZEIGE: seit die Spalte den fertigen
            # Blaupausen-Namen zeigt, wuerde `name` hier ein zweites
            # " Blueprint" bekommen.
            base = str(r9.get("basis") or r9.get("name") or "").strip()
            if not base:
                return ""
            # de_scan4: aus - interner SCHLUESSEL (Kategorie/Stufe/Dict), Anzeige uebersetzt woanders
            if str(r9.get("stage", "")).startswith("Reaktion"):
            # de_scan4: an
                return f"{base} Reaction Formula"
            return f"{base} Blueprint"

        def _bp_tab_menu(pos, rows=rows, tbl=tbl):
            try:
                tbl.rowCount()   # Lebend-Waechter: Dialog kann zu sein
            except RuntimeError:
                return
            from PySide6.QtWidgets import QMenu
            from PySide6.QtWidgets import QApplication as _QA9
            m = QMenu(tbl)
            _hit = tbl.item(tbl.indexAt(pos).row(), 0) \
                if tbl.indexAt(pos).isValid() else None
            if _hit is not None:
                _nm9 = _bp_such_name({"name": _hit.data(Qt.UserRole + 8),
                                      "stage": _hit.data(Qt.UserRole + 7)})
                if _nm9:
                    a1 = m.addAction(t("Copy blueprint name"))
                    a1.triggered.connect(lambda *_a, _n=_nm9: (
                        _QA9.clipboard().setText(_n),
                        self._flash_tip(t("copied: {name}").format(name=_n))))
            a2 = m.addAction(t("Copy all blueprint names"))

            def _alle_kopieren():
                seen, out = set(), []
                for r9 in rows:
                    _n9 = _bp_such_name(r9)
                    if _n9 and _n9 not in seen:
                        seen.add(_n9)
                        out.append(_n9)
                if out:
                    _QA9.clipboard().setText("\n".join(out))
                    self._flash_tip(t("{n} blueprint names copied \u2013 one line per "
                                      "blueprint.").format(n=len(out)))
            a2.triggered.connect(_alle_kopieren)
            m.exec(tbl.viewport().mapToGlobal(pos))
        tbl.setContextMenuPolicy(Qt.CustomContextMenu)
        # Der Fuelllauf kann mehrfach laufen (Icon-Nachtrag!) - alte
        # Verbindungen erst loesen, sonst stapeln sich die Menues.
        # NUR LOESEN, WAS VERBUNDEN IST: beim ersten Lauf gab es nichts, und
        # PySide schrieb dann "Failed to disconnect (None)" in die Konsole
        # (Nutzer-Bildschirm 27.09.2026) - harmlos, aber Laerm.
        if getattr(tbl, "_bp_menue_verbunden", False):
            try:
                tbl.customContextMenuRequested.disconnect()
            except (TypeError, RuntimeError):
                pass
        tbl.customContextMenuRequested.connect(_bp_tab_menu)
        tbl._bp_menue_verbunden = True
        # ICON-NACHTRAG (Auftrag C): fehlende Bilder holen und die Tabelle
        # neu fuellen. LEBEND-WAECHTER noetig: der Rueckruf kommt per
        # QTimer NACH dem Bilder-Holen - ist der Bauplan-Dialog bis dahin
        # geschlossen, ist tbl ein totes C++-Objekt und jeder Zugriff ein
        # RuntimeError-Absturz.
        def _icons_nach(jobs=jobs, sched_chars=sched_chars,
                        recipes=recipes, tbl=tbl):
            try:
                tbl.rowCount()
            except RuntimeError:
                return
            self._fill_blueprint_tab(jobs, sched_chars, recipes, tbl)
        self._icon_prefetch_pending(_icons_nach)
        # WICHTIG: eindeutiger Schlüssel PRO Dialog-Instanz (nicht die feste
        # Zeichenkette "bp_tab"), sonst wird die Spaltenbreite nur beim
        # ALLERERSTEN je geöffneten Bauplan-Dialog an den echten Inhalt
        # angepasst - jeder danach geöffnete Bauplan (oft mit längeren
        # Blueprint-Namen) erbt fälschlich die alten, zu schmalen Breiten von
        # damals (self._sized ist sitzungsweit, nicht pro Dialog).
        # "Max Runs/Job" ist fast immer leer (nur bei begrenzten Aktivitaeten
        # gesetzt) - dann muss die Spalte auch nicht dastehen.
        tbl.setColumnHidden(3, not any(r.get("max_runs") for r in rows))
        # "Empf. Kopien" ausgeblendet (Nutzer: "voellig ueberfluessig").
        # Der Wert wird weiter berechnet - er steckt in der Wellenzahl, die
        # der Runplaner fuer die Zeitplanung braucht.
        tbl.setColumnHidden(4, True)
        # "Runs gesamt" ebenfalls (Nutzer: "die Runs interessieren mich hier
        # noch nicht, das wird erst im Runplaner wichtig"). Die Zahl steckt
        # weiterhin in der Status-Spalte - dort wird sie gegen den BPC-Vorrat
        # geprueft ("genug" / "reicht nicht").
        tbl.setColumnHidden(2, True)
        self._autosize_once(tbl, f"bp_tab_{id(tbl)}")
        # STATUS fuellt den Rest der Breite - dieselbe Ursache wie im
        # Materialien-Tab: die Status-Pille ist ein Zell-WIDGET und zaehlt
        # beim Bemessen nach Inhalt nicht mit, die Spalte blieb gequetscht
        # und schnitt den Text ab (Nutzer zog sie von Hand breit).
        from PySide6.QtWidgets import QHeaderView as _QHV2
        _bh = tbl.horizontalHeader()
        _bh.setSectionResizeMode(6, _QHV2.Stretch)
        # KEIN setMinimumSectionSize hier: das wirkt auf ALLE Abschnitte,
        # auch auf die ausgeblendeten (Breite 0) - Qt zieht die dann auf die
        # Mindestbreite hoch und sie sind wieder da. Genau so kamen im
        # Blueprints-Tab "Runs gesamt", "Max Runs/Job" und "Empf. Kopien"
        # zurueck, obwohl sie versteckt sein sollten.
        # Sicherheitshalber danach erneut verstecken:
        for _c_hide in (2, 3, 4):
            if _c_hide == 3:
                tbl.setColumnHidden(3, not any(r.get("max_runs") for r in rows))
            else:
                tbl.setColumnHidden(_c_hide, True)
        return n_missing, n_low, n_missing_by_stage, n_low_by_stage

    def _transform_schedule_result(self, res, sched_chars):
        """Wandelt das rohe schedule_build()-Ergebnis (char_id/char_name-Felder)
        ins Speicherformat für gespeicherte Pläne um (char/item/slots/char_done
        -Felder, Wellen nach Charakter-NAMEN statt -ID) - EXAKT dieselbe Logik,
        die früher nur der Hintergrund-Recompute hatte. Jetzt geteilt, damit der
        live offene Runplaner-Tab und der Hintergrund-Recompute niemals
        auseinanderlaufen können (das war der Auslöser für den gemeldeten Bug:
        Kalender zeigte andere Zuteilungen als der offene Bauplan)."""
        cap_by_char = {c["id"]: (int(c.get("mfg_slots", 1) or 1),
                                 int(c.get("reaction_slots", 1) or 1))
                      for c in sched_chars}
        pcs = res.get("per_char_stage") or {}
        id2name = {a.get("char_id"): a.get("char_name", "?")
                  for a in (res.get("assignments") or [])}
        waves_raw = res.get("waves_by_char_stage") or {}
        waves_named = {}
        for key, wv in waves_raw.items():
            cid_s, _, st_s = key.partition("|")
            try:
                nm = id2name.get(int(cid_s), cid_s)
            except Exception:
                nm = cid_s
            waves_named[f"{nm}|{st_s}"] = [int(x) for x in wv]
        asg = []
        for a in (res.get("assignments") or []):
            st = a.get("stage", "component")
            cid = a.get("char_id")
            mfg_cap, react_cap = cap_by_char.get(cid, (1, 1))
            cap = react_cap if (st.startswith("reaction") or st == "unrefined") else mfg_cap
            char_done = int(pcs.get(f"{cid}|{st}", 0) or 0)
            asg.append({
                "char": a.get("char_name", "?"),
                "item": a.get("name", "?"),
                # tid/char_id MITSPEICHERN (28.09.2026): ohne sie konnte
                # `_reserve_map_mitlaufend` keinen Haken und keinen Beleg
                # einem Item zuordnen - die Reservierung schrumpfte nie.
                "tid": a.get("tid"),
                "char_id": cid,
                "runs": int(a.get("runs", 0) or 0),
                "jobs": int(a.get("jobs", 1) or 1),
                "seconds": int(a.get("seconds", 0) or 0),
                "stage": st,
                "slots": int(cap),
                "char_done": char_done})
        stg = res.get("stage_times") or {}
        stage_times = {k: int(stg.get(k, 0) or 0)
                       for k in ("fuel", "unrefined", "reaction_1", "reaction_2",
                                 "component", "end")}
        return asg, waves_named, stage_times

    def _fill_schedule_manual(self, jobs, recipes, names, hdr, sub, tbl, plan=None):
        """„Selber aufteilen“: listet alle Runs je Item (nach Stufe gruppiert), OHNE
        Charakter-Zuteilung. Zeigt je Stufe, wie viele BP-Kopien du hast (parallel)."""
        from PySide6.QtWidgets import QTreeWidgetItem
        from collections import defaultdict as _dd
        import math as _math
        cap = {"reaction": int(((getattr(self, "_bd_bp", {}) or {}).get("reaction")
                                or {}).get("copies", 1)),
               "component": int(((getattr(self, "_bd_bp", {}) or {}).get("component")
                                 or {}).get("copies", 1)),
               "end": int(((getattr(self, "_bd_bp", {}) or {}).get("end")
                           or {}).get("copies", 1))}
        cap["reaction_1"] = cap["reaction"]; cap["reaction_2"] = cap["reaction"]
        sd = {"reaction_1": (t("\u2697 Reactions \u2013 Intermediate (ingredients)"), 0),
             "reaction_2": (t("\u2697 Reactions \u2013 Composite (needs stage 1)"), 1),
             "component": (t("Components"), 2),
             "end": (t("End product"), 3)}
        by_stage = _dd(list)
        total_runs = 0
        for j in jobs:
            if j["activity"] == industry.REACTION:
                stage = "reaction_1" if (j.get("reaction_tier") or 2) == 1 else "reaction_2"
            else:
                stage = "end" if j.get("is_end") else "component"
            by_stage[stage].append(j)
            total_runs += int(j["runs"])
        hdr.setText(t("Split yourself: {items} items \u00b7 {runs} runs in total \u2013 "
                      "spread the blueprints across your characters yourself.").format(
            items=len(jobs), runs=f"{total_runs:,}".replace(",", "'")))
        sub.setText(t("Order: reactions (Intermediate first, then Composite) \u2192 "
                      "components \u2192 end product. \u201e\u00d7BP\u201c = that many copies "
                      "you have per setup (that many jobs in parallel)."))
        me_pct = float((getattr(self, "_bd_opts", None) or {}).get("me", 0))
        tbl.blockSignals(True)
        tbl.clear()
        for stage in ("reaction_1", "reaction_2", "component", "end"):
            items = by_stage.get(stage)
            if not items:
                continue
            label, _ord = sd[stage]
            bpc = max(1, cap.get(stage, 1))
            parent = QTreeWidgetItem([f"{label}   ({len(items)} Items)", "",
                                      t("{n}\u00d7 BP").format(n=bpc), "", ""])
            parent.setForeground(0, QColor(theme.CYAN))
            f = parent.font(0); f.setBold(True); parent.setFont(0, f)
            tbl.addTopLevelItem(parent)
            for j in sorted(items, key=lambda x: -x["runs"]):
                runs = int(j["runs"])
                # „Selber aufteilen“: nur die Gesamt-Runs (RUNS-Spalte), keine
                # Kopien-Aufteilung – die verteilst du ja selbst.
                iit = QTreeWidgetItem([j["name"], f"{runs:,}".replace(",", "'"),
                                       "", "", ""])
                iit.setTextAlignment(1, Qt.AlignCenter)
                iit.setFlags(iit.flags() | Qt.ItemIsUserCheckable)
                iit.setCheckState(0, Qt.Unchecked)
                # Materialien je Item (Gesamtmenge) - AUS DEM PLAN, nicht
                # nachgerechnet (Sitzung 13, wie im Runplaner-Baum):
                # plan_mats_pro_run x Runs; Rueckfall auf die Nachrechnung nur
                # ohne build_mats (alter Schnappschuss).
                bp = recipes.product_to_bp.get(j["tid"])
                _pr = industry.plan_mats_pro_run(plan, j["tid"])
                if _pr is not None:
                    _zut = [(m, pr * runs) for m, pr in _pr]
                elif bp:
                    bp_id, activity, _oq = bp
                    mfac = (1 - me_pct / 100.0) if activity == industry.MANUFACTURING else 1.0
                    _zut = [(m, industry.material_menge(bq, runs, mfac))
                            for m, bq in recipes.bp_materials.get((bp_id, activity), [])]
                else:
                    _zut = []
                for mat_id, q in _zut:
                    mit = QTreeWidgetItem([names.get(mat_id, f"#{mat_id}"),
                                           f"{int(q):,}".replace(",", "'"),
                                           "", "", ""])
                    mit.setTextAlignment(1, Qt.AlignCenter)
                    mit.setForeground(0, QColor(theme.MUTED))
                    mit.setForeground(1, QColor(theme.MUTED))
                    iit.addChild(mit)
                parent.addChild(iit)
            parent.setExpanded(False)
        tbl.blockSignals(False)

    _CAL_COLORS = theme.CHART_PALETTE



















    def _bau_scan_build_opts(self, recipes):
        """build_opts des Bau-Scans - der Teil, der im GUI-Thread entstehen
        MUSS (liest self.settings und den Rig-Katalog). Stand frueher inline
        in compute_build(); als Methode ist er von aussen aufrufbar, und genau
        das braucht das Messskript messung_bau_vs_bauplan.py: es muss mit
        DENSELBEN Optionen rechnen wie der Scan, sonst misst es seine eigene
        Nachbildung statt des Scans (Arbeitsregel 9).
        Der ESI-abhaengige Rest steht in _bau_scan_build_opts_esi().
        Reine Zusammenstellung, keine UI-Seiteneffekte ausser
        self._last_build_structs (Anzeige, welche Strukturen gegriffen haben).
        """
        _base_me = self._bau_effective_me()
        _mfg_struct = self._struct_for_activity("manufacturing")
        _react_struct = self._struct_for_activity("reaction")
        _mfg_rig = self._struct_me_rig_pct(_mfg_struct) if _mfg_struct else 0.0
        _react_rig = self._struct_reaction_rig_pct(_react_struct) if _react_struct else 0.0
        _mfg_ec_me = self._STRUCT_ROLE_ME.get(
            (_mfg_struct or {}).get("type", ""), 0.0) if _mfg_struct else 0.0
        _eff_me = (1 - (1 - _base_me / 100.0) * (1 - _mfg_rig / 100.0) *
                  (1 - _mfg_ec_me / 100.0)) * 100.0
        _eff_me_reaction = _react_rig   # Reaktionen selbst sind nie erforschbar
                                        # (immer 0% Basis-ME) - nur der Rig zählt
        build_opts = {
            "me": _eff_me,
            "me_reaction": _eff_me_reaction,
            "job_pct": self.settings.get("bau_job_pct", 3),
            "build_reactions": True,
            "invention": True,
        }
        # KATEGORIEGENAUE RIG-ME - dieselbe Quelle wie der Bauplan-Dialog.
        # `_eff_me` oben ist der beste ME-Rig der Struktur OHNE Abgleich, ob er
        # auf das Item ueberhaupt wirkt (_struct_me_rig_pct). Das ist zweimal
        # falsch: zu optimistisch fuer Items, die der Rig nicht abdeckt, und -
        # schwerer - komplett wirkungslos bei T2. Denn build_cost() ersetzt
        # bei invented Blaupausen `opts["me"]` durch die Invention-ME und
        # kombiniert sie NUR mit `rig_me_map`; ist die leer, faellt der
        # Struktur-Rig genau bei den Items weg, die der Nutzer baut.
        # `_eff_me`/`_eff_me_reaction` bleiben als Rueckfall stehen (greifen,
        # wo kein Map-Eintrag existiert).
        # Berechnet im GUI-Thread, nicht im Worker: die Helfer lesen
        # self.settings und den Rig-Katalog.
        try:
            _mm_ids = set(recipes.product_to_bp.keys())
            _mm_ids |= set(getattr(recipes, "reaction_products", set()) or set())
            _mm_groups = industry.group_names(list(_mm_ids))
            _mm_cat = self._bau_category_me_map(
                list(_mm_ids), _mm_groups, recipes.reaction_products, None,
                use_dialog_me=False)
            _me_map, _me_map_rea, _rig_me_map, _mm_used, _ec_me_map = self._bau_me_maps(
                list(_mm_ids), _mm_groups, recipes.reaction_products, _mm_cat,
                None, use_dialog_me=False, recipes=recipes)
            if _rig_me_map or _me_map:
                build_opts["me_map"] = _me_map
                build_opts["me_map_reaction"] = _me_map_rea
                build_opts["rig_me_map"] = _rig_me_map
                build_opts["ec_me_map"] = _ec_me_map
            self._last_build_structs = _mm_used
        except Exception as _mm_err:
            # Nicht still schlucken: ohne die Maps rechnet der Scan weiter,
            # aber mit der pauschalen Rig-Annahme - das muss nachlesbar sein.
            self._last_build_structs = None
            # de_scan4: aus - Beschriftung fuer fehler.log, nicht Oberflaeche
            self._log_exception("Bau-Scan: Rig-ME-Maps", str(_mm_err))
            # de_scan4: an
        return build_opts

    def _bau_scan_build_opts_esi(self, build_opts, recipes):
        """Ergaenzt build_opts um alles, was ESI/Datenbank braucht (Adjusted
        Prices, Jobkosten-Parameter, Invention-Skill-Modifier, eigene BPCs).
        Laeuft im Worker-Thread des Scans - deshalb getrennt von
        _bau_scan_build_opts(). Aendert build_opts IN PLACE und gibt es
        zusaetzlich zurueck (fuer das Messskript, das beide Haelften
        nacheinander aufruft und so exakt die Scan-Optionen bekommt)."""
        # ZWEITE PREISQUELLE: Adjusted Prices als Rueckfall fuer Material,
        # das am Hub gerade keine Sell-Order hat. build_cost() bricht sonst
        # fuer das GANZE Item ab (ok=False -> None). Der Bauplan-Dialog
        # macht das laengst so; im Scan fehlte es.
        if getattr(self, "_adj_prices", None) is None:
            try:
                self._adj_prices = esi.adjusted_prices()
            except Exception:
                self._adj_prices = {}
        build_opts["adjusted_prices"] = dict(self._adj_prices or {})
        # MIT den Adjusted Prices schaltet _job_cost von der Pauschale auf
        # die EIV-Formel um - dann MUESSEN auch System-Index, Rollenbonus
        # und Facility-Tax mit, sonst rechnet der Scan mit Index 0 und
        # damit systematisch zu billig. Dieselbe Quelle wie der
        # Bauplan-Dialog, nicht eine zweite Rechnung daneben.
        try:
            build_opts.update(self._bau_jobcost_opts())
        except Exception as _jc_err:
            # de_scan4: aus - Beschriftung fuer fehler.log, nicht Oberflaeche
            self._log_exception("Bau-Scan: Jobkosten-Parameter", str(_jc_err))
            # de_scan4: an
        # Skill-Modifier (Encryption+Datacore-Skills) einmalig für ALLE
        # Invention-Rezepte berechnen (bester "Für Invention"-markierter
        # Charakter) - billig (keine Live-Abrufe), macht die Bau-Gewinn-
        # Schätzung über die ganze Liste hinweg realistischer, statt
        # überall nur mit der reinen SDE-Basis-Erfolgschance zu rechnen.
        try:
            inv_skills_map = (getattr(self, "_bd_invention_skills_map", None)
                              or industry.bp_invention_skills_map())
            inv_skill_mod = {}
            for _bp_id, _inv in (recipes.invention_for_bpc or {}).items():
                _mod, _ = self._bau_invention_skill_modifier_with_char(
                    _inv[0], inv_skills_map=inv_skills_map)
                if _mod != 1.0:
                    inv_skill_mod[_bp_id] = _mod
            build_opts["inv_skill_modifier"] = inv_skill_mod
        except Exception as _sk_err:
            # War ein stilles `pass`: ohne Skill-Modifier rechnet der Scan mit
            # der reinen SDE-Basis-Erfolgschance weiter - das ist vertretbar,
            # aber es muss nachlesbar sein, WARUM (Arbeitsregel 8).
            # de_scan4: aus - Beschriftung fuer fehler.log, nicht Oberflaeche
            self._log_exception("Bau-Scan: Invention-Skill-Modifier", str(_sk_err))
            # de_scan4: an
        # EIGENE BPCs: dieselbe Quelle wie der Invention-Tab des Bauplans
        # (gemeinsamer Blaupausen-Cache + industry.owned_bp_runs). Ohne das
        # rechnete der Scan für JEDES T2-Item die vollen Invention-Kosten -
        # der Hauptgrund, warum er Items pessimistischer bewertete als der
        # Bauplan-Dialog für dasselbe Item.
        try:
            build_opts.update(self._scan_owned_bpc_opts())
        except Exception as _bpc_err:
            # de_scan4: aus - Beschriftung fuer fehler.log, nicht Oberflaeche
            self._log_exception("Bau-Scan: eigene BPCs", str(_bpc_err))
            # de_scan4: an
        return build_opts

    def compute_build(self):
        from .. import industry
        if hasattr(self, "b_stack") and self.b_stack.currentIndex() != 0:
            QMessageBox.information(
                self, t("Find blueprints"),
                t("\u201eFind blueprints\u201c works with the scanner filters (preset, "
                  "category, tech level, margin \u2026) and therefore needs the scanner "
                  "page. Please switch to \u201eScanner\u201c at the top left of the Build "
                  "tab and try again there."))
            return
        snapshot = store.get_snapshot()
        if not snapshot:
            self.build_status.setText(t("Please run \u201eMarket scan\u201c in the Daytrade "
                                        "or Swing tab first."))
            return
        if not industry.sde_ready():
            self.build_status.setText(t(
                "Load the blueprints first (that also loads the "
                  "category/tech data)."))
            return
        cat_id = self.b_cat.currentData()
        _TECH_KEY_TO_SET = {"all": None, "t1": {0, 1}, "t2": {2}, "t3": {14}}
        tech_set = _TECH_KEY_TO_SET.get(self.b_tech.currentData())
        race_id = self.b_race.currentData() if hasattr(self, "b_race") else None
        race_map = industry.item_race_map() if race_id is not None else {}
        cmap = industry.item_category_map()
        if not cmap:
            self.build_status.setText(t("Category data missing \u2013 \u201eLoad recipes\u201c."))
            return
        _rec0 = industry.recipes_cached()
        buildable_ids = set(_rec0.product_to_bp.keys())
        buildable_ids |= set(getattr(_rec0, "reaction_products", set()) or set())
        # REAKTIONS-PRESET: die Ausgabe einer Reaktion ist Kategorie 4
        # (Material) und hat Metagruppe 0 - beide Filter unten wuerden sie
        # rauswerfen. Deshalb ein eigener, frueher Zweig: NUR Reaktions-
        # produkte, ohne Kategorie-/Tech-/Capital-Pruefung. Alles andere
        # (Rig-Domaenen, me_map_reaction, System-Index Reaktion) laeuft schon.
        reactions_only = bool(getattr(self, "_build_reactions_only", False))
        _reac_ids = set(getattr(_rec0, "reaction_products", set()) or set())
        # NUR RIGS (Nutzer-Wunsch 15.09.2026). Anders als bei den Reaktionen
        # KEIN eigener frueher Zweig: Rigs sind ganz normale Module und
        # sollen durch dieselben Tore wie alles andere - Tech-Stufe,
        # Kategorie, Blaupausen-Erhaeltlichkeit. Das Preset verengt nur die
        # GRUPPE. Wird nichts geladen (keine SDE), ist das Set leer und die
        # Liste bliebe leer - deshalb greift der Filter nur, wenn wirklich
        # Gruppen da sind (Schutzgitter, wie bei den Schwesterlisten).
        rigs_only = bool(getattr(self, "_build_rigs_only", False))
        _rig_gids = industry.rig_group_ids() if rigs_only else set()
        # CAPITAL-BAU-TEILE (Capital Construction Components) bleiben aus den
        # normalen Scans draussen - das sind Zulieferteile, keine Marktware.
        # Frueher versteckte ein "Capital "-NAMENS-Praefix pauschal ALLES,
        # auch Capital-MODULE und -WAFFEN (Capital Shield Extender II ...) -
        # die sind aber normale T2-Marktware und laufen jetzt regulaer mit
        # (Nutzer-Entscheidung; das "Capital-Komponenten"-Preset entfaellt
        # damit). Kriterium ist der GRUPPENNAME, mit Schutzgitter.
        _cap_part_gids = industry.capital_part_group_ids()
        _booster_gids = industry.booster_group_ids()

        # LP-STORE-BLAUPAUSEN (Nutzer-Erklaerung, deckt sich exakt mit der
        # Trefferliste): Faction-/Sonder-Items wie "Vorton Tuning System II"
        # oder die Polarized-Waffen haben KEINEN Invention-Pfad - ihre BPC
        # gibt es nur im LP-Store (Loyalty Points + ISK) oder als Drop. Dieser
        # BPC-Preis ist bei ihnen oft der groesste Kostenposten, und genau den
        # kennen wir nicht: wir rechnen ausschliesslich Material. Ergebnis
        # waren Fantasie-Margen (Vorton Tuning System II: 8759 % bei 717k
        # "Baukosten" gegen 66,5 Mio Verkaufspreis).
        # ERKENNUNG rein aus der SDE: Fertigungs-Blaupause + Tech II/III +
        # nicht in invention_for_bpc => die Kopie muss anders beschafft
        # werden. Normales T2 (Flycatcher & Co.) hat immer einen
        # Invention-Eintrag und bleibt drin.
        # Der Meta-Filter oben kann das NICHT abfangen: diese Items sind in
        # der SDE als Tech II gefuehrt, nicht als Faction.
        _lp_only = {"n": 0}
        # LP-GESPERRTE GRUPPEN (Nutzer: "Vorton Projektoren und anderes
        # Vorton Zeug ... wuerde ich hier nicht auflisten"): siehe
        # industry._lp_locked_gids_from - der Invention-Filter unten greift
        # bei denen NICHT, weil ihre T2-BPCs erfindbar SIND; verzerrt ist
        # die LP-only-T1-Grundlage.
        _lp_gids = industry.lp_locked_group_ids()

        # BPO-AM-MARKT-KRITERIUM fuer T1 (Nutzer: "die mit der aeusserst
        # hohen Marge sind meist Faction-Items - keine Blueprint-Originale,
        # BPC nur gegen Loyalty Points, da stecken die wahren Kosten. Sowas
        # bauen wir nicht ein - das ist zu viel"): ein regulaeres T1-Item
        # hat eine KAUFBARE BPO, und NPC-geseedete BPOs stehen mit
        # Sell-Orders im Hub-Scan, den wir schon haben. Kein Marktscan-
        # Eintrag fuer die Blaupause -> LP-/Event-/Loot-Quelle -> raus
        # (Stormbringer, 'Magpie'/'Yurt', Modal-, CONCORD-, Booster-BPs).
        # Datengetrieben statt gepflegter Liste. SCHUTZGITTER: tauchte im
        # Snapshot KEINE einzige Fertigungs-Blaupause auf (Scan ohne
        # Blueprint-Kategorie), deaktiviert sich das Tor selbst, statt
        # alles zu leeren.
        _bpo_ids = {int(r["type_id"]) for r in snapshot
                    if (r.get("sell_min") or 0) > 0
                    and (r.get("sell_orders") or 0) > 0}
        _bpo_gate = any(
            bp[0] in _bpo_ids
            for bp in _rec0.product_to_bp.values()
            if bp[1] == industry.MANUFACTURING)

        def _bpc_not_obtainable(tid, meta):
            bp = _rec0.product_to_bp.get(tid)
            if not bp or bp[1] != industry.MANUFACTURING:
                return False               # Reaktionen etc. haben nie Invention
            if meta in (2, 14):            # T2/T3: erfindbar = erhaeltlich
                return bp[0] not in _rec0.invention_for_bpc
            # T1/Meta-1/unbekannt: BPO muss am Hub kaufbar sein.
            return _bpo_gate and bp[0] not in _bpo_ids

        def _ok(tid):
            if tid not in buildable_ids:       # nur Items mit echter Blaupause/Reaktion
                return False
            if reactions_only:
                if tid not in _reac_ids:
                    return False
                # DROGEN RAUS (Nutzer: "Drogen und Booster haben da nix
                # verloren"): die "Pure ..."-Booster sind SDE-Reaktions-
                # produkte der Gas-Kette und kamen deshalb mit rein -
                # gemeint sind mit dem Preset die Mond-/Hybrid-Ketten.
                _info_r = cmap.get(tid)
                if _info_r and _info_r[1] in _booster_gids:
                    return False
                return True
            if tid in _reac_ids:
                # Umgekehrt gilt genauso: ohne das Reaktions-Preset haben
                # Reaktionsprodukte in der Bau-Liste nichts verloren - sie
                # kaemen sonst ueber `buildable_ids` mit rein.
                return False
            info = cmap.get(tid)
            if not info:
                return False
            c_id, _g, m_id = info
            meta = m_id or 0
            # NUR RIGS (Preset, Nutzer-Wunsch 15.09.2026). `_rig_gids` ist
            # nur gefuellt, wenn das Preset laeuft UND die SDE Gruppen
            # liefert - ohne Datenbank filtert hier also nichts, statt alles
            # wegzuwerfen.
            if rigs_only and _rig_gids and _g not in _rig_gids:
                return False
            # only ever real player-buildable tech (T1/T2/T3). Faction(4)/Officer(5)/
            # Deadspace(6)/Storyline(3) and unknown(0) are excluded → no LP fantasy.
            if meta not in self._BUILDABLE_META:
                return False
            if cat_id is not None and c_id != cat_id:
                return False
            # OHNE explizite Kategorie-Wahl ("Alle Kategorien"): nur Schiffe/
            # Module/Munition/Drohnen - das ist gemeint, wenn jemand "T1/T2-
            # Items" filtert. Sonst rutschen z.B. "Design Laboratory" (uralte
            # Starbase-Struktur, KEIN Schiffsmodul) oder "Titanium Diborite
            # Armor Plate" (ein Bauteil/Rohstoff für T2-Schiffsrümpfe, kein
            # fertiges Item) mit rein, nur weil sie zufällig auch Tech II
            # eingestuft sind. Wer die explizit sehen will, wählt die
            # Kategorie oben gezielt aus (dann greift dieser Filter nicht).
            elif cat_id is None and c_id not in self._SELLABLE_CATEGORIES:
                return False
            if tech_set is not None and meta not in tech_set:
                return False
            if _bpc_not_obtainable(tid, meta) or _g in _lp_gids:
                _lp_only["n"] += 1
                return False
            if _g in _cap_part_gids:
                return False
            if race_id is not None:
                # Items ohne Rassen-Eintrag in der SDE (Module, Munition, ...) haben
                # gar keine Rasse - die bleiben bei jeder Wahl sichtbar, sonst würde
                # der Filter fast alles außer Schiffen verschwinden lassen.
                item_race = race_map.get(tid)
                if item_race is not None and item_race != race_id:
                    return False
            return True
        snap = [s for s in snapshot if _ok(s["type_id"])]
        # Getrennt von den find_deals-Zaehlern gemerkt: diese Items werden VOR
        # der Analyse aussortiert, gehoeren also NICHT in die Invariante
        # "analysiert == Treffer + Ausschluesse", muessen aber sichtbar sein.
        self._last_build_lp_only = _lp_only["n"]
        if not snap:
            _diag_counts = {}
            for s in snapshot:
                _tid = s["type_id"]
                if _tid not in buildable_ids:
                    continue
                _info = cmap.get(_tid)
                if _info:
                    _m = _info[2] or 0
                    _diag_counts[_m] = _diag_counts.get(_m, 0) + 1
            _diag_txt = t(" (buildable items in the current scan: T1={t1} \u00b7 T2={t2} "
                          "\u00b7 T3={t3} \u00b7 unknown={t0} - before the margin/volume "
                          "filter)").format(t1=_diag_counts.get(1, 0),
                                            t2=_diag_counts.get(2, 0),
                                            t3=_diag_counts.get(14, 0),
                                            t0=_diag_counts.get(0, 0))
            self.build_status.setText(t("No buildable items (T1\u2013T3) of this "
                                        "category/tech level in the current scan.")
                                      + _diag_txt)
            self._render_build([])
            return

        days = self.b_window.currentData()
        filters = {
            "min_margin": self.b_margin.value(),
            "min_daily_vol": self.b_vol.value(),
            "min_profit_isk": 0,
            "price_min": self.b_pmin.value(),
            "price_max": self.b_pmax.value(),
            "max_items": 400,
            # Ohne das Flag wirft find_deals Reaktionsprodukte raus
            # (is_manufactured deckt nur MANUFACTURING ab) - sie landeten
            # sonst im Trichter unter "nicht baubar".
            "include_reactions": reactions_only,
        }
        # WICHTIG: _bau_effective_me() gibt trotz des (veralteten) Kommentars, der
        # hier mal stand, NUR die reine Blueprint-Basis-ME zurück - der Struktur-
        # Rig-Bonus fehlte im gesamten Scanner komplett (bestätigt über den
        # eigenen Docstring der Funktion: "ME ohne Struktur"). Das drückte die
        # geschätzten Baukosten für JEDEN gescannten Kandidaten systematisch zu
        # hoch, wenn Strukturen/Rigs konfiguriert sind - genau der Verdacht, den
        # wir heute beim Bauplan-Dialog schon zweimal bestätigt haben. Jetzt wird
        # der Rig-Bonus (item-unabhängig, wie auch sonst im Scanner üblich) für
        # Fertigung UND Reaktionen mit reingerechnet - rein lokal aus
        # self.settings["bau_structures"], kein Live-ESI-Abruf nötig, also ohne
        # Tempoeinbußen für den ganzen Scan.
        build_opts = self._bau_scan_build_opts(_rec0)

        region = store.get_scan_region()
        self._sync_fees_to_hub(region)   # broker fee for this hub's standings
        self.build_status.setText(t("Calculating build profits \u2026"))
        self.b_compute_btn.setEnabled(False)

        def job():
            from .. import industry as _ind
            recipes = _ind.recipes_cached()
            self._bau_scan_build_opts_esi(build_opts, recipes)
            _diag = {}
            deals = scanner.find_deals(snap, self.settings, days, "build", filters,
                                       recipes=recipes, build_opts=build_opts,
                                       region=region, diag=_diag,
                                       price_snapshot=snapshot)
            return deals, _diag

        def done(res):
            deals, _diag = res
            self.b_compute_btn.setEnabled(True)
            self._last_build_deals = deals
            self._last_build_opts = dict(build_opts)
            self._last_build_diag = _diag
            self._render_build(deals)

        def fail(msg):
            self.b_compute_btn.setEnabled(True)
            self.build_status.setText(t("Error: ") + msg)
        self._run(Worker(job), done, fail_cb=fail)

    def _render_build(self, deals):
        # `_txt` wird in dieser Methode benutzt - der Import fehlte, weil
        # eine Umbenennung ihn mitgenommen hat (Sitzung 16, pyflakes).
        from ..sprache import t as _txt
        names = store.cached_names([d["type_id"] for d in deals])
        hub = store.get_scan_region()
        hubname = next((lbl for _k, lbl, rid, _s in hubs.NPC_HUBS if rid == hub),
                       "Hub")
        _diag = getattr(self, "_last_build_diag", None) or {}
        _parts = [_txt("{n} buildable hits ({hub}).").format(n=len(deals), hub=hubname)]
        _nh = _diag.get("no_history", 0)
        if _nh:
            _parts.append(
                _txt("\u26a0 {n} candidates WITHOUT price history skipped").format(n=_nh)
                + (_txt(" (ESI limit reached)") if _diag.get("fetch_stopped") else "")
                + _txt(" \u2013 the history is loaded in the background, press "
                       "\u201eCalculate\u201c again in a few minutes. Tip: minimum volume 0 "
                       "shows them right away (without the sales check)."))
        _bm = _diag.get("below_margin", 0)
        _bmr = _diag.get("below_margin_refine", 0)
        _vf = _diag.get("vol_filtered", 0)
        _nm = _diag.get("not_manufactured", 0)
        _nbc = _diag.get("no_build_cost", 0)
        _err = _diag.get("errors", 0)
        _cap = _diag.get("over_cap", 0)
        _gates = [(_vf, _txt("below volume")), (_nh, _txt("without price history")),
                  (_nm, _txt("not buildable")), (_nbc, _txt("build cost not computable")),
                  (_bm, _txt("below margin (quick estimate)")),
                  (_bmr, _txt("below margin (exact calculation)")),
                  (_cap, _txt("above the display limit (not discarded)")),
                  (_err, _txt("\u26a0 analysis error"))]
        _shown = [f"{n} {lbl}" for n, lbl in _gates if n]
        if _shown:
            _parts.append(_txt("Filtered: ") + " \u00b7 ".join(_shown) + ".")
        # INVARIANTE SICHTBAR MACHEN: analysiert == Treffer + alle Ausschluesse.
        # Vorher stimmte sie nicht und niemand konnte es sehen - bei einem
        # T2-Scan des Nutzers gingen 203 von 408 Kandidaten spurlos verloren,
        # weil zwei Tore (nicht baubar, Marge in der Nachrechen-Stufe) gar
        # nicht mitzaehlten. Bleibt hier ein Rest stehen, fehlt ein Zaehler.
        _an = _diag.get("analysed", 0)
        if _an:
            _rest = _an - len(deals) - sum(n for n, _l in _gates)
            _sf = _diag.get("sampled_from", 0)
            if _sf:
                # Der Scan hat eine Stichprobe gezogen - das muss dranstehen,
                # sonst liest sich "N analysiert" wie die Grundgesamtheit.
                _parts.insert(1, _txt("{n} analysed (sample of {sf} buildable candidates "
                                      "at the hub).").format(n=_an, sf=_sf))
            else:
                _parts.insert(1, _txt("{n} analysed (all buildable candidates at the hub "
                                      "\u2013 the market scan found no more here)."
                                      ).format(n=_an))
            if _rest:
                _parts.append(_txt("\u26a0 {n} candidates not assigned \u2013 a gate is "
                                   "missing in the funnel.").format(n=_rest))
        _lp = getattr(self, "_last_build_lp_only", 0)
        if _lp:
            _parts.append(_txt(
                "{n} T2/T3 items skipped: BPC not inventable, only available via "
                "LP store/drop \u2013 the BPC price is missing from the calculation "
                "and would distort the margin.").format(n=_lp))
        _n_fb = sum(1 for d in deals
                    if (d.get("fallback_pct") or 0) >= self.BAU_FALLBACK_WARN_PCT)
        _n_bpc = sum(1 for d in deals if (d.get("inv_saved_unit") or 0) > 0)
        if _n_fb:
            _parts.append(_txt(
                "\u26a0 {n} hits marked with \u2265 {pct} % adjusted-price share "
                "(material without a sell order at the hub) \u2013 build cost "
                "uncertain there.").format(n=_n_fb, pct=f"{self.BAU_FALLBACK_WARN_PCT:.0f}"))
        if _n_bpc:
            _parts.append(_txt(
                "{n} hits calculated without invention cost: own "
                "BPCs/BPOs on hand.").format(n=_n_bpc))
        _parts.append(_txt("Double-click = price history. T1/T2/T3 only \u2013 "
                           "LP/faction excluded. Build cost is an estimate (without "
                           "your system/rigs, without LP cost)."))
        # KURZE ZEILE, VOLLE DIAGNOSE IM TOOLTIP (Nutzer: "keine unnoetigen
        # Angaben mehr"). Der Trichter (analysiert = Treffer + alle
        # Ausschluesse) bleibt vollstaendig erhalten - er ist beim Suchen
        # nach Fehlern unentbehrlich, aber er gehoert nicht als Textwand
        # ueber die Liste.
        # AUSNAHME: KEIN Treffer. Dann ist der Grund die eigentliche
        # Antwort ("keine Preishistorie", "erst Markt-Scan") - der muss
        # sichtbar sein, nicht im Tooltip versteckt (Arbeitsregel 6).
        _full_status = " ".join(_parts)
        if deals:
            _kurz = _txt("{n} hits").format(n=len(deals))
            if _n_fb:
                _kurz += f"  \u26a0 {_n_fb}"
            if _n_bpc:
                _kurz += f" {_n_bpc}"
            self.build_status.setText(_kurz + "  \u24d8")
        else:
            self.build_status.setText(_full_status)
        self.build_status.setToolTip(_full_status)
        self._wrap_tooltips(self.build_status)
        self.b_table.setSortingEnabled(False)
        self.b_table.setRowCount(len(deals))
        green = QColor(theme.GREEN); red = QColor(theme.RED)
        try:
            volmap = industry.item_volume_map([d["type_id"] for d in deals])
        except Exception:
            volmap = {}
        # AN self, nicht nur lokal: _bau_apply_bars() laeuft auch spaeter
        # wieder (nach jedem Sortieren) und braucht die Daten dann noch.
        self._bau_bar_rows = {}   # type_id -> (%, Text, Farbe, Zeilen-Tooltip)
        _bar_rows = self._bau_bar_rows
        for i, d in enumerate(deals):
            bc = d.get("build_cost") or 0
            # ZWEI ANNAHMEN, DIE MAN DER ZAHL NICHT ANSIEHT - deshalb an der
            # Zeile ausweisen statt sie zu verstecken (Arbeitsregel 6):
            # ⚠ = ein grosser Teil der Kosten haengt nur am Adjusted-Price
            #     (kein Angebot am Hub) und ist entsprechend unsicher.
            # 🛰 = Invention nicht berechnet, weil eigene BPCs/BPOs vorliegen.
            _fb = d.get("fallback_pct")
            _inv_saved = d.get("inv_saved_unit") or 0.0
            _cost_mark = ""
            _cost_tip = []
            if _fb is not None and _fb >= self.BAU_FALLBACK_WARN_PCT:
                _cost_mark += "⚠ "
                _cost_tip.append(_txt(
                    "{pct} % of the build cost comes from the adjusted-price fallback: "
                    "there is currently no sell order for this material at the hub. "
                    "The adjusted price is an ESI average, not an offer - the build "
                    "cost can be off in either direction.").format(pct=f"{_fb:.0f}"))
            if _inv_saved > 0:
                _cost_mark += " "
                _cost_tip.append(_txt(
                    "Invention is calculated as 0 because own BPCs/BPOs are on hand - "
                    "without them it would be {isk}/unit more. The saving only holds "
                    "as long as the copies last.").format(isk=isk(_inv_saved)))
            vol = float(volmap.get(d["type_id"], 0) or 0)
            pm3 = (d["profit_unit"] / vol) if vol else 0.0
            iskh = d.get("isk_per_hour", 0.0) or 0.0
            # ALLE UEBRIGEN KENNZAHLEN IN EINEN ZEILEN-TOOLTIP. Sie sind
            # nicht geloescht - sie draengen sich nur nicht mehr auf. Wer
            # sie braucht, faehrt die Zeile an (Nutzer: minimalistisch,
            # aber ohne fachliche Tiefe zu verlieren).
            _tip = [(_txt("Build cost: ") + isk(bc)) if bc else _txt("Build cost: unknown"),
                    _txt("Sell now (sell): ") + isk(d['sell_min']),
                    _txt("Profit/day: ") + isk(d['profit_day'])]
            if iskh:
                _tip.append(_txt("ISK/h: {isk} (profit/unit \u00f7 build time/unit, incl. "
                                 "self-built intermediates)").format(isk=isk(iskh)))
            if vol:
                _tip.append(_txt("Profit/m\u00b3: {isk} \u00b7 volume {vol} m\u00b3/unit").format(
                    isk=isk(pm3), vol=f"{vol:g}"))
            _tip.append(_txt("\u00d8 daily volume: ")
                        + (_txt("unknown (history still loading)")
                           if d.get("vol_unknown") else
                           f"{round(d['daily_vol']):,}".replace(",", "'") + " " + _txt("units")))
            _tip.append(_txt("Volatility: ") + f"{d.get('volatility', 0):.0f} %")
            _tip.append(_txt("Days of stock: ")
                        + ("\u221e" if d["dos"] >= 9000 else f"{d['dos']:.1f}"))
            if d.get("refined_qty"):
                _tip.append(_txt("Recalculated exactly with a realistic batch "
                                 "size of {n} units.").format(
                    n=f"{d['refined_qty']:,}".replace(",", "'")))
            _tip.extend(_cost_tip)
            _row_tip = "\n".join(_tip)
            _bpct, _btxt, _bcol = self._bau_bewertung(d, _fb)
            _bar_rows[d["type_id"]] = (_bpct, _btxt, _bcol, _row_tip)
            cells = [
                (names.get(d["type_id"], f"#{d['type_id']}"), None),
                (f"{d['under_pct']:.1f} %", d["under_pct"]),
                (isk(d["profit_unit"], suffix=False), d["profit_unit"]),
                ("", _bpct),          # Balken haengt als Zell-Widget darueber
            ]
            for j, (text, val) in enumerate(cells):
                it = NumericItem(text, val) if j >= 1 else QTableWidgetItem(text)
                if j >= 1:
                    it.setTextAlignment(Qt.AlignRight | Qt.AlignVCenter)
                if j in (1, 2):
                    # ZAHLEN ENTFLIMMERN (Nutzer-Liste "weniger Excel",
                    # Punkt 2): vorher war ALLES gruen oder rot - wenn jede
                    # Zeile leuchtet, bedeutet die Farbe nichts mehr. Jetzt:
                    # Verlust rot (Warnung bleibt Warnung), klar gute Marge
                    # (>= BAU_MARGE_GUT, dieselbe Schwelle wie im
                    # Bewertungs-Balken - KEINE zweite Regel) gruen, alles
                    # dazwischen gedaempft. Die wenigen Akzente bedeuten
                    # wieder etwas; die exakten Zahlen stehen unveraendert da.
                    if d["profit_unit"] <= 0:
                        it.setForeground(red)
                    elif d["under_pct"] >= self.BAU_MARGE_GUT:
                        it.setForeground(green)
                    else:
                        it.setForeground(QBrush(QColor(theme.MUTED)))
                if j == 0:
                    # Kraeftiger Item-Name (Punkt 1): der Anker der Zeile.
                    _f = it.font()
                    _f.setBold(True)
                    it.setFont(_f)
                if j == 0 and _cost_mark:
                    # Die Vorbehalte bleiben SICHTBAR (Arbeitsregel 6) - sie
                    # wandern nur ans Item, weil die Baukosten-Spalte weg ist.
                    it.setText(_cost_mark + it.text())
                if j == 0 and d.get("refined_qty"):
                    it.setText(" " + it.text())
                if j == 0:
                    icon = self._table_icon(d["type_id"])
                    if icon:
                        it.setIcon(icon)
                it.setToolTip(_row_tip)
                self.b_table.setItem(i, j, it)
            self.b_table.item(i, 0).setData(Qt.UserRole, d["type_id"])
            # STUECKZAHL DES SCANNERS (Bedienidee 2, Nutzer 26.09.2026): mit
            # dieser Losgroesse hat er Kosten und Marge gerechnet - der
            # Mengen-Dialog von "Add to multi build plan" startet damit.
            # Ohne Nachrechnung (kein refined_qty) gibt es keine, dann 1.
            self.b_table.item(i, 0).setData(Qt.UserRole + 5,
                                            int(d.get("refined_qty") or 0) or None)
        self.b_table.setSortingEnabled(True)
        # Standard: bester Gewinn pro Stueck oben - eine der beiden Zahlen,
        # nach denen der Nutzer entscheidet (die andere, die Marge, ist einen
        # Klick auf die Spaltenueberschrift entfernt).
        self.b_table.sortByColumn(2, Qt.DescendingOrder)
        self._bau_apply_bars()
        # Qt sortiert die ITEMS um, laesst Zell-Widgets aber am alten
        # Zeilenindex stehen - danach stuende der Balken einer FREMDEN Zeile
        # daneben. Dieselbe Falle wie im Materialien-Tab, gleiche Loesung.
        _hdr_b = self.b_table.horizontalHeader()
        # NUR die EIGENE alte Verbindung loesen: disconnect() OHNE Argument
        # trennt auch Qts INTERNE Sortier-Verbindung - danach aendert der
        # Header-Klick nur noch den Pfeil, sortiert aber nichts mehr
        # (Nutzer-Fund im Capital-Modus; hier lag dieselbe Mine, nur von
        # der Start-Sortierung verdeckt).
        _alt_b = getattr(self, "_bau_bars_sort_slot", None)
        if _alt_b is not None:
            try:
                _hdr_b.sortIndicatorChanged.disconnect(_alt_b)
            except (TypeError, RuntimeError):
                pass
        self._bau_bars_sort_slot = (lambda *_a: self._bau_apply_bars())
        _hdr_b.sortIndicatorChanged.connect(self._bau_bars_sort_slot)
        self._autosize_once(self.b_table, "build")
        # ICON-NACHTRAG (Auftrag C): die Deals sind in _last_build_deals
        # gemerkt - der Nachtrag rendert daraus neu, ohne neuen Scan.
        self._icon_prefetch_pending(
            lambda: self._render_build(
                getattr(self, "_last_build_deals", None) or []))

    def _bau_apply_bars(self):
        """Bewertungs-Balken der Bau-Trefferliste (Kern: _haenge_balken)."""
        self._haenge_balken(self.b_table,
                            getattr(self, "_bau_bar_rows", None) or {}, 3)

    def _cap_apply_bars(self):
        """Bewertungs-Balken der Capital-Liste - GLEICHER Kern, gleiche
        Sortier-Falle: nach jedem Sortieren neu, Zuordnung per type_id."""
        self._haenge_balken(self.b_cap_table,
                            getattr(self, "_cap_bar_rows", None) or {}, 3)

    def _haenge_balken(self, table, rows, col):
        """Bewertungs-Balken an Tabellenzeilen haengen.

        MUSS nach jedem Sortieren erneut laufen, und die Zuordnung laeuft
        ueber die type_id aus Spalte 0 - NIE ueber den Schleifenindex (s.
        Materialien-Tab: dort sah der Nutzer den Balken einer fremden Zeile).
        """
        from PySide6.QtWidgets import QProgressBar as _QPB
        _rows = rows
        for _r in range(table.rowCount()):
            _c0 = table.item(_r, 0)
            if _c0 is None:
                continue
            _d = _rows.get(_c0.data(Qt.UserRole))
            if not _d:
                continue
            _pct, _txt, _col, _tip = _d
            _bar = _QPB()
            _bar.setRange(0, 100); _bar.setValue(_pct)
            _bar.setTextVisible(True); _bar.setFormat(_txt)
            _bar.setFixedHeight(20)
            _bar.setToolTip(_tip)
            self._wrap_tooltips(_bar)
            _bar.setStyleSheet(
                f"QProgressBar{{background:rgba(255,255,255,0.05); "
                f"border:none; border-radius:5px; color:{_col}; "
                f"font-size:11px; text-align:center;}}"
                f"QProgressBar::chunk{{background:rgba(255,255,255,0.10); "
                f"border-radius:5px;}}")
            table.setCellWidget(_r, col, _bar)

    def _compute_capital_costs(self):
        from ..sprache import t as _txt   # `t` ist hier lokal belegt
        """Baukosten-Schätzung für Capital-Schiffe (Carrier/Dread/FAX/Titan/
        Supercarrier/Freighter) - läuft NICHT über find_deals()/die snapshot-
        Preisprüfung (die verlangt einen echten Verkaufspreis, den Capitals in
        Jita fast nie haben), sondern direkt über industry.build_cost() - die
        reine Rekursion über den SDE-Materialbedarf, die für sowas gebaut ist.
        Verkaufspreis + Marge/Gewinn kommen, wenn vorhanden, aus dem lokal
        gecachten Contract-Preis-Scan (siehe _load_capital_contract_prices) -
        sonst bleiben die Spalten "–" statt eine Zahl zu erfinden."""
        from .. import industry as _ind
        snapshot = store.get_snapshot()
        if not snapshot:
            self.b_cap_status.setText(_txt(
                "Please run „Market scan“ in the Daytrade or Swing tab "
                  "first (for material prices)."))
            return
        if not _ind.sde_ready():
            self.b_cap_status.setText(t("Run \u201eLoad recipes\u201c first."))
            return
        self.b_cap_btn.setEnabled(False)
        self.b_cap_status.setText(t("Searching capital ships + calculating build cost \u2026"))
        region = store.get_scan_region()
        tax = float(self.settings.get("sales_tax_pct", 0) or 0) / 100.0
        broker = float(self.settings.get("broker_fee_pct", 0) or 0) / 100.0

        def job():
            recipes = _ind.recipes_cached()
            cap_products = _ind.capital_ship_products(recipes)
            catmap = _ind.item_category_map()
            price_map = {s["type_id"]: s["sell_min"] for s in snapshot if s["sell_min"] > 0}
            try:
                adj = esi.adjusted_prices() or {}
            except Exception:
                adj = {}
            # Derselbe Rig-Bonus-Fix wie im normalen Scanner - _bau_effective_me()
            # gibt nur die Basis-ME zurück, der Struktur-Rig fehlte auch hier.
            _base_me = self._bau_effective_me()
            _mfg_struct = self._struct_for_activity("manufacturing")
            _react_struct = self._struct_for_activity("reaction")
            _mfg_rig = self._struct_me_rig_pct(_mfg_struct) if _mfg_struct else 0.0
            _react_rig = (self._struct_reaction_rig_pct(_react_struct)
                         if _react_struct else 0.0)
            _mfg_ec_me = self._STRUCT_ROLE_ME.get(
                (_mfg_struct or {}).get("type", ""), 0.0) if _mfg_struct else 0.0
            _eff_me = (1 - (1 - _base_me / 100.0) * (1 - _mfg_rig / 100.0) *
                      (1 - _mfg_ec_me / 100.0)) * 100.0
            build_opts = {
                "me": _eff_me,
                "me_reaction": _react_rig,
                "job_pct": self.settings.get("bau_job_pct", 3),
                "build_reactions": True,
                "invention": True,
                "adjusted_prices": adj,
            }
            memo = {}
            time_memo = {}
            # CONTRACT-PREISE AUS GANZ NEW EDEN bevorzugen (Nutzer-Wunsch):
            # Capitals werden ueberall verkauft, ein Ein-Regionen-Stand
            # liefert fuer viele Typen gar keinen oder nur einen Preis. Der
            # alte regionale Stand bleibt als Rueckfall liegen und wird nur
            # fuer Typen genutzt, die der New-Eden-Scan nicht kennt - so
            # verliert niemand seine bisherigen Daten.
            contract_prices = dict(store.get_contract_prices(region) or {})
            contract_prices.update(
                store.get_contract_prices(store.ALL_REGIONS) or {})
            try:
                volmap = _ind.item_volume_map([p for p, _b, _g in cap_products])
            except Exception:
                volmap = {}
            rows = []
            for product_id, bp_id, gname in cap_products:
                cost = _ind.build_cost(product_id, price_map.get, recipes,
                                       build_opts, memo=memo)
                meta = (catmap.get(product_id) or (None, None, None))[2]
                tech = "T3" if meta == 14 else ("T2" if meta == 2 else "T1")
                cp = contract_prices.get(product_id)
                margin = profit = profit_m3 = isk_h = None
                if cp and cost:
                    sell = cp["median"]
                    net_sell = sell * (1 - tax - broker)
                    profit = net_sell - cost
                    margin = (profit / cost * 100.0) if cost else None
                    vol = float(volmap.get(product_id, 0) or 0)
                    profit_m3 = (profit / vol) if vol else None
                    try:
                        secs = _ind.build_time_per_unit(
                            product_id, price_map.get, recipes, build_opts,
                            time_memo, memo)
                        if secs:
                            isk_h = profit / (secs / 3600.0)
                    except Exception:
                        pass
                rows.append((product_id, gname, tech, cost, cp, margin, profit,
                            profit_m3, isk_h))
            rows.sort(key=lambda r: (r[1], -(r[3] or 0)))   # Gruppe, dann teuerste zuerst
            return rows

        def done(rows):
            self.b_cap_btn.setEnabled(True)
            names = store.cached_names([r[0] for r in rows])
            _tbl = self.b_cap_table
            _tbl.setSortingEnabled(False)
            _tbl.setRowCount(len(rows))
            _tbl.verticalHeader().setDefaultSectionSize(30)
            n_priced = sum(1 for r in rows if r[3])
            n_with_contract = sum(1 for r in rows if r[4])
            green = QColor(theme.GREEN); red = QColor(theme.RED)
            # VIER SPALTEN STATT ELF (Nutzer-Liste "weniger Excel", Punkt 3):
            # Schiff, Baukosten, Contract-Referenz, Bewertungs-Balken - alles
            # Uebrige (Gruppe/Tech, Marge, Gewinn/Stk, Gewinn/m3, ISK/Std,
            # aktive Contracts, Preisspanne) steht im Zeilen-Tooltip. Nichts
            # ist weg, nur weggeraeumt (Regel 6). Die Aussage kommt aus
            # DERSELBEN _bau_bewertung wie in der Hauptliste (Regel 9),
            # ergaenzt um den "kein Contract-Preis"-Zweig.
            self._cap_bar_rows = {}
            for i, (product_id, gname, tech, cost, cp, margin, profit, profit_m3,
                   isk_h) in enumerate(rows):
                cost_txt = isk(cost, suffix=False) if cost else t("\u2014 (material without price)")
                if cp:
                    sell_txt = isk(cp["median"], suffix=False)
                    range_txt = f"{isk(cp['min'], suffix=False)} – {isk(cp['max'], suffix=False)}"
                    count_val = cp["count"]
                else:
                    sell_txt = _txt("\u2013 (load contract prices)")
                    range_txt = "\u2013"
                    count_val = 0
                _tip = [f"{gname} \u00b7 Tech {tech}", ""]
                _tip.append(_txt("Build margin: ")
                            + (f"{margin:.1f} %" if margin is not None else "\u2013"))
                _tip.append(_txt("Profit/unit: ")
                            + (isk(profit) if profit is not None else "\u2013"))
                _tip.append(_txt("Profit/m\u00b3: ")
                            + (isk(profit_m3) if profit_m3 is not None else "\u2013"))
                _tip.append(_txt("ISK/h: ")
                            + (isk(isk_h) if isk_h is not None else "\u2013"))
                _tip.append(_txt("Active contracts: ") + f"{count_val if cp else '\u2013'}"
                            + (_txt(" ({n} of them derived from bundles: ship+accessory "
                                    "contracts, extras deducted at Jita price)").format(
                                   n=cp['from_bundles'])
                               if cp and cp.get("from_bundles") else ""))
                _tip.append(_txt("Price range: ") + range_txt)
                if cp:
                    _tip.append(_txt("(Reference = MEDIAN of the contracts; the mean would "
                                     "be distorted by outliers.)"))
                _row_tip = "\n".join(_tip)
                _d_cap = {"under_pct": margin or 0.0, "daily_vol": 0,
                          "vol_unknown": False, "no_price": cp is None}
                # NICHT `_txt` nennen: in dieser Funktion ist _txt der
                # Uebersetzer, und aa237 hat den Konflikt gemeldet - der
                # Aufruf am Ende haette sonst einen STRING aufgerufen.
                _pct, _bew_txt, _col = self._bau_bewertung(_d_cap)
                self._cap_bar_rows[product_id] = (_pct, _bew_txt, _col, _row_tip)
                cells = [
                    (names.get(product_id, f"#{product_id}"), None),
                    (cost_txt, cost or -1),
                    (sell_txt, cp["median"] if cp else -1),
                    ("", _pct),       # Balken haengt als Zell-Widget darueber
                ]
                for j, (text, val) in enumerate(cells):
                    it = NumericItem(text, val) if j >= 1 else QTableWidgetItem(text)
                    if j in (1, 2):
                        it.setTextAlignment(Qt.AlignRight | Qt.AlignVCenter)
                        # Entflimmert wie die Hauptliste (Punkt 2): nur
                        # Verlust rot und klar gute Marge gruen, Rest ruhig.
                        if margin is not None and profit is not None:
                            if profit <= 0:
                                it.setForeground(red)
                            elif margin >= self.BAU_MARGE_GUT:
                                it.setForeground(green)
                            else:
                                it.setForeground(QBrush(QColor(theme.MUTED)))
                    if j == 0:
                        _f = it.font(); _f.setBold(True); it.setFont(_f)
                        it.setData(Qt.UserRole, product_id)
                        icon = self._table_icon(product_id)
                        if icon:
                            it.setIcon(icon)
                    it.setToolTip(_row_tip)
                    _tbl.setItem(i, j, it)
            _tbl.setSortingEnabled(True)
            self._cap_apply_bars()
            # Gleiche Sortier-Falle wie in der Hauptliste: Qt laesst
            # Zell-Widgets beim Sortieren am alten Index stehen.
            _hdr_cap = _tbl.horizontalHeader()
            # disconnect() ohne Argument war hier die Ursache fuer "keine
            # Spalte sortiert" - es trennte auch Qts interne Verbindung.
            _alt_cap = getattr(self, "_cap_bars_sort_slot", None)
            if _alt_cap is not None:
                try:
                    _hdr_cap.sortIndicatorChanged.disconnect(_alt_cap)
                except (TypeError, RuntimeError):
                    pass
            self._cap_bars_sort_slot = (lambda *_a: self._cap_apply_bars())
            _hdr_cap.sortIndicatorChanged.connect(self._cap_bars_sort_slot)
            self._autosize_once(_tbl, "cap")
            if hasattr(self, "b_cap_search"):
                cur_txt = self.b_cap_search.currentText()
                self.b_cap_search.blockSignals(True)
                self.b_cap_search.clear()
                for nm3 in sorted({names.get(r[0], f"#{r[0]}") for r in rows}):
                    self.b_cap_search.addItem(nm3)
                self.b_cap_search.setEditText(cur_txt)
                self.b_cap_search.blockSignals(False)
                self._apply_cap_filter()
            self.b_cap_status.setText(_txt(
                "{n} capital ships found \u00b7 {priced} with build-cost estimate \u00b7 "
                "{contract} with contract sale price (margin/profit calculated for "
                "those only). \u00d8 daily volume/volatility do not exist for contracts "
                "- no price history in ESI for them.").format(
                n=len(rows), priced=n_priced, contract=n_with_contract))

        def fail(msg):
            self.b_cap_btn.setEnabled(True)
            self.b_cap_status.setText(t("Error: ") + msg)
        self._run(Worker(job), done, fail_cb=fail)

    # AB WANN GILT DER CONTRACT-STAND ALS ALT?
    # NUTZER, 15.09.2026: "sonst vergleicht man hier alte Preise von gestern
    # oder so". Contracts laufen tagelang, ein Stand von heute Morgen ist
    # also brauchbar - einer von gestern nicht mehr verlaesslich. 24 Stunden
    # ist die Grenze, ab der der Knopf blinkt. Bewusst LANG im Vergleich zum
    # Markt-Scan (15 Minuten): ein Contract-Scan kostet Minuten, ein
    # staendig blinkender Knopf waere hier eine Zumutung.
    _CONTRACT_ALT_SEKUNDEN = 24 * 3600

    def _capital_contract_alter_pruefen(self):
        """Contract-Knopf blinken lassen, wenn der Stand fehlt oder alt ist.

        Dieselbe Blink-Regel wie der Markt-Scan-Knopf (`_blink_rahmen`) -
        EINE Stelle fuer das Aussehen. Der Status daneben sagt, WARUM.
        """
        btn = getattr(self, "b_cap_contract_btn", None)
        if btn is None:
            return
        try:
            from PySide6.QtCore import QTimer as _QTimer
            _alter = store.contract_prices_age_seconds(store.ALL_REGIONS)
            _alt = _alter is None or _alter > self._CONTRACT_ALT_SEKUNDEN
            if not hasattr(btn, "_ct_css"):
                # 2 PX SCHON IM RUHEZUSTAND, sonst waechst der Knopf im Takt
                # und schiebt die Kopfzeile (Nutzer-Befund Sitzung 20 am
                # Markt-Scan-Knopf).
                btn._ct_css = "QPushButton{border:2px solid transparent;}"
                btn.setStyleSheet(btn._ct_css)
            tmr = getattr(btn, "_ct_blink_timer", None)
            if not _alt:
                if tmr is not None and tmr.isActive():
                    tmr.stop()
                btn.setStyleSheet(btn._ct_css)
                return
            if tmr is None:
                tmr = _QTimer(btn)
                tmr.setInterval(700)

                def _schritt(_b=btn):
                    try:
                        _b._ct_blink_an = not getattr(_b, "_ct_blink_an", False)
                        self._blink_rahmen(_b, _b._ct_blink_an,
                                           getattr(_b, "_ct_css", ""))
                    except Exception:
                        pass
                tmr.timeout.connect(_schritt)
                btn._ct_blink_timer = tmr
            if not tmr.isActive():
                tmr.start()
        except Exception:
            pass          # ein Hinweis darf die Seite nie kosten

    def _load_capital_contract_prices(self):
        """Scannt öffentliche Contracts in GANZ NEW EDEN nach Capital-Verkäufen
        (siehe scanner.scan_capital_contract_prices_all_regions) und speichert
        das Ergebnis lokal unter store.ALL_REGIONS - danach automatisch
        _compute_capital_costs() neu, damit Marge/Gewinn/ISK-Std mit den
        frischen Preisen nachgezogen werden."""
        from .. import industry as _ind
        if not _ind.sde_ready():
            self.b_cap_status.setText(t("Run \u201eLoad recipes\u201c first."))
            return
        # VORHER FRAGEN (Nutzer, 15.09.2026: "ist das normal dass das fast 5
        # Minuten dauert? ... sollte ein Popup kommen mit einer Warnung").
        # JA, ES IST NORMAL: der Scan holt die Contract-Listen ALLER Regionen
        # und danach zu JEDEM Treffer dessen Inhalt einzeln - das sind
        # tausende Einzelabrufe, und die laufen der Reihe nach, damit ESI
        # nicht ins Error-Limit laeuft. Wer das nicht weiss, haelt das
        # Programm fuer haengen geblieben.
        from PySide6.QtWidgets import QMessageBox as _QMB
        if _QMB.question(
                self, t("Load contract prices"),
                t("This searches the public contracts of ALL regions and then "
                  "looks into every hit individually \u2013 that takes SEVERAL "
                  "MINUTES (around five is normal).\n\nIt runs in the "
                  "background, you can keep working. Start now?"),
                _QMB.Ok | _QMB.Cancel, _QMB.Ok) != _QMB.Ok:
            return
        region = store.get_scan_region()
        self.b_cap_contract_btn.setEnabled(False)
        self.b_cap_status.setText(
            # KEIN "laeuft im Hintergrund" mehr (Nutzer 27.09.2026: "stimmt
            # nicht, es laedt einfach ein paar Minuten, und zwar im
            # Vordergrund") - der Abruf laeuft mit dem grossen Overlay.
            t("Searching public contracts across New Eden \u2026 (takes a few "
              "minutes)"))

        def job(progress=None, should_cancel=None):
            recipes = _ind.recipes_cached()
            cap_ids = {p for p, _b, _g in _ind.capital_ship_products(recipes)}
            # GANZ NEW EDEN (Nutzer-Wunsch), Ergebnis unter der Pseudo-Region
            # store.ALL_REGIONS - der alte regionale Stand bleibt daneben
            # liegen und dient weiter als Rueckfall.
            # Beilagen-Preise fuer die Bundle-Ableitung: Jita-Sell aus dem
            # Markt-Schnappschuss. Ohne Scan bleibt die Quelle leer -> nur
            # Einzel-Contracts (altes, ehrliches Verhalten).
            _sellmap = {int(r["type_id"]): float(r.get("sell_min") or 0)
                        for r in (store.get_snapshot() or [])}
            result = scanner.scan_capital_contract_prices_all_regions(
                cap_ids, should_cancel=should_cancel, progress=progress,
                extra_price_fn=_sellmap.get if _sellmap else None)
            rows = [{"type_id": tid, **info} for tid, info in result.items()]
            store.save_contract_prices(rows, store.ALL_REGIONS)
            return len(rows)

        def done(n_found):
            self.b_cap_contract_btn.setEnabled(True)
            # Stand ist jetzt frisch - das Blinken gehoert sofort aus, nicht
            # erst beim naechsten Oeffnen des Capital-Modus.
            self._capital_contract_alter_pruefen()
            self.b_cap_status.setText(t(
                "Contract scan finished (all of New Eden): {n} capital type(s) with "
                "public offers found. Public contracts only - ESI does not see "
                "alliance-internal ones without Director/Accountant access to the "
                "respective corp.").format(n=n_found))
            self._compute_capital_costs()

        def fail(msg):
            self.b_cap_contract_btn.setEnabled(True)
            self.b_cap_status.setText(t("Contract scan error: ") + msg)
        self._run(Worker(job, with_progress=True, with_cancel=True), done,
                  fail_cb=fail, label=t("Searching contracts …"))

    def _apply_cap_filter(self):
        """Live-Filter für die Capital-Schiffe-Tabelle nach dem Suchtext."""
        t = getattr(self, "b_cap_table", None)
        if t is None or not hasattr(self, "b_cap_search"):
            return
        txt = self.b_cap_search.currentText().strip().lower()
        for r in range(t.rowCount()):
            cell = t.item(r, 0)
            visible = (not txt) or (cell is not None and txt in cell.text().lower())
            t.setRowHidden(r, not visible)

    @staticmethod
    def _build_row_tid_name(tbl, row):
        """(type_id, bereinigter Name) der Trefferzeile - EINE Stelle fuer
        "Bauplan oeffnen" und "zu Plan hinzufuegen"; (None, "") ohne ID."""
        cell = tbl.item(row, 0)
        if not cell:
            return None, ""
        tid = cell.data(Qt.UserRole)
        if tid is None:
            return None, ""
        # Marken (🎯/⚠/🛰) aus dem Anzeigenamen entfernen - der Name geht in
        # den Dialogtitel und in den gespeicherten Plan.
        return int(tid), cell.text().lstrip("⚠ ").strip()

    @classmethod
    def _build_row_auswahl(cls, tbl, row):
        """Eine Scanner-Zeile fuer die Mehrfachauswahl/den Mengen-Dialog:
        {tid, name, vorgabe} - vorgabe = Stueckzahl des Scanners oder 1."""
        tid, name = cls._build_row_tid_name(tbl, row)
        if tid is None:
            return None
        cell = tbl.item(row, 0)
        _q = cell.data(Qt.UserRole + 5) if cell is not None else None
        return {"tid": int(tid), "name": name, "vorgabe": int(_q or 1)}

    def _build_row_open_plan(self, tbl, row):
        """Bauplan fuer die Trefferzeile DIREKT oeffnen (normale wie
        Capital-Tabelle - EINE Funktion, Arbeitsregel 9). Ersetzt die alten
        Picker-Fuetterer, die nur das entfernte Tippfeld befuellten."""
        tid, name = self._build_row_tid_name(tbl, row)
        if tid is None:
            return
        self.open_build_detail(tid, name, fresh=True)


    def _on_cap_header_toggled(self, checked):
        """Lazy-Load: Capital-Baukosten erst berechnen, wenn die Sektion
        tatsächlich aufgeklappt wird (manuell oder über den Capital-Modus-
        Knopf) - NICHT bei jeder normalen "Blaupausen suchen"-Suche."""
        if checked and hasattr(self, "b_cap_table") and self.b_cap_table.rowCount() == 0:
            self._compute_capital_costs()

    def _toggle_capital_mode(self, checked):
        """Capital-Modus: blendet die normale Ergebnisliste + Feinfilter aus,
        Capital-Schiffe füllen dafür das ganze Fenster - Capitals brauchen
        andere Filter (kein Marktpreis, keine Marge/Volumen-Zahlen) als der
        Rest, ein Nebeneinander war unübersichtlich."""
        if hasattr(self, "b_table"):
            self.b_table.setVisible(not checked)
        if hasattr(self, "b_filter_card"):
            self.b_filter_card.setVisible(not checked)
        if hasattr(self, "build_status"):
            self.build_status.setVisible(not checked)
        if hasattr(self, "b_cap_wrap"):
            # Die ganze Capital-Karte existiert NUR im Capital-Modus
            # (Nutzer-Wunsch). Der Klapp-Kopf ist im Vollbild ueberfluessig,
            # der Inhalt immer offen.
            self.b_cap_wrap.setVisible(checked)
        if hasattr(self, "b_cap_header"):
            self.b_cap_header.setVisible(False)
        if hasattr(self, "b_cap_inner"):
            self.b_cap_inner.setVisible(checked)
        if hasattr(self, "b_cap_table"):
            if checked:
                self.b_cap_table.setMaximumHeight(16_777_215)   # Qt "kein Limit"
                self.b_cap_table.setMinimumHeight(500)
            else:
                self.b_cap_table.setMaximumHeight(560)
                self.b_cap_table.setMinimumHeight(320)
        if checked and hasattr(self, "b_cap_table") and self.b_cap_table.rowCount() == 0:
            self._compute_capital_costs()
        # BEIM OEFFNEN DES CAPITAL-MODUS PRUEFEN (Nutzer, 15.09.2026): ist
        # der Contract-Stand alt oder gar nicht da, blinkt der Knopf. Ohne
        # das vergleicht man stillschweigend Preise von gestern.
        if checked:
            self._capital_contract_alter_pruefen()

    def _build_menu_cap(self, pos):
        """Rechtsklick im Capital-Bereich: wie _build_menu für die normale
        Tabelle, aber ohne "Kursverlauf öffnen" (Capitals haben keine Markt-
        Preishistorie, ein Kursverlauf wäre leer/irreführend)."""
        item = self.b_cap_table.itemAt(pos)
        if not item:
            return
        row = item.row()
        cell = self.b_cap_table.item(row, 0)
        if not cell:
            return
        menu = kontext_menue(self.b_cap_table)
        a_plan = menu.addAction(icons.icon("hammer"), t("Open build plan"))
        _tid_c, _nm_c = self._build_row_tid_name(self.b_cap_table, row)
        # MEHRFACHAUSWAHL (Bedienidee 1): mehrere markierte Zeilen -> alle
        # auf einmal in einen Plan / ein neues Buendel.
        _ausw = self._multi_auswahl(self.b_cap_table, row, self._build_row_auswahl)
        a_neu = None
        if _ausw:
            _multi_akt, a_neu = self._multi_auswahl_menue(menu, _ausw)
        else:
            _multi_akt = (self._multi_untermenue(menu, _tid_c, _nm_c)
                          if _tid_c is not None else {})
        self._build_menu_letztes = menu          # b-Suite
        chosen = menu.exec(self.b_cap_table.viewport().mapToGlobal(pos))
        if chosen is a_plan:
            self._build_row_open_plan(self.b_cap_table, row)
        elif a_neu is not None and chosen is a_neu:
            self._multi_neu_aus_auswahl(_ausw)
        elif chosen is not None and chosen in _multi_akt:
            if _ausw:
                self._multi_enden_zu_plan(
                    _multi_akt[chosen],
                    [dict(x, qty=None) for x in _ausw])
            else:
                _v = self._build_row_auswahl(self.b_cap_table, row) or {}
                self._multi_ende_zu_plan(_multi_akt[chosen], _tid_c, _nm_c,
                                         vorgabe=int(_v.get("vorgabe") or 1))

    def _build_menu(self, pos):
        """Rechtsklick im 'Blaupausen suchen'-Scanner: Kursverlauf des ITEMS
        (nicht der Blaupause) öffnen - nutzt dieselbe type_id wie der
        Doppelklick (_build_to_chart), die schon korrekt das Produkt aus dem
        Markt-Snapshot ist, nie die Blueprint-ID."""
        item = self.b_table.itemAt(pos)
        if not item:
            return
        row = item.row()
        cell = self.b_table.item(row, 0)
        if not cell:
            return
        menu = kontext_menue(self.b_table)
        a_chart = menu.addAction(icons.icon("trend_up"), t("Open price history"))
        # "Bauplan AUSWAEHLEN" schrieb das Item frueher nur ins (inzwischen
        # entfernte) Blaupausen-Feld oben - der Bauplan ging erst nach einem
        # zweiten Klick auf. Jetzt oeffnet der Menuepunkt DIREKT (fresh=True,
        # wie jeder neue Bauplan): ein Klick weniger, kein totes Feld.
        a_plan = menu.addAction(icons.icon("hammer"), t("Open build plan"))
        # ZU EINEM BESTEHENDEN PLAN (26.09.2026, Nutzer: "per Rechtsklick in
        # Multiplans umwandeln und immer weitere hinzufuegen").
        _tid_s, _nm_s = self._build_row_tid_name(self.b_table, row)
        # MEHRFACHAUSWAHL (Bedienidee 1, Nutzer 26.09.2026).
        _ausw = self._multi_auswahl(self.b_table, row, self._build_row_auswahl)
        a_neu = None
        if _ausw:
            _multi_akt, a_neu = self._multi_auswahl_menue(menu, _ausw)
        else:
            _multi_akt = (self._multi_untermenue(menu, _tid_s, _nm_s)
                          if _tid_s is not None else {})
        self._build_menu_letztes = menu          # b-Suite
        chosen = menu.exec(self.b_table.viewport().mapToGlobal(pos))
        if chosen is a_chart:
            self._build_to_chart(row, 0)
        elif chosen is a_plan:
            self._build_row_open_plan(self.b_table, row)
        elif a_neu is not None and chosen is a_neu:
            self._multi_neu_aus_auswahl(_ausw)
        elif chosen is not None and chosen in _multi_akt:
            if _ausw:
                self._multi_enden_zu_plan(
                    _multi_akt[chosen],
                    [dict(x, qty=None) for x in _ausw])
            else:
                # MENGE VORBEFUELLT mit der Stueckzahl des Scanners (Idee 2).
                _v = self._build_row_auswahl(self.b_table, row) or {}
                self._multi_ende_zu_plan(_multi_akt[chosen], _tid_s, _nm_s,
                                         vorgabe=int(_v.get("vorgabe") or 1))

    def _build_to_chart(self, row, _col):
        cell = self.b_table.item(row, 0)
        if not cell:
            return
        tid = cell.data(Qt.UserRole)
        if tid is None:
            return
        self._build_to_chart_tid(tid, cell.text())

    def _build_to_chart_tid(self, tid, name=None):
        """Kursverlauf zu einer type_id oeffnen.

        ALTLAST BEHOBEN: `_build_to_chart` las IMMER `self.b_table`, egal aus
        welcher Tabelle der Doppelklick kam - im Materialien-Tab oeffnete er
        dadurch die Zeile mit derselben NUMMER aus einer anderen Tabelle.
        Jetzt geht die type_id direkt mit.
        """
        if tid is None:
            return
        if not name:
            name = str(tid)
        self.tabs.setCurrentWidget(self.market_tab)
        idx = self.mk_item.findData(tid)
        if idx >= 0:
            self.mk_item.setCurrentIndex(idx)
        else:
            self.mk_item.setEditText(name)
        self._do_plot(tid)

    @staticmethod
    def _aggregate_invention_needs(needs):
        """Gesamtbedarf über ALLE Invention-Items eines Bauplans (Nutzer-
        Wunsch: „die Gesamten will ich auch sehen"). needs =
        _bd_invention_needs ({bp_id: {datacores:[(id, GESAMT-qty)],
        decryptor_id, decryptor_qty, attempts}}). Rückgabe:
        (dc_totals {id: qty}, dcy_totals {id: qty}, attempts_sum)."""
        dc, dcy, att = {}, {}, 0
        for info in (needs or {}).values():
            att += int(info.get("attempts") or 0)
            for d, q in (info.get("datacores") or []):
                if q > 0:
                    dc[d] = dc.get(d, 0) + int(round(q))
            did = info.get("decryptor_id")
            dq = int(info.get("decryptor_qty") or 0)
            if did and dq > 0:
                dcy[did] = dcy.get(did, 0) + dq
        return dc, dcy, att

    @staticmethod
    def _best_invention_option(base_runs, out_per_run, options, plan_cost_fn,
                               net_sell):
        """Bester Decryptor für eine 🧪-Zeile (Nutzer-Wunsch „Meine
        Blueprints"): probiert jede Option (inkl. „Kein Decryptor") mit ihrer
        EIGENEN optimalen Menge - dem vollen BPC-Batch (Basis-Runs +
        Run-Mod) x Output/Run, denn genau diese Menge baut man nach einer
        erfolgreichen Invention real, und erst auf ihr sind Invention-EV und
        Batch-Rundung fair amortisiert. Verglichen wird GEWINN/STK (nicht
        Gesamtkosten - die Mengen unterscheiden sich ja je Run-Mod!).
        options: [(name, (prob_mult, run_mod, me_mod, te_mod, type_id)), …]
        plan_cost_fn(qty, dv) -> Gesamtkosten des Plans für qty Stück
        Rückgabe: {name, dv, opt_qty, cost_unit, profit_unit} oder None."""
        best = None
        for name, dv in (options or []):
            qty = max(1, int(base_runs) + int(dv[1] or 0)) * max(1, int(out_per_run))
            try:
                total = plan_cost_fn(qty, dv)
            except Exception:
                continue
            if not total or total <= 0:
                continue
            cu = total / qty
            pu = (net_sell - cu) if net_sell else None
            cand = {"name": name, "dv": dv, "opt_qty": qty,
                    "cost_unit": cu, "profit_unit": pu}
            if best is None or (pu is not None
                                and (best["profit_unit"] is None
                                     or pu > best["profit_unit"])):
                best = cand
        return best

    @staticmethod
    def _bp_me_map(rows, bp_to_product, me_global):
        """ME je Produkt aus den ECHTEN Blaupausen des Nutzers - schlechtester
        Fall (Regel 3).

        NUTZER (Sitzung 16): "lieber haette ich, dass der geringere Wert
        angezeigt wird - dass, wenn man den Bauplan dann genauer einstellt mit
        ME, man positiv ueberrascht wird."

        BIS SITZUNG 16 rechnete im Blueprints-Tab JEDE Zeile mit der globalen
        Einstellung `bau_me` (Vorgabe 10), waehrend die ME-Spalte daneben das
        echte ME aus ESI zeigte. Zwei Zahlen, eine Anzeige.

        ZWEI REGELN, BEIDE BEWUSST IN DIE SICHERE RICHTUNG:
        * Mehrere Kopien desselben Blaupausen-Typs mit verschiedenem ME ->
          die SCHLECHTESTE zaehlt, nicht der Mittelwert. Welche Kopie er im
          Spiel einlegt, weiss das Werkzeug nicht.
        * Zusaetzlich gegen `me_global` gedeckelt (min), damit KEINE Zahl
          optimistischer wird als vorher. Damit ist die Richtung zugesagt:
          Kosten koennen nur steigen, der Gewinn nur sinken - im Bauplan mit
          dem genauen ME wird es dann besser, nie schlechter.

        WICHTIG, GEMESSEN (Sitzung 16): das wirkt NUR auf Blaupausen OHNE
        Invention-Rezept, also T1. Erfundene T2 laufen in
        `industry.production_plan` ueber `_invention_me_pct` (feste
        Invention-ME + Decryptor) und ignorieren `me_map` - dort war die
        Rechnung schon vorher richtig. Container-Messung: T1 90'000 -> 100'000
        bei me_map[x]=0, T2 unveraendert 98'000.
        """
        schlechtestes = {}
        for b in (rows or []):
            bp_type = b.get("type_id")
            if not bp_type:
                continue
            me_wert = b.get("material_efficiency")
            if me_wert is None:
                continue
            vorher = schlechtestes.get(bp_type)
            schlechtestes[bp_type] = (float(me_wert) if vorher is None
                                      else min(vorher, float(me_wert)))
        raus = {}
        for bp_type, me_wert in schlechtestes.items():
            ziel = (bp_to_product or {}).get(bp_type)
            if ziel:
                raus[ziel[0]] = min(float(me_global), me_wert)
        return raus

    @staticmethod
    def _inventable_rows_from(owned_rows, invention_for_bpc):
        """Aus besessenen T1-Blueprints die ERFINDBAREN T2-Blueprints ableiten
        (Nutzer-Wunsch „Meine Blueprints"): wer die T1-Blaupause hat, kann per
        Invention jede zugehörige T2-Variante bauen - die soll mit eigener
        Wirtschaftlichkeit in der Liste stehen. Regeln:
        - dedupliziert (mehrere T1-Kopien -> eine T2-Zeile)
        - T2, die man SELBST schon besitzt, werden nicht doppelt gelistet
          (die echte, eigene Zeile ist informativer: echte ME/TE/Runs)
        - ME 2 / TE 4 = Invented-Basiswerte ohne Decryptor; Runs = Basis-Runs
          der Invention; Besitzer-Charakter = der des T1 (für den Char-Filter)
        Die Kosten-/Gewinnrechnung läuft danach über denselben Ökonomie-Pfad
        wie besessene Blueprints - production_plan mit invention=True rechnet
        den Invention-Erwartungswert (Datacores, Fehlversuche) mit ein."""
        owned_types = {r.get("type_id") for r in owned_rows}
        inv_rev = {}
        for t2_bp, inv in (invention_for_bpc or {}).items():
            inv_rev.setdefault(inv[0], []).append(t2_bp)
        out, added = [], set()
        for r in owned_rows:
            t1_bp = r.get("type_id")
            for t2_bp in inv_rev.get(t1_bp, []):
                if t2_bp in owned_types or t2_bp in added:
                    continue
                added.add(t2_bp)
                base_runs = int((invention_for_bpc[t2_bp][1]) or 1)
                out.append({"type_id": t2_bp, "quantity": 0,
                            "material_efficiency": 2, "time_efficiency": 4,
                            "runs": base_runs, "is_bpo": False,
                            "location_id": 0, "_char": r.get("_char"),
                            "_cid": r.get("_cid"),
                            "_inventable_from": t1_bp})
        return out

    @staticmethod
    def _bd_producible_fn(recipes):
        """„Kann ich das selbst herstellen?" - Fertigung ODER Reaktion.

        `recipes.is_manufactured()` beantwortet nur die halbe Frage (nur
        MANUFACTURING). Wer damit filtert, laesst Reaktionen still
        verschwinden. Pendant zu `_producible()` in scanner.find_deals -
        dieselbe Regel, damit Scanner und Bauplan nicht auseinanderlaufen.
        """
        if recipes is None:
            return lambda _t: False
        reac = getattr(recipes, "reaction_products", None) or set()
        return lambda t: recipes.is_manufactured(t) or t in reac

    @staticmethod
    def _unscheduled_build_items(plan, built_tids, is_manufactured_fn):
        """Baubare Items, die der Plan BEWUSST nicht baut - fürs
        „ℹ Nicht eingeplant"-Segment im Runplaner. Liefert
        [(tid, qty, 'buy'|'stock'), …] absteigend nach Menge:
        'buy'   = Plan hat entschieden, dass Kaufen billiger ist
        'stock' = Bedarf komplett durch Bestand/Pipeline gedeckt
        Teilweise gedeckte Items (auch in built_tids) erscheinen NICHT -
        die haben ja eine echte Bau-Zeile."""
        buy = (plan or {}).get("buy") or {}
        stock_used = (plan or {}).get("stock_used") or {}
        out = []
        for tid, q in buy.items():
            if q > 0 and is_manufactured_fn(tid):
                out.append((tid, int(q), "buy"))
        for tid, q in stock_used.items():
            if (q > 0 and tid not in (built_tids or set())
                    and not buy.get(tid) and is_manufactured_fn(tid)):
                out.append((tid, int(q), "stock"))
        out.sort(key=lambda x: -x[1])
        return out

    @staticmethod
    def _runplan_pool_char_ids(settings):
        """Charakter-Pool für den Runplaner-Bestand: JEDER Charakter, der
        rechts IRGENDEIN Rollen-Häkchen hat (Bau, Reakt, Inv ODER Kop).
        Nutzer-Setup: ein gemeinsames Ingame-Inventar, zum Bauen auf die
        Charaktere verteilt - Material kann also bei jedem Häkchen-Charakter
        liegen. Vorher zählten nur Bau+Reakt: lag ein Intermediate im Hangar
        eines reinen Inv/Kop-Charakters, sah der Plan es nie und plante die
        Reaktion tagelang immer wieder neu."""
        pool = set()
        for key in ("bau_build_chars", "bau_reaction_chars",
                    "bau_invention_chars", "bau_copy_chars"):
            pool |= set((settings or {}).get(key, []) or [])
        return pool

    @staticmethod
    def _parse_pasted_stock(text, name_map):
        """Bestandsliste aus dem Spiel einlesen (Nutzer-Wunsch, Vorbild EVE
        Cookbook). Verarbeitet die Formate, die ingame/aus Tools wirklich
        anfallen:
          Ingame-Hangar-Kopie: "Name<TAB>1.234<TAB>Gruppe<TAB>..."
          Multibuy/Listen:     "Name 1234"  ·  "Name x1234"  ·  "1234 Name"
          nur Name            -> Menge 1
        Punkt/Komma als Tausendertrenner werden entfernt (EVE kopiert
        "1.234" bzw. "1,234"). Rückgabe: ({type_id: menge}, [unbekannt…]).
        Doppelte Zeilen werden ADDIERT (mehrere Hangar-Register)."""
        import re as _re
        out, unknown = {}, []
        for raw in (text or "").splitlines():
            line = raw.strip()
            if not line or line.startswith("#"):
                continue
            qty, name = None, None
            if "\t" in line:                      # Ingame-Kopie
                parts = [p.strip() for p in line.split("\t")]
                name = parts[0]
                for p in parts[1:]:
                    c = p.replace(".", "").replace(",", "").replace("'", "")
                    if c.isdigit():
                        qty = int(c)
                        break
            if name is None:
                m = _re.match(r"^(.*?)[\s]*[x*]?[\s]*([\d.,']+)$", line)
                if m and _re.sub(r"[.,']", "", m.group(2)).isdigit():
                    name, qty = m.group(1).strip(), int(
                        _re.sub(r"[.,']", "", m.group(2)))
                else:
                    m2 = _re.match(r"^([\d.,']+)[\s]+(.*)$", line)
                    if m2 and _re.sub(r"[.,']", "", m2.group(1)).isdigit():
                        qty, name = int(_re.sub(r"[.,']", "", m2.group(1))), \
                            m2.group(2).strip()
                    else:
                        name = line
            name = (name or "").strip(" \t-•*")
            if not name:
                continue
            tid = name_map.get(name.lower())
            # NAMEN, DIE AUF ZIFFERN ENDEN (Sitzung 17): eine Zeile OHNE
            # Menge wurde am letzten Zahlenblock zerlegt - aus "Zainou
            # 'Beancounter' Industry BX-802" wurde Name "...BX", Menge 802.
            # Ergibt das Zerlegen einen UNBEKANNTEN Namen, die ganze Zeile
            # aber ist bekannt, gilt die ganze Zeile mit Menge 1. Eine
            # zweite Pruefung VOR dem Zerlegen waere doppelt gemoppelt -
            # sie blieb in der Rotprobe blind (Mutation 639).
            if tid is None and name_map.get(line.lower()) is not None:
                tid, qty = name_map[line.lower()], 1
            if tid is None:
                unknown.append(name)
                continue
            out[int(tid)] = out.get(int(tid), 0) + int(qty if qty else 1)
        return out, unknown

    @staticmethod
    def _merge_frozen_stock(frozen, live):
        """Bestand eines EINGEFRORENEN Plans mit dem Live-Bestand mischen:
        pro Item max(eingefroren, live). Semantik (Nutzer-Fall „ich baue seit
        3 Tagen dieselben Intermediate-Reaktionen und sie verschwinden nie"):
        - Eingekaufte Materialien werden beim Bauen VERBRAUCHT - live fällt
          unter den Einfrier-Stand. Der Einfrier-Stand bleibt stehen (max),
          sonst würde der Plan verbrauchtes Material wieder als "zu kaufen"
          aufreißen - genau das soll der 🔒-Knopf ja verhindern.
        - Seither GEBAUTE Zwischenprodukte (inkl. virtuellem Bestand aus
          fertigen/frisch abgelieferten Jobs) lassen live ÜBER den Einfrier-
          Stand steigen - dieser Zuwachs wird gutgeschrieben, der Runplaner
          plant sie nicht mehr ewig neu.
        max() ist mathematisch identisch mit "eingefroren + nur-Zuwächse"
        (frozen + max(0, live - frozen))."""
        # Keys ZUERST normalisieren (JSON macht aus Dict-Keys Strings, der
        # Live-Bestand hat Ints): sonst läuft derselbe Key als "34" UND 34
        # durch die Union und der zweite Durchgang überschreibt den ersten -
        # die Gutschrift ginge je nach Iterationsreihenfolge still verloren
        # (von der Testkette gefangen, Schritt h).
        fz = {int(k): int(v or 0) for k, v in (frozen or {}).items()}
        lv = {int(k): int(v or 0) for k, v in (live or {}).items()}
        return {t: max(fz.get(t, 0), lv.get(t, 0)) for t in set(fz) | set(lv)}

    # Kategorie-ME/TE („ANDERE BLAUPAUSEN": Komponenten / T1-Hüllen /
    # Fuel Blocks / Tools). EINE Quelle für Attribut-Name, Settings-Schlüssel
    # und Notfall-Default - vorher standen die 10/20 an fünf Stellen hart im
    # Code und die eigene Einstellung war bei jedem NEUEN Bauplan wieder weg
    # (Nutzer-Meldung). TE-Default 20 statt 10: ein voll erforschtes BPO hat
    # TE 20 % (ME 10 % ist das Maximum, TE 20 %) - die 10 in config.DEFAULTS
    # war eine Altlast, die nie gewirkt hat, weil der Code hart 20 setzte.
    _CAT_ME_TE_KEYS = (
        ("_bd_me_component", "bau_me_component", 10),
        ("_bd_te_component", "bau_te_component", 20),
        ("_bd_me_t1hull", "bau_me_t1hull", 10),
        ("_bd_te_t1hull", "bau_te_t1hull", 20),
        ("_bd_me_fuel", "bau_me_fuel", 10),
        ("_bd_te_fuel", "bau_te_fuel", 20),
        ("_bd_me_tools", "bau_me_tools", 10),
        ("_bd_te_tools", "bau_te_tools", 20),
    )

    @classmethod
    def _cat_me_te_defaults(cls, settings):
        """Kategorie-ME/TE-Vorgabe für einen NEUEN Bauplan: die zuletzt
        benutzten Werte aus den Settings, sonst der Notfall-Default.
        Gespeicherte Pläne überschreiben das mit ihren EIGENEN Werten."""
        out = {}
        for attr, key, dflt in cls._CAT_ME_TE_KEYS:
            try:
                out[attr] = int((settings or {}).get(key, dflt))
            except (TypeError, ValueError):
                out[attr] = dflt
        return out

    @staticmethod
    def _me_te_dirty(current, applied):
        """Weichen die EINGESTELLTEN ME/TE-Werte von den zuletzt GERECHNETEN
        ab? (Nutzer-Fund: man kann die Regler drehen, aber `_store_cat_me_te`
        laeuft ausschliesslich in `_recompute` - bis zum Klick auf
        „Neu berechnen" zeigte der Dialog also Kosten, die nicht mehr zur
        sichtbaren Einstellung passten. Stille Divergenz, gleiche Klasse wie
        die Bestands-Vermischung.)

        `applied` leer/None = es wurde in diesem Dialog noch nichts gerechnet
        -> NICHT als abweichend melden (sonst startet der Dialog schon mit
        einem Warnmarker, ohne dass der Nutzer etwas getan hat).
        """
        if not applied:
            return False
        cur = current or {}
        for k in set(cur) | set(applied):
            try:
                if int(cur.get(k, 0) or 0) != int(applied.get(k, 0) or 0):
                    return True
            except (TypeError, ValueError):
                return True
        return False

    def _tool_parent(self):
        """Eltern-Fenster fuer Werkzeug-Dialoge (Optimierer, Orderbuch-genau,
        …): der offene Bauplan-Dialog, sonst das Hauptfenster.

        Grund: der Bauplan-Dialog ist ein parentloses Top-Level-Fenster (damit
        er minimierbar ist). Ein Werkzeug an der MainWindow erscheint deshalb
        HINTER ihm - der Nutzer klickt, das Bauplan-Fenster rutscht weg und
        das Werkzeug ist nicht zu sehen ("es passiert nichts"). Als Kind des
        Bauplan-Fensters liegt es garantiert obendrauf."""
        d = getattr(self, "_bd_dialog", None)
        if d is None:
            return self
        try:
            # Kanonische Pruefung: nach einem deleteLater() lebt der Python-
            # Wrapper weiter, waehrend das C++-Objekt schon weg ist. isVisible()
            # wirft dann NICHT immer zuverlaessig - shiboken sagt es sicher.
            import shiboken6
            if not shiboken6.isValid(d):
                self._bd_dialog = None
                return self
        except Exception:
            pass                        # shiboken nicht verfuegbar -> weiter
        try:
            if d.isVisible():
                return d
        except RuntimeError:
            self._bd_dialog = None      # Qt-Objekt schon geloescht
        return self

    @staticmethod
    def _frozen_stock_rebase_diff(frozen_stock, live_stock):
        """Was wuerde „Einfrier-Bestand neu setzen" konkret aendern?
        Vergleicht den eingefrorenen Bestand mit dem aktuellen Live-Stand.

        Rueckgabe: {"changed": [(tid, alt, neu), … groesste Differenz zuerst],
                    "down": n, "up": n, "gone": n}
        Ohne diese Vorschau war der Knopf eine Blackbox: er meldete nur einen
        2-Sekunden-Tooltip, und wenn sich im Plan nichts sichtbar aenderte,
        konnte niemand unterscheiden zwischen „hat funktioniert, war aber
        dasselbe" und „hat gar nicht ausgeloest" (Nutzer-Meldung).
        """
        fz = {int(k): int(v or 0) for k, v in (frozen_stock or {}).items()}
        lv = {int(k): int(v or 0) for k, v in (live_stock or {}).items()}
        changed, down, up, gone = [], 0, 0, 0
        for tid in set(fz) | set(lv):
            a, b = fz.get(tid, 0), lv.get(tid, 0)
            if a == b:
                continue
            changed.append((tid, a, b))
            if b == 0:
                gone += 1
            elif b < a:
                down += 1
            else:
                up += 1
        changed.sort(key=lambda x: -abs(x[1] - x[2]))
        return {"changed": changed, "down": down, "up": up, "gone": gone}

    @staticmethod
    def _char_from_where_label(label):
        """„Peanut Motor · Hangar" -> „Peanut Motor". Das Trennzeichen setzt
        _owned_where; alles davor ist der Charaktername, alles danach der
        Ablageort (Hangar/Container)."""
        return (str(label or "").split(" \u00b7 ")[0].strip() or "?")



    @classmethod
    def _cart_conflict_rows(cls, items, needed=None, owned=None,
                            where_by_tid=None, selling=None, buying=None,
                            show_all=False, scope_stock=None):
        """Aufbereitete Zeilen fuer den „Schon vorhanden"-Dialog - pure
        Funktion, damit die Rechnung ohne Qt pruefbar ist.

        Rueckgabe je Konflikt-Item:
          {tid, name, need, own, missing, status, status_txt,
           by_char {Charakter: Menge}, main_char, flags [..]}
        Nur Items MIT Konflikt (Bestand vorhanden oder offene Order) kommen
        vor - alles andere wandert ungefragt in den Wagen.
        """
        selling = set(selling or ())
        buying = set(buying or ())
        needed = needed or {}
        owned = owned or {}
        where_by_tid = where_by_tid or {}
        out = []
        for tid, name in items:
            tid = int(tid)
            own = int(owned.get(tid, 0) or 0)
            flags = []
            if tid in selling:
                flags.append(t("Sell order"))
            if tid in buying:
                flags.append(t("Buy order"))
            # NUTZER: "es waere doch interessanter zu sehen, was mir noch
            # fehlt und was ich mit dieser Liste kaufen werde." Zu Recht -
            # bisher zeigte der Dialog nur die AUSNAHMEN (was man schon hat)
            # und lie\u00df ausgerechnet die Einkaufsliste ungefragt durchlaufen.
            # Mit show_all=True steht ALLES drin, was in den Wagen geht.
            if own <= 0 and not flags and not show_all:
                continue
            _nd = needed.get(tid)
            need = int(_nd) if _nd is not None else None
            # WORAN wird "gedeckt" gemessen? An dem Bestand, mit dem der PLAN
            # rechnet - nicht am Portfolio (Nutzer: "die 91 Cormorants sollten
            # mir gar nicht angezeigt werden, die liegen auf keiner
            # eingetragenen Bau-Station").
            # Das war ein RECHENFEHLER, keine Geschmacksfrage: der Plan
            # verlangte 20 Cormorants, der Dialog meldete "gedeckt" und liess
            # sie unangekreuzt - wer der Liste folgte, kaufte sie nicht und
            # der Bau scheiterte. `own` bleibt fuer die ANZEIGE erhalten
            # ("du hast 91, nur woanders").
            _base = (int((scope_stock or {}).get(tid, 0) or 0)
                     if scope_stock is not None else own)
            missing = None if need is None else max(0, need - _base)
            by_char = {}
            for lbl, q in (where_by_tid.get(tid) or []):
                c = cls._char_from_where_label(lbl)
                by_char[c] = by_char.get(c, 0) + int(q or 0)
            status, status_txt = cls._cart_need_status(need, _base)
            # WIEVIEL wandert beim Ankreuzen wirklich in den Wagen? Die
            # NIE MEHR ALS DIE FEHLMENGE (Nutzer, Sitzung 12: "warum sollte
            # ich mehr einkaufen wollen, als ich brauche? Mach das auf jeden
            # Fall weg").
            #
            # Frueher lag bei einem GEDECKTEN Item die VOLLE Menge im Wagen -
            # gedacht als "er will es trotzdem". In der Praxis fuehrte das
            # dazu, dass laengst gekaufte Mineralien wieder auf der
            # Einkaufsliste standen. Ist nichts offen, ist auch nichts zu
            # kaufen; wer trotzdem Vorrat will, nimmt den Puffer.
            cart_qty = missing
            _scoped = scope_stock is not None
            out.append({
                "cart_qty": cart_qty,
                "scoped": _scoped,
                "tid": tid, "name": name, "need": need, "own": own,
                "missing": missing, "status": status, "status_txt": status_txt,
                "by_char": by_char,
                # Zuordnung: der Charakter mit dem GROESSTEN Anteil. Damit
                # taucht jedes Item genau EINMAL als ankreuzbare Zeile auf
                # (die Aufteilung steht in den Unterzeilen) - sonst muesste
                # man dasselbe Haekchen an mehreren Stellen bedienen.
                "main_char": (max(by_char.items(), key=lambda kv: kv[1])[0]
                              if by_char else None),
                "flags": flags})
        _rank = {"none": 0, "partial": 1, "unknown": 2, "covered": 3}
        out.sort(key=lambda r: (_rank.get(r["status"], 9), r["name"]))
        return out

    @staticmethod
    def _manual_stock_is_current(manual_ts, esi_ts, permanent=False):
        """Gilt die per Clipboard EINGEFÜGTE Bestandsliste noch? (Nutzer-
        Auftrag Punkt 3, „Zeitstempel-Automatik".)

        Regel: der eingefügte Wert ist nur so lange die Wahrheit, wie er
        NEUER ist als die ESI-Bestandsdaten. Sobald ESI frischer ist, hat
        ESI die aktuellere Sicht auf den Hangar und übernimmt automatisch
        wieder. Damit versteinern eingefügte Zahlen nicht mehr - altes
        Verhalten: sie galten dauerhaft, auch nach Stunden, ohne Warnung.

        Zwei bewusste Ausnahmen:
        - permanent=True (Dauerhaft-Häkchen, Punkt 4): Corp-Hangar-Material,
          das der Charakter-Assets-Endpunkt PRINZIPIELL nie liefert. Ohne
          diese Ausnahme fiele der Wert beim nächsten ESI-Abruf fälschlich
          auf 0 zurück - ESI wäre zwar frischer, wüsste aber nichts.
        - esi_ts is None (kein ESI-Lagerbestand geladen / Abruf gescheitert /
          Scope zählt nichts): dann ist die Einfügung die einzige datierte
          Quelle und gilt.
        Ohne Einfügung (manual_ts is None) gilt nie etwas.
        """
        if manual_ts is None:
            return False
        if permanent:
            return True
        if esi_ts is None:
            return True
        return float(manual_ts) >= float(esi_ts)

    @classmethod
    def _resolve_stock_sources(cls, esi_stock, virtual_stock, manual_stock,
                               manual_ts=None, esi_ts=None,
                               manual_permanent=False, manual_only=False):
        """Effektiver Bestand + HERKUNFT je Item (Nutzer-Auftrag Punkt 2,
        „Trennung statt Vermischung").

        Vorher überschrieb der eingefügte Wert den ESI-Wert STILL (nur die
        Statuszeile nannte die Anzahl) - genau die Art stiller Vermischung,
        die im Rest des Tools überall abgeschafft wurde. Jetzt wird pro Item
        mitgeführt, WOHER die Zahl kommt.

        Drei Bausteine je Item:
          esi_stock      Lagerbestand laut ESI-Assets
          virtual_stock  Pipeline: fertige / frisch abgelieferte / laufende
                         Jobs (s. _virtual_stock)
          manual_stock   per Clipboard eingefügte Hangar-Menge

        WICHTIG: die eingefügte Menge ersetzt NUR den LAGER-Anteil (ESI-
        Assets); die Pipeline wird IMMER dazugezählt. Grund: der Output eines
        laufenden Jobs steht noch in keinem Hangar, kann in der eingefügten
        Liste also gar nicht vorkommen. Würde die Einfügung ihn mit
        überschreiben, plante der Runplaner laufende Jobs erneut ein - exakt
        der Fehler, der mit dem virtuellen Bestand behoben wurde.

        manual_only=True (Punkt 5): ESI-LAGERBESTAND komplett aus, es zählt
        nur die eingefügte Liste - der virtuelle Job-Bestand läuft weiter.

        Rückgabe: (stock, src)
          stock {tid: menge}  - effektiv, wandert nach opts["stock"]
          src   {tid: {"src": "esi"|"manuell", "esi": n,
                       "manual": m oder None, "job": v}}
                „manual": None heißt ausdrücklich „nicht eingefügt" (anders
                als eine eingefügte 0).
        """
        esi_q = {int(k): int(v or 0) for k, v in (esi_stock or {}).items()}
        virt = {int(k): int(v or 0) for k, v in (virtual_stock or {}).items()}
        man = {int(k): int(v or 0) for k, v in (manual_stock or {}).items()}
        active = cls._manual_stock_is_current(manual_ts, esi_ts,
                                              manual_permanent)
        stock, src = {}, {}
        for tid in set(esi_q) | set(virt) | set(man):
            e = esi_q.get(tid, 0)
            m = man.get(tid)
            j = virt.get(tid, 0)
            use_manual = bool(manual_only or (m is not None and active))
            qty = (m or 0 if use_manual else e) + j
            src[tid] = {"src": "manuell" if use_manual else "esi",
                        "esi": e, "manual": m, "job": j}
            if qty > 0:
                stock[tid] = qty
        return stock, src








    def _reservierungen_anwenden(self, stock):
        """Reservierungen ANDERER Plaene vom Bestand abziehen - an EINER
        Stelle fuer jeden Weg, der `opts["stock"]` setzt.

        HERAUSGEZOGEN (Sitzung 20, Pruefung der Reservierungslogik): der
        eingefrorene Plan bekam seinen Bestand in `open_build_detail` OHNE
        diesen Abzug, der Live-Weg (`_recompute_bd_stock`) MIT. Bis die
        Assets nachgeladen waren, rechnete ein eingefrorener Plan also mit
        Material, das andere Plaene laengst halten - und schlug im Zweifel
        zu wenig zum Kauf vor. Blieb der Assets-Abruf aus (ESI-Fehler),
        blieb es dabei. Jetzt laeuft beides durch dieselbe Funktion.
        Aendert `stock` an Ort und Stelle; setzt die Anzeigefelder
        `_bd_reserved_applied/_plans/_pending`.
        """
        _res_map, _res_plans = self._reserved_by_other_plans(
            self.settings, getattr(self, "_bd_open_plan_id", None))
        # DIE EIGENE RESERVIERUNG SCHUETZT DEN EIGENEN BESTAND (Sitzung 17,
        # Nutzer-Fall: er hatte fuer diesen Plan gekauft UND reserviert,
        # trotzdem meldete die Einkaufsliste alles als fehlend). Der eigene
        # Plan war bisher nur von der Kuerzung AUSGENOMMEN - andere Plaene
        # durften den Bestand rechnerisch bis auf Null aufbrauchen, auch
        # seine reservierten Einheiten.
        #
        # DIE REGEL IST DIE FAIRE AUFTEILUNG: jeder Plan bekommt zuerst
        # seinen reservierten Anteil, vom Rest bedient er sich. Gerechnet
        # als Deckel - beides ergibt dasselbe:
        #   eigen + max(0, Bestand - alle Reservierungen)
        #   == max(Bestand - fremde Reservierungen, eigen)      [<= Bestand]
        _eigen = self._reserved_by_this_plan(
            self.settings, getattr(self, "_bd_open_plan_id", None))
        # BAU-PRIORITAET (28.09.2026, Kartenreihenfolge): hat der Plan einen
        # Rang, sieht er oben nur die Plaene VOR ihm - und die gehen vor.
        # Der Eigenschutz wuerde sonst dieselben Einheiten ein zweites Mal
        # zaehlen (#1 haelt sie, #3 "schuetzt" sie auch).
        if str(getattr(self, "_bd_open_plan_id", None)) in self.plan_rang(self.settings):
            _eigen = {}
        _applied = self.bestand_nach_reservierungen(stock, _res_map, _eigen)
        self._bd_reserved_applied = _applied
        self._bd_reserved_plans = _res_plans
        # NOCH NICHT ANGELIEFERTER ANSPRUCH (Nutzer-Frage: "was, wenn das
        # Frachtunternehmen den Bestand noch liefert?"): der Abzug ist auf
        # das Vorhandene gedeckelt - der Rest des Anspruchs "wartet" und
        # greift automatisch, sobald die Lieferung im Bestand auftaucht
        # (Courier-Fracht ist laut ESI unterwegs NICHT in den Assets).
        # Diese Wartemenge wird ANGEZEIGT, damit ein scheinbar zu kleiner
        # Bestand in der Uebergangszeit erklaerbar ist statt raetselhaft.
        self._bd_reserved_pending = sum(
            max(0, int(_q) - _applied.get(_t, 0))
            for _t, _q in (_res_map or {}).items())

    def _bd_bestand_mitnehmen(self):
        """Lager-Bausteine des OFFENEN, nicht eingefrorenen Bauplan-Fensters
        fuer das Fenster, das gleich an seiner Stelle neu oeffnet (Ende
        anhaengen, Einzelplan -> Buendel, Kopie). Vorher setzte das neue
        Fenster den Bestand auf leer, bis der Assets-Abruf fertig war - in
        dieser Zeit fehlte alles, und wer da einfror, fror einen LEEREN
        Bestand ein (emm253-Fall, nachgestellt 01.10.2026, emm308).
        None = nichts mitzunehmen (kein Fenster, eingefroren, kein Bestand)."""
        if self._offener_bauplan() is None or getattr(self, "_bd_frozen", None):
            return None
        _base = getattr(self, "_bd_esi_stock_base", None)
        _virt = getattr(self, "_bd_virt_stock", None) or {}
        if not _base and not _virt:
            return None
        return {"base": dict(_base or {}), "virt": dict(_virt),
                "ts": getattr(self, "_bd_esi_stock_ts", None)}

    def _recompute_bd_stock(self):
        """Effektiven Bauplan-Bestand + Herkunft aus den gemerkten Bausteinen
        neu bilden - ohne ESI-Abruf. Damit wirkt jede Änderung am Clipboard-
        Panel (Übernehmen/Leeren/Dauerhaft/„nur eingefügte") SOFORT, statt
        einen kompletten Assets-Rundgang auszulösen."""
        stock, src = self._resolve_stock_sources(
            getattr(self, "_bd_esi_stock_base", None) or {},
            getattr(self, "_bd_virt_stock", None) or {},
            getattr(self, "_bd_manual_stock", None) or {},
            manual_ts=getattr(self, "_bd_manual_ts", None),
            esi_ts=getattr(self, "_bd_esi_stock_ts", None),
            manual_permanent=bool(getattr(self, "_bd_manual_perm", False)),
            manual_only=bool(getattr(self, "_bd_manual_only", False)))
        # RESERVIERUNGEN ANDERER PLAENE ABZIEHEN - an dieser EINEN Stelle,
        # damit es fuer ESI-, Pipeline- UND Clipboard-Bestand gleichermassen
        # gilt (Arbeitsregel 9). Sichtbar gemacht wird der Abzug ueber
        # _bd_reserved_applied/_bd_reserved_plans in der Seitenleiste -
        # still schrumpfender Bestand waere eine neue Falle (Regel 6).
        self._reservierungen_anwenden(stock)
        self._bd_stock_src = src
        if not hasattr(self, "_bd_opts") or self._bd_opts is None:
            self._bd_opts = {}
            self._bd_plan_cache = None
        if stock:
            self._bd_opts["stock"] = stock
        else:
            self._bd_opts.pop("stock", None)
        return stock, src

    @staticmethod
    def _stock_age_text(ts, now=None):
        """„eingefügt vor X" für das Clipboard-Panel - Minuten unter 1 h,
        sonst Stunden, ab 48 h Tage. None -> „noch nichts eingefügt"."""
        if not ts:
            return t("nothing pasted yet")
        import time as _t
        secs = max(0.0, float(now if now is not None else _t.time()) - float(ts))
        if secs < 3600:
            return t("pasted {n} min ago").format(n=int(secs // 60))
        if secs < 48 * 3600:
            return t("pasted {h} h ago").format(h=f"{secs / 3600:.1f}".replace(".0", ""))
        return t("pasted {d} days ago").format(d=int(secs // 86400))

    @classmethod
    def _efficiency_floor_build_opts(cls, settings):
        """Baukosten-Optionen des BEST-CASE-Produzenten - der Rückkehr-Boden
        für „Unter Baupreis". Nutzer-Kritik (korrekt): der Boden mit den
        EIGENEN Baukosten gerechnet zeigt falsche Schnäppchen, weil der
        Nullsec-Großbauer 10-20 % billiger baut und der Preis deshalb nie auf
        das eigene Niveau zurückkehren muss. Der Boden muss der GÜNSTIGSTE
        relevante Produzent sein: ME 10, T2-ME-Rig x Nullsec-Multiplikator,
        Engineering-Complex-Bonus, Reaktionsketten selbst gebaut (T2-Reaktor-
        Rig x Null-Multiplikator). Alle Zahlen aus den vorhandenen, ingame-
        verifizierten Konstanten (_ME_RIG_PCT/_STRUCT_ROLE_ME/_SEC_LEVELS) -
        KEIN Kategorie-Abgleich nötig: dem Best-Case-Bauer wird das jeweils
        passende Rig schlicht unterstellt (er hat für jede Item-Klasse die
        richtige Struktur). Job-Kosten (Systemindex) bleiben die des Nutzers -
        kleiner Posten, und einen "billigsten Index der Galaxis" zu raten
        wäre ein neuer Fixwert ohne Quelle."""
        null_mult = max(v for v, _lbl in cls._SEC_LEVELS)        # Null/WH x2.1
        rig_t2 = cls._ME_RIG_PCT.get(2, 2.4)
        mfg_rig = rig_t2 * null_mult                              # 5.04 %
        ec_me = max(cls._STRUCT_ROLE_ME.values() or [0.0])        # EC +1 %
        eff_me = (1 - (1 - 10.0 / 100.0) * (1 - mfg_rig / 100.0) *
                  (1 - ec_me / 100.0)) * 100.0
        react_rig = rig_t2 * 1.1        # Reaktor-Sicherheits-Mult (Null x1.1)
        return {
            "me": eff_me,
            "me_reaction": react_rig,
            "job_pct": (settings or {}).get("bau_job_pct", 3),
            # WICHTIG: build_reactions=True würde das Selbstbauen von
            # Reaktionen ERZWINGEN, auch wenn der Markt das Reaktionsprodukt
            # billiger verkauft - ein Boden darf aber an jedem Knoten nur das
            # MINIMUM aus Bauen und Kaufen nehmen (erzwungenes Bauen kann ihn
            # nur nach oben verfälschen; Zealot-Kanarienvogel: Tool 167M vs.
            # Cookbook 129M nach den ersten zwei Fixes). Mit False rechnet
            # build_cost die Reaktionskette trotzdem durch und wählt sie,
            # WENN sie billiger ist - genau die Boden-Semantik.
            "build_reactions": False,
            # nur für die Detail-Ansicht (build_tree): Reaktionen dort
            # ebenfalls per Minimum entscheiden statt hart zu kaufen -
            # build_cost macht das bei False ohnehin schon.
            "reaction_min": True,
            "invention": True,
            "max_depth": 12,
        }

