    def _hold_preset_to_custom(self, *args):
        if getattr(self, "_applying_hold_preset", False):
            return
        if hasattr(self, "h_preset") and self.h_preset.currentIndex() != 0:
            self.h_preset.blockSignals(True)
            self.h_preset.setCurrentIndex(0)
            self.h_preset.blockSignals(False)

    def _apply_hold_preset(self):
        p = self.h_preset.currentData()
        if not p:
            return
        self._applying_hold_preset = True
        try:
            wi = self.h_window.findData(p.get("window", 90))
            if wi >= 0:
                self.h_window.setCurrentIndex(wi)
            self.h_below.setValue(p.get("below", 0))
            self.h_maxbelow.setValue(p.get("maxbelow", 40))
            self.h_exp.setValue(p.get("exp", 0))
            self.h_expisk.setValue(p.get("expisk", 0))
            self.h_vol.setValue(p.get("vol", 0))
            self.h_exitqty.setValue(p.get("exitqty", 0))
            self.h_sellfill.setValue(p.get("sellfill", 0))
            self.h_dos.setValue(p.get("dos", 0))
            self.h_pmin.setValue(p.get("pmin", 0))
            self.h_pmax.setValue(p.get("pmax", 0))
        finally:
            self._applying_hold_preset = False
        if not hasattr(self, "hold_status"):
            return
        if store.get_snapshot():
            self.hold_status.setText(t("Preset set \u2013 now \u201eLoad deals\u201c."))
        else:
            self.hold_status.setText(t(
                "Preset applied. First „Market scan“, then „Load deals“."))

    @staticmethod
    def _hold_min_hist_days(days):
        """Mindest-Historientage für den Swing-Normalpreis: ~Fenster/4,
        mindestens 20, höchstens 45 (0 = "Alles" -> 20)."""
        # entschärft (45 leerte den 180-Tage-Scan zusammen mit S3 zu stark):
        return max(20, min(30, int(days or 0) // 6))

    def compute_hold(self):
        snapshot = store.get_snapshot()
        if not snapshot:
            self.hold_status.setText(t("Please run \u201eMarket scan\u201c first."))
            return
        days = self.h_window.currentData()
        filters = {
            "min_margin": self.h_below.value(),
            "max_under_pct": self.h_maxbelow.value(),
            # Phantom-Tor (s. Widget-Kommentar): Feld ist aus der Sicht
            # entfernt, hart 0 senden statt eines unsichtbaren Werts.
            "min_sell_fill": 0,
            # dynamisch ans Fenster gekoppelt: ein 180-Tage-"Normalpreis" auf
            # nur 20 Datenpunkten ist wackelig. Ein Viertel des Fensters,
            # mindestens 20, gedeckelt bei 45.
            "min_hist_days": self._hold_min_hist_days(days),
            "min_daily_vol": self.h_vol.value(),
            "min_exit_qty": self.h_exitqty.value(),
            "max_dos": self.h_dos.value(),
            "avoid_falling": True,
            "min_expected_pct": self.h_exp.value(),
            "min_expected_isk": self.h_expisk.value(),
            "price_min": self.h_pmin.value(),
            "price_max": self.h_pmax.value(),
            "max_items": 300,
        }
        hold_mode = self.h_mode.currentData() if hasattr(self, "h_mode") else "under"
        if hold_mode == "under":
            # Analyse-Deckel getrennt nach ECHTEN Kosten: eine bereits gecachte
            # Preishistorie kostet nur einen DB-Lesevorgang, also werden ALLE
            # gecachten Kandidaten mitanalysiert; gedeckelt wird nur, wie viele
            # Historien ein Scan NEU von ESI holt. Die Swing-Grundgesamtheit
            # wächst damit über wenige Scans von ein paar hundert auf einige
            # tausend Items, ohne dass ein Scan länger am ESI-Limit hängt.
            # BEWUSST NUR HIER: in "underbuild" kostet jeder weitere Kandidat
            # eine komplette Baukosten-Rechnung (rekursive Stückliste), nicht
            # nur einen DB-Lesevorgang - dort bliebe der Deckel sonst nicht
            # gratis, sondern würde den Scan spürbar verlangsamen.
            # KALIBRIERT am echten Nutzer-Topf (4'843 gecachte Items beim
            # ersten Praxislauf, Analyse ~1,4 ms/Item -> 6'000 ≈ 8-9 s):
            # Deckel = Topf + Luft. Das Nachladen (350/Scan) läuft damit
            # automatisch wieder an, bis der Topf ~6'000 erreicht (~4 Scans),
            # dann greift die Abruf-Pause erneut und Preset-Wechsel sind
            # wieder reine Cache-Läufe. Weiteres Anheben nur, wenn die
            # Trichterzahlen zeigen, dass Reichweite (nicht die Filter) der
            # Engpass ist - beim Kalibrier-Lauf war es umgekehrt ("nicht tief
            # genug" war das mit Abstand größte Tor).
            filters["max_cached_items"] = 6000
            filters["max_new_history"] = 350
        if hold_mode == "underbuild" and not industry.sde_ready():
            self.hold_status.setText(t("For „below build cost“ load the blueprints first."))
            return
        if hold_mode == "underbuild":
            # EFFIZIENZ-PRODUZENT-BODEN (Design-Entscheid mit dem Nutzer):
            # NICHT die eigenen Baukosten (eigene Rigs/Strukturen), sondern
            # der Best-Case-Produzent ist die Rückkehr-Schwelle - unter DEM
            # baut niemand dauerhaft, also erst dort ist "unter Baupreis"
            # wirklich ein Kaufsignal. Details im Docstring des Helpers.
            build_opts = self._efficiency_floor_build_opts(self.settings)
        else:
            build_opts = None
        self.hold_btn.setEnabled(False)
        self.hold_status.setText(t("Searching hold candidates (loading price histories) …"))

        scan_region = store.get_scan_region()
        self._sync_fees_to_hub(scan_region)   # broker fee for THIS hub's standings

        def job(progress=None, should_cancel=None):
            recipes = industry.recipes_cached() if hold_mode == "underbuild" else None
            if recipes is not None and build_opts is not None:
                # Zwei Boden-Lücken, die NUR T2 betrafen (Nutzer-Fund per
                # EVE-Cookbook-Gegenprobe am Zealot: Tool-Boden 178M vs.
                # Cookbook 129M; T2-Munition teils 10x drüber):
                # (1) Invented BPCs ignorieren opts["me"] komplett - sie
                #     rechnen Invention-ME (2 %) x rig_me_map[type_id]. Ohne
                #     rig_me_map baute der "Best-Case-Produzent" alle T2-
                #     Items OHNE Rig. Jetzt: T2-Rig x Nullsec (5,04 %) für
                #     jedes baubare Produkt unterstellt (genau das IST der
                #     Best Case - kein Kategorie-Abgleich nötig).
                # (2) Ohne inv_skill_modifier gilt die Basis-Erfolgschance
                #     OHNE Skills - der Best-Case hat Encryption V + beide
                #     Datacore-Skills V = x1,4583 (1 + 5/40 + 10/30):
                #     Invention-Kosten waren ~46 % zu hoch.
                _floor_rig = (self._ME_RIG_PCT.get(2, 2.4)
                              * max(v for v, _l in self._SEC_LEVELS))
                build_opts["rig_me_map"] = {
                    tid: _floor_rig for tid in recipes.product_to_bp}
                _mod = 1.0 + 5 / 40.0 + 10 / 30.0
                build_opts["inv_skill_modifier"] = {
                    bp: _mod for bp in recipes.invention_for_bpc}
                self._last_floor_opts = dict(build_opts)
            _diag = {}
            deals = scanner.find_deals(snapshot, self.settings, days, hold_mode, filters,
                                       progress=progress, region=scan_region,
                                       recipes=recipes, build_opts=build_opts,
                                       should_cancel=should_cancel, diag=_diag)
            if should_cancel and should_cancel():
                return [], _diag
            esi.resolve_names([d["type_id"] for d in deals])
            return deals, _diag

        w = Worker(job, with_progress=True, with_cancel=True)
        w.progress.connect(lambda d, tot: self.hold_status.setText(t("Analysing \u2026 {d}/{n}").format(d=d, n=tot)))

        def done(res):
            deals, _diag = res
            self.hold_btn.setEnabled(True)
            self._last_hold_diag = _diag
            self._last_hold_mode = hold_mode
            self._render_hold(deals)

        def fail(msg):
            self.hold_btn.setEnabled(True)
            self.hold_status.setText(t("Error: ") + msg)
        self._run(w, done, fail_cb=fail, label=t("Searching swing candidates …"))

    def _swing_quality(self, d):
        """How good an ACCUMULATION target is – Swing logic, not Daytrade. No
        turnover/tradability weighting (you hold for weeks). Rewards a deep
        discount, a real expected reversion profit, safety (not falling, enough
        history) and enough resale liquidity to eventually get out."""
        exp = d.get("exp_pct", 0) or 0
        under = d.get("under_pct", 0) or 0
        exp_norm = min(1.0, max(0.0, exp) / 30.0)
        under_norm = min(1.0, max(0.0, under) / 40.0)
        trend = d.get("trend", "—")
        trend_pct = d.get("trend_pct", 0) or 0
        # safety: rising/sideways good, falling bad (you'd catch a falling knife).
        # Gemeinsame Swing-Funktion – gleiche Recovery-Gewichtung wie im Score.
        trend_factor = scanner.recovery_factor(trend, trend_pct)
        active = d.get("active_ratio", 0) or 0        # how consistently it trades
        conf = 0.4 + 0.6 * min(1.0, active)           # reliability of the "normal" level
        vol = d.get("daily_vol", 0) or 0
        resale = min(1.0, vol / 50.0)                 # can you eventually sell it?
        resale = 0.3 + 0.7 * resale                   # never zero – you WILL exit someday
        return (0.6 * exp_norm + 0.4 * under_norm) * trend_factor * conf * resale

    def _toggle_hold_top(self, on):
        if getattr(self, "_last_hold", None):
            self._render_hold(self._last_hold)

    # Trichter-Reihenfolge = Reihenfolge der Tore in scanner.find_deals, damit
    # die Zeile von links nach rechts wirklich den Weg eines Kandidaten erzählt.
    # ENGLISCH als Schluessel, uebersetzt beim Zusammensetzen (t(label) in
    # _hold_diag_text) - dasselbe Muster wie _DEAL_DIAG_LABELS. Sitzung 16.
    # de_scan3: aus - ENGLISCHE SCHLUESSEL, uebersetzt beim ANZEIGEN
    # (_hold_diag_text -> t(label), Katalog bewacht von aa270). Sitzung 17: der Scanner hielt die Liste
    # wegen ihres Namens fuer Anzeigetext.
    _HOLD_DIAG_LABELS = [
        ("errors", "\u26a0 analysis error (please load again)"),
        ("no_history", "without price history"),
        ("no_build_cost", "build cost not computable"),
        ("vol_filtered", "below volume"),
        ("trade_score_low", "too hard to trade"),
        ("both_sides_low", "buy side rarely fills"),
        ("buy_reach_low", "buy side barely reached"),
        ("two_sided_low", "not two-sided"),
        ("vola_low", "too little movement"),
        ("dos_high", "stock too large (days of supply)"),
        ("competitors_high", "too much competition"),
        ("exit_thin", "exit too thin"),
        ("hist_too_short", "history too short"),
        ("below_min_margin", "not deep enough"),
        ("under_too_deep", "implausibly deep"),
        ("falling_skipped", "still falling"),
        ("contradictory", "contradictory (deep + rising)"),
        ("exp_nonpositive", "no profit after fees"),
        ("exp_pct_low", "expected profit % too small"),
        ("exp_isk_low", "ISK profit too small"),
        ("sell_fill_low", "sell fill too small"),
    ]
    # de_scan3: an

    def _hold_diag_text(self):
        """Swing-Diagnosezeile (Muster: Bauen-Tab/_last_build_diag). Beantwortet
        „warum so wenige Treffer?" mit echten Zahlen statt Vermutungen - und ist
        zugleich die Kalibriergrundlage für die Preset-Bänder: man sieht, an
        welchem Tor der Trichter tatsächlich zugeht."""
        d = getattr(self, "_last_hold_diag", None) or {}
        if not d:
            return ""

        def _n(x):
            return f"{int(x):,}".replace(",", "'")

        parts = []
        analyzed = d.get("analyzed", 0)
        if analyzed:
            src = []
            ca = d.get("cached_analyzed", 0)
            pool = d.get("cached_pool", 0)
            if ca:
                # Topf-Größe IMMER mit anzeigen: DAS ist die Kalibrier-Zahl.
                # "4'000 von 6'200 gecacht" = der Deckel schneidet ab; steht
                # dort "1'900 von 1'900", ist der Cache selbst die Grenze.
                if pool and pool > ca:
                    src.append(t("{a} of {b} cached (\u22647 d)").format(a=_n(ca), b=_n(pool)))
                else:
                    src.append(t("{n} from cache (\u22647 d, complete)").format(n=_n(ca)))
            if d.get("fetch_slots"):
                src.append(t("{n} newly loaded").format(n=_n(d['fetch_slots'])))
            parts.append(t("{n} analysed").format(n=_n(analyzed))
                         + (f" ({' \u00b7 '.join(src)})" if src else ""))
        for key, label in self._HOLD_DIAG_LABELS:
            if d.get(key):
                parts.append(f"{_n(d[key])} {t(label)}")
        if getattr(self, "_last_hold_mode", "") == "underbuild":
            parts.append(t("floor = best-case producer (ME 10 \u00b7 T2 rigs \u00b7 "
                           "nullsec \u00b7 own reactions) \u2013 not your own build cost"))
        if d.get("fetch_stopped"):
            parts.append(t("\u26a0 ESI limit reached \u2013 missing histories are loaded "
                           "in the background, run \u201eLoad deals\u201c again shortly"))
        elif d.get("fetch_paused"):
            parts.append(t("reloading paused: the cache pool exceeds the analysis cap "
                           "({cap}) \u2013 new fetches would add no candidates. Preset "
                           "switches now run purely from the cache").format(
                cap=_n(d.get('cached_cap', 0))))
        elif d.get("fetch_slots"):
            parts.append(t("newly loaded histories come free with the next scan"))
        return (" · ".join(parts) + ". ") if parts else ""

    def _rerender_hold(self):
        _d = getattr(self, "_hold_last", None)
        if _d is not None:
            self._render_hold(_d)

    def _render_hold(self, deals):
        self._hold_last = deals
        self._last_hold = deals
        names = store.cached_names([d["type_id"] for d in deals])
        if "swing" in self._ladder_ctx:
            self._ladder_ctx["swing"]["deals"] = {d["type_id"]: d for d in deals}
            self._ladder_ctx["swing"]["added"].clear()
        # Top-15 = best accumulation targets by combined Swing quality
        highlight = getattr(self, "hold_top_btn", None) and self.hold_top_btn.isChecked()
        ranked = sorted(deals, key=self._swing_quality, reverse=True)
        top_ids = {d["type_id"] for d in ranked[:15]}
        if highlight:
            deals = ranked
        tint = QColor(theme.AMBER); tint.setAlpha(28)
        self.hold_status.setText(
            t("{n} hold candidates. ").format(n=len(deals)) + self._hold_diag_text() +
            t("Sortable by column click \u00b7 double-click = history \u00b7 right-click = "
              "open in game / shopping list."))
        self.hold_table.setSortingEnabled(False)
        self.hold_table.setRowCount(len(deals))
        green = QColor(theme.GREEN); red = QColor(theme.RED)
        for i, d in enumerate(deals):
            trend = d.get("trend", "—")
            trend_txt = {"falling": t("\u2193 falling"), "sideways": t("\u2192 sideways"),
                         "rising": t("\u2191 rising")}.get(trend, "\u2014")
            sf = d.get("sell_fill", 0)
            star = "★ " if (highlight and d["type_id"] in top_ids) else ""
            if d.get("dump_risk"):
                star += "\u26a0 "
            recov = d.get("recovery", 1.0)
            # grobe Haltedauer-Schätzung: nur für bereits steigende Items sinnvoll
            # (Rabatt ÷ aktuelles Anstiegstempo pro Tag). Sonst „—“.
            window_days = self.h_window.currentData() or 90
            tp = d.get("trend_pct", 0) or 0
            under = d.get("under_pct", 0) or 0
            _rd = d.get("recovery_days", 0) or 0
            if _rd > 0:
                # GEMESSEN aus vergleichbaren früheren Dips (S1) - deutlich
                # belastbarer als die Drift-Hochrechnung darunter.
                hold_txt = f"~{round(_rd)} T"; hold_val = float(_rd)
            elif tp > 0 and under > 0:
                days_est = min(999.0, under * window_days / tp)
                mark = "" if trend == "rising" else "?"   # schwacher Drift = unsicher
                hold_txt = f"~{round(days_est)} T{mark}"; hold_val = days_est
            else:
                hold_txt = "—"; hold_val = 9999.0
            cells = [
                (star + names.get(d["type_id"], f"#{d['type_id']}"), None),
                (isk(d["sell_min"], suffix=False), d["sell_min"]),
                (isk(d.get("target_sell", 0), suffix=False), d.get("target_sell", 0)),
                (f"{d['under_pct']:.1f} %", d["under_pct"]),
                (trend_txt, d.get("trend_pct", 0)),
                (isk(d.get("exp_profit", 0), suffix=False), d.get("exp_profit", 0)),
                (f"{d.get('exp_pct', 0):.1f} %", d.get("exp_pct", 0)),
                (f"{sf:.0f} %", sf),
                (f"{round(d['daily_vol']):,}".replace(",", "'"), d["daily_vol"]),
                (f"{recov*100:.0f}", recov),
                (hold_txt, hold_val),
            ]
            for j, (text, val) in enumerate(cells):
                it = NumericItem(text, val) if j >= 1 else QTableWidgetItem(text)
                if j == 0:
                    # Bauplan-Optik (Layout-Programm): Icon-Anker
                    # + fetter Name, wie Wagen/Verkaufsliste.
                    _f0 = it.font(); _f0.setBold(True); it.setFont(_f0)
                    _ic0 = self._table_icon(d["type_id"])
                    if _ic0:
                        it.setIcon(_ic0)
                if j >= 1:
                    it.setTextAlignment(Qt.AlignRight | Qt.AlignVCenter)
                if j == 4:
                    tc = {"falling": theme.RED, "sideways": theme.GREEN,
                          "rising": theme.AMBER}.get(trend, theme.MUTED)
                    it.setForeground(QColor(tc))
                if j in (5, 6):
                    it.setForeground(green if d.get("exp_profit", 0) > 0 else red)
                if j == 7:
                    # green when your sell order fills well, red when it just sits
                    it.setForeground(QColor(theme.GREEN if sf >= 50 else
                                            (theme.AMBER if sf >= 25 else theme.RED)))
                if j == 9:
                    it.setForeground(QColor(theme.GREEN if recov >= 0.85 else
                                            (theme.AMBER if recov >= 0.6 else theme.RED)))
                if j == 0 and d.get("dump_risk"):
                    it.setForeground(QColor(theme.AMBER))
                    it.setToolTip(
                        t("\u26a0 Suspected dump: the price drop came with MASSIVELY increased volume "
                          "(\u22652.5x median) - that smells like a real revaluation (patch/meta), not "
                          "a dip. The old price often does NOT come back then. The rating is "
                          "already strongly dampened."))
                if j == 2 and d.get("spike_distorted"):
                    it.setToolTip(
                        t("The window's normal price was distorted upwards by a short spike (user "
                          "case: outlier months ago, decay phase inside the window). The target "
                          "was secured to the yearly baseline (median of the full history) - the "
                          "expectation is honest accordingly."))
                if j == 10 and (d.get("recovery_days", 0) or 0) > 0:
                    _ed = d.get("exp_day", 0) or 0
                    it.setToolTip(
                        t("MEASURED from comparable earlier dips of this item "
                          "(not extrapolated).\n"
                          "Expected swing yield: {isk} ISK/day "
                          "(profit \u00f7 recovery time) - a shallow fast dip "
                          "thus beats the deep slow one.").format(
                            isk=f"{_ed:,.0f}".replace(",", "'")))
                if highlight and d["type_id"] in top_ids:
                    it.setBackground(tint)
                self.hold_table.setItem(i, j, it)
            self.hold_table.item(i, 0).setData(Qt.UserRole, d["type_id"])
        self._hold_top_ids = top_ids if highlight else None
        self.hold_table.setSortingEnabled(not highlight)
        self._autosize_once(self.hold_table, "hold")
        self._icon_prefetch_pending(self._rerender_hold)

    def _open_chart_for(self, tid, name=None):
        """Springt in den Kursverlauf-Tab und zeigt das Item – von überall nutzbar."""
        if not tid:
            return
        idx = self.mk_item.findData(tid)
        if idx < 0:
            self.mk_item.addItem(name or f"#{tid}", tid)
            idx = self.mk_item.findData(tid)
        self.mk_item.setCurrentIndex(idx)
        self.tabs.setCurrentWidget(self.market_tab)
        self._plot_history()

    def _hold_to_chart(self, row):
        item = self.hold_table.item(row, 0)
        if not item:
            return
        tid = item.data(Qt.UserRole)
        idx = self.mk_item.findData(tid)
        if idx < 0:
            self.mk_item.addItem(item.text(), tid)
            idx = self.mk_item.findData(tid)
        self.mk_item.setCurrentIndex(idx)
        self.tabs.setCurrentWidget(self.market_tab)
        self._plot_history()


    # ---- Swing Gold-Suche: best accumulation chances across under + drop -----
    _SWING_GOLD_PRESETS = {
        "under": {"min_margin": 10, "min_daily_vol": 5, "avoid_falling": True,
                  "max_dos": 90, "min_hist_days": 20, "max_under_pct": 60,
                  "price_min": 0, "price_max": 0, "max_items": 400},
        "drop":  {"min_margin": 15, "min_daily_vol": 10, "max_dos": 40,
                  "max_under_pct": 70, "price_min": 0, "price_max": 0,
                  "max_items": 400},
    }
    _SWING_GOLD_WINDOW = {"under": 90, "drop": 30}

    def open_swing_gold(self):
        if not store.get_snapshot():
            QMessageBox.information(self, t("Gold search"), t("Please run \u201eMarket scan\u201c first."))
            return
        self._gold_knopf(False, swing=True)
        self.hold_status.setText(t("Gold search running …"))
        region = store.get_scan_region()
        self._sync_fees_to_hub(region)
        settings = self.settings

        def job(progress=None, should_cancel=None):
            out = {}
            modes = ["under", "drop"]
            for k, mode in enumerate(modes):
                if should_cancel and should_cancel():
                    return None
                filt = dict(self._SWING_GOLD_PRESETS[mode])
                days = self._SWING_GOLD_WINDOW[mode]
                res = scanner.find_deals(store.get_snapshot(), settings, days, mode,
                                         filt, region=region, should_cancel=should_cancel)
                out[mode] = res
                if progress:
                    progress(k + 1, len(modes))
            if should_cancel and should_cancel():
                return None
            names = esi.resolve_names(
                [d["type_id"] for r in out.values() for d in r])
            return {"by_mode": out, "names": names}

        w = Worker(job, with_progress=True, with_cancel=True)
        # Lambda-Parameter NICHT `t` nennen - das ueberdeckt den Uebersetzer.
        w.progress.connect(lambda d, tot: self.hold_status.setText(
            t("Gold search \u2026 mode {d}/{n}").format(d=d, n=tot)))

        def done(res):
            self._gold_knopf(True, swing=True)
            if not res:
                self.hold_status.setText(t("Gold search cancelled."))
                return
            self.hold_status.setText(t("Gold search done."))
            self._swing_gold_by_mode = res["by_mode"]
            self._swing_gold_names = res["names"]
            rows = self._build_swing_gold_list(res["by_mode"])
            self._show_swing_gold_dialog(rows, res["names"])

        def fail(msg):
            self._gold_knopf(True, swing=True)
            self.hold_status.setText(t("Gold search error: ") + msg)
        self._run(w, done, fail_cb=fail, label=t("Gold search …"))

    def _build_swing_gold_list(self, by_mode, capital=0):
        """Merge under + drop into the best ACCUMULATION opportunities. Ranked by
        discount depth × expected recovery × safety × resale-ability. No turnover
        weighting – you hold for weeks. Items strong in BOTH modes rank highest."""
        agg = {}
        label = {"under": t("Below Ø"), "drop": t("Price crash")}
        for mode, deals in by_mode.items():
            for d in deals:
                tid = d["type_id"]
                a = agg.setdefault(tid, {
                    "type_id": tid, "modes": set(), "discount": 0.0, "exp": 0.0,
                    "sell_min": d.get("sell_min", 0), "target_sell": d.get("target_sell", 0),
                    "trend": d.get("trend", "—"), "trend_pct": d.get("trend_pct", 0),
                    "daily_vol": d.get("daily_vol", 0),
                    "active_ratio": d.get("active_ratio", 0)})
                a["modes"].add(label[mode])
                a["discount"] = max(a["discount"], d.get("under_pct", 0) or 0)
                a["exp"] = max(a["exp"], d.get("exp_pct", 0) or 0)
                if d.get("target_sell"):
                    a["target_sell"] = d["target_sell"]
                if d.get("trend") and d["trend"] != "—":
                    a["trend"] = d["trend"]; a["trend_pct"] = d.get("trend_pct", 0)
        rows = []
        for a in agg.values():
            discount = a["discount"]
            # drop-only items have no reversion target → estimate recovery net of
            # fees from the crash depth
            exp_eff = a["exp"] if a["exp"] > 0 else max(0.0, discount - 8.0)
            # GATE: real recovery, real discount
            if exp_eff < 3.0 or discount < 8.0:
                continue
            # Kapital-Fit (optional): Märkte ausblenden, die zu dünn sind, um dein
            # Kapital über einen Halte-Horizont aufzunehmen. Sanfter als Daytrade
            # (5 % statt 20 %), weil du beim Swing über Wochen einsammelst.
            if capital:
                flow = (a.get("daily_vol", 0) or 0) * (a.get("sell_min", 0) or 0)
                if flow < capital * 0.05:
                    continue
            # kein harter falling-Ausschluss mehr: frisch gecrashte „Preis-Crash“-
            # Items sind über das Fenster meist fallend – das ist ja der Zweck. Der
            # Recovery-Faktor wertet steile Weiter-Stürze ab statt sie zu verwerfen.
            exp_norm = min(1.0, exp_eff / 30.0)
            disc_norm = min(1.0, discount / 40.0)
            trend_factor = scanner.recovery_factor(a["trend"], a.get("trend_pct", 0) or 0)
            conf = 0.4 + 0.6 * min(1.0, a["active_ratio"])
            resale = 0.3 + 0.7 * min(1.0, (a["daily_vol"] or 0) / 50.0)
            n_modes = len(a["modes"])
            multi = 1.0 + 0.5 * (n_modes - 1)      # strong in both modes = bonus
            a["exp_eff"] = exp_eff
            a["gold"] = (0.6 * exp_norm + 0.4 * disc_norm) * trend_factor * \
                conf * resale * multi * 100.0
            rows.append(a)
        rows.sort(key=lambda x: x["gold"], reverse=True)
        return rows

    def _fill_swing_gold_table(self, tbl, rows, names):
        # Sortierpause waehrend des Fuellens - siehe _fill_gold_table.
        tbl.setSortingEnabled(False)
        tbl.setRowCount(len(rows))
        gold = QColor(theme.AMBER); green = QColor(theme.GREEN); cyan = QColor(theme.CYAN)
        for i, a in enumerate(rows):
            # Die Raenge sind ANZEIGETEXT, kein Schluessel - sie landen
            # direkt in der Zelle. "Silber" stand hier bis Sitzung 22
            # deutsch in der englischen Oberflaeche.
            if i < 5:
                rank = t("Gold")
            elif i < 15:
                rank = t("Silver")
            else:
                rank = t("Bronze")
            trend = a.get("trend", "—")
            trend_txt = {"falling": t("\u2193 falling"), "sideways": t("\u2192 sideways"),
                         "rising": t("\u2191 rising")}.get(trend, "\u2014")
            # Trend hat eine natuerliche Ordnung (faellt < seitwaerts < steigt).
            # Vorher stand hier fuer JEDE Zeile die 0 - die Spalte war damit
            # zwar anklickbar, sortierte aber nichts. Unbekannt ("—") liegt
            # zwischen fallend und seitwaerts, nicht am Rand.
            trend_rank = {"falling": 0, "sideways": 2,
                          "rising": 3}.get(trend, 1)
            nm = names.get(a["type_id"], f"#{a['type_id']}")
            cells = [
                (rank, i),
                (nm, None),
                (isk(a["sell_min"], suffix=False), a["sell_min"]),
                (" · ".join(sorted(a["modes"])), None),
                (f"{a['discount']:.1f} %", a["discount"]),
                (f"{a['exp_eff']:.1f} %", a["exp_eff"]),
                (trend_txt, trend_rank),
                (f"{a['gold']:.0f}", a["gold"]),
            ]
            for j, (text, val) in enumerate(cells):
                it = NumericItem(text, val) if val is not None else QTableWidgetItem(text)
                if j in (2, 4, 5, 7):
                    it.setTextAlignment(Qt.AlignRight | Qt.AlignVCenter)
                if j == 0:
                    it.setForeground(gold if i < 5 else (cyan if i < 15 else green))
                if j == 5:
                    it.setForeground(green)
                if j == 3:
                    it.setForeground(cyan)
                tbl.setItem(i, j, it)
            tbl.item(i, 1).setData(Qt.UserRole, a["type_id"])
        # Pfeil ZUERST setzen, DANN einschalten - siehe _fill_gold_table.
        tbl.horizontalHeader().setSortIndicator(0, Qt.AscendingOrder)
        tbl.setSortingEnabled(True)

    def _show_swing_gold_dialog(self, rows, names):
        dlg = MinimizableDialog(self)
        dlg.setWindowTitle(t("\u2728 Swing gold search \u2013 best items to collect"))
        dlg.setMinimumSize(920, 620)
        v = QVBoxLayout(dlg); v.setContentsMargins(18, 14, 18, 14); v.setSpacing(10)
        intro = QLabel(
            t(
                "Merged from „below Ø“ and „price crash“. Rated by "
                  "discount depth × expected recovery profit × safety × "
                  "resaleability."))
        intro.setWordWrap(True); intro.setObjectName("Muted")
        v.addWidget(intro)

        caprow = QHBoxLayout()
        caprow.addWidget(QLabel(t("Capital you want to use:")))
        cap_spin = IskMillionSpin()
        cap_spin.setRange(0, 100_000_000)
        cap_spin.setSingleStep(100)
        cap_spin.setValue(0)
        cap_spin.setMinimumWidth(120)
        cap_spin.setToolTip(t("Optional: how much ISK you want to collect here. Hides markets too thin "
                              "to absorb your capital over a holding horizon (you would buy the price "
                              "up yourself otherwise). 0 = no filter."))
        caprow.addWidget(cap_spin)
        caprow.addStretch()
        v.addLayout(caprow)

        tbl = QTableWidget(0, 8)
        tbl.setHorizontalHeaderLabels(
            [t("Rank"), t("Item"), t("Buy price"), t("Found in"), t("Discount %"),
             t("Exp. profit %"), t("Trend"), t("Gold score")])
        tbl.verticalHeader().setVisible(False)
        tbl.setEditTriggers(QTableWidget.NoEditTriggers)
        tbl.setSelectionBehavior(QTableWidget.SelectRows)
        tbl.horizontalHeader().setSectionResizeMode(1, QHeaderView.Stretch)
        self._fill_swing_gold_table(tbl, rows, names)

        def _swing_gold_refilter():
            cap = cap_spin.value() * 1_000_000
            rows2 = self._build_swing_gold_list(getattr(self, "_swing_gold_by_mode", {}),
                                                capital=cap)
            self._fill_swing_gold_table(tbl, rows2,
                                        getattr(self, "_swing_gold_names", names))
            if cap:
                self.statusBar().showMessage(t(
                    "Swing gold filtered to markets that can absorb ~{cap} ({n} hits)."
                ).format(cap=isk(cap), n=tbl.rowCount()))
        cap_spin.valueChanged.connect(lambda _=0: _swing_gold_refilter())
        v.addWidget(tbl, 1)

        import pyqtgraph as pg
        # KEIN HINWEISTEXT (Nutzer-Wunsch Sitzung 12): dass ein Klick
        # den Kursverlauf zeigt, merkt man beim ersten Klick - dafuer
        # braucht es keine Dauerzeile unter dem Diagramm.
        chart_lbl = QLabel("")
        chart_lbl.setObjectName("Muted"); v.addWidget(chart_lbl)
        chart = pg.PlotWidget(); chart.setBackground(theme.PANEL2)
        chart.setMaximumHeight(190); chart.showGrid(x=True, y=True, alpha=0.15)
        chart.getAxis("left").setTextPen(theme.MUTED)
        chart.getAxis("bottom").setTextPen(theme.MUTED)
        v.addWidget(chart)
        _region = store.get_scan_region()

        def show_hist(row):
            it = tbl.item(row, 1)
            if not it:
                return
            tid = it.data(Qt.UserRole)
            try:
                hist = scanner.history_cached(tid, _region)
            except Exception:
                hist = []
            chart.clear()
            if not hist:
                chart_lbl.setText(t("{name} \u2013 no history in the cache.").format(name=it.text()))
                return
            ys = [r["average"] for r in hist if r.get("average")]
            xs = list(range(len(ys)))
            if ys:
                chart.plot(xs, ys, pen=pg.mkPen(theme.CYAN, width=2))
            chart_lbl.setText(t("Price history: {name}").format(name=it.text()))
        tbl.cellClicked.connect(lambda r, c: show_hist(r))

        def to_full_chart(row, _c):
            it = tbl.item(row, 1)
            if not it:
                return
            tid = it.data(Qt.UserRole)
            idx = self.mk_item.findData(tid)
            if idx < 0:
                self.mk_item.addItem(it.text(), tid)
                idx = self.mk_item.findData(tid)
            self.mk_item.setCurrentIndex(idx)
            self._go_tab("market")
            dlg.raise_()
        tbl.cellDoubleClicked.connect(to_full_chart)

        tbl.setContextMenuPolicy(Qt.CustomContextMenu)

        def menu(pos):
            it = tbl.itemAt(pos)
            if not it:
                return
            cell = tbl.item(it.row(), 1)
            tid = cell.data(Qt.UserRole); nm = cell.text()
            m = kontext_menue(tbl)
            a_open = m.addAction(t("Open market in game"))
            a_chart = m.addAction(t("Show history"))
            a_cart = m.addAction(t("→ Shopping list"))
            ch = m.exec(tbl.viewport().mapToGlobal(pos))
            if ch == a_open:
                self.open_ingame_market(tid)
            elif ch == a_chart:
                show_hist(it.row())
            elif ch == a_cart and tid not in self._cart_ids():
                store.add_shopping(tid, nm, 1, 0, 0)
                self._render_shopping()
                self.statusBar().showMessage(t("{name} added to the shopping list.").format(name=nm))
        kopier_menue(tbl, menu)

        row = QHBoxLayout()
        add_sel = _btn_icon(QPushButton(t("Selection → shopping list")), "cart")
        def add_selected():
            picked = {tbl.item(r.row(), 1).data(Qt.UserRole)
                      for r in tbl.selectionModel().selectedRows()}
            cart = self._cart_ids(); added = 0
            for tid in picked:
                if tid in cart:
                    continue
                store.add_shopping(tid, names.get(tid, ""), 1, 0, 0)
                added += 1
            self._render_shopping()
            self.statusBar().showMessage(
                t("{n} gold items added to the shopping list (quantity 1 \u2013 please adjust).").format(n=added))
        add_sel.clicked.connect(add_selected)
        row.addWidget(add_sel); row.addStretch()
        close = QPushButton(t("Close")); close.clicked.connect(dlg.close)
        close.setIcon(icons.icon("close"))
        row.addWidget(close)
        v.addLayout(row)
        self._swing_gold_dlg = dlg
        dlg.setModal(False); dlg.show(); dlg.raise_()

    def _hold_selected_rows(self):
        sm = self.hold_table.selectionModel()
        if not sm:
            return []
        return sorted({i.row() for i in sm.selectedIndexes()})

    def _owned_where(self, tid):
        """Wo liegt ein Item? Liste [(label, qty)] je Charakter/Container, aus den
        bereits geladenen Assets (_assets_struct) – keine neue ESI-Abfrage."""
        cid2name = {c["character_id"]: c["character_name"]
                    for c in store.list_characters()}
        out = []
        for cid, st in (getattr(self, "_assets_struct", {}) or {}).items():
            cname = cid2name.get(cid, f"Char {cid}")
            loose = (st.get("hangar") or {}).get(tid, 0)
            if loose:
                out.append((f"{cname} · Hangar", loose))
            for c in st.get("containers", []) or []:
                q = (c.get("contents") or {}).get(tid, 0)
                if q:
                    out.append((f"{cname} · {c.get('name') or t("Containers")}", q))
        out.sort(key=lambda x: -x[1])
        return out

    def _owned_and_selling(self):
        """(owned, selling): owned = {type_id: Bestandsmenge} aus dem Portfolio-Cache,
        selling = {type_id} mit offener Sell-Order. Beides aus bereits geladenen Daten –
        Portfolio laden bzw. „offene Orders prüfen“ macht die Warnung vollständig."""
        owned = {}
        for h in (getattr(self, "_holdings", None) or []):
            tid = getattr(h, "type_id", None)
            qty = getattr(h, "quantity", 0)
            if tid and qty:
                owned[int(tid)] = qty
        selling = set(getattr(self, "_sell_order_ids", None) or set())
        return owned, selling

    def _cart_conflict_filter(self, items, needed=None, qty_out=None,
                              plan_stock=None, show_all=False,
                              copy_mode=False, copy_qty=None):
        from ..sprache import t as _txt   # `t` ist hier lokal belegt
        """Warnt, wenn Items schon im Bestand oder in offenen Orders sind, bevor
        sie in die Einkaufsliste wandern. items = [(tid, name)];
        needed = optional {tid: benoetigte Menge} - damit zeigt der Dialog
        Benoetigt/Besitze/Fehlt mit Ampelfarben statt nur „ist schon da".
        qty_out = optionales dict; wird mit {tid: MENGE FUER DEN WAGEN}
        gefuellt. Ohne das legt der Aufrufer die volle Plan-Menge in den
        Wagen, obwohl der Dialog die Fehlmenge anzeigt - genau der vom
        Nutzer gemeldete Fehler ("so kaufe ich viel zu viel ein").
        Rueckgabe: die tatsaechlich hinzuzufuegende Liste (kann leer sein)."""
        # "BUY DATACORES/DECRYPTORS" AUS HEISST AUS (Nutzer-Befund, Sitzung
        # 20): "wenn ich keine Datacores kaufen will, dann will ich keine
        # kaufen, Punkt." Die beiden Haken wirkten nur auf den Weg, der die
        # Invention-Mengen NACHTRAEGLICH anhaengt (_plan_to_cart). Der
        # Materialien-Reiter listet Datacores und Decryptoren aber als ganz
        # normale Materialzeilen - ueber "Einkaufsliste erstellen" landeten
        # sie trotzdem im Wagen und im Multibuy.
        # HIER ist die richtige Stelle: beide Wege gehen durch diesen Filter.
        _inv_aus = set()
        if not bool(self.settings.get("bau_buy_datacores", True)):
            for _i in (getattr(self, "_bd_invention_needs", None) or {}).values():
                for _d, _q in (_i.get("datacores") or []):
                    _inv_aus.add(int(_d))
        if not bool(self.settings.get("bau_buy_decryptors", True)):
            for _i in (getattr(self, "_bd_invention_needs", None) or {}).values():
                if _i.get("decryptor_id"):
                    _inv_aus.add(int(_i["decryptor_id"]))
        if _inv_aus:
            items = [(t, n) for t, n in items if int(t) not in _inv_aus]
        owned, selling = self._owned_and_selling()
        buying = set(getattr(self, "_buy_order_ids", None) or set())
        where_by_tid = {int(t): self._owned_where(int(t)) for t, _n in items}
        rows = self._cart_conflict_rows(items, needed, owned, where_by_tid,
                                        selling, buying, show_all=show_all,
                                        scope_stock=plan_stock)
        if copy_qty:
            # IM KOPIER-MODUS GELTEN DIE ZAHLEN DES PLANS - fuer die ANZEIGE
            # genauso wie fuer die Kopie. Vorher rechnete der Dialog Kopfzeile
            # und Spalten weiter mit SEINER Bestandslogik: er meldete "27 von
            # 38 Positionen fehlen dir", waehrend der Plan darunter "15 zu
            # kaufen, 12 werden gebaut" sagte und auch 15 kopierte. Angezeigte
            # und kopierte Zahl kamen also aus zwei Rechnungen (Arbeitsregel
            # 10). Der Plan ist hier massgeblich: er weiss, was gebaut statt
            # gekauft wird - das kann diese Funktion gar nicht wissen.
            for _r in rows:
                _pq = copy_qty.get(_r["tid"])
                if not _pq:
                    continue
                _r["need"] = int(_pq.get("need", 0) or 0)
                _r["missing"] = int(_pq.get("missing", 0) or 0)
                _r["vollkauf"] = int(_pq.get("vollkauf", 0) or 0)
                # "own" bleibt UNANGETASTET: das ist der ECHTE Bestand aus dem
                # Asset-Abruf. Ihn aus need-missing abzuleiten war eine
                # REGRESSION: bei Gebautem ist missing=0 -> "own = need"
                # (behaupteter Besitz), bei Gekauftem mit Bestand ist
                # missing=need -> "own = 0" (Tritanium: 21 Mio. weg). Der Plan
                # ist nur fuer MENGEN massgeblich (need/missing), nicht fuer
                # den Besitz - den kennt allein der Asset-Abruf.
                # Ampel im Kopier-Modus aus dem PLAN (s. _copy_mode_status):
                # missing=0 heisst "nichts einkaufen" - dann sagt die Zeile
                # den GRUND (gebaut / Plan deckt's), statt mit "es fehlen X"
                # eine Fehlmenge zu behaupten, die der Kopier-Knopf dann
                # folgerichtig NICHT kopiert (Nutzer-Vorfall Cerberus).
                _r["status"], _r["status_txt"] = self._copy_mode_status(
                    _r["missing"], _pq.get("built", 0), _r["need"], _r["own"])
                # AUCH HIER NUR DIE FEHLMENGE - siehe oben. Beide Stellen
                # muessen dasselbe sagen, sonst haengt es vom Weg ab, wie
                # viel im Wagen landet.
                _r["cart_qty"] = _r["missing"]
        if not rows:
            return items
        from PySide6.QtWidgets import (QVBoxLayout, QHBoxLayout, QPushButton,
                                       QLabel, QTreeWidget, QTreeWidgetItem,
                                       QHeaderView)
        cids = {r["tid"] for r in rows}
        # FEHLENDE NAMEN NACHLADEN (Nutzer, Sitzung 9: "hab hier noch eine
        # Zahl anstelle eines Namens gefunden" - im Dialog stand "#16650").
        # Ursache: der Namens-Cache kennt manche type_ids nicht (frisch
        # eingefuehrte oder unpublished Items). esi.resolve_names holt sie
        # nach UND schreibt sie in den Cache, inkl. Einzel-Fallback ueber
        # /universe/types/. Schlaegt das fehl, bleibt die Nummer stehen -
        # besser eine ehrliche Nummer als ein erfundener Name.
        _fehl9 = sorted({int(r["tid"]) for r in rows
                         if str(r.get("name") or "").startswith("#")}
                        | {int(_t) for _t, _n in items
                           if str(_n or "").startswith("#")})
        if _fehl9:
            try:
                _nach9 = esi.resolve_names(_fehl9) or {}
            except Exception:
                _nach9 = {}
            if _nach9:
                for _r9 in rows:
                    _nm9 = _nach9.get(int(_r9["tid"]))
                    if _nm9 and str(_r9.get("name") or "").startswith("#"):
                        _r9["name"] = _nm9
                items = [(_t, _nach9.get(int(_t), _n)
                          if str(_n or "").startswith("#") else _n)
                         for _t, _n in items]
        non_conflict = [(t, n) for t, n in items if int(t) not in cids]
        dlg = MinimizableDialog(self._tool_parent())
        dlg.setWindowTitle(_txt("Already on hand \u2013 what do you have where?"))
        dlg.setMinimumWidth(820); dlg.resize(900, 620)
        v = QVBoxLayout(dlg); v.setContentsMargins(16, 14, 16, 14); v.setSpacing(9)
        _n_cov = sum(1 for r in rows if r["status"] == "covered")
        _n_part = sum(1 for r in rows if r["status"] == "partial")
        # Kopfzahl: im KOPIER-MODUS zaehlt die PLAN-Fehlmenge (alles andere
        # ist per Definition nicht einzukaufen - gebaut oder gedeckt). Ohne
        # copy_qty wie bisher: fehlend oder gar kein Besitz.
        if copy_qty:
            _n_miss = sum(1 for _r in rows if (_r.get("missing") or 0) > 0)
        else:
            # GEBAUTES ZAEHLT NICHT ALS FEHLEND (Sitzung 20) - sonst sagt der
            # Kopf "dir fehlen 9 von 9", waehrend der Materialien-Reiter
            # "0 zu kaufen" meldet. Dieselbe Menge, zwei Aussagen.
            _baut_kopf = set(getattr(self, "_bd_plan_builds", None) or ())
            _n_miss = sum(1 for _r in rows
                          if int(_r["tid"]) not in _baut_kopf
                          and ((_r.get("missing") or 0) > 0
                               or _r.get("own", 0) <= 0))
        # NUR NOCH DIE ZAHL, KEINE BEDIENUNGSANLEITUNG (Nutzer: "das ist alles
        # selbsterklaerend und ueberladet nur das Layout"). Haken und Farben
        # erklaeren sich beim Hinsehen; die Legende darunter bleibt.
        head = QLabel(
            ("<b style='font-size:15px;'>"
             + (_txt("you are missing {m} of {n} positions").format(
                 m=_n_miss, n=len(rows)) if show_all
                else _txt("you already have {n} item(s)").format(n=len(rows)))
             + "</b>"))
        head.setWordWrap(True); v.addWidget(head)
        legend = QLabel(
            f"<span style='color:{theme.GREEN};'>\u25cf "
            + _txt("covered") + "</span> &nbsp; "
            + f"<span style='color:{theme.AMBER};'>\u25cf "
            + _txt("partly") + "</span> &nbsp; "
            + f"<span style='color:{theme.RED};'>\u25cf "
            + _txt("missing entirely") + "</span>"
            + (" &nbsp;\u00b7&nbsp; "
               + _txt("{c} covered, {p} partly").format(c=_n_cov, p=_n_part)
               if (_n_cov or _n_part) else ""))
        legend.setStyleSheet("font-size:11px;"); v.addWidget(legend)

        tree = QTreeWidget()
        kopier_menue(tree)                    # Rechtsklick -> Copy
        tree.setColumnCount(7)
        tree.setIconSize(QSize(22, 22))   # gleiche Groesse wie Material-/BP-Tab
        tree.setHeaderLabels([_txt("Item / character"), _txt("Required"), _txt("Owned"),
                              _txt("at build location"), _txt("Missing"),
                              _txt("To cart"), _txt("Status")])
        tree.headerItem().setToolTip(2,
            _txt("What you own IN TOTAL \u2013 per portfolio, at ANY location."))
        tree.headerItem().setToolTip(3,
            _txt("Of that, at the linked BUILD structures. Only this quantity is deducted "
                 "from the demand by the build plan; everything else you have to haul "
                 "there first (or set the stock scope to \u201e Everywhere\u201c)."))
        tree.headerItem().setToolTip(4,
            _txt("This quantity goes into the shopping list when ticked \u2013 the SHORTFALL, "
                 "not the full demand.\n"
                 "For items already covered (Missing 0) it is the full quantity: ticking "
                 "there explicitly means \u201ebuy anyway\u201c."))
        tree.setAlternatingRowColors(True)
        tree.setRootIsDecorated(True)
        tree.header().setSectionResizeMode(0, QHeaderView.Stretch)
        v.addWidget(tree, 1)

        _cols = {"covered": theme.GREEN, "partial": theme.AMBER,
                 "none": theme.RED, "unknown": theme.MUTED}

        def _num(x):
            return "\u2013" if x is None else f"{int(x):,}".replace(",", "'")
        # Nach Charakter gruppieren; Items ohne bekannten Ort (z.B. nur eine
        # offene Order) kommen in eine eigene, klar benannte Gruppe.
        groups = {}
        for r in rows:
            groups.setdefault(r["main_char"], []).append(r)
        checks = []
        for char in sorted(groups, key=lambda c: (c is None, str(c))):
            grows = groups[char]
            _gc = sum(1 for r in grows if r["status"] == "covered")
            _gp = sum(1 for r in grows if r["status"] == "partial")
            _gn = sum(1 for r in grows if r["status"] == "none")
            _bits = []
            if _gc:
                _bits.append(_txt("{n} covered").format(n=_gc))
            if _gp:
                _bits.append(_txt("{n} partial").format(n=_gp))
            if _gn:
                _bits.append(_txt("{n} missing").format(n=_gn))
            gi = QTreeWidgetItem(tree, [
                (f"{char}" if char else
                 _txt("\u26a0 Not held by any character (only in open orders)")),
                "", "", "", "", "",
                f"{len(grows)} Items \u00b7 " + " \u00b7 ".join(_bits)])
            _f = gi.font(0); _f.setBold(True); gi.setFont(0, _f)
            gi.setForeground(0, QColor(theme.CYAN if char else theme.AMBER))
            gi.setForeground(6, QColor(theme.MUTED))
            gi.setFlags(gi.flags() & ~Qt.ItemIsUserCheckable)
            for r in grows:
                it = QTreeWidgetItem(gi, [
                    r["name"], _num(r["need"]), _num(r["own"]),
                    _num((plan_stock or {}).get(r["tid"], 0)),
                    _num(r["missing"]), _num(r.get("cart_qty")),
                    r["status_txt"]
                    + (" \u00b7 " + " \u00b7 ".join(r["flags"]) if r["flags"] else "")])
                # Item-Bild wie in den anderen Listen (Nutzer: "sieht
                # huebscher aus") - derselbe Helfer, also auch derselbe Cache.
                _ric = self._table_icon(r["tid"])
                if _ric:
                    it.setIcon(0, _ric)
                it.setFlags(it.flags() | Qt.ItemIsUserCheckable)
                # In der Gesamtliste ist vorangekreuzt, was FEHLT - das ist
                # die Einkaufsliste. Gedeckte Positionen bleiben leer.
                # WAS DER PLAN SELBST BAUT, WIRD NICHT VORANGEKREUZT
                # (Nutzer-Befund, Sitzung 20: der Materialien-Reiter meldete
                # "0 zu kaufen - 7 werden gebaut", derselbe Plan bot im
                # Dialog aber genau diese sieben Komponenten zum Kauf an).
                # `missing` heisst nur "liegt nicht am Bau-Ort" - bei einem
                # Item, das der Plan baut, ist das kein Einkauf, sondern der
                # Bau-Auftrag. Es zu kaufen waere doppelt bezahlt: die
                # Materialien dafuer stehen bereits auf der Liste.
                # Ankreuzen kann man es weiterhin von Hand - der Haken ist
                # eine bewusste Handlung ("trotzdem kaufen").
                _baut = set(getattr(self, "_bd_plan_builds", None) or ())
                _wird_gebaut = int(r["tid"]) in _baut
                _pre = (show_all and not _wird_gebaut
                        and ((r.get("missing") or 0) > 0
                             or (r.get("own") or 0) <= 0))
                it.setCheckState(0, Qt.Checked if _pre else Qt.Unchecked)
                if _wird_gebaut:
                    it.setText(6, _txt("this plan builds it"))
                    it.setToolTip(6, _txt(
                        "The build plan makes this item itself - the material "
                        "for it is already on the list. Buying it as well would "
                        "pay for it twice. Tick it only if you deliberately want "
                        "to buy it instead."))
                _fw = it.font(5); _fw.setBold(True); it.setFont(5, _fw)
                it.setForeground(5, QColor(theme.CYAN))
                # "am Bau-Ort = 0" ist die wichtigste Zahl der Zeile: das
                # Material liegt zwar irgendwo, aber NICHT dort, wo gebaut
                # wird - du musst es also hinkarren. Deshalb amber und fett
                # statt unauffaellig grau (Nutzer-Wunsch).
                _pq = (plan_stock or {}).get(r["tid"], 0)
                if _pq:
                    it.setForeground(3, QColor(theme.GREEN))
                    # TEILWEISE RESERVIERT WAR BISHER UNSICHTBAR (Nutzer,
                    # Sitzung 20: "ich hab alles gekauft und vor Ort gebracht,
                    # trotzdem soll ich Unmengen nachkaufen"). Steht die
                    # Spalte auf 0, sagt die Zeile seit Sitzung 9 "reserviert".
                    # Bleibt aber ein REST uebrig, stand dort nur die nackte
                    # Zahl - dass andere Plaene den groesseren Teil halten,
                    # war nirgends zu sehen. Genau die Sorte stille Kuerzung,
                    # die Regel 6 verbietet.
                    _resv_t = int((getattr(self, "_bd_reserved_applied", None)
                                   or {}).get(r["tid"], 0) or 0)
                    if _resv_t > 0:
                        _pl_t = ", ".join(
                            getattr(self, "_bd_reserved_plans", None) or [])
                        it.setText(3, _num(_pq) + "  \u00b7 "
                                   + _txt("{n} reserved").format(
                                       n=f"{_resv_t:,}".replace(",", "'")))
                        it.setForeground(3, QColor(theme.AMBER))
                        it.setToolTip(3, (
                            _txt("{n} units are on site as well, but reserved for "
                                 "other build plans").format(
                                     n=f"{_resv_t:,}".replace(",", "'"))
                            + (f" ({_pl_t})" if _pl_t else "")
                            + _txt(". Release the reservation on the other plan's "
                                   "card or finish that plan, then this plan can "
                                   "use them.")))
                else:
                    # WARUM 0? ZWEI GRUENDE, EIN ETIKETT (Nutzer-Befund
                    # Sitzung 9: "Das Tool behauptet, gewisse Materialien
                    # waeren nicht vor Ort, dabei sind sie es"). Der Wert
                    # dieser Spalte ist der PLANBARE Bestand - und der wird
                    # an einer Stelle um die Reservierungen ANDERER Plaene
                    # gekuerzt. Ein reservierter Rohstoff liegt also sehr
                    # wohl vor Ort, ist hier aber 0. Das wird jetzt
                    # unterschieden, statt beides "nicht vor Ort" zu nennen.
                    _resv = int((getattr(self, "_bd_reserved_applied", None)
                                 or {}).get(r["tid"], 0) or 0)
                    if _resv > 0:
                        _pl9 = ", ".join(
                            getattr(self, "_bd_reserved_plans", None) or [])
                        # "0 - reserved" las der Nutzer als "nichts reserviert"
                        # (01.10.2026) - der Satz sagt jetzt, WER es haelt.
                        it.setText(3, "0  \u2013 " + _txt("reserved by other plans"))
                        it.setToolTip(3, (
                            _txt("It IS there on site, but {n} units are reserved "
                              "for other build plans").format(
                                n=f"{_resv:,}".replace(",", "'"))
                            + (f" ({_pl9})" if _pl9 else "")
                            + _txt(". This plan must therefore not schedule "
                                "them. Release the reservation on the other "
                                "plan's card ( button) or finish "
                                "that plan \u2013 then it is freed "
                                "automatically.")))
                    else:
                        it.setText(3, _txt("0  \u2013 not on site"))
                        it.setToolTip(3, _txt("NOTHING of it lies at the build location. You own it, but elsewhere \u2013 "
                                              "the build plan cannot deduct it, you have to bring it there (or set the "
                                              "stock scope to \u201e Everywhere\u201c)."))
                    it.setForeground(3, QColor(theme.AMBER))
                    _fb = it.font(3); _fb.setBold(True); it.setFont(3, _fb)
                for c in (1, 2, 3, 4, 5):
                    it.setTextAlignment(c, Qt.AlignRight | Qt.AlignVCenter)
                _col = QColor(_cols.get(r["status"], theme.MUTED))
                it.setForeground(4, _col); it.setForeground(6, _col)
                it.setForeground(2, QColor(theme.GREEN if r["own"] else theme.MUTED))
                _tip = [_txt("Required: ") + _num(r['need']),
                        _txt("Owned:  ") + _num(r['own']),
                        _txt("Missing:    ") + _num(r['missing'])]
                if len(r["by_char"]) > 1:
                    _tip.append("")
                    _tip.append(_txt("Stock spread across:"))
                    for _c, _q in sorted(r["by_char"].items(),
                                         key=lambda kv: -kv[1]):
                        _tip.append(f"  {_c}: " + _num(_q))
                it.setToolTip(0, "\n".join(_tip))
                # Liegt es bei MEHREREN Charakteren, die Aufteilung als
                # Unterzeilen zeigen - sonst waere die Gruppierung eine Luege.
                if len(r["by_char"]) > 1:
                    for _c, _q in sorted(r["by_char"].items(),
                                         key=lambda kv: -kv[1]):
                        _si = QTreeWidgetItem(it, [_txt("\u21b3 with {who}").format(who=_c), "",
                                                   _num(_q), "", "", "", ""])
                        _si.setFlags(_si.flags() & ~Qt.ItemIsUserCheckable)
                        for _c2 in range(7):
                            _si.setForeground(_c2, QColor(theme.MUTED))
                        _si.setTextAlignment(2, Qt.AlignRight | Qt.AlignVCenter)
                checks.append((it, r["tid"], r["name"], r.get("cart_qty")))
            gi.setExpanded(True)
        for _c in range(1, 7):
            tree.resizeColumnToContents(_c)
        if non_conflict:
            # Beim Namen nennen - "1 neue Items" liess den Nutzer raten, WAS
            # ueberhaupt in den Wagen wandert.
            _nn = ", ".join(str(n) for _t, n in non_conflict[:6])
            if len(non_conflict) > 6:
                _nn += f" \u2026 (+{len(non_conflict) - 6})"
            note = QLabel(_txt("\u2795 Into the cart without demand ({n}): ").format(
                n=len(non_conflict)) + _nn)
            note.setWordWrap(True)
            note.setStyleSheet(f"font-size:11px; color:{theme.GREEN};")
            v.addWidget(note)
        row = QHBoxLayout()
        selall = QPushButton(_txt("Tick all"))
        selall.setIcon(icons.icon("check"))
        selall.clicked.connect(
            lambda: [it.setCheckState(0, Qt.Checked)
                     for it, _t, _n, _q in checks])
        selnone = QPushButton(_txt("None"))
        selnone.setIcon(icons.icon("close"))
        selnone.clicked.connect(
            lambda: [it.setCheckState(0, Qt.Unchecked)
                     for it, _t, _n, _q in checks])
        selmiss = QPushButton(_txt("Tick only missing"))
        selmiss.setIcon(icons.icon("target"))
        selmiss.setToolTip(_txt("Ticks exactly those whose stock does NOT cover the demand (yellow + "
                                "red) - the usual case."))
        # Status \u00dcBER DIE type_id zuordnen, nicht \u00fcber die Position:
        # `checks` entsteht in GRUPPEN-Reihenfolge, `rows` in SORTIER-
        # Reihenfolge - ein zip() der beiden h\u00e4tte die Status vertauscht
        # und die falschen Zeilen angekreuzt.
        _stat_by_tid = {r["tid"]: r["status"] for r in rows}
        selmiss.clicked.connect(lambda: [
            it.setCheckState(0, Qt.Checked
                             if _stat_by_tid.get(_t) in ("partial", "none")
                             else Qt.Unchecked) for it, _t, _n, _q in checks])
        row.addWidget(selall); row.addWidget(selmiss); row.addWidget(selnone)
        row.addStretch()
        state = {"ok": False}
        if copy_mode:
            # KOPIER-MODUS (Bauplan): derselbe Dialog, andere Aktion. Der
            # Nutzer will die Liste NICHT in den globalen Einkaufswagen legen,
            # sondern als EVE-Multibuy in die Zwischenablage - einmal alles,
            # einmal nur die Fehlmenge. Den Dialog dafuer nachzubauen waere
            # eine zweite Wahrheit gewesen (er kann Icons, Aufklappen nach
            # Charakter und Ampelfarben laengst); getauscht wird nur die
            # Knopfleiste.
            _amber = ("QPushButton{background:rgba(242,162,60,0.14); "
                      f"color:{theme.AMBER}; border:1px solid rgba(242,162,60,0.55); "
                      "border-radius:7px; padding:7px 14px; font-weight:700;}"
                      "QPushButton:hover{background:rgba(242,162,60,0.28);}")
            selall.setVisible(False)
            selmiss.setVisible(False)
            selnone.setVisible(False)
            # Ergebnis-Label fuer die Kopier-Knoepfe - VOR _copy_rows
            # definiert (Closure greift darauf zu), eingehaengt weiter
            # unten in die Knopfzeile.
            _copy_note = QLabel("")
            _copy_note.setWordWrap(True)

            def _copy_rows(feld, was):
                # MENGEN AUS DEM PLAN, NICHT AUS DIESEM DIALOG. Der Dialog
                # rechnet sein eigenes `missing` aus dem GLOBALEN Bestand; der
                # Bauplan rechnet mit dem Bestand, den er selbst verplant hat.
                # Beim Nutzer kam so "Chromium 12'035" (Gesamtbedarf) statt
                # "6'770" (Fehlmenge) heraus - zwei Wahrheiten fuer dieselbe
                # Frage. Massgeblich ist der Plan, also `copy_qty`; ohne das
                # bleibt der bisherige Weg.
                _lines = []
                _n = 0
                _skipped = []
                # WAS DER PLAN SELBST BAUT, GEHOERT NICHT INS MULTIBUY
                # (Nutzer-Befund Sitzung 20, an seiner Appraisal belegt).
                # Der Materialien-Reiter meldete "0 zu kaufen - 7 werden
                # gebaut", dieser Knopf kopierte trotzdem 9 Zeilen - darunter
                # die sieben Komponenten, zusammen 1,7 Mrd ISK. Grund: fuer
                # ein Item, das nicht am Bau-Ort liegt, meldet die
                # Fehlbedarf-Rechnung die volle Menge, und "fehlt" wurde hier
                # mit "kaufen" gleichgesetzt.
                # DAS IST DIE TEURE RICHTUNG: die Materialien fuer diese
                # Komponenten stehen bereits in derselben Liste. Wer beides
                # kauft, zahlt zweimal - genau der kritische Fall, der schon
                # einmal Geld gekostet hat.
                _baut_kopie = set(getattr(self, "_bd_plan_builds", None) or ())
                _gebaut_raus = []
                for _r in rows:
                    if int(_r["tid"]) in _baut_kopie:
                        _gebaut_raus.append(_r.get("name") or f"#{_r['tid']}")
                        continue
                    # `rows` traegt im Kopier-Modus bereits die Plan-Zahlen
                    # (siehe oben) - also EINE Quelle fuer Anzeige und Kopie,
                    # statt hier nochmal separat nachzuschlagen.
                    _q = int(_r.get(feld) or 0)
                    if _q <= 0:
                        continue
                    _nm = (_r.get("name") or "").strip()
                    # Unaufgeloeste Namen ("#16642") kann EVE-Multibuy nicht
                    # lesen - sie landeten als roter Fehlerblock in der
                    # Appraisal. Lieber benennen als still mitschicken.
                    if not _nm or _nm.startswith("#"):
                        _skipped.append(_nm or f"#{_r['tid']}")
                        continue
                    # PUFFER wie im Einkaufswagen (Nutzer). Derselbe Helfer
                    # und dieselbe Einstellung `bau_buy_surplus`, die auch der
                    # Bauplan-Fuss und `_plan_to_cart` benutzen - sonst haetten
                    # wir wieder zwei Puffer-Rechnungen nebeneinander.
                    _lines.append(f"{_nm}\t{self._buy_surplus_qty(_q)}")
                    _n += 1
                if not _n:
                    # SICHTBAR IM DIALOG (Nutzer-Vorfall Cerberus: "wird
                    # nichts kopiert"). Der Flash-Tip erschien im
                    # HAUPTFENSTER - hinter diesem modalen Dialog sah man
                    # ihn schlicht nicht. Und den GRUND dazu: der Plan hat
                    # nichts zu kaufen; das ist Ergebnis, kein Defekt.
                    _copy_note.setStyleSheet(f"color:{theme.AMBER}; "
                                             f"font-size:13px;")
                    _copy_note.setText(_txt(
                        "Nothing copied \u2013 the plan has 0 {what} (everything is built "
                        "or covered from stock/jobs, see status per row).").format(what=was)
                        + (_txt(" {n} position(s) are made by the plan itself.").format(
                            n=len(_gebaut_raus)) if _gebaut_raus else ""))
                    self._flash_tip(_txt("No {what} to copy.").format(what=was),
                                    ms=self.FLASH_LESEN_MS)
                    return
                # KEINE "# Kategorie"-Zeilen: Multibuy und die Appraisal-Seiten
                # stolpern darueber (Nutzer-Screenshot: roter Block mit allen
                # Ueberschriften). Der Einkaufswagen schickt sie auch nicht.
                from PySide6.QtWidgets import QApplication as _QA
                _QA.clipboard().setText("\n".join(_lines))
                _copy_note.setStyleSheet(f"color:{theme.GREEN}; "
                                         f"font-size:13px;")
                _copy_note.setText(
                    _txt("{n} {what} copied \u2713").format(n=_n, what=was)
                    + (_txt(" \u2013 {n} skipped without a name").format(
                        n=len(_skipped)) if _skipped else "")
                    + (_txt(" \u2013 {n} left out, this plan builds them").format(
                        n=len(_gebaut_raus)) if _gebaut_raus else ""))
                self._flash_tip(
                    _txt("{n} {what} copied \u2713 \u2013 {k} without a resolved name "
                         "skipped ({names})").format(n=_n, what=was, k=len(_skipped),
                                                     names=", ".join(_skipped[:3]))
                    if _skipped else
                    _txt("{n} {what} copied \u2713 (EVE multibuy format)").format(n=_n, what=was))
            from PySide6.QtWidgets import QSpinBox as _QSB
            _pf_lbl = QLabel(_txt("Buffer:"))
            _pf_lbl.setObjectName("Muted")
            _pf = _QSB()
            _pf.setRange(0, 100)
            _pf.setSuffix(" %")
            _pf.setMaximumWidth(80)
            _pf.setValue(int(self.settings.get("bau_buy_surplus", 0) or 0))
            _pf.setToolTip(
                _txt("Safety margin on every copied quantity \u2013 e.g. 5 %, so a wrong purchase "
                     "or rounding loss does not immediately force a second shopping trip.\n"
                     "This is THE SAME buffer as below in the build plan and in the shopping "
                     "list (setting \u201ebau_buy_surplus\u201c) \u2013 changed here, it applies there too."))

            def _save_puffer(_v):
                self.settings["bau_buy_surplus"] = int(_v)
                config.save_settings(self.settings)
            _pf.valueChanged.connect(_save_puffer)
            # "Alle Materialien kopieren" ist ENTFERNT (Nutzer: "ich habe
            # mich anders entschieden, komplett entfernen") - direkt nach
            # dem Umbau auf die Fertigungsgrenzen-Semantik. Es bleibt EIN
            # Kopier-Knopf: die Fehlmengen-Liste ("genau so ist es
            # richtig"). Wer den Komplett-Einkauf ohne Bestand will:
            # "Assets abziehen" aus + Neu berechnen, dann ist die
            # Fehlmengen-Liste genau das. Das "vollkauf"-Feld in den
            # Dialog-rows bleibt harmlos liegen (eine Zeile Durchreichung),
            # falls die Entscheidung nochmal kippt.
            _b_miss = QPushButton(_txt("Copy missing materials"))
            _b_miss.setIcon(icons.icon("clipboard"))
            _b_miss.setStyleSheet(_amber)
            _b_miss.setToolTip(_txt("Only what the PLAN does not cover \u2013 the actual shopping list. If the "
                                    "top says \u201e0 to buy\u201c, there is nothing to copy here (built/covered does "
                                    "not count as missing)."))
            _b_miss.clicked.connect(
                lambda: _copy_rows("missing", _txt("missing item(s)")))
            _close = QPushButton(_txt("Close")); _close.clicked.connect(dlg.reject)
            _close.setIcon(icons.icon("close"))
            row.insertWidget(0, _b_miss)
            # Puffer direkt hinter den Kopier-Knopf, vor den Stretch.
            row.insertWidget(1, _pf_lbl)
            row.insertWidget(2, _pf)
            # Ergebnis-Zeile IM Dialog (Nutzer-Vorfall: der Flash-Tip im
            # Hauptfenster war hinterm modalen Dialog unsichtbar - "wird
            # nichts kopiert"). _copy_rows schreibt hierher.
            row.insertWidget(3, _copy_note)
            row.addWidget(_close)
        else:
            cancel = QPushButton(_txt("Cancel")); cancel.clicked.connect(dlg.reject)
            cancel.setIcon(icons.icon("close"))
            add = QPushButton(_txt("Add")); add.setObjectName("Primary")
            add.setIcon(icons.icon("plus"))
            add.clicked.connect(lambda: (state.update(ok=True), dlg.accept()))
            row.addWidget(cancel); row.addWidget(add)
        v.addLayout(row)
        dlg.exec()
        if not state["ok"]:
            return []
        picked = []
        for it, _t, _n, _q in checks:
            if it.checkState(0) != Qt.Checked:
                continue
            picked.append((_t, _n))
            if qty_out is not None and _q is not None:
                qty_out[_t] = int(_q)
        return non_conflict + picked

    def _hold_add_rows(self, rows):
        by_id = {d["type_id"]: d for d in (getattr(self, "_last_hold", None) or [])}
        cart = self._cart_ids()
        items = []
        for r in rows:
            cell = self.hold_table.item(r, 0)
            if not cell:
                continue
            tid = cell.data(Qt.UserRole)
            if tid is None or tid in cart:
                continue
            items.append((tid, store.item_name_rein(cell.text())))   # emm359: auch "⚠ "
        items = self._cart_conflict_filter(items)   # warnt bei Bestand/Sell-Order
        added = 0
        for tid, name in items:
            d = by_id.get(tid, {})
            # WICHTIG: hier NICHT mehr fest "1" für jedes Item - das ließ
            # unterschiedliche Mengen beim Multibuy-Kopieren komplett verschwinden
            # (jedes Item landete mit Menge 1 im Warenkorb, egal wie unterschiedlich
            # sie eigentlich sein sollten). _deal_default_qty gibt's schon (nutzt
            # Tagesvolumen/Konkurrenz) - hier wiederverwendet statt neu erfunden.
            qty = self._deal_default_qty(d) if d else 1
            store.add_shopping(tid, name, qty, d.get("sell_min", 0) or 0,
                               d.get("target_sell", 0) or 0, source="swing")
            added += 1
        if hasattr(self, "_render_shopping"):
            self._render_shopping()
        return added


    def _show_floor_breakdown(self, tid, name):
        from ..sprache import t as _txt   # `t` ist hier lokal belegt
        """Röntgenbild für den „Unter Baupreis"-Boden: die komplette
        Bau-vs.-Kauf-Entscheidungskette (industry.build_tree) mit EXAKT den
        Boden-Optionen des letzten Scans - damit Ausreißer wie der Zealot-
        Kanarienvogel oder die absurden T2-Munitions-Böden nicht mehr
        Rätselraten sind, sondern Zeile für Zeile ablesbar, WELCHER Posten
        den Boden treibt (Invention? ein einzelnes überteuertes Material?
        eine falsche Output-Menge?)."""
        if not industry.sde_ready():
            QMessageBox.information(self, _txt("Floor calculation"),
                                    _txt("Please run \u201eLoad recipes\u201c first."))
            return
        snapshot = store.get_snapshot()
        if not snapshot:
            QMessageBox.information(self, _txt("Floor calculation"),
                                    _txt("Please run \u201eMarket scan\u201c first."))
            return
        opts = dict(getattr(self, "_last_floor_opts", None)
                    or self._efficiency_floor_build_opts(self.settings))

        def job():
            recipes = industry.recipes_cached()
            if "rig_me_map" not in opts:      # Fallback: Extras wie im Scan
                _rig = (self._ME_RIG_PCT.get(2, 2.4)
                        * max(v for v, _l in self._SEC_LEVELS))
                opts["rig_me_map"] = {_pid: _rig for _pid in recipes.product_to_bp}
                _mod = 1.0 + 5 / 40.0 + 10 / 30.0
                opts["inv_skill_modifier"] = {
                    bp: _mod for bp in recipes.invention_for_bpc}
            price_map = {s["type_id"]: s["sell_min"]
                         for s in snapshot if s["sell_min"] > 0}
            tree = industry.build_tree(tid, price_map.get, recipes, opts)
            ids = set()

            def _collect(node):
                if not node:
                    return
                ids.add(node["type_id"])
                for c in node.get("components") or []:
                    ids.add(c["type_id"])
                    _collect(c.get("subtree"))
            _collect(tree)
            try:
                esi.resolve_names(ids)
            except Exception:
                pass
            return tree, store.cached_names(list(ids))

        def done(res):
            tree, names = res
            if not tree:
                QMessageBox.information(self, _txt("Floor calculation"),
                                        _txt("No build recipe found for this item."))
                return

            def _n(tid_):
                return names.get(tid_, f"#{tid_}")

            lines = []

            def _walk(node, indent):
                pad = "  " * indent
                lines.append(
                    pad + _txt("{name} \u00b7 output {q}/run \u00b7 floor/unit {v}").format(
                        name=_n(node['type_id']), q=f"{node['output_qty']:g}",
                        v=isk(node['per_unit'], suffix=False))
                    + (_txt(" \u00b7 of which invention {v}").format(
                           v=isk(node['invention_per_unit'], suffix=False))
                       if node.get("invention_per_unit") else ""))
                for c in node.get("components") or []:
                    dec = c.get("decision")
                    dtxt = {"buy": _txt("BUY"), "build": _txt("BUILD")}.get(dec, dec or "?")
                    alt = ""
                    if dec == "buy" and c.get("build_cost"):
                        alt = _txt("  (building would have cost {isk})").format(
                            isk=isk(c['build_cost'], suffix=False))
                    elif dec == "build" and c.get("buy_price"):
                        alt = _txt("  (market {isk})").format(
                            isk=isk(c['buy_price'], suffix=False))
                    lines.append(
                        f"{pad}  - {c['qty']:g}x {_n(c['type_id'])}: {dtxt} @ "
                        f"{isk(c.get('unit_cost') or 0, suffix=False)}{alt}")
                    if dec == "build" and c.get("subtree"):
                        _walk(c["subtree"], indent + 2)
            _walk(tree, 0)
            head = (_txt("FLOOR CALCULATION \u00b7 {name}\n").format(name=name)
                    + _txt("Best-case producer: ME {me} % \u00b7 T2 rigs x nullsec \u00b7 "
                           "invention skills V \u00b7 reaction only if cheaper than "
                           "buying\n").format(me=f"{opts.get('me', 0):.2f}")
                    + _txt("Material prices: current market snapshot (sell min)\n")
                    + "=" * 72 + "\n")
            from PySide6.QtWidgets import QDialog, QPlainTextEdit, QVBoxLayout as _V
            dlg = QDialog(self)
            dlg.setWindowTitle(t("Floor calculation \u00b7 {name}").format(name=name))
            dlg.resize(860, 600)
            txt = QPlainTextEdit(head + "\n".join(lines))
            txt.setReadOnly(True)
            txt.setStyleSheet("font-family:{theme.MONO}; font-size: 13px;")
            lay = _V(dlg)
            lay.addWidget(txt)
            dlg.show()

        def fail(msg):
            QMessageBox.warning(self, t("Floor calculation"), t("Error: ") + str(msg))
        self._run(Worker(job), done, fail_cb=fail, label=_txt("Calculating the floor …"))

    def _hold_menu(self, pos):
        item = self.hold_table.itemAt(pos)
        if not item:
            return
        row = item.row()
        cell = self.hold_table.item(row, 0)
        tid = cell.data(Qt.UserRole)
        name = cell.text()
        sel_rows = self._hold_selected_rows()
        if row not in sel_rows:          # Rechtsklick außerhalb der Auswahl = nur diese Zeile
            sel_rows = [row]
        menu = kontext_menue(self)
        a_floor = None
        if getattr(self, "_last_hold_mode", "") == "underbuild":
            a_floor = menu.addAction(icons.icon("search"), t("Show floor calculation"))
        a_chart = menu.addAction(t("Show history"))
        a_open = menu.addAction(t("Open market in game"))
        a_buy = menu.addAction(t("→ Shopping list"))
        a_batch = None
        if len(sel_rows) > 1:
            a_batch = menu.addAction(t("\u2192 selection into the cart ({n} items)").format(n=len(sel_rows)))
        chosen = menu.exec(self.hold_table.viewport().mapToGlobal(pos))
        if a_floor is not None and chosen == a_floor:
            self._show_floor_breakdown(
                tid, name.replace("★ ", "").replace("⚠ ", ""))
            return
        if chosen == a_chart:
            self._hold_to_chart(row)
        elif chosen == a_open:
            self.open_ingame_market(tid)
        elif chosen == a_buy:
            added = self._hold_add_rows([row])
            self.statusBar().showMessage(
                t("{name} added to the shopping cart.").format(
                    name=name.replace('\u2605 ', '')) if added else
                t("Already in the shopping cart."))
        elif a_batch is not None and chosen == a_batch:
            added = self._hold_add_rows(sel_rows)
            self._flash_tip(t("{n} \u2192 shopping cart \u2713").format(n=added))
            self.statusBar().showMessage(
                t("{n} swing items added to the shopping cart.").format(n=added))

