    def _apply_rg_preset(self):
        p = self.rg_preset.currentData()
        if not p:
            return
        self._applying_rg_preset = True
        try:
            mi = self.rg_mode.findData(p.get("mode", "relist"))
            if mi >= 0:
                self.rg_mode.setCurrentIndex(mi)
            self.rg_margin.setValue(p.get("margin", 0))
            self.rg_profit.setValue(p.get("profit", 0))
            self.rg_liq.setValue(p.get("liq", 0))
            self.rg_vol.setValue(p.get("vol", 0))
            self.rg_m3.setValue(p.get("m3", 0))
            self.rg_pmin.setValue(p.get("pmin", 0))
            self.rg_pmax.setValue(p.get("pmax", 0))
        finally:
            self._applying_rg_preset = False

    def _rg_preset_to_custom(self, *args):
        if getattr(self, "_applying_rg_preset", False):
            return
        if hasattr(self, "rg_preset") and self.rg_preset.currentIndex() != 0:
            self.rg_preset.blockSignals(True)
            self.rg_preset.setCurrentIndex(0)
            self.rg_preset.blockSignals(False)

