        self._sell_paste_info.setObjectName("Muted")
        self._sell_paste_info.setWordWrap(True)
        self._sell_paste_info.setStyleSheet("font-size:11px;")
        # NUTZER-LAYOUT: "Itemliste und Copy-Clipboard links/rechts
