        # darueber." Also: Knopf UEBER dem Einfuegefeld, Feld hochkant
        # (volle Hoehe statt 110 px), Ergebniszeile darunter.
        self._sell_paste.setFixedHeight(16777215)  # Qt-Max = frei
        self._sell_paste.setMinimumHeight(0)
        paste_card = QFrame(); paste_card.setObjectName("Card")
        _pv = QVBoxLayout(paste_card)
        _pv.setContentsMargins(12, 10, 12, 10); _pv.setSpacing(6)
