        self._orders_inner = QTabWidget()
        buy_page = QWidget(); bl = QVBoxLayout(buy_page); bl.setContentsMargins(0, 6, 0, 0)
        self.buyord_table = self._make_order_table(True); bl.addWidget(self.buyord_table)
        sell_page = QWidget(); sl = QVBoxLayout(sell_page); sl.setContentsMargins(0, 6, 0, 0)
        self.sellord_table = self._make_order_table(False); sl.addWidget(self.sellord_table)
        # Symbol GLEICH BEIM BAUEN (Sitzung 16): frueher erst beim ersten
