    def _nav_sichtbarkeit(self, cur):
        """Blendet im Industrie-Reiter die reinen Handels-Werkzeuge aus.

        Nur setVisible, kein Umbauen: die Knoepfe bleiben im Layout und
        damit am Leben (Handler, Tests, Tutorial-Ziele greifen weiter).
        """
        _tw = getattr(self, "_tab_widget", None) or {}
        ist_bau = cur is not None and cur is _tw.get("build")
        # NUR DIE LINKE LEISTE (Nutzer-Befund 22.09.2026: "wenn man auf
        # Industry wechselt, verschwinden auch Daytrade, Swingtrade,
        # Regional Trade - somit ist es unmoeglich zurueckzukehren").
        # `_nav_buttons` traegt BEIDES: die Werkzeuge links UND die vier
        # Reiter oben (sie teilen sich das Woerterbuch, damit die
        # Markierung "wo bin ich" an einer Stelle sitzt). Ueber alles zu
        # laufen hat deshalb den Rueckweg mitgenommen. Gefragt wird jetzt
        # `_common_keys` - dieselbe Liste, aus der die linke Leiste gebaut
        # wird, also keine zweite Wahrheit.
        for k in (getattr(self, "_common_keys", None) or []):
            b = (getattr(self, "_nav_buttons", None) or {}).get(k)
            if b is None:
                continue
            b.setVisible((not ist_bau) or k in self._NAV_INDUSTRIE)

    def _on_tab_changed(self, idx):
        # keep the sidebar/top-bar highlight in sync, even on programmatic jumps
        cur = self.tabs.widget(idx) if idx is not None and idx >= 0 else None
        # Trade-Tab-Layout (60/40-Split + einheitliche Höhe) neu anwenden, sobald ein
        # Tab sichtbar wird – erst dann hat der Splitter seine echte Breite, sodass
        # der 60/40-Split korrekt greift (statt auf 50/50 zu normalisieren).
        from PySide6.QtCore import QTimer as _FitT
        _FitT.singleShot(0, lambda: [f() for f in
                                     getattr(self, "_cal_fit_top_fns", [])])
        # remember where we came from, so ESC in the chart can return there
        prev = getattr(self, "_active_tab_widget", None)
        self._active_tab_widget = cur
        if (cur is getattr(self, "market_tab", None) and prev is not None
                and prev is not cur):
            self._market_return = prev
        if cur is getattr(self, "market_tab", None):
            self._mk_auto_start()
        if cur is not None and hasattr(self, "_tab_widget"):
            for k, wdg in self._tab_widget.items():
                if wdg is cur:
                    self._highlight_nav(k)
                    break
        self._nav_sichtbarkeit(cur)
        if getattr(self, "_shopping_w", None) is None:
            return
        if self.tabs.widget(idx) is self._shopping_w:
            rows = store.list_shopping()
            if rows and any(r["type_id"] not in self._sh_ladders for r in rows):
                self.shopping_load_prices()
            # Die Kauf-Order-Warnung braucht Daten. Gedrosselt wie beim
            # Order-Update-Reiter, und BILLIG: ein Abruf je Charakter, nicht
            # einer je Artikel.
            self._orders_nachziehen("_sh_orders_at", self._render_shopping)
        # ORDER UPDATE LAEDT BEIM OEFFNEN VON SELBST (Sitzung 17, Nutzer:
        # "brauchen wir den Refresh-Knopf wirklich? kann das nicht automatisch
        # gehen?"). NICHT bei jedem Wechsel: der Lauf holt EIN ORDERBUCH JE
        # ARTIKEL - bei 200 Positionen sind das 200 ESI-Abrufe. Deshalb wie im
        # Transaktionen-Tab gedrosselt: nur wenn noch nichts geladen ist, der
        # Hub gewechselt hat oder die Daten aelter als 5 Minuten sind. Der
        # Knopf BLEIBT - fuer "jetzt sofort", z.B. direkt nach dem Umpreisen.
        if self.tabs.widget(idx) is getattr(self, "_orders_w", None):
            if self.settings.get("client_id") and not getattr(
                    self, "_ord_laeuft", False):
                import time as _t_ord
                _hub_jetzt = self._active_hub()[2] or self._active_hub()[1]
                _hub_jetzt = (_hub_jetzt or {}).get("structure_id") if isinstance(
                    _hub_jetzt, dict) else _hub_jetzt
                _alt = getattr(self, "_ord_geladen_at", 0)
                if (not _alt or _hub_jetzt != getattr(self, "_ord_geladen_hub", None)
                        or (_t_ord.time() - _alt) > 300):
                    self._load_order_mods()
        if self.tabs.widget(idx) is getattr(self, "_sell_w", None):
            self._sell_tab_betreten()
        # opening Transaktionen → pull the latest from EVE if not fresh (throttled
        # to ~5 min so we don't hammer ESI), then it renders when done
        if self.tabs.widget(idx) is getattr(self, "_transactions_w", None):
            self._render_transactions()
            cids = [c["character_id"] for c in store.list_characters()]
            if self.settings.get("client_id") and any(
                    not store.tx_is_fresh(cid, 5) for cid in cids):
                self.sync_transactions_now(silent=True)

    def shopping_clear(self):
        if QMessageBox.question(self, t("Clear"), t("Empty the shopping cart?")) == QMessageBox.Yes:
            store.clear_shopping()
            for ctx in self._ladder_ctx.values():
                ctx["added"].clear()
            self._render_shopping()

    # ---- Profit (realised) -------------------------------------------------
    def _build_profit_tab(self):
        w = QWidget()
        root = QVBoxLayout(w)
        root.setContentsMargins(14, 8, 14, 8)
        root.setSpacing(7)

        head = QHBoxLayout()
        # Nutzer (Sitzung 8): "Charakter- und Zeitraum-Dropdown nach links
        # bringen - auf der rechten Seite schaut mein Auge selten hin."
        # Der Stretch wandert deshalb ans ENDE der Zeile.
        head.addWidget(QLabel(t("Character:")))
        self.pr_char = QComboBox()
        self.pr_char.currentIndexChanged.connect(self._render_profit)
        head.addWidget(self.pr_char)
        head.addWidget(QLabel(t("Period:")))
        self.pr_window = QComboBox()
        for label, days in [(t("{n} days").format(n=7), 7),
                            (t("{n} days").format(n=30), 30),
                            (t("{n} days").format(n=90), 90),
                            (t("{n} days").format(n=180), 180),
                            (t("1 year"), 365), (t("All"), 0)]:
            self.pr_window.addItem(label, days)
        # VORGABE "ALLES" (Nutzer, Sitzung 16). Vorher stand hier Index 1,
        # also 30 Tage - und das war eine Falle: die Tesseract Capacitor Unit
        # zeigte -12,5 Mio, ueber alle Trades waren es +70,6 Mio. Das Fenster
        # schnitt die alten, guenstigen Kaeufe ab, sodass nur die teuren
        # Nachkaeufe gegen die Verkaeufe standen. Ein voreingestellter Filter,
        # der Geld falsch darstellt, ist schlimmer als gar keiner.
        # UEBER DIE DATEN, nicht ueber die Position: wer die Liste umsortiert,
        # soll die Vorwahl nicht versehentlich mitverschieben.
        self.pr_window.setCurrentIndex(max(0, self.pr_window.findData(0)))
        self.pr_window.currentIndexChanged.connect(self._render_profit)
        head.addWidget(self.pr_window)
        head.addStretch()
        root.addLayout(head)

        kpis = QHBoxLayout()
        self.pk_net_c, self.pk_net = kpi_card(t("Profit (net)"), "pr_net", self)
        self.pk_rev_c, self.pk_rev = kpi_card(t("Revenue"), "pr_rev", self)
        self.pk_trades_c, self.pk_trades = kpi_card(t("Trades"), "pr_trades", self)
        self.pk_margin_c, self.pk_margin = kpi_card(
            t("\u00d8 margin"), "pr_margin", self, amber=True)
        self.pk_fees_c, self.pk_fees = kpi_card(t("Fees actual (journal)"))
        # NUTZER (Sitzung 8): "Gebuehren ausblenden, Marge als erste
        # Position ganz links." Die Marge ist die Leitzahl des Tabs - sie
        # steht jetzt vorn, wo das Auge zuerst hinschaut. Die
        # Gebuehren-Karte bleibt am Leben (die Render-Logik schreibt
        # weiter hinein), ist aber unsichtbar: die Zahl steckt bereits im
        # Netto-Gewinn, sie doppelt also nur.
        for c in (self.pk_margin_c, self.pk_net_c, self.pk_rev_c,
                  self.pk_trades_c, self.pk_fees_c):
            kpis.addWidget(c)
        self.pk_fees_c.setVisible(False)
        root.addLayout(kpis)

        self.pr_table = QTableWidget(0, 5)
        kopier_menue(self.pr_table)           # Rechtsklick -> Copy
        self.pr_table.setHorizontalHeaderLabels(
            [t("Item"), t("Sold"), t("Revenue"), t("Profit (net)"), t("Margin %")])
        hdr = self.pr_table.horizontalHeader()
        hdr.setSectionResizeMode(0, QHeaderView.Stretch)
        for col in range(1, 5):
            hdr.setSectionResizeMode(col, QHeaderView.ResizeToContents)
        self._make_columns_friendly(self.pr_table)
        self.pr_table.verticalHeader().setVisible(False)
        self.pr_table.setEditTriggers(QTableWidget.NoEditTriggers)
        self.pr_table.setShowGrid(False)
        root.addWidget(self.pr_table)

        # DAUERHINWEIS ENTFERNT (Nutzer-Wunsch Sitzung 12: "ich hasse
        # Infos, die das Tool ueberladen aussehen lassen").
        hint = QLabel("")
        hint.setVisible(False)
        hint.setObjectName("Muted")
        hint.setWordWrap(True)
        root.addWidget(hint)

        self.tabs.addTab(w, t("Profits"))

    def _render_profit(self):
        cid = self.pr_char.currentData()
        txs = store.get_transactions(None if cid in (None, "all") else cid)
        tax = self.settings["sales_tax_pct"] / 100.0
        broker = self.settings["broker_fee_pct"] / 100.0
        # HANDELS-PAAR ALS EIN BETRIEB RECHNEN (Sitzung 16). Der Nutzer kauft
        # mit einem Charakter in Jita und verkauft mit einem anderen in
        # 4-HWWF. FIFO je Charakter findet fuer diesen Verkauf kein Kauf-Lot -
        # der Handel fiel spurlos aus dieser Ansicht. In seinen echten Daten
        # gemessen: 26,4 Mrd ISK Umsatz.
        # NUR BEI "ALLE CHARAKTERE": waehlt er einen EINZELNEN, will er
        # dessen Zahlen sehen und nicht die des Paares - sonst zeigte die
        # Auswahl etwas anderes an, als sie verspricht.
        _paar = (self._handels_charaktere() if cid in (None, "all") else None)
        # FRACHT (Nutzer 30.09.2026): verkaufte Stueck, die woanders gekauft
        # wurden als verkauft, tragen m3 x heutigen Satz.
        _fr_satz = self._fracht_satz()
        _fr_vols = (self._fracht_volumen({x["type_id"] for x in txs})
                    if _fr_satz > 0 else {})
        _fr_ohne = {int(x) for x in (self.settings.get("fracht_aus_items") or [])
                    if str(x).lstrip("-").isdigit()}
        events = market.realized_trades(txs, tax, broker, paar=_paar,
                                        fracht_satz=_fr_satz, volumen=_fr_vols,
                                        ohne=_fr_ohne)
        days = self.pr_window.currentData()
        totals, rows = market.realized_summary(events, days)

        self.pk_net.setText(isk(totals["net"]))
        self.pk_net.setStyleSheet(f"color:{theme.GREEN if totals['net'] >= 0 else theme.RED}")
        self.pk_rev.setText(isk(totals["revenue"]))
        self.pk_trades.setText(str(totals["trades"]))
        cost = totals["revenue"] - totals["gross"] + totals.get("fracht", 0.0)
        avg_margin = (totals["net"] / cost * 100) if cost else 0.0
        # NUTZER (Sitzung 8): "Mache die Marge-Anzeige unter Gewinne groesser
        # und faerbe gruen bei Gewinn, rot bei Verlust." Diese Marge kommt
        # aus ECHTEN, abgeschlossenen Verkaeufen (Journal) - im Gegensatz zu
        # Erwartungswerten ist sie belastbar und darf deshalb Gewicht haben.
        # Vorzeichen mit anzeigen, damit ein Minus nicht uebersehen wird.
        self.pk_margin.setText(f"{avg_margin:+.1f} %")
        self.pk_margin.setStyleSheet(
            f"color:{theme.GREEN if avg_margin >= 0 else theme.RED}; "
            f"font-family:{theme.MONO}; font-size:26px; font-weight:800;")
        self.pk_margin.setToolTip(
            t("Average margin of the REAL sales in the chosen period: net profit "
              "{net} against purchases of {cost} over {trades} trades. "
              "ISK-weighted \u2013 big trades count more than small ones.").format(
                net=isk(totals['net']), cost=isk(cost), trades=totals['trades']))

        # Echte Gebühren aus dem Wallet-Journal (gleiches Zeitfenster). Anders
        # als die Formel-Schätzung der Tabellenzeilen enthalten sie auch den
        # KAUF-Broker deiner Buy-Orders (und jede Order-Änderung).
        import datetime as _dt
        since = ""
        if days:
            since = (_dt.date.today() - _dt.timedelta(days=days)).isoformat()
        fees = store.journal_fee_sums(None if cid in (None, "all") else cid, since)
        fee_total = fees["brokers_fee"] + fees["transaction_tax"]
        if fees.get("earliest"):
            self.pk_fees.setText(isk(fee_total))
            net_real = totals["gross"] - fee_total
            self.pk_fees_c.setToolTip(
                t("Actually paid according to the wallet journal since {since}:\n"
                  "\u2022 Broker (buy + sell + order changes): {broker}\n"
                  "\u2022 Sales tax: {tax}\n\n"
                  "Exact net profit (gross \u2212 real fees): {net}\n"
                  "(ESI delivers the journal ~30 days back; the DB collects "
                  "from introduction on \u2013 older periods are incomplete "
                  "accordingly.)").format(
                    since=fees['earliest'], broker=isk(fees['brokers_fee']),
                    tax=isk(fees['transaction_tax']), net=isk(net_real)))
        else:
            self.pk_fees.setText("\u2013")
            self.pk_fees_c.setToolTip(
                t("No journal data yet \u2013 run \u201eRefresh\u201c once, then the real fees are "
                  "collected."))

        names = store.cached_names([r["type_id"] for r in rows])
        self.pr_table.setSortingEnabled(False)
        self.pr_table.setRowCount(len(rows))
        for i, r in enumerate(rows):
            cells = [
                (names.get(r["type_id"], f"#{r['type_id']}"), None),
                (f"{r['qty']:,}".replace(",", "'"), r["qty"]),
                (isk(r["revenue"], suffix=False), r["revenue"]),
                (isk(r["net"], suffix=False), r["net"]),
                (f"{r['margin']:.1f} %", r["margin"]),
            ]
            for j, (text, val) in enumerate(cells):
                it = QTableWidgetItem(text) if j == 0 else NumericItem(text, val)
                if j >= 1:
                    it.setTextAlignment(Qt.AlignRight | Qt.AlignVCenter)
                if j in (3, 4):
                    it.setForeground(QColor(theme.GREEN if r["net"] >= 0 else theme.RED))
                if j == 3 and r.get("fracht", 0) > 0:
                    # Kisten-Symbol wie in der Verkaufsliste (kein Emoji)
                    it.setIcon(icons.icon("package", theme.CYAN))
                    it.setData(Qt.UserRole + 20, float(r["fracht"]))
                    it.setToolTip(t(
                        "Includes freight of {isk}: units sold somewhere else than "
                        "where they were bought, m\u00b3 \u00d7 your current rate "
                        "({satz} ISK/m\u00b3).").format(
                            isk=isk(r["fracht"]),
                            satz=f"{_fr_satz:,}".replace(",", "'")))
                self.pr_table.setItem(i, j, it)
        self.pr_table.setSortingEnabled(True)

