    def _tx_filters(self):
        cid = self.tx_char.currentData()
        is_buy = self.tx_type.currentData()
        days = self.tx_period.currentData() or 0
        name = self.tx_search.text().strip() or None
        since = None
        if days:
            from datetime import datetime, timedelta
            since = (datetime.utcnow() - timedelta(days=days)).strftime("%Y-%m-%d")
        return cid, is_buy, since, name

    def _render_transactions(self):
        cid, is_buy, since, name = self._tx_filters()
        stats = store.transaction_stats(cid, since=since, is_buy=is_buy, name_like=name)
        net = stats["sold"] - stats["bought"]
        self.tx_summary.setText(
            f"{stats['n']:,}".replace(",", "'") +
            t(" trades \u00b7 bought {b} \u00b7 sold {s} \u00b7 turnover balance {n}"
              ).format(b=isk(stats["bought"]), s=isk(stats["sold"]), n=isk(net)))
        txs = store.get_transactions(cid, since=since, is_buy=is_buy, name_like=name,
                                     limit=self._TX_DISPLAY_CAP)
        names = store.cached_names([_tx["type_id"] for _tx in txs])
        self.tx_table.setUpdatesEnabled(False)
        self.tx_table.setSortingEnabled(False)
        self.tx_table.setRowCount(len(txs))
        # Laufvariable NICHT `t` (Uebersetzer) - aa237 hat es gemeldet. Und
        # Kauf/Verkauf laufen gleich mit durch den Katalog.
        for i, tx in enumerate(txs):
            buy = tx["is_buy"]
            total = tx["unit_price"] * tx["quantity"]
            date = QTableWidgetItem(tx["date"][:10])
            typ = NumericItem(t("Buy") if buy else t("Sell"), 0 if buy else 1)
            typ.setForeground(QColor(theme.RED if buy else theme.GREEN))
            name_it = QTableWidgetItem(names.get(tx["type_id"], f"#{tx['type_id']}"))
            qty = NumericItem(f"{tx['quantity']:,}".replace(",", "'"), tx["quantity"])
            price = NumericItem(isk(tx["unit_price"]), tx["unit_price"])
            summ = NumericItem(isk(total), total)
            for col, it in enumerate((date, typ, name_it, qty, price, summ)):
                if col >= 3:
                    it.setTextAlignment(Qt.AlignRight | Qt.AlignVCenter)
                self.tx_table.setItem(i, col, it)
        self.tx_table.setSortingEnabled(True)
        self.tx_table.setUpdatesEnabled(True)
        if stats["total"] > len(txs):
            self.tx_note.setText(t(
                "Showing the newest {shown} of {total} transactions. Use the filters or "
                "the CSV export for the rest. (The summary above counts all of them.)"
            ).format(shown=f"{len(txs):,}".replace(",", "'"),
                     total=f"{stats['total']:,}".replace(",", "'")))
        else:
            self.tx_note.setText(
                t("{n} transactions (all shown).").format(
                    n=f"{stats['total']:,}".replace(",", "'")))

    def sync_transactions_now(self, silent=False):
        """Pull the latest wallet transactions from EVE for all characters,
        bypassing the 30-minute throttle, then re-render. (EVE's own wallet cache
        still limits how fresh this can be – roughly hourly.)"""
        chars = store.list_characters()
        client_id = self.settings.get("client_id")
        if not chars or not client_id:
            return
        cid_list = [c["character_id"] for c in chars]
        if hasattr(self, "tx_refresh"):
            self.tx_refresh.setEnabled(False)
        if not silent and hasattr(self, "tx_note"):
            self.tx_note.setText(t("Fetching the latest transactions from EVE \u2026"))

        def job():
            for cid in cid_list:
                try:
                    txs = esi.fetch_wallet_transactions(
                        client_id, cid,
                        stop_at_id=store.newest_transaction_id(cid))
                    store.save_transactions(cid, txs)
                    self._tx_altes_nachholen(client_id, cid)
                    # Gebuehren-Journal mitziehen (echte Broker-/Steuer-Beträge
                    # für den Gewinne-Tab). Zusatzinfo: darf den Transaktions-
                    # Sync nie scheitern lassen.
                    try:
                        store.save_journal(cid,
                            esi.fetch_wallet_journal(client_id, cid))
                    except Exception:
                        pass
                    store.set_tx_synced(cid)
                except Exception:
                    pass
            try:
                esi.resolve_names({_ti["type_id"] for _ti in store.get_transactions()})
            except Exception:
                pass
            return True

        def done(_):
            if hasattr(self, "tx_refresh"):
                self.tx_refresh.setEnabled(True)
            self._render_transactions()

        def fail(msg):
            if hasattr(self, "tx_refresh"):
                self.tx_refresh.setEnabled(True)
            if hasattr(self, "tx_note"):
                self.tx_note.setText(t("Update failed: ") + str(msg))

        self._run(Worker(job), done, fail_cb=fail, overlay=not silent)

    def _export_transactions(self):
        from PySide6.QtWidgets import QFileDialog
        import csv
        cid, is_buy, since, name = self._tx_filters()
        txs = store.get_transactions(cid, since=since, is_buy=is_buy, name_like=name)
        if not txs:
            self.statusBar().showMessage(t("No transactions to export."))
            return
        path, _ = QFileDialog.getSaveFileName(
            self, t("Export transactions"), t("transactions.csv"),
            t("CSV files (*.csv)"))
        if not path:
            return
        names = store.cached_names([_tx["type_id"] for _tx in txs])
        try:
            with open(path, "w", newline="", encoding="utf-8-sig") as f:
                wr = csv.writer(f, delimiter=";")
                wr.writerow([t("Date"), t("Type"), t("Item"), t("Quantity"),
                             t("Price/unit"), t("Total")])
                for tx in txs:          # nicht `t` - das ist der Uebersetzer
                    wr.writerow([
                        tx["date"][:19],
                        t("Buy") if tx["is_buy"] else t("Sell"),
                        names.get(tx["type_id"], f"#{tx['type_id']}"),
                        t["quantity"], f"{t['unit_price']:.2f}",
                        f"{t['unit_price'] * t['quantity']:.2f}"])
            self.statusBar().showMessage(
                f"{len(txs):,}".replace(",", "'") + t(" transactions exported: {path}").format(path=path))
        except Exception as e:
            self.statusBar().showMessage(t("Export error: ") + str(e))

    # ---- Market ------------------------------------------------------------
    def _build_market_tab(self):
        from PySide6.QtWidgets import QCheckBox, QSpinBox, QCompleter
        w = QWidget()
        root = QVBoxLayout(w)
        root.setContentsMargins(14, 8, 14, 8)
        head = QHBoxLayout()
        head.addStretch()
        self.mk_item = QComboBox()
        self.mk_item.setMinimumWidth(260)
        self.mk_item.setEditable(True)
        self.mk_item.setInsertPolicy(QComboBox.NoInsert)
        # VERVOLLSTAENDIGUNG UEBER ALLE BEKANNTEN NAMEN (Nutzer 18.09.2026:
        # "zeigt nicht alle Items wenn ich anfange zu tippen"). Die Liste
        # der Combo bleibt der Bestand (eine Handvoll); der Completer haengt
        # an einem EIGENEN Modell mit dem ganzen Namens-Cache (~13k nach
        # einem Market scan) - ein QStringListModel dieser Groesse kostet
        # nichts, nur das Einfuegen von 13k Combo-Eintraegen fror die
        # Oberflaeche ein (alter Befund).
        from PySide6.QtCore import QStringListModel as _QSLM
        self._mk_namen_modell = _QSLM()
        self._mk_namen_ids = {}
        comp = QCompleter(self._mk_namen_modell, self.mk_item)
        comp.setCompletionMode(QCompleter.PopupCompletion)
        comp.setFilterMode(Qt.MatchContains)
        comp.setCaseSensitivity(Qt.CaseInsensitive)
        comp.setMaxVisibleItems(14)
        self.mk_item.setCompleter(comp)
        comp.activated[str].connect(self._mk_name_gewaehlt)
        head.addWidget(QLabel(t("Item:")))
        head.addWidget(self.mk_item)
        self.mk_window = QComboBox()
        for label, days in [(t("{n} days").format(n=30), 30),
                            (t("{n} days").format(n=90), 90),
                            (t("{n} days").format(n=180), 180),
                            (t("1 year"), 365), (t("Max"), 0)]:
            self.mk_window.addItem(label, days)
        self.mk_window.setCurrentIndex(2)
        self.mk_window.setToolTip(t("Highlights this window. The full history stays visible dimmed in the "
                                    "background \u2013 so you see the long-term trend on the side."))
        # changing the window just re-highlights (no re-fetch needed)
        self.mk_window.currentIndexChanged.connect(lambda _: self._replot())
        head.addWidget(self.mk_window)
        self.mk_ma = QCheckBox(t("\u00d8 line"))
        self.mk_ma.setIcon(icons.icon("chart"))
        self.mk_ma.setChecked(True)
        self.mk_ma.stateChanged.connect(lambda _: self._replot())
        head.addWidget(self.mk_ma)
        self.mk_ma_n = QSpinBox(); self.mk_ma_n.setRange(2, 120); self.mk_ma_n.setValue(7)
        self.mk_ma_n.setSuffix(" T"); self.mk_ma_n.valueChanged.connect(lambda _: self._replot())
        head.addWidget(self.mk_ma_n)
        # auto-load when the item changes (picked from list or typed + Enter);
        # no manual "Laden" button needed
        self.mk_item.activated.connect(lambda _: self._plot_history())
        self.mk_item.lineEdit().returnPressed.connect(self._plot_history)
        root.addLayout(head)

        class IskAxis(pg.AxisItem):
            def tickStrings(self, values, scale, spacing):
                out = []
                for v in values:
                    a = abs(v)
                    if a >= 1e9:
                        out.append(f"{v/1e9:.2f}B")
                    elif a >= 1e6:
                        out.append(f"{v/1e6:.2f}M")
                    elif a >= 1e3:
                        out.append(f"{v/1e3:.0f}k")
                    else:
                        out.append(f"{v:.0f}")
                return out

        pg.setConfigOptions(antialias=True, background=theme.PANEL, foreground=theme.MUTED)
        self.plot = pg.PlotWidget(axisItems={"bottom": pg.DateAxisItem(),
                                             "left": IskAxis(orientation="left")})
        self.plot.showGrid(x=True, y=True, alpha=0.18)
        self.plot.getAxis("left").setTextPen(theme.MUTED)
        self.plot.getAxis("bottom").setTextPen(theme.MUTED)
        self.plot.addLegend(offset=(10, 10))
        # crosshair
        self._vline = pg.InfiniteLine(angle=90, pen=pg.mkPen(theme.MUTED, width=1,
                                                             style=Qt.DashLine))
        self._hline = pg.InfiniteLine(angle=0, pen=pg.mkPen(theme.MUTED, width=1,
                                                            style=Qt.DashLine))
        self.plot.addItem(self._vline, ignoreBounds=True)
        self.plot.addItem(self._hline, ignoreBounds=True)
        self._cross_lbl = pg.TextItem(color=theme.CYAN, anchor=(0, 1))
        self.plot.addItem(self._cross_lbl, ignoreBounds=True)
        self.plot.scene().sigMouseMoved.connect(self._on_mouse_move)
        # secondary view box (right axis) for volume bars at the bottom
        p1 = self.plot.getPlotItem()
        p1.showAxis("right")
        self._vol_vb = pg.ViewBox()
        p1.scene().addItem(self._vol_vb)
        p1.getAxis("right").linkToView(self._vol_vb)
        self._vol_vb.setXLink(p1)
        p1.getAxis("right").setLabel(t("Daily volume"))
        p1.getAxis("right").setTextPen(theme.MUTED)

        def _sync_vol_view():
            self._vol_vb.setGeometry(p1.vb.sceneBoundingRect())
            self._vol_vb.linkedViewChanged(p1.vb, self._vol_vb.XAxis)
        p1.vb.sigResized.connect(_sync_vol_view)
        self._sync_vol_view = _sync_vol_view
        root.addWidget(self.plot)
        self._mk_xs, self._mk_ys = [], []
        self._mk_highs, self._mk_lows, self._mk_vols = [], [], []
        self._mk_full = []
        self._chart_items = []
        self.market_tab = w
        self.tabs.addTab(w, t("Price history"))
        # ESC returns to whichever tab you came from
        from PySide6.QtGui import QShortcut, QKeySequence
        esc = QShortcut(QKeySequence(Qt.Key_Escape), w)
        esc.setContext(Qt.WidgetWithChildrenShortcut)
        esc.activated.connect(self._market_escape_back)

    def _market_escape_back(self):
        target = getattr(self, "_market_return", None)
        if target is not None and target is not self.market_tab:
            try:
                self.tabs.setCurrentWidget(target)
            except Exception:
                pass

    def _on_mouse_move(self, pos):
        import time as _t
        if not self._mk_xs:
            return
        vb = self.plot.getViewBox()
        if not self.plot.sceneBoundingRect().contains(pos):
            return
        mp = vb.mapSceneToView(pos)
        x = mp.x()
        # nearest data point
        xs = self._mk_xs
        idx = min(range(len(xs)), key=lambda i: abs(xs[i] - x))
        px, py = xs[idx], self._mk_ys[idx]
        self._vline.setPos(px)
        self._hline.setPos(py)
        date = _t.strftime("%d.%m.%Y", _t.localtime(px))
        self._cross_lbl.setText(f"{date}\n{isk(py)}")
        self._cross_lbl.setPos(px, py)

    def _plot_history(self):
        tid = self.mk_item.currentData()
        text = self.mk_item.currentText().strip()
        # if the typed text doesn't match the selected item, resolve it
        if (tid is None or (text and text != self.mk_item.itemText(self.mk_item.currentIndex()))):
            if not text:
                return
            # Erst lokal (Namens-Cache, ohne Netz), dann ESI.
            _lok = {k.lower(): v for k, v in
                    (getattr(self, "_mk_namen_ids", None) or {}).items()}
            _tid_lok = _lok.get(text.lower())
            if _tid_lok is not None:
                _name = next((k for k in self._mk_namen_ids
                              if k.lower() == text.lower()), text)
                if self.mk_item.findData(_tid_lok) < 0:
                    self.mk_item.addItem(_name, _tid_lok)
                self.mk_item.setCurrentIndex(self.mk_item.findData(_tid_lok))
                self._do_plot(_tid_lok)
                return

            def done(res):
                if self.mk_item.findData(res["id"]) < 0:
                    self.mk_item.addItem(res["name"], res["id"])
                self.mk_item.setCurrentIndex(self.mk_item.findData(res["id"]))
                self._do_plot(res["id"])

            self._run(Worker(self._resolve_one, text), done,
                      fail_cb=lambda _: self.statusBar().showMessage(t("Item not found.")))
            return
        self._do_plot(tid)

    def _do_plot(self, tid):
        self.statusBar().showMessage(t("Loading price history \u2026"))
        region = store.get_scan_region()
        # Zuletzt angesehenes Item merken - beim naechsten Oeffnen des Tabs
        # steht sofort ein Graph da (Nutzer 18.09.2026).
        try:
            self.settings["mk_last_item"] = [int(tid), self.mk_item.currentText()]
        except Exception:
            pass

        def done(data):
            self._mk_full = data or []          # keep the FULL history in memory
            self._replot()                       # window is applied at draw time
            if self._mk_full:
                ys = [d["average"] for d in self._mk_full if d.get("average")]
                vols = [d.get("volume") or 0 for d in self._mk_full]
                if ys:
                    # Der Tausenderpunkt wird jetzt NUR auf das Volumen
                    # angewendet (vorher auf die ganze Zeile) - isk() setzt
                    # seine Apostrophe selbst, und ein Komma im Itemnamen
                    # gehoert nicht ersetzt.
                    self.statusBar().showMessage(
                        t("{item} · {days} days history · Ø {avg} "
                          "· Σ volume {vol}").format(
                            item=self.mk_item.currentText(), days=len(ys),
                            avg=isk(sum(ys) / len(ys)),
                            vol=f"{sum(vols):,}".replace(",", "'")))
            else:
                self.statusBar().showMessage(
                    t("No history available (item may be traded rarely)."))
        self._run(Worker(scanner.history_cached, tid, region), done)

    def _replot(self):
        import time as _t
        # remove ONLY the chart items we added last time (band + scatter + bars +
        # lines were previously leaking → ghost pieces). Crosshair stays.
        for it in getattr(self, "_chart_items", []):
            try:
                self.plot.removeItem(it)
            except Exception:
                pass
        self._chart_items = []
        legend = self.plot.getPlotItem().legend
        if legend is not None:
            legend.clear()
        if hasattr(self, "_vol_vb"):
            for it in list(self._vol_vb.allChildItems()):
                try:
                    self._vol_vb.removeItem(it)
                except Exception:
                    pass

        full = getattr(self, "_mk_full", []) or []
        fxs, fys, fhi, flo, fvol = [], [], [], [], []
        for d in full:
            if not d.get("average"):
                continue
            fxs.append(_t.mktime(_t.strptime(d["date"], "%Y-%m-%d")))
            fys.append(d["average"])
            fhi.append(d.get("highest") or d["average"])
            flo.append(d.get("lowest") or d["average"])
            fvol.append(d.get("volume") or 0)
        # crosshair reads the full series so hovering works everywhere
        self._mk_xs, self._mk_ys = fxs, fys
        self._mk_highs, self._mk_lows, self._mk_vols = fhi, flo, fvol
        if not fxs:
            return

        days = self.mk_window.currentData()
        if days and len(fxs) > days:
            sxs, sys_, shi, slo = fxs[-days:], fys[-days:], fhi[-days:], flo[-days:]
            sel_start = sxs[0]
            windowed = True
        else:
            sxs, sys_, shi, slo = fxs, fys, fhi, flo
            sel_start = fxs[0]
            windowed = False

        def track(item):
            self.plot.addItem(item)
            self._chart_items.append(item)
            return item

        # (a) faint shaded box behind the selected window so you SEE what's picked
        if windowed:
            reg = pg.LinearRegionItem(values=(sel_start, fxs[-1]), movable=False,
                                      brush=pg.mkBrush(70, 224, 200, 20),
                                      pen=pg.mkPen(None))
            reg.setZValue(-20)
            track(reg)

        # (b) FULL history dimmed in the background (context: value a year ago)
        try:
            hi_c = pg.PlotDataItem(fxs, fhi, pen=pg.mkPen(theme.BORDER, width=1))
            lo_c = pg.PlotDataItem(fxs, flo, pen=pg.mkPen(theme.BORDER, width=1))
            band = pg.FillBetweenItem(hi_c, lo_c, brush=pg.mkBrush(70, 224, 200, 12))
            track(band); track(hi_c); track(lo_c)
        except Exception:
            pass
        track(pg.PlotDataItem(fxs, fys, pen=pg.mkPen(QColor(70, 224, 200, 85), width=1)))

        # (c) SELECTED window highlighted on top (bright, thicker) + detail dots
        track(pg.PlotDataItem(sxs, sys_, pen=pg.mkPen(theme.CYAN, width=2),
                              name=t("\u00d8 price")))
        try:
            spots = []
            for x, y, hi, lo in zip(sxs, sys_, shi, slo):
                rng = (hi - lo) if hi > lo else 0
                pos = (y - lo) / rng if rng else 0.5
                col = (QColor(theme.AMBER) if pos >= 0.6 else
                       QColor(theme.GREEN) if pos <= 0.4 else QColor(theme.MUTED))
                spots.append({"pos": (x, y), "brush": col, "pen": None, "size": 6})
            track(pg.ScatterPlotItem(spots=spots))
        except Exception:
            pass

        # (d) moving average over the full series (continuous trend line)
        if self.mk_ma.isChecked():
            n = self.mk_ma_n.value()
            if len(fys) >= n:
                from collections import deque
                ma, s, dq = [], 0.0, deque()
                for v in fys:
                    dq.append(v); s += v
                    if len(dq) > n:
                        s -= dq.popleft()
                    ma.append(s / len(dq))
                track(pg.PlotDataItem(fxs, ma, pen=pg.mkPen(theme.AMBER, width=1.5),
                                      name=f"Ø {n}T"))

        # (e) volume bars along the bottom (full range, faint)
        if hasattr(self, "_vol_vb") and fvol and any(fvol):
            try:
                bars = pg.BarGraphItem(x=fxs, height=fvol, width=0.7 * 86400,
                                       brush=pg.mkBrush(70, 224, 200, 50),
                                       pen=pg.mkPen(None))
                self._vol_vb.addItem(bars)
                vmax = max(fvol) or 1
                self._vol_vb.setYRange(0, vmax * 3.2, padding=0)
                if hasattr(self, "_sync_vol_view"):
                    self._sync_vol_view()
            except Exception:
                pass

        # (f) show the full range by default + constrain zoom so you can't fling
        # out into an empty infinite grid (Bild 3). Min 7-day window keeps it
        # readable; can't pan/zoom beyond the data + a little padding.
        vb = self.plot.getViewBox()
        x0, x1 = fxs[0], fxs[-1]
        span = max(x1 - x0, 86400.0)
        xpad = span * 0.03
        ytop = (max(fhi) if fhi else max(fys)) * 1.1 or 1.0
        min_x_range = min(7 * 86400, span)   # short histories: don't exceed the data
        vb.setLimits(xMin=x0 - xpad, xMax=x1 + xpad, yMin=0, yMax=ytop * 1.05,
                     minXRange=min_x_range, maxXRange=span + 2 * xpad,
                     minYRange=max(1.0, ytop * 0.02))
        vb.setRange(xRange=(x0 - xpad, x1 + xpad), yRange=(0, ytop), padding=0)

    # ---- Characters --------------------------------------------------------
    def _rg_fuelle_charakter_auswahl(self):
        """Beide Auswahllisten mit den verknuepften Charakteren fuellen und
        die gespeicherte Wahl wiederherstellen.

        Die Signale werden waehrenddessen STILLGELEGT: sonst schriebe das
        Fuellen die Einstellung mit halbfertigem Stand zurueck und die
        gespeicherte Wahl waere weg, bevor sie gesetzt ist.
        """
        try:
            chars = store.list_characters()
        except Exception:
            chars = []
        gespeichert = sorted(self._handels_charaktere())
        for i, cb in enumerate((getattr(self, "rg_buyer", None),
                                getattr(self, "rg_seller", None))):
            if cb is None:
                continue
            cb.blockSignals(True)
            cb.clear()
            cb.addItem("\u2014", None)
            for c in chars:
                cb.addItem(c["character_name"], c["character_id"])
            if i < len(gespeichert):
                idx = cb.findData(gespeichert[i])
                cb.setCurrentIndex(idx if idx >= 0 else 0)
            cb.blockSignals(False)

    def _rg_handels_paar_speichern(self, *_a):
        """Auswahl sichern. Doppelte und Leereintraege fallen weg - wer
        zweimal denselben Charakter waehlt, meint eine Menge mit einem
        Eintrag, nicht mit zweien."""
        ids = []
        for cb in (getattr(self, "rg_buyer", None),
                   getattr(self, "rg_seller", None)):
            if cb is None:
                continue
            d = cb.currentData()
            if d is not None and int(d) not in ids:
                ids.append(int(d))
        self.settings["handels_charaktere"] = ids
        config.save_settings(self.settings)

    def _handels_charaktere(self):
        """Die als HANDELS-Charaktere markierten IDs - oder eine leere Menge,
        wenn nichts eingestellt ist (dann zaehlen wie bisher alle).

        NUTZER (Sitzung 16): "im Fall von Regional Trading habe ich 2
        Charaktere, einer in Jita und einer in 4-HWWF. Wenn man da beide
        Charaktere als Ein- und Verkaeufer eintragen koennte, und man nur von
        diesen 2 Charakteren die Transaktionen wertet?"

        DER FALL, DER DAHINTER STEHT: ein dritter Charakter kaufte einmal
        2 Stueck zu einem Ladenpreis, um ein Schiff zu fitten - kein Handel.
        Weil der Einstand ueber ALLE Charaktere zusammengelegt wird, zog
        dieser eine Kauf den Ø-Einkauf hoch und das Order-Update meldete
        Verlust, wo keiner war.

        WARUM NICHT EINFACH "NUR DER AKTIVE CHARAKTER" (seine zweite Idee) -
        GEMESSEN: der Verkaeufer in 4-HWWF hat nie etwas GEKAUFT. Allein
        betrachtet haette er gar keinen Einstand, die Spalte zeigte ueberall
        "-" und die Verlust-Pruefung waere komplett aus. Das waere
        schlechter als der heutige Stand. Es braucht die MENGE, nicht den
        einen.

        LEER = ALLE. Wer nichts einstellt, sieht genau das Verhalten von
        vorher - eine neue Einstellung darf niemandem still die Zahlen
        verschieben.
        """
        roh = self.settings.get("handels_charaktere")
        if not isinstance(roh, (list, tuple, set)):
            return set()
        raus = set()
        for x in roh:
            try:
                raus.add(int(x))
            except (TypeError, ValueError):
                continue
        return raus

    def _handels_transaktionen(self):
        """Transaktionen der Handels-Charaktere - oder aller, wenn keine
        Auswahl besteht. EINE Stelle, damit die Auswahl nicht an drei Orten
        verschieden ausgelegt wird."""
        ids = self._handels_charaktere()
        if not ids:
            return store.get_transactions()
        raus = []
        for cid in sorted(ids):
            raus.extend(store.get_transactions(cid))
        return raus

    def _build_characters_tab(self):
        w = QWidget()
        root = QVBoxLayout(w)
        root.setContentsMargins(14, 8, 14, 8)
        root.setSpacing(7)
        info = QLabel(t(
            "Link your EVE characters with the official login. Only a "
            "refresh token is stored securely – no password."))
        info.setObjectName("Muted")
        info.setWordWrap(True)
        root.addWidget(info)

        # DIE HANDELS-SPALTE STAND HIER KURZ UND IST WIEDER WEG (Sitzung 16).
        # Der Nutzer hat sie hier nicht gesucht: "Ein und Verkaeufer gehoert
        # zum Regional Tab, wenn dann will ich es da waehlen koennen." Sie
        # sitzt jetzt als zwei Auswahllisten in der Route-Karte, direkt neben
        # "kaufen in / verkaufen in" - dort ergibt sie sich aus dem Kontext.
        # NICHT AN BEIDEN ORTEN: eine Einstellung, eine Stelle.
        self.char_table = QTableWidget(0, 3)
        kopier_menue(self.char_table)         # Rechtsklick -> Copy
        self.char_table.setHorizontalHeaderLabels([t("Character"), "ID", t("Action")])
        from PySide6.QtCore import QSize
        self.char_table.setIconSize(QSize(36, 36))
        hdr = self.char_table.horizontalHeader()
        hdr.setSectionResizeMode(0, QHeaderView.Stretch)
        hdr.setSectionResizeMode(1, QHeaderView.ResizeToContents)
        hdr.setSectionResizeMode(2, QHeaderView.Fixed)
        # Platz fuer ZWEI Knoepfe: "Re-link" und "Remove" (emm357).
        self.char_table.setColumnWidth(2, 280)
        self.char_table.verticalHeader().setVisible(False)
        self.char_table.setEditTriggers(QTableWidget.NoEditTriggers)
        # KEINE Sortierung (Auftrag A, Sitzung 9 gestrichen): Spalte 2 traegt
        # ein Knopf-Widget, das Qt beim Umordnen verwirft - und die Tabelle
        # zeigt ohnehin nur eine Handvoll Charaktere. Sortieren waere Aufwand
        # gegen ein Problem, das es hier nicht gibt.
        root.addWidget(self.char_table)

        btnrow = QHBoxLayout()
        add = QPushButton(t("Link character"))
        add.setIcon(icons.icon("plus"))
        add.setObjectName("Primary")
        add.clicked.connect(self.link_character)
        # "EINRICHTUNG" IST HIER WEG (Nutzer-Befund Sitzung 11: "muss das
        # jeder sehen koennen?"). Der Knopf lud zum Klicken ein, und was
        # dann kam, sah nach Pflichtarbeit aus ("Einmalige Einrichtung,
        # ~2 Minuten") - obwohl der ausgelieferte Stand eine eingebaute
        # Client-ID hat und niemand das je braucht. Ein Schritt, den 99 %
        # nicht gehen muessen, gehoert nicht neben den einen Knopf, den
        # ALLE druecken.
        # ER IST NICHT VERSCHWUNDEN: er sitzt in den Einstellungen direkt
        # neben dem Feld "ESI Client-ID" - dort sucht ihn, wer eine eigene
        # Anwendung eintragen will, und nur dort.
        btnrow.addWidget(add)
        btnrow.addStretch()
        root.addLayout(btnrow)
        self.tabs.addTab(w, t("Characters"))
        self._render_characters()

    def _render_characters(self):
        chars = store.list_characters()
        self.char_table.setRowCount(len(chars))
        for i, c in enumerate(chars):
            name_item = QTableWidgetItem(c["character_name"])
            icon = self._character_icon(c["character_id"], size=36)
            if icon:
                name_item.setIcon(icon)
            self.char_table.setItem(i, 0, name_item)
            self.char_table.setItem(i, 1, QTableWidgetItem(str(c["character_id"])))
            cell = QWidget()
            cl = QHBoxLayout(cell); cl.setContentsMargins(6, 3, 6, 3)
            # NEU VERLINKEN NEBEN ENTFERNEN (emm357, Nutzer: "Nutzer trauen
            # sich vielleicht nicht, den Remove-Button zu druecken"). Derselbe
            # Login wie "Link character": Token und Rechte werden erneuert,
            # Transaktionen und Einstellungen bleiben.
            rl = _btn_icon(QPushButton(t("Re-link")), "refresh")
            # BREITE AUS DEM TEXT, nicht fest (emm358, Nutzer-Screenshot: die
            # Knoepfe ueberschnitten sich, "Re-" / "Ren" abgeschnitten).
            rl.setFixedHeight(26)
            rl.setStyleSheet(
                f"QPushButton{{background:{theme.PANEL2}; border:1px solid {theme.CYAN}; "
                f"color:{theme.CYAN}; border-radius:6px; padding:2px 14px;}}"
                f"QPushButton:hover{{background:{theme.CYAN_FILL};}}")
            rl.setCursor(Qt.PointingHandCursor)
            rl.setToolTip(t("Log in again with {name} \u2013 renews the ESI permissions. "
                            "Nothing is deleted. In the EVE login, pick {name}.").format(
                                name=c["character_name"]))
            rl.clicked.connect(lambda _=False: self.link_character())
            rl.setMinimumWidth(rl.sizeHint().width())   # NACH dem Stil (Polster)
            cl.addStretch(); cl.addWidget(rl)
            btn = _btn_icon(QPushButton(t("Remove")), "trash")
            btn.setFixedHeight(26)
            btn.setStyleSheet(
                f"background:{theme.PANEL2}; border:1px solid {theme.RED}; "
                f"color:{theme.RED}; border-radius:6px; padding:2px 14px;")
            btn.setCursor(Qt.PointingHandCursor)
            btn.clicked.connect(lambda _, cid=c["character_id"]: self.unlink_character(cid))
            cl.addWidget(btn); cl.addStretch()
            btn.setMinimumWidth(btn.sizeHint().width())
            cl.setSpacing(8)
            self.char_table.setCellWidget(i, 2, cell)
            self.char_table.setRowHeight(i, 44)
        self._char_aktionen_breite()

    def _char_aktionen_breite(self):
        """Aktions-Spalte so breit, dass "Re-link" UND "Remove" nebeneinander
        passen (emm358). Auch NACH dem Wiederherstellen gemerkter Spalten-
        breiten - ein alter Zustand (150 px) liess die Knoepfe ueberlappen."""
        tbl = getattr(self, "char_table", None)
        if tbl is None:
            return
        _w = 280
        for _r in range(tbl.rowCount()):
            _c = tbl.cellWidget(_r, 2)
            if _c is not None:
                _w = max(_w, _c.sizeHint().width() + 12)
        if tbl.columnWidth(2) < _w:
            tbl.setColumnWidth(2, _w)

    def link_character(self):
        if not self.settings.get("client_id"):
            self.open_setup()
            if not self.settings.get("client_id"):
                return
        self.statusBar().showMessage(t("Browser opened \u2013 please log in \u2026"))

        def done(res):
            was_first = not store.list_characters()   # vor dem Einfügen prüfen
            store.upsert_character(res["character_id"], res["character_name"])
            self._bau_rollen_vorbelegen(res["character_id"])
            tokens.set_token(res["character_id"], res["refresh_token"])
            esi.cache_access_token(res["character_id"], res["access_token"],
                                   res.get("expires_in", 1200))
            self._render_characters()
            self._reload_character_combos()
            # auto-read skills + standings so the user never types them in
            if self.settings.get("fees_from_skills"):
                self._pull_skills_for(res["character_id"], silent=True)
            # Nur beim ALLERERSTEN Charakter automatisch voll aktualisieren (damit
            # die App direkt einsatzbereit ist). Verlinkt man weitere Charaktere,
            # NICHT jedes Mal den schweren Refresh starten -- man hängt oft mehrere
            # hintereinander an und drückt danach selbst „↻ Alles aktualisieren“.
            if was_first:
                self.statusBar().showMessage(t("{name} linked.").format(name=res['character_name']))
                self.refresh_everything()
            else:
                self.statusBar().showMessage(t(
                    "{name} linked. For the new data press \u201eRefresh\u201c "
                    "at the top.").format(name=res['character_name']))

        scopes = self._gewuenschte_scopes()
        self._run(
            Worker(auth.login, self.settings["client_id"],
                   int(self.settings["callback_port"]), scopes),
            done,
            err_prefix=t("Login failed"),
        )

    def _gewuenschte_scopes(self):
        """Die ESI-Rechte, die das Tool mit den aktuellen Einstellungen
        anfragt - EINE Stelle fuer den Login UND die Pruefung beim Start
        (emm355)."""
        scopes = list(config.DEFAULT_SCOPES)
        if self.settings.get("use_assets"):
            scopes.append(config.ASSETS_SCOPE)
        if self.settings.get("use_structures"):
            scopes.extend(config.STRUCTURE_SCOPES)
        if self.settings.get("use_ui"):
            scopes.append(config.UI_SCOPE)
        if self.settings.get("fees_from_skills"):
            scopes.extend(config.SKILL_SCOPES)   # read Accounting/Broker + standings
        if self.settings.get("use_implants"):
            scopes.append(config.IMPLANT_SCOPE)  # Fertigungszeit-Bonus-Implantate erkennen
        if self.settings.get("use_corp"):
            scopes.extend(config.CORP_SCOPES)    # Corp-Hangar fuers Bauen (1.0.8)
        if self.settings.get("use_location"):
            scopes.append(config.LOCATION_SCOPE)  # Standort-Hinweis (emm313)
        return scopes

    def _scope_gruppen_namen(self, fehlende):
        """Fehlende Scopes -> lesbare Funktionsnamen (fuer das Popup)."""
        gruppen = [
            (set(config.SKILL_SCOPES), t("skills, standings, industry jobs, blueprints")),
            ({config.IMPLANT_SCOPE}, t("implants")),
            ({config.ASSETS_SCOPE}, t("stock in your hangars")),
            (set(config.STRUCTURE_SCOPES), t("structure markets")),
            ({config.UI_SCOPE}, t("open in game")),
            (set(config.CORP_SCOPES), t("corporation hangar")),
            ({config.LOCATION_SCOPE}, t("location hint")),
            (set(config.DEFAULT_SCOPES), t("wallet and orders")),
        ]
        f = set(fehlende or ())
        out = [nm for sc, nm in gruppen if f & sc]
        return out

    def _scope_check_beim_start(self):
        """Beim Start einmal: fehlen einem verknuepften Charakter ESI-Rechte,
        die das Tool mit den aktuellen Einstellungen braucht, kommt ein
        Fenster (emm355, Nutzer: "re-link oben sieht kein Mensch, da muss
        direkt beim Login ein Popup kommen ... darf ruhig etwas Humor
        haben"). Unbekannt (Token nicht lesbar, kein Netz) = kein Fenster.
        "Nicht mehr fragen" gilt nur fuer GENAU diese fehlenden Rechte - ein
        spaeteres Update mit neuen Rechten fragt wieder."""
        client_id = self.settings.get("client_id")
        try:
            chars = store.list_characters()
        except Exception:
            chars = []
        if not client_id or not chars:
            return
        soll = self._gewuenschte_scopes()

        def job():
            erteilt = {}
            namen = {}
            for ch in chars:
                cid = int(ch["character_id"])
                namen[cid] = ch.get("character_name") or str(cid)
                try:
                    erteilt[cid] = set(esi.granted_scopes(client_id, cid) or set()) or None
                except Exception:
                    erteilt[cid] = None
            return erteilt, namen

        def done(res):
            erteilt, namen = res
            self._scope_fenster_zeigen(soll, erteilt, namen)
        self._run(Worker(job), done, overlay=False)

    def _scope_fenster_zeigen(self, soll, erteilt, namen, antwort=None):
        """Das Popup selbst (getrennt fuer die b-Suite: `antwort` statt
        Klick: "relink" / "later" / "never"). -> fehlende {cid: [...]}."""
        from .mw_helpers import fehlende_scopes
        fehlt = fehlende_scopes(soll, erteilt)
        self._scope_fehlt_stand = dict(fehlt)          # b-Suite
        if not fehlt:
            return fehlt
        _sig = sorted({s for v in fehlt.values() for s in v})
        if self.settings.get("scope_hinweis_aus") == _sig:
            return fehlt
        _zeilen = []
        for cid, sc in sorted(fehlt.items(), key=lambda kv: str(namen.get(kv[0], kv[0]))):
            _zeilen.append("\u2022 " + str(namen.get(cid, cid)) + ": "
                           + ", ".join(self._scope_gruppen_namen(sc)))
        box = QMessageBox(self)
        box.setIcon(QMessageBox.Information)
        box.setWindowTitle(t("New ESI permissions \u2013 quick re-link please"))
        # TEXT VOM NUTZER (emm356): "o7 Pilot! Leider musst du deine
        # Charaktere neu verlinken ... ist das nicht toll?" Darunter klein,
        # welche Charaktere es betrifft.
        box.setText(t("o7 Pilot!\nUnfortunately you have to link your characters "
                      "again to enjoy the full functionality of Eve MoMa. But in "
                      "return there are lots of new features \u2013 isn't that great?"))
        box.setInformativeText("\n".join(_zeilen))
        from PySide6.QtWidgets import QCheckBox as _QCB
        _nie = _QCB(t("Don't remind me again for these permissions"))
        box.setCheckBox(_nie)
        box._nie_ref = _nie        # PySide: sonst raeumt Python den Haken weg
        _jetzt = box.addButton(t("Re-link now"), QMessageBox.AcceptRole)
        box.addButton(t("Later"), QMessageBox.RejectRole)
        box.setDefaultButton(_jetzt)
        self._scope_box = box                           # b-Suite
        if antwort is None:
            box.exec()
            _wahl = "relink" if box.clickedButton() is _jetzt else "later"
            _still = _nie.isChecked()
        else:
            _wahl = "relink" if antwort == "relink" else "later"
            _still = antwort == "never"
        if _still:
            self.settings["scope_hinweis_aus"] = _sig
            config.save_settings_async(self.settings)
        if _wahl == "relink":
            if hasattr(self, "_go_tab"):
                self._go_tab("characters")
            self.link_character()
        return fehlt

    def unlink_character(self, cid):
        # Anzahl gespeicherter Transaktionen dieses Chars zeigen, damit klar wird,
        # was auf dem Spiel steht (die lokale Historie ist über die Zeit gewachsen
        # und über ESI NICHT wiederherstellbar -- ESI liefert nur ~30 Tage).
        try:
            n_tx = len(store.get_transactions(cid))
        except Exception:
            n_tx = 0
        box = QMessageBox(self)
        box.setIcon(QMessageBox.Warning)
        box.setWindowTitle(t("Remove character?"))
        box.setText(t("Remove the character and its locally stored data?"))
        info = t("\u26a0 This deletes the entire local transaction history of this "
                 "character. On re-linking, EVE/ESI only returns the last ~30 days "
                 "\u2013 older history (and the profit calculated from it) is gone for "
                 "good afterwards.")
        if n_tx:
            info += t("\n\nAffected: {n} stored transactions.").format(
                n=f"{n_tx:,}".replace(",", "'"))
        info += t("\n\nA backup of the database is created automatically before "
                  "deleting.")
        box.setInformativeText(info)
        del_btn = box.addButton(t("Remove permanently"), QMessageBox.DestructiveRole)
        box.addButton(t("Cancel"), QMessageBox.RejectRole)
        box.setDefaultButton(box.buttons()[-1])   # Default = Abbrechen (sicher)
        box.exec()
        if box.clickedButton() is not del_btn:
            return
        # Sicherheitsnetz: DB kopieren, BEVOR unwiderruflich gelöscht wird.
        bpath = store.backup_db(reason="unlink")
        store.remove_character(cid)
        tokens.delete_token(cid)
        self._render_characters()
        self._reload_character_combos()
        # Kein refresh_all() (voller ESI-Abruf über ALLE übrigen Chars) mehr --
        # beim Entfernen werden nur Daten gelöscht, nichts Neues geholt. Ein
        # lokales _recompute() baut Portfolio/Transaktionen/Gewinne aus den bereits
        # gespeicherten Daten neu auf (der gelöschte Char fällt dabei raus), ohne
        # die sekundenlange Netzwerk-Aktualisierung. Der Nutzer kann bei Bedarf
        # weiterhin selbst „↻ Alles aktualisieren“ drücken.
        try:
            self._recompute()
        except Exception:
            pass
        if bpath:
            import os as _os
            self.statusBar().showMessage(
                t("Character removed. Backup saved: {file}").format(file=_os.path.basename(bpath)))
        else:
            self.statusBar().showMessage(t("Character removed."))

