        self.s_implants.addItem(t("On (detect manufacturing-time implants)"), True)
        self.s_implants.setCurrentIndex(1 if self.settings.get("use_implants") else 0)
        # STANDORT-HINWEIS (emm313): eigener Scope, STANDARD AUS.
