    # ---- ungespeicherte Einstellungen -------------------------------------
    def _einstellungen_feldstand(self):
        """Der Stand ALLER Eingabefelder der Einstellungsseite.

        BEWUSST DIE FELDER, NICHT `self.settings`: zwei der gespeicherten
        Werte (`sales_tax_pct`, `broker_fee_pct`) werden bei "aus Skills
        rechnen" laufend neu abgeleitet - auch vom aktiven Handelshub. Ein
        Vergleich gegen die Einstellungen haette deshalb "geaendert"
        gemeldet, ohne dass jemand etwas angefasst hat, und die Rueckfrage
        waere zum Dauergast geworden. Was hier zaehlt, ist allein: steht in
        den Feldern noch dasselbe wie beim letzten Speichern?
        """
        stand = {
            "client": self.s_client.text().strip(),
            "port": int(self.s_port.value()),
            "margin": float(self.s_margin.value()),
            "tax": float(self.s_tax.value()),
            "broker": float(self.s_broker.value()),
            "sbroker": float(self.s_sbroker.value()),
            "fees_skills": bool(self.s_fees_skills.currentData()),
            "accounting": int(self.s_accounting.value()),
            "broker_rel": int(self.s_broker_rel.value()),
            "mode": self.s_mode.currentData(),
            "source": bool(self.s_source.currentData()),
            "struct": bool(self.s_struct.currentData()),
            "ui": bool(self.s_ui.currentData()),
            "implants": bool(self.s_implants.currentData()),
            "location": bool(self.s_location.currentData()),
            "use_corp": bool(self.s_corp.currentData()),
            "corp_divs": tuple(n for n, c in self.s_corp_divs.items()
                               if c.isChecked()),
        }
        for _k, _sp in self.s_hub_corp.items():
            stand["corp_" + str(_k)] = float(_sp.value())
        for _k, _sp in self.s_hub_faction.items():
            stand["fac_" + str(_k)] = float(_sp.value())
        return stand

    def _einstellungen_stand_merken(self):
        """Den aktuellen Feldstand als "gespeichert" festhalten."""
        try:
            self._einst_stand = self._einstellungen_feldstand()
        except Exception:
            self._einst_stand = None

    def _einstellungen_offen(self):
        """Steht etwas in den Feldern, das nicht gespeichert ist?"""
        alt = getattr(self, "_einst_stand", None)
        if alt is None:
            return False        # kein Vergleichsstand -> nichts behaupten
        try:
            return self._einstellungen_feldstand() != alt
        except Exception:
            return False

    def _einstellungen_wechsel_pruefen(self, alt, _neu):
        """Riegel vor jedem Seitenwechsel. True = wechseln erlaubt.

        Fragt NUR beim Verlassen der Einstellungsseite und NUR, wenn dort
        wirklich etwas offen ist - sonst waere es eine Rueckfrage, die man
        wegklickt, ohne sie zu lesen.
        """
        _seite = getattr(self, "_settings_w", None)
        if _seite is None or self.tabs.widget(alt) is not _seite:
            return True
        if not self._einstellungen_offen():
            return True
        _antwort = self._einstellungen_frage()
        if _antwort == "speichern":
            self.save_settings()        # merkt den Stand selbst nach
            return True
        if _antwort == "verwerfen":
            # ZURUECK AUF DEN GESPEICHERTEN STAND: die Seite wird beim
            # naechsten Besuch NICHT neu gebaut, die verworfenen Zahlen
            # stuenden also weiter in den Feldern und saehen aus, als
            # gaelten sie.
            self._einstellungen_felder_zuruecksetzen()
            return True
        return False                    # "Zurueck zu den Einstellungen"

    def _einstellungen_frage(self):
        """Die Rueckfrage selbst. Gibt "speichern", "verwerfen" oder
        "zurueck" zurueck.

        EIGENE METHODE, damit die Entscheidung pruefbar ist: ein modales
        Fenster laesst sich in der Testsuite nicht bedienen (b59 bewacht
        genau diese Falle). Der Wächter b7k fährt damit alle drei Wege
        wirklich durch, statt nur den Quelltext zu lesen.
        """
        box = QMessageBox(self)
        box.setIcon(QMessageBox.Warning)
        box.setWindowTitle(t("Unsaved settings"))
        box.setText(t("You changed settings but did not save them."))
        box.setInformativeText(t(
            "Without saving they have no effect – the program keeps "
            "working with the old values."))
        _sp = box.addButton(t("Save and continue"), QMessageBox.AcceptRole)
        _vw = box.addButton(t("Discard changes"), QMessageBox.DestructiveRole)
        box.addButton(t("Back to settings"), QMessageBox.RejectRole)
        box.setDefaultButton(_sp)
        box.exec()
        _geklickt = box.clickedButton()
        if _geklickt is _sp:
            return "speichern"
        if _geklickt is _vw:
            return "verwerfen"
        return "zurueck"

    def _einstellungen_felder_zuruecksetzen(self):
        """Alle Felder wieder auf den gespeicherten Stand bringen.

        Die Schalter, die SOFORT speichern (Berechtigungen), sind bewusst
        dabei: ihr gespeicherter Wert ist der, den sie zeigen sollen. Ihre
        Signale werden dabei still gelegt, sonst schriebe das Zuruecksetzen
        selbst wieder in die Einstellungen.
        """
        _combos = (self.s_mode, self.s_source, self.s_struct, self.s_ui,
                   self.s_implants, self.s_fees_skills, self.s_corp, self.s_location)
        for _c in _combos:
            _c.blockSignals(True)
        for _c in self.s_corp_divs.values():
            _c.blockSignals(True)
        try:
            self.s_client.setText(self.settings.get("client_id", ""))
            self.s_port.setValue(int(self.settings.get("callback_port", 8635)))
            self.s_margin.setValue(float(self.settings.get("target_margin", 0)))
            self.s_tax.setValue(float(self.settings.get("sales_tax_pct", 0)))
            self.s_broker.setValue(float(self.settings.get("broker_fee_pct", 0)))
            self.s_sbroker.setValue(
                float(self.settings.get("structure_broker_pct", 1.0)))
            self.s_accounting.setValue(
                int(self.settings.get("skill_accounting", 0)))
            self.s_broker_rel.setValue(
                int(self.settings.get("skill_broker_relations", 0)))
            self.s_fees_skills.setCurrentIndex(
                1 if self.settings.get("fees_from_skills") else 0)
            self.s_mode.setCurrentIndex(
                0 if self.settings.get("sell_mode") == "relist" else 1)
            self.s_source.setCurrentIndex(
                1 if self.settings.get("use_assets") else 0)
            self.s_struct.setCurrentIndex(
                1 if self.settings.get("use_structures") else 0)
            self.s_ui.setCurrentIndex(
                1 if self.settings.get("use_ui") else 0)
            self.s_implants.setCurrentIndex(
                1 if self.settings.get("use_implants") else 0)
            self.s_location.setCurrentIndex(
                1 if self.settings.get("use_location") else 0)
            self.s_corp.setCurrentIndex(
                1 if self.settings.get("use_corp") else 0)
            from .. import corp as _corp_r
            _gw = set(_corp_r.divisions_bereinigt(
                self.settings.get("corp_divisions")))
            for _n, _c in self.s_corp_divs.items():
                _c.setChecked(_n in _gw)
            _hub_st = self.settings.get("hub_standings", {}) or {}
            for _k, _sp in self.s_hub_corp.items():
                _sp.setValue(float((_hub_st.get(_k) or {}).get("corp", 0.0)))
            for _k, _sp in self.s_hub_faction.items():
                _sp.setValue(float((_hub_st.get(_k) or {}).get("faction", 0.0)))
        except Exception as _e_res:
            self._log_exception("Einstellungen zuruecksetzen", str(_e_res))
        finally:
            for _c in _combos:
                _c.blockSignals(False)
            for _c in self.s_corp_divs.values():
                _c.blockSignals(False)
        self._einstellungen_stand_merken()

    def _fmt_size(self, b):
        for unit in ("B", "KB", "MB", "GB"):
            if b < 1024 or unit == "GB":
                return f"{b:.0f} {unit}" if unit == "B" else f"{b:.1f} {unit}"
            b /= 1024.0

    def _refresh_storage_stats(self):
        try:
            st = store.db_stats()
        except Exception as e:
            self.s_storage.setText(t("Size not readable: ") + str(e))
            return
        c = st["counts"]
        self.s_storage.setText(t(
            "Database: {size}  \u00b7  Market history: {hist} rows  \u00b7  Snapshot: "
            "{snap} items  \u00b7  Transactions: {tx} (are kept)").format(
            size=self._fmt_size(st['size_bytes']),
            hist=f"{c['history']:,}".replace(",", "'"),
            snap=f"{c['market_snapshot']:,}".replace(",", "'"),
            tx=f"{c['transactions']:,}".replace(",", "'")))

    def _clear_market_cache(self):
        from PySide6.QtWidgets import QMessageBox
        r = QMessageBox.question(
            self, t("Clear market cache"),
            t("The cached market history and the last hub scan are deleted and the "
              "database shrinks.\n\nOn the next \u201eMarket scan\u201c / \u201eCalculate "
              "deals\u201c everything is reloaded automatically (slower once).\n\n"
              "Transactions, characters and shopping list are kept. Continue?"),
            QMessageBox.Yes | QMessageBox.No, QMessageBox.No)
        if r != QMessageBox.Yes:
            return
        try:
            res = store.clear_market_cache()
            self._refresh_storage_stats()
            self.statusBar().showMessage(
                t("Market cache cleared \u2013 {size} freed.").format(size=self._fmt_size(res["freed_bytes"])))
        except Exception as e:
            self.statusBar().showMessage(t("Cleanup error: ") + str(e))

    def _sde_kontextmenue(self, pos):
        """Rechtsklick auf "Baurezepte laden": Werte tiefenpruefen."""
        from PySide6.QtWidgets import QMenu
        m = QMenu(self.g_sde_btn)
        _akt = m.addAction(t("Deep-check values"))
        _akt.setToolTip(t(
            "Compares every yield and ingredient amount of the loaded "
            "blueprints against the game data and reports what is out of "
            "date."))
        if m.exec(self.g_sde_btn.mapToGlobal(pos)) is _akt:
            self._check_recipes()

    def _check_recipes(self):
        from ..sprache import t as _txt   # `t` ist hier lokal belegt
        """Einstellungen -> "Rezepte pruefen" (Nutzer-Wunsch, Sitzung 8).

        Fuehrt beide Haelften von pruefe_rezepte.py aus und zeigt EINEN
        Bericht: Zensus (offline, lokale Daten in sich) + Patch-Abgleich
        (laedt 2 CSVs von Fuzzwork). Schlaegt der Abgleich fehl (kein Netz),
        wird der Zensus-Teil TROTZDEM gezeigt - mit klarer Ansage, was
        fehlte, statt gar nichts (Regel 6: markieren, nicht raten)."""
        import pruefe_rezepte as PR

        def job(progress=None, should_cancel=None):
            return PR.bericht_fuer_ui()

        def done(r):
            from ..sprache import t as _txt   # `t` ist hier lokal belegt
            if r.get("leer"):
                QMessageBox.information(
                    self, _txt("Check recipes"),
                    _txt("No recipes in the local database \u2013 run \u201eLoad "
                         "recipes\u201c first."))
                return
            # Liste NICHT `t` nennen (Uebersetzer). Sitzung 16.
            z = [_txt("{n} reaction formulas checked.").format(n=r['n']), ""]
            z.append(_txt("YIELD CENSUS (yield per run: number of formulas):"))
            for q, n in list(r["zensus"].items())[:12]:
                z.append(f"   {q:>8}: {n}")
            z.append("")
            probleme = False
            if r["hart"]:
                probleme = True
                z.append(_txt("!! {n} formula(s) with yield NULL/0 - the import "
                              "silently turns that into 1!").format(n=len(r['hart'])))
            if r["falsch"]:
                probleme = True
                z.append(_txt("!! {n} yield(s) do NOT arrive 1:1 in the loaded "
                              "recipes!").format(n=len(r['falsch'])))
            if not r["hart"] and not r["falsch"]:
                z.append(_txt("Census: no anomalies, import arrived 1:1. \u2713"))
            z.append("")
            if r["diff"] is None:
                z.append(_txt("PATCH COMPARISON NOT POSSIBLE ({err}) \u2013 the census "
                              "above still applies. Check again later with "
                              "internet.").format(err=r['sde_fehler']))
            else:
                ausbeute, zutaten, entfernt, neu = r["diff"]
                if ausbeute:
                    probleme = True
                    z.append(_txt("!! {n} YIELD(S) OUTDATED (CCP patch) - first:").format(
                        n=len(ausbeute)))
                    for (bp, akt, pid), alt_, soll in sorted(ausbeute)[:8]:
                        z.append(_txt("   Product {pid}: local {loc}/run, game {game}/run"
                                      ).format(pid=pid,
                                               loc=f"{alt_:,}".replace(",", "'"),
                                               game=f"{soll:,}".replace(",", "'")))
                if zutaten:
                    probleme = True
                    z.append(_txt("!! {n} INGREDIENT QUANTITY/QUANTITIES OUTDATED."
                                  ).format(n=len(zutaten)))
                if entfernt:
                    z.append(_txt("\u26a0 {n} recipe(s) removed in game, still here "
                                  "locally.").format(n=len(entfernt)))
                if neu:
                    z.append(_txt("\u26a0 {n} new recipe(s) in game, unknown locally."
                                  ).format(n=len(neu)))
                if not (ausbeute or zutaten or entfernt or neu):
                    z.append(_txt("Patch comparison: ALL yields and ingredient "
                                  "quantities up to date. \u2713"))
            if probleme or (r["diff"] and any(r["diff"])):
                z.append("")
                z.append(_txt("-> run \u201eLoad recipes\u201c, then check again (must be "
                              "empty afterwards)."))
            dlg = QMessageBox(self)
            dlg.setWindowTitle(_txt("Check recipes"))
            dlg.setIcon(QMessageBox.Warning if probleme
                        else QMessageBox.Information)
            dlg.setText("\n".join(z))
            dlg.exec()

        def fail(e):
            QMessageBox.warning(self, _txt("Check recipes"),
                                _txt("Check failed: ") + str(e))

        self._run(Worker(job), done, fail_cb=fail,
                  label=_txt("Checking recipes \u2026"))

    def _bd_load_contract_prices_for(self, type_id):
        """Werkzeuge -> "Contract-Preise laden (New Eden)" (Nutzer, Sitzung 9:
        "Capital Schiffspreise sind im Jita-Markt nicht zu finden, nur ueber
        Contracts"). Uebernimmt den MEDIAN der oeffentlichen New-Eden-
        Contracts als Verkaufspreis des Endprodukts.

        Reihenfolge: erst der GESPEICHERTE New-Eden-Stand aus dem Scanner
        (Capital-Modus) - der ist sofort da. Fehlt das Item darin, wird
        GEZIELT NUR dieses eine Item frisch gescannt (derselbe Weg wie der
        Scanner, nur mit einem einzigen Typ - dadurch Minuten statt
        Viertelstunde). KEINE zweite Preisrechnung daneben: Quelle und
        Aggregation (Median gegen Scam-Ausreisser) sind exakt die des
        Scanners."""
        try:
            info = (store.get_contract_prices(store.ALL_REGIONS) or {}).get(
                int(type_id))
        except Exception:
            info = None
        if info and info.get("median"):
            self._bd_contract_sell = info
            self._flash_tip(t("Contract price applied: median ") + isk(info["median"]))
            _fn = getattr(self, "_bd_full_rebuild", None)
            if _fn is not None:
                _fn()
            return
        # Nicht "im Hintergrund" - er laeuft mit dem Overlay (Nutzer 27.09.2026).
        self._flash_tip(t("Searching public contracts across all of New Eden \u2026"))

        def job(progress=None, should_cancel=None):
            _sellmap = {int(r["type_id"]): float(r.get("sell_min") or 0)
                        for r in (store.get_snapshot() or [])}
            result = scanner.scan_capital_contract_prices_all_regions(
                {int(type_id)}, should_cancel=should_cancel,
                progress=progress,
                extra_price_fn=_sellmap.get if _sellmap else None)
            # MERGEN statt speichern: save_contract_prices ERSETZT den Stand
            # der Region komplett - ein Ein-Item-Scan wuerde sonst den ganzen
            # New-Eden-Stand des Scanners wegwerfen. Der Leser liefert alle
            # Felder, die der Schreiber braucht (updated_at ignoriert er).
            merged = dict(store.get_contract_prices(store.ALL_REGIONS) or {})
            merged.update(result)
            rows = [{"type_id": _t, **_i} for _t, _i in merged.items()]
            store.save_contract_prices(rows, store.ALL_REGIONS)
            return result.get(int(type_id))

        def done(info2):
            if info2 and info2.get("median"):
                self._bd_contract_sell = info2
                self._flash_tip(t("Contract price applied: median ") + isk(info2["median"]))
                _fn = getattr(self, "_bd_full_rebuild", None)
                if _fn is not None:
                    _fn()
            else:
                # EHRLICH: kein Treffer heisst kein neuer Preis - still auf
                # dem alten Jita-Wert sitzen zu bleiben saehe aus wie Erfolg.
                self._flash_tip(t("No public contract found for this item \u2013 the "
                                  "sale price stays unchanged."))

        def fail(msg):
            self._flash_tip(t("Contract scan error: ") + str(msg)[:80])
        self._run(Worker(job, with_progress=True, with_cancel=True), done,
                  fail_cb=fail, label=t("Searching contracts …"))

    def _buy_missing_again(self):
        """Werkzeuge -> "Fehlendes nachkaufen" (Nutzer-Wunsch Sitzung 12).

        Nimmt NUR echte Verluste auf: Material, das schon einmal GEDECKT war
        und jetzt fehlt (versehentlich weggeworfen, anderweitig verbaut).
        Der gewoehnliche Rest-Bedarf kommt hier NIE hinein - die
        Einkaufsliste soll nicht von selbst wachsen ("gekauft ist gekauft"),
        deshalb ist das ein bewusster Klick und kein Automatismus.
        """
        from ..sprache import t as _txt
        verlust = dict(getattr(self, "_bd_verlust", None) or {})
        if not verlust:
            QMessageBox.information(
                self, _txt("Buy missing again"),
                _txt("Nothing is missing that was already covered \u2013 "
                     "there is nothing to buy again."))
            return
        namen = getattr(self, "_bd_names_ref", None) or {}
        # DIE ECHTE Einkaufslisten-Funktion benutzen (store.add_shopping),
        # nicht eine erfundene: sie fuehrt vorhandene Zeilen zusammen, statt
        # Doppel-Posten anzulegen.
        n_add = 0
        for tid, menge in verlust.items():
            try:
                store.add_shopping(int(tid), str(namen.get(int(tid), tid)),
                                   int(menge), source="build")
                n_add += 1
            except Exception:
                continue
        try:
            self._render_shopping()
        except Exception:
            pass          # Anzeige-Auffrischung ist Komfort, nie kritisch
        QMessageBox.information(
            self, _txt("Buy missing again"),
            _txt("{n} materials added to the shopping list.").format(n=n_add)
            + "\n\n" + ", ".join(
                str(namen.get(_t, _t)) for _t in list(verlust)[:8]))

    def _fehlbedarf_jetzt(self):
        """Fehlbedarf der RESTLICHEN Runs - EINE Wahrheit fuer Knopf UND
        Dauer-Anzeige (Nutzer-Wunsch Sitzung 12: "lieber eine staendige
        automatische Loesung").

        Rueckgabe wie `fehlbedarf_vorschau`: Liste von
        (type_id, fehlt, rest_bedarf, da, rest_produktion); leer = gedeckt.
        Gibt [] zurueck, wenn kein gerechneter Plan offen ist - die
        Dauer-Anzeige soll dann einfach schweigen, nicht warnen.

        WARUM GETEILT: haette die Dauer-Anzeige eine eigene Rechnung, koennten
        Knopf und Zeile Verschiedenes sagen - genau die Art Widerspruch, die
        den Nutzer in dieser Sitzung schon einmal zu unnoetigen Kaeufen
        verleitet hat (Materialien-Reiter sagte "noch 78 kaufen", die Pruefung
        sagte "alles deckt sich").
        """
        from eve_trader.ui.mw_helpers import fehlbedarf_vorschau
        plan = (getattr(self, "_bd_plan_ref", None) or {}).get("plan") or {}
        build_runs = plan.get("build_runs") or {}
        build_mats = plan.get("build_mats") or {}
        if not build_runs or not build_mats:
            return []
        recipes = getattr(self, "_bd_recipes", None)
        out_qty = {}
        if recipes is not None:
            for _t in build_runs:
                bp = recipes.product_to_bp.get(_t)
                if bp:
                    out_qty[_t] = bp[2]
        # DEN BESTAND NEHMEN, MIT DEM DER PLAN RECHNET - nicht den rohen
        # Live-Stand.
        #
        # NUTZER-VORFALL (Sitzung 12): der Materialien-Reiter meldete
        # "gedeckt fuer die restlichen Runs", die Einkaufsliste kopierte
        # trotzdem Tritanium 9'142'651 und Isogen 113'526. Beides stimmte
        # aus seiner Sicht - nur schauten die beiden auf VERSCHIEDENE
        # Bestaende:
        #   `_bd_opts["stock"]` ist um die RESERVIERUNGEN anderer Plaene
        #   gekuerzt (und auf den Bestands-Scope begrenzt),
        #   `_bd_live_stock` ist der ROHE Stand ohne beides.
        # Material, das ein anderer Plan beansprucht, ist fuer DIESEN Plan
        # nicht verfuegbar - es als "gedeckt" zu melden ist eine falsche
        # Entwarnung, und der Nutzer stuende am Reaktor ohne Material.
        live = ((getattr(self, "_bd_opts", None) or {}).get("stock")
                or getattr(self, "_bd_live_stock", None) or {})
        # NUR SICHER ZUGEORDNETES (Befund 21.09.2026, nachgestellt): ESI
        # sagt nicht, zu welchem Bauplan ein Job gehoert - bauen zwei
        # eingefrorene Plaene dieselbe Reaktion, bekamen BEIDE dieselben
        # Runs gutgeschrieben und meldeten "nichts fehlt". Die ANZEIGE darf
        # das weiterhin raten (`_bd_runplan_delivered`), diese Rechnung
        # nicht: sie sagt dem Nutzer, was ihm fehlen wird.
        # SEIT 30.09.2026 DIESELBE ERLEDIGT-KARTE WIE DIE EINKAUFSLISTE
        # (`_rest_geliefert_jetzt`: sicher geliefert + Hand-Haken + Vorstufen).
        # Nutzer (Basilisk): alle Composite-Reaktionen abgehakt, aber noch
        # nicht abgeholt - die Fehlt-Zeilen verlangten ihre Intermediates
        # trotzdem (Titanium Chromide 43'316 - 21'932 = 21'384 "fehlt"),
        # obwohl die laengst verbraucht waren. Der Output der Jobs zaehlt
        # ueber die Pipeline im Bestand (`live`).
        geliefert = self._rest_geliefert_jetzt()
        # ERZEUGNIS SCHON IM BESTAND = sicher geliefert + laufende/abholbereite
        # Jobs DIESES Plans (deren Output steckt als Pipeline in `live`). Ein
        # abgehakter Run, den ESI noch nicht kennt, bleibt kommende
        # Produktion (s. fehlbedarf_vorschau, `im_bestand`).
        _im_bestand = {int(_t): int(_n or 0) for _t, _n in
                       (getattr(self, "_bd_runplan_delivered_sicher", None)
                        or {}).items()}
        for _t, _js in (getattr(self, "_bd_active_jobs_map", None) or {}).items():
            _im_bestand[int(_t)] = (_im_bestand.get(int(_t), 0)
                                    + sum(int(_j.get("runs") or 0) for _j in (_js or [])))
        _fehl = fehlbedarf_vorschau(build_runs, build_mats, out_qty,
                                    geliefert, live, im_bestand=_im_bestand)
        # REPROCESSING (1.0.9, Weg B): solange Stufe 0 nicht abgehakt ist,
        # deckt das Erz die Minerale - und das Erz selbst muss da sein.
        return reprocess.fehl_anpassen(
            _fehl, ((plan.get("reprocess") or {}).get("schritte") or []),
            set(getattr(self, "_bd_runplan_checked", None) or set())
            | self._erz_durch_bestand(), live)

    def _rest_geliefert_jetzt(self):
        """{type_id: erledigte Runs} = sicher ESI-geliefert ODER von Hand
        abgehakt, je Item das Maximum (derselbe Run kann in beiden stehen).

        Herausgeloest aus `_restbedarf_jetzt` (26.09.2026), damit der
        Materialien-Reiter dieselbe Zahl fuer die OFFENEN RUNS eines
        Eigenbau-Items zeigen kann (`_rest_runs_jetzt`) - eine Wahrheit,
        nicht zwei Rechnungen.
        """
        geliefert = dict(getattr(self, "_bd_runplan_delivered_sicher",
                                 None) or {})
        _checked = getattr(self, "_bd_runplan_checked", None) or set()
        _by_key = getattr(self, "_bd_runplan_runs_by_key", None) or {}
        _hand = {}
        for _k in _checked:
            _paar = _by_key.get(_k)
            if _paar:
                _hand[_paar[0]] = _hand.get(_paar[0], 0) + _paar[1]
        for _t, _n in _hand.items():
            geliefert[_t] = max(int(geliefert.get(_t, 0) or 0), int(_n))
        # VORSTUFEN, DIE KEIN VERBRAUCHER MEHR BRAUCHT (Nutzer 28.09.2026,
        # Phenolic Composites: alle Komponenten fertig, trotzdem 4 Runs
        # offen). Erledigt heisst hier wie im Runplaner: geliefert, abgehakt
        # ODER laufend - ein laufender Job hat sein Material schon verbraucht.
        # Die Namen merkt sich `_bd_vorstufen_fertig` fuer die Statuszeile.
        self._bd_vorstufen_fertig = set()
        try:
            from eve_trader.ui.mw_helpers import vorstufen_erledigt
            _plan_v = (getattr(self, "_bd_plan_ref", None) or {}).get("plan") or {}
            _erl_v = dict(geliefert)
            for _t, _js in (getattr(self, "_bd_active_jobs_map", None) or {}).items():
                _erl_v[int(_t)] = (int(_erl_v.get(int(_t), 0) or 0)
                                   + sum(int(_j.get("runs") or 0) for _j in (_js or [])))
            for _t, _n in vorstufen_erledigt(_plan_v.get("build_runs"),
                                             _plan_v.get("build_mats"),
                                             _erl_v).items():
                geliefert[_t] = max(int(_n), int(geliefert.get(_t, 0) or 0))
                self._bd_vorstufen_fertig.add(int(_t))
        except Exception as _ve:
            self._log_exception("Vorstufen erledigt", str(_ve))
        return geliefert

    def _rest_runs_jetzt(self):
        """{type_id: noch offene Runs} je Eigenbau-Item - oder None, wenn
        kein gerechneter Plan offen ist.

        NUTZER 26.09.2026 (Silicon Diborite): der Materialien-Reiter sagte
        "can be built - 13'019 units", obwohl der Runplaner laengst nur
        noch 0 Runs offen hatte. Die 13'019 waren Plan-Bedarf minus
        Bestand - eine Zahl, die vom Bauen nichts weiss. Hier steht, was
        der Runplaner wirklich noch baut: dieselbe Rechnung wie die
        Einkaufsliste (`restbedarf_map` mit der SICHEREN Liefer-Karte).
        """
        from eve_trader.ui.mw_helpers import restbedarf_map
        plan = (getattr(self, "_bd_plan_ref", None) or {}).get("plan") or {}
        build_runs = plan.get("build_runs") or {}
        build_mats = plan.get("build_mats") or {}
        if not build_runs or not build_mats:
            return None
        _rem, _need = restbedarf_map(build_runs, build_mats,
                                     self._rest_geliefert_jetzt())
        return {int(k): int(v) for k, v in (_rem or {}).items()}

    def _restbedarf_jetzt(self):
        """{type_id: Menge}, die die NOCH OFFENEN Runs brauchen.

        Leer, wenn kein gerechneter Plan offen ist oder nichts mehr aussteht.
        Speist die Einkaufsliste, damit sie sich waehrend des Bauens
        mitbewegt (Nutzer, Sitzung 16).
        """
        from eve_trader.ui.mw_helpers import restbedarf_map
        plan = (getattr(self, "_bd_plan_ref", None) or {}).get("plan") or {}
        build_runs = plan.get("build_runs") or {}
        build_mats = plan.get("build_mats") or {}
        if not build_runs or not build_mats:
            return {}
        # ESI-GELIEFERT **UND** VON HAND ABGEHAKT (Sitzung 16, zweiter
        # Nutzer-Befund): `_bd_runplan_delivered` kennt nur, was ESI als
        # geliefert meldet. Runs, die er selbst abgehakt hat, galten damit
        # weiter als offen - ihr Material stand wieder auf der Einkaufsliste,
        # obwohl es laengst in der naechsten Stufe steckt.
        # Je Item das MAXIMUM beider Quellen, nicht die Summe: derselbe Run
        # kann in beiden stehen (ESI sieht ihn UND der Nutzer hakt ab), und
        # doppelt gezaehlt fiele der Restbedarf zu niedrig aus - dann stuende
        # er am Reaktor ohne Material.
        # SICHERE Karte, nicht die geratene (Befund 21.09.2026, s.
        # _fehlbedarf_jetzt und mw_helpers.delivered_sicher): hier haengt
        # die EINKAUFSLISTE dran. Ein fremder Job, der faelschlich diesem
        # Plan angerechnet wird, senkt sonst den Restbedarf - der Nutzer
        # kauft zu wenig und steht mitten im Bauen ohne Material
        # ("ich muss staendig Reactions nachbauen").
        geliefert = self._rest_geliefert_jetzt()
        _checked = getattr(self, "_bd_runplan_checked", None) or set()
        _rem, need = restbedarf_map(build_runs, build_mats, geliefert)
        # REPROCESSING (1.0.9, Weg B): nicht abgehakte Schritte - Erz statt
        # der gedeckten Minerale (s. reprocess.rest_anpassen). Ein Schritt,
        # dessen Minerale schon im Bestand liegen, zaehlt wie abgehakt
        # (28.09.2026, `_erz_durch_bestand`).
        return reprocess.rest_anpassen(
            need, ((plan.get("reprocess") or {}).get("schritte") or []),
            set(_checked) | self._erz_durch_bestand())

    def _erz_durch_bestand(self):
        """Erz-Schritte des offenen Plans, deren Minerale der Bestand schon
        deckt (reprocess.schritte_durch_bestand) - EINE Stelle fuer
        Einkaufsliste, Fehlbedarf, Materialien-Reiter und Runplaner.
        Bestand = der fuer DIESEN Plan zaehlende (`_bd_opts["stock"]`, nach
        fremden Reservierungen), Bedarf = Restbedarf der offenen Runs."""
        try:
            from eve_trader.ui.mw_helpers import restbedarf_map
            plan = (getattr(self, "_bd_plan_ref", None) or {}).get("plan") or {}
            _sch = (plan.get("reprocess") or {}).get("schritte") or []
            if not _sch or not plan.get("build_runs") or not plan.get("build_mats"):
                return set()
            _stock = (getattr(self, "_bd_opts", None) or {}).get("stock") or {}
            if not _stock:
                return set()
            _rem, need = restbedarf_map(plan.get("build_runs") or {},
                                        plan.get("build_mats") or {},
                                        self._rest_geliefert_jetzt())
            return reprocess.schritte_durch_bestand(_sch, need, _stock)
        except Exception as _eb:
            self._log_exception("Erz durch Bestand", str(_eb))
            return set()

    def _check_shortfall(self):
        from ..sprache import t as _txt   # `t` ist hier lokal belegt
        """Werkzeuge -> "Fehlbedarf pruefen" (Sitzung 8, nach dem dritten
        Verschwundener-Bestand-Vorfall). Reine Anzeige, aendert nichts am
        Plan; Kern ist mw_helpers.fehlbedarf_vorschau (pur, aa168)."""
        from eve_trader.ui.mw_helpers import fehlbedarf_vorschau

        plan = (getattr(self, "_bd_plan_ref", None) or {}).get("plan") or {}
        build_runs = plan.get("build_runs") or {}
        build_mats = plan.get("build_mats") or {}
        if not build_runs or not build_mats:
            QMessageBox.information(
                self, t("Check shortfall"),
                t("No calculated plan with build positions open \u2013 run "
                  "\u201eRecalculate\u201c first (older saved plans do not know the "
                  "exact ingredient quantities yet)."))
            return
        # DIESELBE Rechnung wie die Dauer-Anzeige im Materialien-Reiter.
        defizite = self._fehlbedarf_jetzt()
        names = getattr(self, "_bd_names_ref", None) or {}
        if not defizite:
            QMessageBox.information(
                self, t("Check shortfall"),
                t("Everything is covered \u2713\n\nHangar + pipeline + your remaining "
                  "runs cover the remaining need of every ingredient.\n(Calculated "
                  "against the REAL current stock, not the frozen state.)"))
            return
        z = [t("Working through the remaining runs, THIS WILL BE MISSING:"), ""]
        for tid, fehlt, bedarf, da, prod in defizite[:25]:
            _z = lambda n: f"{n:,}".replace(",", "'")   # noqa: E731
            z.append(t("{name}: {n} units   (remaining need {need}, on hand {have}, "
                       "remaining production {prod})").format(
                name=names.get(tid, f'#{tid}'), n=_z(fehlt), need=_z(bedarf),
                have=_z(da), prod=_z(prod)))
        z += ["",
              t("The cause is usually stock that was counted at freeze time and is "
                "gone by now (used/sold/counted as pipeline). The plan deliberately "
                "sticks to the frozen state so the shopping list stays stable \u2013 "
                "this preview is the honest counter-calculation."),
              t("\u2192 Buy the shortfalls OR push the affected reaction runs.")]
        dlg = QMessageBox(self)
        dlg.setWindowTitle(_txt("Check shortfall"))
        dlg.setIcon(QMessageBox.Warning)
        dlg.setText("\n".join(z))
        dlg.exec()

    def _prune_transactions(self):
        from PySide6.QtWidgets import QMessageBox
        from datetime import datetime, timedelta
        days = self.s_prune_period.currentData()
        cutoff = (datetime.utcnow() - timedelta(days=days)).strftime("%Y-%m-%d")
        r = QMessageBox.warning(
            self, t("Delete old transactions"),
            t("All transactions before {date} are permanently deleted.\n\nCareful: "
              "very old purchases are the cost basis (FIFO) for long-held items \u2013 "
              "their profit calculation may be incomplete afterwards. Continue?"
              ).format(date=cutoff),
            QMessageBox.Yes | QMessageBox.No, QMessageBox.No)
        if r != QMessageBox.Yes:
            return
        try:
            res = store.prune_transactions(cutoff)
            self._refresh_storage_stats()
            if hasattr(self, "_render_transactions"):
                self._render_transactions()
            self.statusBar().showMessage(
                t("{n} old transactions deleted.").format(
                    n=f"{res['removed']:,}".replace(",", "'")))
        except Exception as e:
            self.statusBar().showMessage(t("Delete error: ") + str(e))

    def _reload_pull_chars(self):
        if not hasattr(self, "s_pull_char"):
            return
        self.s_pull_char.blockSignals(True)
        self.s_pull_char.clear()
        for c in store.list_characters():
            icon = self._character_icon(c["character_id"], size=24)
            if icon:
                self.s_pull_char.addItem(icon, c["character_name"], c["character_id"])
            else:
                self.s_pull_char.addItem(c["character_name"], c["character_id"])
        # Gespeicherte Wahl wiederherstellen. Ohne das fiel die Auswahl nach
        # jedem Neustart auf den ERSTEN Charakter der Liste zurueck - der
        # Nutzer waehlte Lezaar, klickte Speichern, und beim naechsten Start
        # stand wieder jemand anderes drin (gemeldet).
        _want = self.settings.get("fees_char_id")
        if _want is not None:
            _ix = self.s_pull_char.findData(int(_want))
            if _ix >= 0:
                self.s_pull_char.setCurrentIndex(_ix)
        self.s_pull_char.blockSignals(False)
        # Nur EINMAL verbinden. Ein disconnect() ohne bestehende Verbindung
        # gibt in PySide eine RuntimeWarning aus (im Aufbau-Smoke-Test
        # aufgefallen) - ein Merker ist sauberer als Ausnahmen abzufangen.
        if not getattr(self, "_fees_char_connected", False):
            self.s_pull_char.currentIndexChanged.connect(self._save_fees_char)
            self._fees_char_connected = True

    def _save_fees_char(self, _i=0):
        """Die Charakter-Wahl fuer die Gebuehren-Berechnung festhalten."""
        cid = self.s_pull_char.currentData()
        if cid is None:
            return
        self.settings["fees_char_id"] = int(cid)
        config.save_settings(self.settings)

    def pull_best_char_skills(self):
        """Liest Accounting/Broker Relations + Standings ALLER verknüpften
        Charaktere und übernimmt automatisch den mit den niedrigsten
        Gebühren im aktiven Hub - für den Fall, dass man mehrere
        Charaktere hat und nicht mehr weiß, welcher fürs Traden am besten
        geskillt ist."""
        client_id = self.settings.get("client_id")
        chars = store.list_characters()
        if not client_id or not chars:
            if hasattr(self, "s_pull_status"):
                self.s_pull_status.setText(t("No linked characters."))
            return
        if hasattr(self, "s_pull_best_btn"):
            self.s_pull_best_btn.setEnabled(False)
        if hasattr(self, "s_pull_status"):
            self.s_pull_status.setText(
                t("Reading skills & standings of {n} characters \u2026").format(n=len(chars)))
        try:
            akey = hubs.hub_key_for_region(store.get_scan_region())
        except Exception:
            akey = "jita"
        own = hubs.HUB_OWNERS.get(akey, {})

        def job(progress=None):
            results = []
            for c in chars:
                cid = c["character_id"]
                try:
                    skills = esi.fetch_skills(client_id, cid)
                    standings = esi.fetch_standings(client_id, cid)
                    names = esi.resolve_entity_names([s.get("from_id") for s in standings])
                except Exception:
                    continue
                acc = int(skills.get(esi.SKILL_ACCOUNTING, 0) or 0)
                br = int(skills.get(esi.SKILL_BROKER_RELATIONS, 0) or 0)
                name_to_st = {names.get(s.get("from_id")): s.get("standing", 0.0)
                             for s in standings}
                fst = float(name_to_st.get(own.get("faction"), 0.0) or 0.0)
                cst = float(name_to_st.get(own.get("corp"), 0.0) or 0.0)
                tax = config.effective_sales_tax(acc)
                broker = config.effective_broker_fee(br, fst, cst)
                results.append({"cid": cid, "name": c.get("character_name", str(cid)),
                               "acc": acc, "br": br, "fst": fst, "cst": cst,
                               "tax": tax, "broker": broker, "combined": tax + broker,
                               "skills": skills, "standings": standings, "names": names})
            return results

        def done(results):
            if hasattr(self, "s_pull_best_btn"):
                self.s_pull_best_btn.setEnabled(True)
            if not results:
                if hasattr(self, "s_pull_status"):
                    self.s_pull_status.setText(
                        t(
                            "Could not read skills/standings for any character – the "
                              "scope may be missing, link again once."))
                return
            # ALLE Charaktere merken, nicht nur den Sieger - der Bauplan
            # laesst den Verkaufscharakter waehlen und braucht dessen Saetze.
            self.settings["char_fees"] = {
                str(r["cid"]): {"name": r["name"], "acc": r["acc"],
                                "br": r["br"], "tax": r["tax"],
                                "broker": r["broker"],
                                "combined": r["combined"]}
                for r in results}
            best = min(results, key=lambda r: r["combined"])
            # Den Sieger auch als DAUERHAFTE Wahl festhalten, nicht nur im
            # Dropdown anzeigen.
            self.settings["fees_char_id"] = int(best["cid"])
            # Genau dieselbe Übernahme-Logik wie beim manuellen "Aus EVE holen",
            # nur mit dem bereits geladenen Ergebnis statt neuem ESI-Abruf.
            self.settings["skill_accounting"] = best["acc"]
            self.settings["skill_broker_relations"] = best["br"]
            if hasattr(self, "s_accounting"):
                self.s_accounting.setValue(best["acc"])
            if hasattr(self, "s_broker_rel"):
                self.s_broker_rel.setValue(best["br"])
            if hasattr(self, "s_pull_char"):
                idx = self.s_pull_char.findData(best["cid"])
                if idx >= 0:
                    self.s_pull_char.setCurrentIndex(idx)
            name_to_st = {best["names"].get(s.get("from_id")): s.get("standing", 0.0)
                         for s in best["standings"]}
            hub_st = dict(self.settings.get("hub_standings", {}) or {})
            for key in hubs.HUB_OWNERS:
                o = hubs.HUB_OWNERS.get(key, {})
                cst = name_to_st.get(o.get("corp"))
                fst = name_to_st.get(o.get("faction"))
                cur = dict(hub_st.get(key, {}))
                if cst is not None:
                    cur["corp"] = float(cst)
                    if hasattr(self, "s_hub_corp") and key in self.s_hub_corp:
                        self.s_hub_corp[key].setValue(float(cst))
                if fst is not None:
                    cur["faction"] = float(fst)
                    if hasattr(self, "s_hub_faction") and key in self.s_hub_faction:
                        self.s_hub_faction[key].setValue(float(fst))
                if cur:
                    hub_st[key] = cur
            self.settings["hub_standings"] = hub_st
            config.save_settings(self.settings)
            self._sync_fees_to_hub()
            if hasattr(self, "_update_fee_preview"):
                self._update_fee_preview()
            _sorted = sorted(results, key=lambda r: r["combined"])
            _cmp = " · ".join(f"{r['name']}: {r['combined']:.2f}%" for r in _sorted[:4])
            msg = t("{name} has the lowest fees ({combined}% = {tax}% tax + "
                    "{broker}% broker) and was applied. Comparison: {cmp}").format(
                name=best['name'], combined=f"{best['combined']:.3f}",
                tax=f"{best['tax']:.3f}", broker=f"{best['broker']:.3f}", cmp=_cmp)
            if hasattr(self, "s_pull_status"):
                self.s_pull_status.setText(msg)
            self.statusBar().showMessage(msg)

        def fail(msg):
            if hasattr(self, "s_pull_best_btn"):
                self.s_pull_best_btn.setEnabled(True)
            if hasattr(self, "s_pull_status"):
                self.s_pull_status.setText(t("Error: ") + str(msg))

        self._run(Worker(job), done, fail_cb=fail,
                  label=t("Comparing characters \u2026"), overlay=True)

    def pull_skills_from_eve(self):
        cid = self.s_pull_char.currentData() if hasattr(self, "s_pull_char") else None
        if not cid:
            self.s_pull_status.setText(t(
                "No character linked – please log in under „Characters“ "
                  "first."))
            return
        self._pull_skills_for(cid, silent=False)

    def _pull_skills_for(self, cid, silent=False):
        """Fetch Accounting/Broker levels + standings for a character, fill the
        settings widgets, persist them and refresh the fee preview. Used by the
        button (silent=False) and automatically right after login (silent=True)."""
        client_id = self.settings.get("client_id")
        if hasattr(self, "s_pull_btn"):
            self.s_pull_btn.setEnabled(False)
        if not silent and hasattr(self, "s_pull_status"):
            self.s_pull_status.setText(t("Reading skills & standings from EVE \u2026"))

        def job(progress=None):
            skills = esi.fetch_skills(client_id, cid)
            standings = esi.fetch_standings(client_id, cid)
            names = esi.resolve_entity_names([s.get("from_id") for s in standings])
            return {"skills": skills, "standings": standings, "names": names}

        def done(res):
            if hasattr(self, "s_pull_btn"):
                self.s_pull_btn.setEnabled(True)
            skills = res["skills"]
            acc = skills.get(esi.SKILL_ACCOUNTING)
            br = skills.get(esi.SKILL_BROKER_RELATIONS)
            if acc is not None:
                self.settings["skill_accounting"] = int(acc)
                if hasattr(self, "s_accounting"):
                    self.s_accounting.setValue(int(acc))
            if br is not None:
                self.settings["skill_broker_relations"] = int(br)
                if hasattr(self, "s_broker_rel"):
                    self.s_broker_rel.setValue(int(br))
            name_to_st = {}
            for s in res["standings"]:
                nm = res["names"].get(s.get("from_id"))
                if nm:
                    name_to_st[nm] = s.get("standing", 0.0)
            hub_st = dict(self.settings.get("hub_standings", {}) or {})
            filled = 0
            for key in hubs.HUB_OWNERS:
                own = hubs.HUB_OWNERS.get(key, {})
                cst = name_to_st.get(own.get("corp"))
                fst = name_to_st.get(own.get("faction"))
                cur = dict(hub_st.get(key, {}))
                if cst is not None:
                    cur["corp"] = float(cst); filled += 1
                    if hasattr(self, "s_hub_corp") and key in self.s_hub_corp:
                        self.s_hub_corp[key].setValue(float(cst))
                if fst is not None:
                    cur["faction"] = float(fst); filled += 1
                    if hasattr(self, "s_hub_faction") and key in self.s_hub_faction:
                        self.s_hub_faction[key].setValue(float(fst))
                if cur:
                    hub_st[key] = cur
            self.settings["hub_standings"] = hub_st
            # persist immediately so every calculation uses the real values now
            config.save_settings(self.settings)
            self._sync_fees_to_hub()
            if hasattr(self, "_update_fee_preview") and hasattr(self, "s_fee_result"):
                self._update_fee_preview()
            msg = t("Taken from EVE: Accounting {acc}, Broker Relations {br}, "
                    "{n} standing values \u2013 saved automatically.").format(
                acc=acc if acc is not None else '\u2014',
                br=br if br is not None else '\u2014', n=filled)
            if hasattr(self, "s_pull_status"):
                self.s_pull_status.setText(msg)
            self.statusBar().showMessage(msg)

        def fail(msg):
            if hasattr(self, "s_pull_btn"):
                self.s_pull_btn.setEnabled(True)
            low = str(msg).lower()
            if "403" in low or "401" in low or "forbidden" in low or "scope" in low:
                txt = t("Skills could not be read \u2013 the token does not have the new "
                        "scopes yet. Please remove and re-link once in the Characters "
                        "tab.")
            else:
                txt = t("Error reading the skills: ") + str(msg)
            if hasattr(self, "s_pull_status"):
                self.s_pull_status.setText(txt)
            if silent:
                self.statusBar().showMessage(txt)

        self._run(Worker(job), done, fail_cb=fail, label=t("Reading skills & standings \u2026"),
                  overlay=not silent)

    def _update_fee_preview(self):
        """Live-compute per-hub fees. Sales tax is hub-independent (SCC); broker
        fee uses each hub's own standings. When 'from skills' is on, the ACTIVE
        scan hub's values are pushed into the (locked) manual tax/broker fields."""
        from_skills = bool(self.s_fees_skills.currentData())
        tax = config.effective_sales_tax(self.s_accounting.value())
        # per-hub broker fee
        for key in self.s_hub_corp:
            bf = config.effective_broker_fee(
                self.s_broker_rel.value(),
                self.s_hub_faction[key].value(), self.s_hub_corp[key].value())
            self.s_hub_fee_lbl[key].setText(f"{bf:.3f} %")
        # active hub (the current scan region)
        try:
            akey = hubs.hub_key_for_region(store.get_scan_region())
        except Exception:
            akey = "jita"
        active_broker = config.effective_broker_fee(
            self.s_broker_rel.value(),
            self.s_hub_faction[akey].value(), self.s_hub_corp[akey].value())
        alabel = dict((k, l) for k, l, _r, _s in hubs.NPC_HUBS).get(akey, "Jita")
        self.s_fee_result.setText(
            t("\u2192 active hub {hub}:  sales tax {tax} %  \u00b7  "
              "broker fee {broker} %").format(
                hub=alabel.split(" (")[0], tax=f"{tax:.3f}",
                broker=f"{active_broker:.3f}"))
        for wdg in [self.s_accounting, self.s_broker_rel] + \
                list(self.s_hub_corp.values()) + list(self.s_hub_faction.values()):
            wdg.setEnabled(from_skills)
        if from_skills:
            self.s_tax.setValue(tax)
            self.s_broker.setValue(active_broker)
        self.s_tax.setEnabled(not from_skills)
        self.s_broker.setEnabled(not from_skills)

    def _sync_fees_to_hub(self, region=None):
        """When fees come from skills, set the effective tax/broker for the given
        (or current) scan hub, so every calculation uses that hub's real fee."""
        if not self.settings.get("fees_from_skills"):
            return
        try:
            region = region if region is not None else store.get_scan_region()
        except Exception:
            return
        key = hubs.hub_key_for_region(region)
        st = (self.settings.get("hub_standings", {}) or {}).get(key, {})
        self.settings["sales_tax_pct"] = config.effective_sales_tax(
            self.settings.get("skill_accounting", 4))
        self.settings["broker_fee_pct"] = config.effective_broker_fee(
            self.settings.get("skill_broker_relations", 5),
            st.get("faction", 0.0), st.get("corp", 0.0))

    def createPopupMenu(self):
        """Qt-Override: das Fenster bietet KEIN Rechtsklick-Menue mehr an.

        QMainWindow baut hier von sich aus eine Liste aller Werkzeugleisten
        zum Aus- und Einblenden. Genau der Haken darin hat dem Nutzer die
        obere Leiste weggeschaltet (15.09.2026). Es gibt im Programm keinen
        Grund, eine Leiste zu verstecken - also gibt es das Menue nicht.

        SIEHT UNBENUTZT AUS, IST ES ABER NICHT: Qt ruft die Methode selbst,
        so wie `__lt__` und `validate` (s. Kopf von mw_basis.py). Nicht
        loeschen.
        """
        return None

    def _update_cb_label(self):
        self._cb_label.setText(
            t("Enter this callback URL in the ESI app:  ")
            + config.callback_url(int(self.s_port.value())))

    def _corp_division_sofort(self):
        """Eine Division an-/abgewaehlt: SOFORT speichern, wie die
        Berechtigungs-Schalter. Sie entscheidet mit, was der naechste
        Bauplan zaehlt - was man sieht, muss gelten."""
        neu = [n for n, c in self.s_corp_divs.items() if c.isChecked()]
        if list(self.settings.get("corp_divisions") or []) == neu:
            return
        self.settings["corp_divisions"] = neu
        config.save_settings(self.settings)
        self._einstellungen_stand_merken()
        self.statusBar().showMessage(
            t("Corp divisions saved: {n}").format(n=len(neu)) if neu
            else t("No corp division selected – corp hangars count nothing."))

    def _corp_division_namen_laden(self):
        """Division-Namen aus ESI holen und an die Kaestchen schreiben.

        Ueber den ERSTEN Charakter, der Corp-Scope und Director-Rolle hat -
        derselbe Abrufplan wie im Bauplan (corp.abrufplan). Findet sich
        keiner, sagt die Statuszeile warum, statt still nichts zu tun.
        """
        from .. import corp as _corp
        client_id = self.settings.get("client_id")
        chars = store.list_characters()
        if not client_id or not chars:
            self.statusBar().showMessage(t("No characters / client ID"))
            return

        def job():
            corp_von, rollen_von, relink = {}, {}, []
            for ch in chars:
                cid = ch["character_id"]
                corp_von[cid] = esi.fetch_character_corporation(cid)
                try:
                    _gs = esi.granted_scopes(client_id, cid)
                except Exception:
                    _gs = set()
                if (config.CORP_ROLES_SCOPE not in _gs
                        or config.CORP_DIVISIONS_SCOPE not in _gs):
                    relink.append(ch.get("character_name", str(cid)))
                    rollen_von[cid] = None
                    continue
                try:
                    rollen_von[cid] = esi.fetch_character_roles(client_id, cid)
                except Exception:
                    rollen_von[cid] = None
            plan, ohne = _corp.abrufplan(chars, corp_von, rollen_von,
                                         _corp.ROLLE_DIVISIONS)
            namen = {}
            for corp_id, cid in plan.items():
                namen[corp_id] = _corp.division_namen(
                    esi.fetch_corporation_divisions(client_id, cid, corp_id))
            return {"namen": namen, "relink": relink, "no_role": list(ohne)}

        def done(res):
            namen = res.get("namen") or {}
            if namen:
                # Bei mehreren Corps: Namen beider nebeneinander, getrennt
                # durch " / " - die Division-NUMMER ist das, was gilt.
                for n, cb in self.s_corp_divs.items():
                    _teile = [v.get(n) for v in namen.values() if v.get(n)]
                    cb.setText(" / ".join(_teile) if _teile
                               else t("Corp-Hangar {n}").format(n=n))
                self.statusBar().showMessage(t("Division names loaded."))
            elif res.get("relink"):
                self.statusBar().showMessage(t(
                    "Re-link {names} first – the login has no corp "
                    "permission yet.").format(names=", ".join(res["relink"])))
            else:
                self.statusBar().showMessage(t(
                    "No linked character holds the Director role – names "
                    "cannot be loaded."))

        self._run(Worker(job), done, err_prefix=t("Corp divisions"))

    def _scope_schalter_sofort(self, key, combo):
        """Einen Berechtigungs-Schalter SOFORT uebernehmen und speichern.

        Sitzung 17: vorher galt er erst nach "Save" - wer umstellte und direkt
        neu verlinkte, bekam die Berechtigung nicht. Der Hinweis sagt, was
        noch zu tun ist: EVE erteilt eine neue Berechtigung nur beim Verlinken.
        """
        neu = bool(combo.currentData())
        if bool(self.settings.get(key)) == neu:
            return
        self.settings[key] = neu
        config.save_settings(self.settings)
        # Dieser Schalter hat sich SELBST gespeichert - er darf den
        # Seitenwechsel nicht als "ungespeichert" blockieren.
        self._einstellungen_stand_merken()
        if neu and key == "use_location":
            self.statusBar().showMessage(t(
                "Switched on and saved. Add esi-location.read_location.v1 to your "
                "EVE app, then re-link your character (Characters tab)."))
        elif neu:
            self.statusBar().showMessage(t(
                "Switched on and saved. Now re-link your character (Characters "
                "tab) so EVE grants the permission."))
        else:
            self.statusBar().showMessage(t("Switched off and saved."))
        if key == "use_location":
            self._standort_pruefen()
        if key == "use_assets" and store.list_characters():
            self.refresh_all()

    def save_settings(self):
        old_assets = self.settings.get("use_assets", False)
        new_assets = bool(self.s_source.currentData())
        old_implants = self.settings.get("use_implants", False)
        new_implants = bool(self.s_implants.currentData())
        from_skills = bool(self.s_fees_skills.currentData())
        # collect per-hub standings
        hub_standings = {}
        for key in self.s_hub_corp:
            hub_standings[key] = {
                "corp": float(self.s_hub_corp[key].value()),
                "faction": float(self.s_hub_faction[key].value()),
            }
        # if fees come from skills, derive tax + the ACTIVE hub's broker fee
        if from_skills:
            tax = config.effective_sales_tax(self.s_accounting.value())
            try:
                akey = hubs.hub_key_for_region(store.get_scan_region())
            except Exception:
                akey = "jita"
            broker = config.effective_broker_fee(
                self.s_broker_rel.value(),
                hub_standings.get(akey, {}).get("faction", 0.0),
                hub_standings.get(akey, {}).get("corp", 0.0))
        else:
            tax = float(self.s_tax.value())
            broker = float(self.s_broker.value())
        self.settings.update({
            "client_id": self.s_client.text().strip(),
            "callback_port": int(self.s_port.value()),
            "target_margin": float(self.s_margin.value()),
            "sales_tax_pct": tax,
            "broker_fee_pct": broker,
            "structure_broker_pct": float(self.s_sbroker.value()),
            "fees_from_skills": from_skills,
            "skill_accounting": int(self.s_accounting.value()),
            "skill_broker_relations": int(self.s_broker_rel.value()),
            "hub_standings": hub_standings,
            "sell_mode": self.s_mode.currentData(),
            "use_assets": new_assets,
            "use_structures": bool(self.s_struct.currentData()),
            "use_ui": bool(self.s_ui.currentData()),
            "use_implants": bool(self.s_implants.currentData()),
            "use_location": bool(self.s_location.currentData()),
            "use_corp": bool(self.s_corp.currentData()),
            "corp_divisions": [n for n, c in self.s_corp_divs.items()
                               if c.isChecked()],
        })
        config.save_settings(self.settings)
        # STAND NACHZIEHEN (Nutzer, 15.09.2026): ohne das gaelten die eben
        # gespeicherten Werte weiter als "offen", und die Rueckfrage kaeme
        # beim naechsten Seitenwechsel trotz Speichern.
        self._einstellungen_stand_merken()
        self._update_cb_label()
        if new_assets and not old_assets:
            self.statusBar().showMessage(t(
                "Inventory enabled. Important: add scope esi-assets.read_assets.v1 "
                "in the app AND re-link the character for it to take effect."))
        elif new_implants and not old_implants:
            self.statusBar().showMessage(t(
                "Implant detection enabled. Important: add scope "
                "esi-clones.read_implants.v1 in the app AND re-link the character "
                "for it to take effect."))
        else:
            self.statusBar().showMessage(t("Settings saved."))
        if new_assets != old_assets and store.list_characters():
            self.refresh_all()
        else:
            self._recompute()

    # ---- data refresh ------------------------------------------------------
    def refresh_everything(self, *, beim_start=False):
        """Smart central refresh: always your data + prices; the big 13k Jita scan
        only when its cache is stale (older than 6h) or missing. The scan is
        chained AFTER the portfolio refresh (not run concurrently) to avoid two
        heavy background threads racing."""
        # VORGEHALTENE SERVERWEITE LISTEN VERWERFEN (Sitzung 20): Marktpreise
        # und Systemkostenindex werden 15 Minuten wiederverwendet, damit das
        # Oeffnen eines Bauplans nicht jedes Mal zwei grosse Abrufe kostet.
        # Wer hier drueckt, will ausdruecklich frische Zahlen - also weg damit.
        try:
            esi.cache_leeren()
        except Exception:
            pass
        # Ohne verknüpfte Charaktere kann NICHTS von deinen persönlichen Daten
        # (Wallet/Orders/Portfolio) aktualisiert werden -- aber ein reiner Jita-
        # Markt-Scan (für Scanner/Deals) geht trotzdem. Statt still nur eine
        # Statuszeile zu setzen (leicht übersehen), klar per Popup hinweisen und
        # beide sinnvollen Optionen anbieten.
        if not store.list_characters():
            box = QMessageBox(self)
            box.setIcon(QMessageBox.Information)
            box.setWindowTitle(t("No character linked"))
            box.setText(t("No EVE character is linked yet."))
            box.setInformativeText(
                t("For wallet, orders and portfolio you need at least one linked "
                  "character. You can scan the Jita market without a character too "
                  "(for scanner & deals)."))
            go_btn = box.addButton(t("Link character"), QMessageBox.AcceptRole)
            scan_btn = box.addButton(t("Scan market only"), QMessageBox.ActionRole)
            box.addButton(t("Cancel"), QMessageBox.RejectRole)
            box.exec()
            clicked = box.clickedButton()
            if clicked is go_btn:
                self._go_tab("characters")
            elif clicked is scan_btn:
                self.scan_jita()
                self.update_ages()
            return
        age = store.snapshot_age_seconds()
        # BEIM START SCHON AB EINER STUNDE (Nutzer 27.09.2026: "jetzt blinkt
        # danach Market scan - sind die Preise beim ersten Oeffnen noch nicht
        # aktuell?" -> "mach das"). Vorher: Warnung ab 1 h, automatischer
        # Scan erst ab 6 h - dazwischen blinkte es, ohne dass etwas geschah.
        # Beim Start laeuft der Scan im Hintergrund (Anzeige oben), der Knopf
        # "Refresh" bleibt bei 6 h und mit Lade-Fenster.
        _grenze = self._SCAN_ALT_SEKUNDEN if beim_start else 6 * 3600
        need_scan = age is None or age > _grenze
        self._scan_im_hintergrund = bool(beim_start)
        if self.settings.get("client_id"):
            self._scan_after_refresh = need_scan
            self.refresh_all(overlay=not beim_start)
        elif need_scan:
            self.scan_jita()
        elif not need_scan:
            self.statusBar().showMessage(
                t("Jita scan still fresh ({age}) \u2013 cache used.").format(age=self._age_str(age)))
        self.update_ages()

    @staticmethod
    def _age_str(sec):
        # PLATZHALTER BLEIBEN AUSSERHALB DES KATALOGS (Sitzung 12): der Text
        # wird uebersetzt, die Zahl danach eingesetzt. Sonst braeuchte jede
        # moegliche Minutenzahl eine eigene Zeile im Woerterbuch.
        if sec is None:
            return t("never")
        if sec < 90:
            return t("just now")
        if sec < 3600:
            return t("{n} min ago").format(n=int(sec / 60))
        if sec < 86400:
            return t("{n} h ago").format(n=int(sec / 3600))
        return t("{n} d ago").format(n=int(sec / 86400))

    def update_ages(self):
        import time as _t
        try:
            tx = store.tx_age_seconds()
            sn = store.snapshot_age_seconds()
        except Exception:
            return
        price_age = (_t.time() - self._prices_ts) if getattr(self, "_prices_ts", 0) else None
        _n_live = int(getattr(self, "_prices_live_n", 0) or 0)
        self.age_label.setText(
            f"{t('Prices (live)')}: {self._age_str(price_age)}"
            + (" (" + t("{n} of your items").format(n=_n_live) + ")" if _n_live else "")
            + "   ·   "
            f"{t('Portfolio')}: {self._age_str(tx)}   ·   "
            f"{t('Market scan')}: {self._age_str(sn)}")

    def _rebuild_asset_totals(self):
        """Build per-character {type_id: qty}, excluding ignored containers."""
        ignored = store.ignored_containers()
        self._assets_by_char = {}
        for cid, st in getattr(self, "_assets_struct", {}).items():
            totals = dict(st["hangar"])
            for c in st["containers"]:
                if c["item_id"] in ignored:
                    continue
                for tid, q in c["contents"].items():
                    totals[tid] = totals.get(tid, 0) + q
            self._assets_by_char[cid] = totals

    # DECKEL fuer die Live-Preise beim Portfolio-Refresh: je Item ein ESI-
    # Abruf. Mehr als das ist kein Portfolio mehr, sondern ein Markt-Scan -
    # und den gibt es schon. Bewusst gesetzt, nicht gemessen.
    PORTFOLIO_LIVE_MAX = 400

    @staticmethod
    def _portfolio_live_ids(assets_struct, ignored, all_tx, orders_je_char):
        """Welche Items bekommen beim Portfolio-Refresh einen LIVE-Preis?
        (Nutzer 27.09.2026: "ich frage mich, ob die Logik dahinter sinnvoll
        ist" - der Knopf nahm alle Preise aus dem letzten Markt-Scan, bis
        zu 6 h alt.) Was du HAST (Assets ohne ignorierte Container) und was
        in deinen OFFENEN ORDERS steht. Ohne Asset-Daten: die Items, von
        denen die Transaktionen einen positiven Bestand ergeben."""
        ids = set()
        for st in (assets_struct or {}).values():
            ids |= {int(k) for k in (st.get("hangar") or {})}
            for c in st.get("containers") or []:
                if c.get("item_id") in (ignored or ()):
                    continue
                ids |= {int(k) for k in (c.get("contents") or {})}
        for v in (orders_je_char or {}).values():
            ids |= {int(x) for x in (v.get("buy") or ())}
            ids |= {int(x) for x in (v.get("sell") or ())}
        if not any((st.get("hangar") or st.get("containers"))
                   for st in (assets_struct or {}).values()):
            netto = {}
            for tx in all_tx or []:
                q = int(tx.get("quantity", 0) or 0)
                netto[int(tx["type_id"])] = netto.get(int(tx["type_id"]), 0) + (
                    q if tx.get("is_buy") else -q)
            ids |= {k for k, v in netto.items() if v > 0}
        return ids

    def _portfolio_live_preise(self, prices, type_ids):
        """Live-Preise fuer `type_ids` vom Hub, aus dem das Portfolio seine
        Preise nimmt (`store.get_hub_source`, nur NPC-Hubs - fuer eine
        Struktur gibt es keinen Einzel-Abruf je Item). Ueberschreibt in
        `prices` NUR die Seite, fuer die es gerade Orders gibt; eine leere
        Seite laesst den Scan-Wert stehen. Gibt die Zahl der live
        bepreisten Items zurueck (0 = alles aus dem Scan)."""
        src = str(store.get_hub_source() or "")
        if not src.startswith("hub:") or not type_ids:
            return 0
        try:
            region = int(src.split(":", 1)[1])
        except (TypeError, ValueError):
            return 0
        station = next((st for _k, _l, rg, st in hubs.NPC_HUBS if rg == region), None)
        if station is None:
            return 0
        ids = sorted(int(x) for x in type_ids)[:self.PORTFOLIO_LIVE_MAX]
        import concurrent.futures as _cf

        def _hole(tid):
            try:
                return tid, esi.fetch_type_orders(tid, station=station, region=region)
            except Exception:
                return tid, None
        n = 0
        with _cf.ThreadPoolExecutor(max_workers=8) as ex:
            for tid, lad in ex.map(_hole, ids):
                if lad is None:
                    continue
                alt = dict(prices.get(tid) or {"buy_max": 0.0, "sell_min": 0.0})
                if lad.get("sell"):
                    alt["sell_min"] = float(lad["sell"][0][0])
                if lad.get("buy"):
                    alt["buy_max"] = float(lad["buy"][0][0])
                prices[tid] = alt
                n += 1
        return n

    def refresh_all(self, *, overlay=True):
        from ..sprache import t as _txt   # `_ti` ist hier lokal belegt
        chars = store.list_characters()
        if not chars:
            self.statusBar().showMessage(_txt("No characters linked."))
            return
        if not self.settings.get("client_id"):
            self.statusBar().showMessage(_txt("Client ID missing \u2013 see settings."))
            return
        self.refresh_btn.setEnabled(False)
        self.statusBar().showMessage(_txt("Importing transactions + prices \u2026"))
        cid_list = [c["character_id"] for c in chars]
        client_id = self.settings["client_id"]
        max_min = self.settings["tx_cache_minutes"]

        def job():
            for cid in cid_list:
                # DAS NACHHOLEN STEHT VOR DER FRISCHE-SPERRE (Sitzung 17,
                # zweite Runde): sonst laeuft es beim Start NIE, solange die
                # Transaktionen frisch sind - und genau dann fehlen die alten
                # Kaeufe weiter. Es kostet nichts: ist ESI erschoepft, merkt
                # sich das die DB und der Aufruf kehrt sofort zurueck.
                self._tx_altes_nachholen(client_id, cid)
                if not store.tx_is_fresh(cid, max_min):
                    txs = esi.fetch_wallet_transactions(
                        client_id, cid,
                        stop_at_id=store.newest_transaction_id(cid))
                    store.save_transactions(cid, txs)
                    try:
                        store.save_journal(cid,
                            esi.fetch_wallet_journal(client_id, cid))
                    except Exception:
                        pass
                    store.set_tx_synced(cid)
            all_tx = store.get_transactions()
            type_ids = {_ti["type_id"] for _ti in all_tx}

            assets_struct = {}
            assets_ok = False
            if self.settings.get("use_assets"):
                for cid in cid_list:
                    try:
                        st = esi.fetch_assets_structured(client_id, cid)
                        assets_struct[cid] = st
                        assets_ok = True
                        type_ids |= set(st["hangar"].keys())
                        for c in st["containers"]:
                            type_ids |= set(c["contents"].keys())
                            type_ids.add(c["type_id"])
                    except Exception:
                        assets_struct[cid] = {"hangar": {}, "containers": []}
            esi.resolve_names(type_ids)
            # Preise aus dem ESI-Markt-Snapshot - EINE Preisquelle fürs ganze
            # Tool. Vorher kam hier der Fuzzwork-Aggregator (Drittanbieter,
            # hinkt ESI Minuten bis Stunden hinterher) zum Einsatz: Verstoß
            # gegen die Grundregel "nur ESI/SDE" UND die einzige Stelle mit
            # einer ZWEITEN Preisquelle - Portfolio-Margen konnten dadurch
            # systematisch von Bauplan/Daytrade/Swing abweichen.
            # PORTFOLIO IMMER AUS DER HUB-QUELLE (Sitzung 9): dort wird
            # verkauft, und ein Struktur-Scan darf die Bewertung nicht
            # mehr verfaelschen.
            _snap = store.get_snapshot(store.get_hub_source())
            prices = {s["type_id"]: {"buy_max": s["buy_max"],
                                     "sell_min": s["sell_min"]}
                      for s in _snap}
            snap_age = store.snapshot_age_seconds(store.get_hub_source())

            # normal price level (median over 90d) for items we actually hold,
            # used for the green "return to normal → sell" signal
            ignored = store.ignored_containers()
            held_ids = set(_ti["type_id"] for _ti in all_tx)
            for cid, st in assets_struct.items():
                held_ids |= set(st["hangar"].keys())
                for c in st["containers"]:
                    if c["item_id"] in ignored:
                        continue
                    held_ids |= set(c["contents"].keys())
            normals = {}
            import concurrent.futures as _cf

            def _normal(_ti):
                try:
                    ts = scanner.trend_stats(scanner.history_cached(_ti), 90)
                    return _ti, ts.get("normal") or 0
                except Exception:
                    return _ti, 0
            if held_ids:
                with _cf.ThreadPoolExecutor(max_workers=6) as ex:
                    for _ti, n in ex.map(_normal, list(held_ids)):
                        if n:
                            normals[_ti] = n
            # wallet balance + open orders per character → total wealth
            wallet = {}
            orders = {}
            # AUCH HIER JE CHARAKTER (dieselbe Quelle wie
            # `_fetch_open_orders`, siehe `_orders_uebernehmen`) - sonst
            # haette der grosse Scan die Order-Auskunft wieder flachgeklopft
            # und das Portfolio zeigte nach einem "Refresh all" erneut die
            # Orders fremder Charaktere auf dem eigenen Bestand.
            orders_je_char = {}
            for cid in cid_list:
                try:
                    wallet[cid] = esi.fetch_wallet_balance(client_id, cid)
                except Exception:
                    wallet[cid] = 0.0
                sell_value = 0.0
                buy_escrow = 0.0
                _b, _s = set(), set()
                try:
                    for o in esi.fetch_character_orders(client_id, cid):
                        tid = o.get("type_id")
                        if o.get("is_buy_order"):
                            buy_escrow += float(o.get("escrow", 0) or 0)
                            if tid:
                                _b.add(int(tid))
                        else:
                            sell_value += float(o.get("price", 0) or 0) * \
                                int(o.get("volume_remain", 0) or 0)
                            if tid:
                                _s.add(int(tid))
                except Exception:
                    pass
                orders_je_char[int(cid)] = {"buy": _b, "sell": _s}
                orders[cid] = {"sell_value": sell_value, "buy_escrow": buy_escrow}
            live_n = self._portfolio_live_preise(
                prices, self._portfolio_live_ids(assets_struct, ignored, all_tx,
                                                 orders_je_char))
            return {"prices": prices, "assets_struct": assets_struct,
                    "assets_ok": assets_ok, "normals": normals,
                    "wallet": wallet, "orders": orders,
                    "orders_je_char": orders_je_char,
                    "snap_missing": not _snap, "snap_age": snap_age,
                    "live_n": live_n}

        def done(res):
            import time as _t
            self._hintergrund_laden_zeigen(False)
            self._log_step("done: start")
            self._prices = res["prices"]
            # EHRLICHES PREIS-ALTER (Nutzer 27.09.2026): vorher stand hier
            # immer "jetzt", auch wenn alle Preise aus einem bis zu 6 h alten
            # Scan kamen. Jetzt: live geholt -> jetzt; sonst das Alter des
            # Scans, aus dem die Preise stammen.
            self._prices_live_n = int(res.get("live_n") or 0)
            if self._prices_live_n:
                self._prices_ts = _t.time()
            elif res.get("snap_age") is not None:
                self._prices_ts = _t.time() - float(res["snap_age"])
            else:
                self._prices_ts = 0
            self._assets_struct = res["assets_struct"]
            self._assets_ok = res["assets_ok"]
            self._normal_levels = res.get("normals", {})
            self._wallet = res.get("wallet", {})
            self._orders = res.get("orders", {})
            self._orders_uebernehmen(res.get("orders_je_char") or {})
            self._log_step(f"done: rebuild_asset_totals (assets_struct={len(self._assets_struct)})")
            self._rebuild_asset_totals()
            self.refresh_btn.setEnabled(True)
            self._log_step("done: render_containers")
            self._render_containers()
            self._log_step("done: recompute")
            self._recompute()
            self._log_step("done: update_ages")
            self.update_ages()
            self._log_step("done: finished")
            src = (_txt("Inventory") if (self._assets_ok and
                   self.settings.get("use_assets")) else _txt("Transactions"))
            self.statusBar().showMessage(
                t("Updated ({src}): ").format(src=src) + dt.datetime.now().strftime("%H:%M:%S"))
            if self.settings.get("use_assets") and not self._assets_ok:
                self.statusBar().showMessage(_txt(
                    "Inventory scope missing \u2013 using transactions. Add the scope in "
                    "the app + re-link the character."))
            if res.get("snap_missing"):
                self.statusBar().showMessage(_txt(
                    "\u26a0 No market snapshot \u2013 portfolio without prices. Please run "
                    "\u201eMarket scan\u201c once."))
            elif (res.get("snap_age") and res["snap_age"] > 6 * 3600
                  and not res.get("live_n")):
                # Nur ohne Live-Preise - mit ihnen stimmt der Satz nicht mehr.
                self.statusBar().showMessage(_txt(
                    "\u2139 Portfolio prices from the market snapshot of {h} h ago \u2013 "
                    "rescan for current margins.").format(h=int(res['snap_age'] // 3600)))
            # Preisquelle EHRLICH ausweisen: die Spalte hieß hart "Jita Sell",
            # obwohl der Snapshot vom oben gewählten Hub stammt (auch Keepstar).
            # Jetzt zeigt der Spaltenkopf den echten Quell-Hub - und wenn oben
            # inzwischen ein ANDERER Hub gewählt ist als der gescannte, warnt
            # die Statuszeile, statt still mit alten Preisen zu vergleichen
            # (Nutzer-Fall: Daytrade-Orders in 4-HWWF gegen Jita-Preise).
            _scan_lbl = store.get_scan_label()
            _hdr = self.pf_table.horizontalHeaderItem(4)
            if _hdr is not None:
                _hdr.setText("Sell @ " + self._short_hub_label(_scan_lbl))
                _hdr.setToolTip(_txt("Sell price from the market scan of: {when}").format(when=_scan_lbl))
            _cur_lbl = self._active_hub_label()
            if (not res.get("snap_missing") and _scan_lbl and _cur_lbl
                    and self._short_hub_label(_scan_lbl)
                    != self._short_hub_label(_cur_lbl)):
                self.statusBar().showMessage(_txt(
                    "\u26a0 Portfolio/sell list compare against \u201e{scan}\u201c (last "
                    "scan) \u2013 \u201e{cur}\u201c is selected above. Run a market scan to "
                    "compare against {short}.").format(
                    scan=_scan_lbl, cur=_cur_lbl, short=self._short_hub_label(_cur_lbl)))
            # run the heavy Jita scan only now (chained, not concurrent)
            if getattr(self, "_scan_after_refresh", False):
                self._scan_after_refresh = False
                QTimer.singleShot(0, self._scan_nach_refresh)

        def fail(msg):
            self._hintergrund_laden_zeigen(False)
            self.refresh_btn.setEnabled(True)
            self.statusBar().showMessage(t("Error: ") + msg)
            if getattr(self, "_scan_after_refresh", False):
                self._scan_after_refresh = False
                QTimer.singleShot(0, self._scan_nach_refresh)
        self._run(Worker(job), done, fail_cb=fail, label=_txt("Refreshing portfolio + prices …"),
                  overlay=overlay)
        # ERST NACH _run: dann steht der Job schon in _workers - sonst haette
        # die Sicherung in _lade_tick die Anzeige sofort wieder geloescht
        # (b126 fand genau das).
        if not overlay:
            self._hintergrund_laden_zeigen(True)

    def _hintergrund_laden_zeigen(self, an, was="portfolio"):
        """Arbeit im Hintergrund sichtbar machen: Anzeige oben; beim
        Portfolio sagt ausserdem der Leer-Hinweis "wird geladen" statt
        "Nothing here yet / Market scan" (Nutzer-Bildschirm 27.09.2026).
        was: "portfolio" oder "scan" (Markt-Scan beim Start)."""
        import time as _tz
        self._portfolio_laedt = bool(an) and was == "portfolio"
        self._lade_was = was
        lbl = getattr(self, "g_lade_lbl", None)
        takt = getattr(self, "_lade_takt", None)
        if lbl is not None and takt is not None:
            if an:
                lbl.setToolTip(
                    t("The market scan runs in the background. Daytrade, Swing "
                      "Trade and Regional Trading fill in afterwards.")
                    if was == "scan" else
                    t("Wallet, assets, orders and prices are being fetched from ESI in "
                      "the background. You can already use the tool."))
                self._lade_t0 = _tz.monotonic()
                lbl.setVisible(True)
                self._lade_tick()
                takt.start()
            else:
                takt.stop()
                lbl.setVisible(False)
        self._leerhinweise_aktualisieren()

    def _lade_tick(self):
        import time as _tz
        lbl = getattr(self, "g_lade_lbl", None)
        if lbl is None:
            return
        # SICHERUNG: laeuft gar kein Job mehr (etwa weil ein Rueckruf
        # verworfen wurde), verschwindet die Anzeige von selbst.
        if not getattr(self, "_workers", None):
            self._hintergrund_laden_zeigen(False)
            return
        _s = int(_tz.monotonic() - getattr(self, "_lade_t0", _tz.monotonic()))
        if getattr(self, "_lade_was", "portfolio") == "scan":
            lbl.setText(t("\u27f3 Market scan \u2026 {s} s").format(s=_s))
        else:
            lbl.setText(t("\u27f3 Loading portfolio + prices \u2026 {s} s").format(s=_s))

    def _log_step(self, msg):
        """Append a timestamped line to a perf log so we can see which step hangs
        even when the UI freezes."""
        try:
            import time as _t
            with open(os.path.join(config.app_data_dir(), "motor_market_perf.log"),
                      "a", encoding="utf-8") as f:
                f.write(f"{_t.strftime('%H:%M:%S')} {msg}\n")
        except Exception:
            pass

    def _recompute(self):
        self._fracht_cache = None      # neue Transaktionen -> Fracht neu
        prices = getattr(self, "_prices", {})
        assets_by_char = getattr(self, "_assets_by_char", {})
        use_assets = (self.settings.get("use_assets", False)
                      and getattr(self, "_assets_ok", False))
        all_assets = {}
        for a in assets_by_char.values():
            for tid, q in a.items():
                all_assets[tid] = all_assets.get(tid, 0) + q
        # Namens-Universum = Snapshot ∪ Transaktionen ∪ ASSETS. Vorher stand
        # hier `prices.keys() or tx` - sobald ein Snapshot existierte, wurden
        # NUR Snapshot-IDs aus dem Cache geholt: per Inventar-Import gehaltene
        # Items, die gerade nicht am Hub gelistet sind (Abyssals, Filamente,
        # Spezialitems), zeigten "#12345", selbst wenn ihr Name längst im
        # Cache lag (Nutzer-Screenshot Portfolio).
        _tid_universe = (set(prices.keys())
                         | {t["type_id"] for t in store.get_transactions()}
                         | set(all_assets))
        names = store.cached_names(list(_tid_universe))
        # Selbstheilung: was trotz Cache namenlos ist (z.B. weil die Auflösung
        # im Refresh am Rate-Limit scheiterte), einmal still im Hintergrund
        # nachziehen und danach neu rendern - pro ID nur EIN Versuch je
        # Sitzung (kein Endlos-Loop bei wirklich unauflösbaren IDs).
        _attempted = getattr(self, "_name_fix_attempted", set())
        _missing = sorted(t for t in _tid_universe
                          if t not in names and t not in _attempted)
        if _missing:
            self._name_fix_attempted = _attempted | set(_missing)
            _w = Worker(esi.resolve_names, _missing)
            self._run(_w, lambda res: (res and self._recompute()),
                      fail_cb=lambda _m: None, overlay=False)

        def build(transactions, assets):
            if use_assets:
                h = market.holdings_from_assets(assets, transactions)
            else:
                h = market.aggregate_holdings(transactions)
            return market.evaluate(h, names, prices, self.settings)
        self._log_step(f"recompute: build holdings (all_assets={len(all_assets)})")
        self._holdings = build(store.get_transactions(), all_assets)
        self._holdings_by_char = {}
        for c in store.list_characters():
            cid = c["character_id"]
            self._holdings_by_char[cid] = build(
                store.get_transactions(cid), assets_by_char.get(cid, {}))
        self._log_step(f"recompute: reload_market_items (holdings={len(self._holdings)})")
        self._reload_market_items(names)
        self._log_step(f"recompute: render_portfolio (holdings={len(self._holdings)})")
        self._render_portfolio()
        self._log_step("recompute: render_transactions")
        self._render_transactions()
        self._log_step("recompute: render_profit")
        self._render_profit()
        self._log_step("recompute: done")

    def _reload_market_items(self, names):
        current = self.mk_item.currentData()
        self.mk_item.blockSignals(True)
        self.mk_item.clear()
        seen = set()
        # only your holdings go into the dropdown (a handful of items). Adding the
        # full ~13k snapshot here froze the UI; the field is editable, so any other
        # item can still be found by typing its name (resolved via ESI).
        for h in sorted(self._holdings, key=lambda x: x.name):
            if h.type_id not in seen:
                self.mk_item.addItem(h.name, h.type_id)
                seen.add(h.type_id)
        idx = self.mk_item.findData(current)
        if idx >= 0:
            self.mk_item.setCurrentIndex(idx)
        self.mk_item.blockSignals(False)
        self._mk_namen_laden()

    _MK_STARTITEM = "Acolyte II"

    def _mk_auto_start(self):
        """Beim Oeffnen des Preisverlaufs ohne Graph: zuletzt angesehenes
        Item, sonst das erste aus dem Bestand - statt einer leeren Flaeche
        (Nutzer 18.09.2026: "standardmaessig sollte ein Item aufgehen")."""
        if getattr(self, "_mk_full", None) or getattr(self, "_mk_auto_lief", False):
            return
        self._mk_auto_lief = True
        _letzt = self.settings.get("mk_last_item") or None
        tid = None
        if isinstance(_letzt, (list, tuple)) and len(_letzt) == 2:
            try:
                tid = int(_letzt[0])
                if self.mk_item.findData(tid) < 0:
                    self.mk_item.addItem(str(_letzt[1]), tid)
            except (TypeError, ValueError):
                tid = None
        if tid is None:
            # KEIN gemerktes Item: "Acolyte II" - das Item, zu dem auch das
            # Tutorial fuehrt (Nutzer 18.09.2026: "sonst hat man ein leeres
            # Fenster vor sich und ist schnell frustriert"). Ueber den NAMEN
            # aufgeloest (Namens-Cache, sonst ESI), keine Type-ID im Code.
            self.mk_item.setEditText(self._MK_STARTITEM)
            self._plot_history()
            return
        self.mk_item.blockSignals(True)
        self.mk_item.setCurrentIndex(self.mk_item.findData(tid))
        self.mk_item.blockSignals(False)
        self._do_plot(tid)

    def _mk_namen_laden(self):
        """Namens-Cache in das Completer-Modell des Preisverlaufs laden."""
        try:
            _echt = {str(n): int(i) for i, n in store.all_names().items() if n}
        except Exception:
            _echt = {}
        for h in getattr(self, "_holdings", []) or []:
            _echt.setdefault(h.name, h.type_id)
        self._mk_namen_ids = _echt
        self._mk_namen_modell.setStringList(sorted(_echt, key=str.lower))

    def _mk_name_gewaehlt(self, text):
        """Eintrag aus der Vervollstaendigung: Item in die Combo, dann zeichnen."""
        tid = self._mk_namen_ids.get(text)
        if tid is None:
            return
        if self.mk_item.findData(tid) < 0:
            self.mk_item.addItem(text, tid)
        self.mk_item.setCurrentIndex(self.mk_item.findData(tid))
        self._do_plot(tid)

    def _standort_pruefen(self):
        """Steht der oben gewaehlte Charakter am oben gewaehlten Hub? (emm313)

        Fragt ESI im Hintergrund (Standort, 5 s Cache) - nur mit Schalter
        `use_location`, nur fuer EINEN gewaehlten Charakter. Ohne Scope sagt
        das Feld leise, dass neu verknuepft werden muss; weiss man nichts,
        bleibt es leer (keine Meldung ist besser als eine falsche)."""
        from .mw_helpers import hub_ort_id
        _lbl = getattr(self, "g_ort_warn", None)
        if _lbl is None:
            return
        cid = self.g_char.currentData() if hasattr(self, "g_char") else None
        hub_id = hub_ort_id(self.g_hub.currentData()) if hasattr(self, "g_hub") else None
        client_id = self.settings.get("client_id")
        if (not self.settings.get("use_location") or cid in (None, "all")
                or not hub_id or not client_id):
            self._ort_zeigen(False)
            return
        if getattr(self, "_ort_job_laeuft", False):
            return
        self._ort_job_laeuft = True
        _hub_lbl = self.g_hub.currentText()
        _name = self.g_char.currentText().strip()

        def job():
            if config.LOCATION_SCOPE not in (esi.granted_scopes(client_id, cid) or set()):
                return {"scope": False}
            _ort = esi.fetch_character_location(client_id, cid) or {}
            try:
                _nm = esi.orts_namen([_ort.get("station_id"),
                                      _ort.get("solar_system_id")])
            except Exception:
                _nm = {}
            return {"scope": True, "ort": _ort, "namen": _nm}

        def done(res):
            self._ort_job_laeuft = False
            self._standort_anzeigen(res, cid, hub_id, _hub_lbl, _name)

        def fail(msg):
            self._ort_job_laeuft = False
            self._ort_zeigen(False)
            self._log_exception("Standort-Hinweis", str(msg))
        self._run(Worker(job), done, fail_cb=fail, overlay=False)

    def _standort_anzeigen(self, res, cid, hub_id, hub_lbl, name):
        """Ergebnis von _standort_pruefen ins Feld neben dem Charakter."""
        from .mw_helpers import hub_ort_id, standort_am_hub
        _lbl = getattr(self, "g_ort_warn", None)
        if _lbl is None:
            return
        # Inzwischen umgestellt? Dann gilt die Antwort nicht mehr.
        if (self.g_char.currentData() != cid
                or hub_ort_id(self.g_hub.currentData()) != hub_id):
            return
        if not (res or {}).get("scope"):
            _lbl.setStyleSheet(f"color:{theme.MUTED}; padding:0 8px;")
            _lbl.setText(t("Location: re-link"))
            _lbl.setToolTip(t(
                "The location hint is on, but {name} was linked without the "
                "location permission. Add esi-location.read_location.v1 to your "
                "EVE app and link the character again (Characters).").format(name=name))
            self._ort_zeigen(True)
            return
        _ort = res.get("ort") or {}
        _da = standort_am_hub(_ort, hub_id)
        if _da is None or _da:
            self._ort_zeigen(False)
            return
        _nm = res.get("namen") or {}
        if _ort.get("station_id"):
            _wo = _nm.get(int(_ort["station_id"])) or str(_ort["station_id"])
        elif _ort.get("structure_id"):
            _wo = t("a player structure in {system}").format(
                system=_nm.get(int(_ort.get("solar_system_id") or 0)) or "?")
        else:
            _wo = t("in space in {system}").format(
                system=_nm.get(int(_ort.get("solar_system_id") or 0)) or "?")
        _lbl.setStyleSheet(f"color:{theme.AMBER}; font-weight:700; padding:0 8px;")
        _lbl.setText("\u26a0 " + t("Not at the hub"))
        _lbl.setToolTip(t(
            "{name} is at {where}, not at {hub}. Orders you place in the game "
            "go where the character is docked – the prices here are for "
            "{hub}.").format(name=name, where=_wo, hub=hub_lbl))
        self._ort_zeigen(True)

    def _ort_zeigen(self, an):
        """Standort-Hinweis ein/aus - ueber die Toolbar-Aktion (s. oben)."""
        _act = getattr(self, "_g_ort_act", None)
        if _act is not None:
            _act.setVisible(bool(an))
        elif getattr(self, "g_ort_warn", None) is not None:
            self.g_ort_warn.setVisible(bool(an))

    def _ort_sichtbar(self):
        """Steht der Standort-Hinweis gerade da? (fuer Pruefungen)"""
        _act = getattr(self, "_g_ort_act", None)
        return bool(_act.isVisible()) if _act is not None else False

    def _pick_global_char(self, *_):
        """Global dropdown changed → apply to every per-tab dropdown, which makes
        each tab refresh for that character. One place to switch the whole tool."""
        if getattr(self, "_syncing_char", False):
            return
        data = self.g_char.currentData()
        self._syncing_char = True
        try:
            for combo in (self.pf_char, self.tx_char, self.pr_char, self.sh_char,
                          self.ord_char):
                idx = combo.findData(data)
                if idx >= 0 and combo.currentIndex() != idx:
                    combo.setCurrentIndex(idx)   # fires the tab's own refresh handler
        finally:
            self._syncing_char = False

    def _sync_global_from_tab(self, *_):
        """A per-tab dropdown changed → reflect it in the global dropdown (without
        re-propagating to all tabs), so the global selector always shows the truth."""
        if getattr(self, "_syncing_char", False):
            return
        sender = self.sender()
        if sender is None:
            return
        data = sender.currentData()
        self._syncing_char = True
        try:
            idx = self.g_char.findData(data)
            if idx >= 0 and self.g_char.currentIndex() != idx:
                self.g_char.setCurrentIndex(idx)
        finally:
            self._syncing_char = False

    # AUSWAHL JE CHARAKTER-FELD MERKEN (Sitzung 17, Nutzer: "ausgewaehlte
    # Charaktere bleiben auf Position in allen Dropdowns"). Feste Namen, damit
    # die Zuordnung ein Programmneustart ueberlebt.
    _CHAR_COMBOS = ("pf_char", "tx_char", "pr_char", "sh_char", "ord_char",
                    "g_char", "bp_myb_char")

    def _char_wahl_merken(self, name):
        try:
            _c = getattr(self, name, None)
            if _c is None:
                return
            _alle = dict(self.settings.get("ui_char_wahl") or {})
            _alle[name] = _c.currentData()
            self.settings["ui_char_wahl"] = _alle
            config.save_settings_async(self.settings)
        except Exception:
            pass

    # CORP IM DROPDOWN AUSGEBAUT (emm301, Nutzer 30.09.2026: "Corp
    # Blueprints lassen sich nicht laden, wenn man im Dropdown die Corp
    # auswaehlt ... waehlt man einen Charakter mit Director-Rolle, sieht man
    # die Blueprints der Corp - entfernen wir die nicht funktionierende
    # Moeglichkeit"). Ersetzt emm257/emm262 (_bp_corp_eintraege,
    # _bp_corp_vorab). Corp-Zeilen stehen unter "All characters" und beim
    # Director, ueber den sie geladen wurden (bp_besitzer_passt, via).

    def _reload_character_combos(self):
        chars = store.list_characters()
        _gemerkt = self.settings.get("ui_char_wahl") or {}
        for _cname in self._CHAR_COMBOS:
            combo = getattr(self, _cname, None)
            if combo is None:
                continue
            combo.blockSignals(True)
            _vorher = combo.currentData() if combo.count() else _gemerkt.get(_cname)
            combo.clear()
            combo.addItem(t("All characters"), "all")
            for c in chars:
                icon = self._character_icon(c["character_id"], size=24)
                if icon:
                    combo.addItem(icon, c["character_name"], c["character_id"])
                else:
                    combo.addItem(c["character_name"], c["character_id"])
            if _vorher is not None:
                _i = combo.findData(_vorher)
                if _i >= 0:
                    combo.setCurrentIndex(_i)
            combo.blockSignals(False)
            # Erst NACH dem Fuellen verbinden - sonst schreibt jedes clear()
            # eine leere Auswahl in die Einstellungen.
            if not getattr(combo, "_wahl_gemerkt", False):
                combo.currentIndexChanged.connect(
                    lambda _i, _n=_cname: self._char_wahl_merken(_n))
                combo._wahl_gemerkt = True
        self._reload_pull_chars()
        if hasattr(self, "_reload_bau_char"):
            self._reload_bau_char()          # Bau-/Reaktions-Charakter-Dropdowns
        if hasattr(self, "_reload_char_roles"):
            self._reload_char_roles()        # Rollen-Roster (neue Chars übernehmen)

