    def _pick_tip(self):
        """Return the next tip from a shuffled bag so every tip is shown once
        before any repeats – feels varied instead of the same few each time."""
        import random
        if not self._TRADING_TIPS:
            return ""
        bag = getattr(self, "_tip_bag", None)
        if not bag:
            bag = list(range(len(self._TRADING_TIPS)))
            random.shuffle(bag)
            # avoid showing the same tip twice across a bag boundary
            if len(bag) > 1 and bag[0] == getattr(self, "_tip_idx", -1):
                bag.append(bag.pop(0))
        self._tip_idx = bag.pop(0)
        self._tip_bag = bag
        return t(self._TRADING_TIPS[self._tip_idx])   # beim Anzeigen uebersetzen

    def _next_tip(self):
        if not self._TRADING_TIPS:
            return
        self._overlay_tip.setText(self._pick_tip())

    def _set_loading(self, text):
        """Set the headline of the loading overlay (what is happening)."""
        if hasattr(self, "_overlay_text"):
            self._overlay_text.setText(text)
        if hasattr(self, "_overlay_progress"):
            self._overlay_progress.setText("")

    def _set_loading_progress(self, done, total):
        if not hasattr(self, "_overlay_progress"):
            return
        if total:
            pct = int(done * 100 / total) if total else 0
            bar_len = 24
            fill = int(bar_len * done / total) if total else 0
            bar = "█" * fill + "░" * (bar_len - fill)
            self._overlay_progress.setText(
                f"{bar}  {done:,}".replace(",", "'") +
                f" / {total:,}".replace(",", "'") + f"  ({pct} %)")
        elif done < 0:
            # Phase ohne Zahl (download_sde meldet -1 fuer "Entpacken +
            # Einlesen"): Text statt "-1 ..." (Nutzer 18.09.2026, zweiter
            # Fundort nach der Statuszeile - hier der grosse Ladeschirm).
            self._overlay_progress.setText(t("Unpacking and importing …"))
        else:
            self._overlay_progress.setText(f"{done:,}".replace(",", "'") + " …")

    # ---- worker plumbing ---------------------------------------------------
    def _spin_tick(self):
        self._spin_i = (self._spin_i + 1) % len(self._spin_frames)
        self._spinner.setText(self._spin_frames[self._spin_i] + " " + t("Loading \u2026"))
        if hasattr(self, "_overlay_spin"):
            self._overlay_spin.setText(self._spin_frames[self._spin_i])

    def _position_overlay(self):
        if hasattr(self, "_overlay"):
            cw = self.centralWidget()
            if cw:
                self._overlay.setGeometry(cw.geometry())

    def resizeEvent(self, event):
        super().resizeEvent(event)
        self._position_overlay()

    def _show_overlay_now(self):
        if self._overlay_want > 0 and hasattr(self, "_overlay"):
            self._position_overlay()
            self._overlay_tip.setText(self._pick_tip())
            self._overlay.show()
            self._overlay.raise_()
            if not self._overlay_tip_timer.isActive():
                self._overlay_tip_timer.start()

    def _hide_overlay(self):
        self._overlay_want = 0
        if hasattr(self, "_overlay_delay"):
            self._overlay_delay.stop()
        if hasattr(self, "_overlay_tip_timer"):
            self._overlay_tip_timer.stop()
        if hasattr(self, "_overlay"):
            self._overlay.hide()

    def _spinner_start(self):
        if not hasattr(self, "_spin_timer"):
            return
        if not self._spin_timer.isActive():
            self._spin_timer.start()
            self._spin_tick()

    def _spinner_stop(self):
        if not hasattr(self, "_spin_timer"):
            return
        if not self._workers:
            self._spin_timer.stop()
            self._spinner.setText("")

    def _set_header_tips(self, table, tips: dict):
        """Spaltentipps setzen - UEBERSETZT HIER (Sitzung 16). Die Dicts an
        den Aufrufstellen tragen englische Schluessel; t() auf einen schon
        uebersetzten Text ist unschaedlich (kein Eintrag -> unveraendert)."""
        for col, text in tips.items():
            it = table.horizontalHeaderItem(col)
            if it:
                it.setToolTip(t(text))

    def _install_tip(self, widget, label):
        """Attach an explanatory tooltip to the TITLE label only (not the input
        field), shown above the title and kept visible while hovering it."""
        tip = widget.toolTip()
        if not tip:
            return
        # move the tooltip off the input field onto the title label
        widget.setToolTip("")
        label.setToolTip(tip)
        if label not in self._tip_anchor:
            label.installEventFilter(self)
        self._tip_anchor[label] = tip

    def _show_pending_tip(self):
        obj = self._tip_pending
        if not obj or obj not in self._tip_anchor:
            return
        from PySide6.QtWidgets import QToolTip
        # show below the cursor so the box never covers the title (no hover steal)
        pos = QCursor.pos() + QPoint(0, 22)
        QToolTip.showText(pos, self._tip_anchor[obj], obj, obj.rect(), 60000)

    def eventFilter(self, obj, event):
        # LEER-HINWEISE MITTIG HALTEN (Sitzung 17). MUSS in DIESEN Filter -
        # ein zweiter eventFilter in derselben Klasse haette den hier
        # stillgelegt (beim Bauen bemerkt).
        try:
            if event.type() in (QEvent.Resize, QEvent.Show):
                for _tbl, _f in (getattr(self, "_leerhinweise", None) or []):
                    try:
                        if _tbl.viewport() is obj:
                            _f()
                    except RuntimeError:
                        continue
        except Exception:
            pass
        if obj in self._tip_anchor:
            et = event.type()
            if et == QEvent.Enter:
                # show after a short delay, near the cursor (below it so it does
                # not overlap the title and steal the hover → no flicker)
                self._tip_pending = obj
                self._tip_timer.start(450)
                return False
            if et == QEvent.ToolTip:
                return True   # suppress Qt's own (instant) tooltip
            if et == QEvent.Leave:
                self._tip_timer.stop()
                self._tip_pending = None
                from PySide6.QtWidgets import QToolTip
                QToolTip.hideText()
                return False
        return super().eventFilter(obj, event)

    # ---- two-level column prioritisation (right-click a header) -------------
    # ---- Top-15 pin + sort only the starred items -------------------------
    def _install_top_sort(self, table, get_top_ids):
        """When a Top-15 pin is active, clicking a column header sorts ONLY the
        starred items (they stay on top); the rest are left untouched below.
        When no pin is active, native click-sorting works as usual."""
        table._get_top_ids = get_top_ids
        table._top_sort_state = [None, True]        # [last_col, descending]
        table.horizontalHeader().sectionClicked.connect(
            lambda col, t=table: self._top_sort_clicked(t, col))

    def _top_sort_clicked(self, table, col):
        get = getattr(table, "_get_top_ids", None)
        top_ids = get() if get else None
        if not top_ids:
            return                                   # pin off → native sort handles it
        st = table._top_sort_state
        desc = True if st[0] != col else (not st[1])
        st[0], st[1] = col, desc
        self._reorder_top_only(table, col, desc, top_ids)
        table.horizontalHeader().setSortIndicator(
            col, Qt.DescendingOrder if desc else Qt.AscendingOrder)

    def _reorder_top_only(self, table, col, desc, top_ids):
        n = table.rowCount()
        cols = table.columnCount()
        if n == 0:
            return
        starred, others = [], []
        for r in range(n):
            idc = table.item(r, 0)
            tid = idc.data(Qt.UserRole) if idc else None
            (starred if tid in top_ids else others).append(r)

        def val(r):
            it = table.item(r, col)
            if it is None:
                return float("-inf")
            v = getattr(it, "_value", None)
            return v if v is not None else it.text().lower()

        try:
            starred.sort(key=val, reverse=desc)
        except TypeError:
            starred.sort(key=lambda r: str(val(r)), reverse=desc)
        order = starred + others
        if order == list(range(n)):
            return
        table.setSortingEnabled(False)
        taken = [[table.takeItem(r, c) for c in range(cols)] for r in range(n)]
        for new_r, old_r in enumerate(order):
            for c in range(cols):
                if taken[old_r][c] is not None:
                    table.setItem(new_r, c, taken[old_r][c])




    def _make_columns_friendly(self, table):
        """Let the user drag column headers to reorder and resize them. No
        stretch column, so dragging a divider resizes exactly that column and
        nothing jumps (a horizontal scrollbar appears if needed). Columns
        start sized to fit their header labels, so tables look right even
        before any data has loaded (Qt's own default widths are too narrow
        for our bold/uppercase header font and clip the label) - not just
        after the first _autosize_once() once rows exist."""
        from PySide6.QtWidgets import QAbstractItemView
        h = table.horizontalHeader()
        h.setSectionsMovable(True)
        h.setStretchLastSection(False)
        h.setMinimumSectionSize(70)
        h.setDefaultAlignment(Qt.AlignCenter)
        for i in range(table.columnCount()):
            h.setSectionResizeMode(i, QHeaderView.Interactive)
        table.setHorizontalScrollMode(QAbstractItemView.ScrollPerPixel)
        fm = table.fontMetrics()
        for i in range(table.columnCount()):
            item = table.horizontalHeaderItem(i)
            if item:
                # Großzügiger Puffer (+44): die Header sind fett + GROSSGESCHRIEBEN
                # und rendern in der echten App breiter als fontMetrics im
                # Offscreen-Test meldet -- mit zu wenig Puffer werden zentrierte
                # Labels wie „BAUKOSTEN/STK“ links/rechts abgeschnitten.
                head_w = fm.horizontalAdvance(item.text()) + 44
                table.setColumnWidth(i, max(table.columnWidth(i), head_w, 78))

    # ---- SPALTENBREITEN MERKEN (Sitzung 17, Nutzer: "wenn man die breiter
    # zieht, sollen sie beim naechsten Start genau so wieder da sein - fuer
    # ALLE Spalten und Tabellen im Tool") -------------------------------
    def _tabellen_register(self):
        """(Name, Kopfleiste) fuer jede Tabelle/jeden Baum des Hauptfensters.

        Der Name kommt aus dem ATTRIBUTNAMEN (self.bp_table -> "bp_table") -
        der ist im Quelltext festgeschrieben und ueberlebt damit jeden
        Neustart, anders als eine laufende Nummer.
        """
        from PySide6.QtWidgets import QTableWidget as _QTW, QTreeWidget as _QTrW
        out = []
        for _n, _w in list(vars(self).items()):
            if isinstance(_w, (_QTW, _QTrW)):
                try:
                    out.append((_n, _w.header() if isinstance(_w, _QTrW)
                                else _w.horizontalHeader()))
                except RuntimeError:
                    continue          # Widget schon abgeraeumt
        return out

    # ---- SORTIERUNG UND FILTER MERKEN (Sitzung 17, Nutzer: "das werden wir
    # sofort machen") -----------------------------------------------------
    #
    # NUR DIESE Filter, mit voller Absicht als feste Liste: eine Reihe
    # "alle QCheckBox/QComboBox" haette auch Schalter erfasst, die beim
    # Wiederherstellen etwas AUSLOESEN (z.B. "Subtract assets" laedt den
    # Bestand nach). Was hier steht, filtert nur eine Ansicht.
    _FILTER_WIDGETS = (
        # My blueprints
        "bp_cb_end", "bp_cb_comp", "bp_cb_react", "bp_cb_profit",
        "bp_cb_invent", "bp_cb_bpo", "bp_cb_bpc", "bp_cb_missing",
        # Transaktionen
        "tx_type", "tx_period",
    )

    def _filter_merken(self):
        """Zustand der Ansichts-Filter ablegen."""
        from PySide6.QtWidgets import QCheckBox as _QCB, QComboBox as _QCo
        _alle = dict(self.settings.get("ui_filter") or {})
        for _n in self._FILTER_WIDGETS:
            _w = getattr(self, _n, None)
            try:
                if isinstance(_w, _QCB):
                    _alle[_n] = bool(_w.isChecked())
                elif isinstance(_w, _QCo):
                    _d = _w.currentData()
                    _alle[_n] = _d if _d is not None else _w.currentText()
            except RuntimeError:
                continue
        self.settings["ui_filter"] = _alle

    def _filter_wiederherstellen(self):
        """Gemerkte Filter setzen - OHNE Signale, damit beim Start nichts
        losrennt; die Ansichten fuellen sich ohnehin gleich neu."""
        from PySide6.QtWidgets import QCheckBox as _QCB, QComboBox as _QCo
        _alle = self.settings.get("ui_filter") or {}
        for _n, _v in _alle.items():
            _w = getattr(self, _n, None)
            if _w is None:
                continue
            try:
                _w.blockSignals(True)
                if isinstance(_w, _QCB):
                    _w.setChecked(bool(_v))
                elif isinstance(_w, _QCo):
                    _i = _w.findData(_v)
                    if _i < 0:
                        _i = _w.findText(str(_v))
                    if _i >= 0:
                        _w.setCurrentIndex(_i)
            except RuntimeError:
                continue
            finally:
                try:
                    _w.blockSignals(False)
                except RuntimeError:
                    pass

    def _sortierung_merken(self):
        """Nach welcher Spalte und in welche Richtung jede Tabelle sortiert
        ist. Die Kopfleiste allein reicht nicht: nach dem Neufuellen steht
        zwar der Pfeil richtig, sortiert wird aber erst beim naechsten
        setSortingEnabled(True) - deshalb merken wir es getrennt und setzen
        es beim Start ausdruecklich."""
        _alle = dict(self.settings.get("ui_sort") or {})
        for _n, _hv in self._tabellen_register():
            try:
                _sp = _hv.sortIndicatorSection()
                if _sp is not None and _sp >= 0:
                    _alle[_n] = [int(_sp), int(_hv.sortIndicatorOrder().value)]
            except Exception:
                continue
        self.settings["ui_sort"] = _alle

    def _sortierung_wiederherstellen(self):
        from PySide6.QtCore import Qt as _Qt
        from PySide6.QtWidgets import QTableWidget as _QTW, QTreeWidget as _QTrW
        _alle = self.settings.get("ui_sort") or {}
        if not _alle:
            return
        for _n, _w in list(vars(self).items()):
            _s = _alle.get(_n)
            if not _s or not isinstance(_w, (_QTW, _QTrW)):
                continue
            try:
                _ord = (_Qt.DescendingOrder if int(_s[1]) == 1
                        else _Qt.AscendingOrder)
                if isinstance(_w, _QTrW):
                    _w.sortByColumn(int(_s[0]), _ord)
                else:
                    _w.sortItems(int(_s[0]), _ord)
            except Exception:
                continue

    def _spalten_merken(self):
        """Beim Schliessen: Kopfleisten-Zustand jeder Tabelle ablegen."""
        from PySide6.QtCore import QByteArray  # noqa: F401  (Symmetrie zum Laden)
        _alle = dict(self.settings.get("ui_spalten") or {})
        _anz = dict(self.settings.get("ui_spalten_n") or {})
        for _n, _hv in self._tabellen_register():
            try:
                _alle[_n] = bytes(_hv.saveState().toBase64()).decode()
                _anz[_n] = int(_hv.count())
            except Exception:
                continue
        self.settings["ui_spalten"] = _alle
        # SPALTENZAHL MITMERKEN (emm354): kommt eine Spalte dazu, passt der
        # alte Zustand nicht mehr - er wird dann nicht wiederhergestellt.
        self.settings["ui_spalten_n"] = _anz

    def _spalten_wiederherstellen(self):
        """Beim Start: gemerkte Breiten setzen. Wiederhergestellte Tabellen
        werden als 'schon bemessen' vermerkt, damit _autosize_once sie nicht
        gleich wieder ueberschreibt."""
        from PySide6.QtCore import QByteArray
        _alle = self.settings.get("ui_spalten") or {}
        if not _alle:
            return
        _anz = self.settings.get("ui_spalten_n") or {}
        for _n, _hv in self._tabellen_register():
            _s = _alle.get(_n)
            if not _s:
                continue
            try:
                if _n in _anz and int(_anz[_n]) != int(_hv.count()):
                    continue          # Spaltenzahl geaendert: alter Zustand passt nicht
            except (TypeError, ValueError, RuntimeError):
                continue
            try:
                _hv.restoreState(QByteArray.fromBase64(_s.encode()))
                self._sized.add(_n)
                if _n == "char_table":
                    self._char_aktionen_breite()
            except Exception:
                continue

    @staticmethod
    def _bp_in_job_tooltip(jobs):
        """Kurztext fuer Blaupausen im Job: je Job Taetigkeit + Ende (lokal).
        activity_id nach ESI: 1 Fertigung, 3 TE-, 4 ME-Forschung, 5 Kopie,
        8 Invention, 11 Reaktion."""
        namen = {1: t("Manufacturing"), 3: t("TE research"), 4: t("ME research"),
                 5: t("Copying"), 8: t("Invention"), 11: t("Reaction")}
        zeilen = [t("Not available \u2013 in an industry job:")]
        for j in jobs or []:
            akt = namen.get(j.get("activity_id"), t("Job"))
            ende = j.get("end_date") or ""
            try:
                import datetime as _dt
                _ts = _dt.datetime.fromisoformat(ende.replace("Z", "+00:00"))
                ende = _ts.astimezone().strftime("%Y-%m-%d %H:%M")
            except (ValueError, AttributeError, OSError):
                pass
            zeilen.append(t("{activity} until {end}").format(activity=akt, end=ende or "?"))
        return "\n".join(zeilen)

    @staticmethod
    def _bp_zeilen_gruppieren(rows):
        """Gleiche Blaupausen zu EINER Zeile zusammenfassen (Sitzung 17,
        Nutzer: "wenn ich sie 50x besitze, stehen die 50x untereinander -
        nur 1x auflisten, dafuer die Anzahl daneben").

        SCHLUESSEL: type_id + BPO/BPC + Charakter. Nicht zusammengefasst wird
        ueber Charaktere hinweg - der Charakter-Filter und der Runplaner
        arbeiten je Charakter, sonst zeigte die Liste Zeilen, die es fuer den
        gewaehlten Charakter gar nicht gibt.

        ME/TE: die SCHLECHTESTEN Werte der Gruppe (Nutzer: "somit gehen wir
        immer vom Mindestverdienst aus und sehen nicht irgendwelche
        Mondpreise"). Runs: bei BPC die SUMME (das ist der Vorrat, den man
        wirklich hat), bei BPO unbegrenzt. Ort: "mehrere", wenn sie sich
        unterscheiden - sonst behauptete die Zeile einen Ort, an dem nur ein
        Teil liegt.
        """
        gruppen, reihenfolge = {}, []

        def _schluessel(b):
            return (b.get("type_id"), bool(b.get("is_bpo")), b.get("_cid"),
                    b.get("_inventable_from"))
        # BLAUPAUSEN IN JOBS (26.09.2026, esi.blaupausen_in_jobs) zaehlen
        # NICHT in Anzahl, Runs oder ME/TE der Zeile - im Spiel sind sie
        # nicht greifbar, und ihr ME/TE aendert sich gerade. Sie stehen als
        # `_in_job` (Stueck) + `_in_job_jobs` (Job-Daten) daneben.
        # Nutzer: "ich habe eigentlich nur 5 ... die anderen sind am
        # Researchen und das Tool denkt ich besitze 8 Stueck."
        belegt = [b for b in (rows or []) if b.get("in_job")]
        for b in rows or []:
            if b.get("in_job"):
                continue
            key = _schluessel(b)
            g = gruppen.get(key)
            _menge = int(b.get("quantity", 1) or 1)
            _runs = b.get("runs", -1)
            if g is None:
                g = dict(b)
                g["quantity"] = _menge
                g["_stacks"] = 1
                g["_orte"] = {(b.get("location_id"), b.get("division"))}
                gruppen[key] = g
                reihenfolge.append(key)
                continue
            g["quantity"] = int(g.get("quantity", 1) or 1) + _menge
            g["_stacks"] += 1
            # Ort = Ort + Corp-Hangar: zwei Hangars desselben Bueros sind
            # zwei Orte (1.1.0), sonst nennte die Zeile nur den ersten.
            g["_orte"].add((b.get("location_id"), b.get("division")))
            for _f in ("material_efficiency", "time_efficiency"):
                g[_f] = min(int(g.get(_f, 0) or 0), int(b.get(_f, 0) or 0))
            if not g.get("is_bpo") and _runs != -1 and g.get("runs", -1) != -1:
                g["runs"] = int(g.get("runs", 0) or 0) + int(_runs)
        for b in belegt:
            key = _schluessel(b)
            g = gruppen.get(key)
            if g is None:
                # Alle Exemplare im Job: Zeile mit 0 verfuegbar, 0 Runs.
                g = dict(b)
                g.pop("in_job", None)
                g["quantity"] = 0
                g["_stacks"] = 0
                g["_orte"] = {(b.get("location_id"), b.get("division"))}
                if not g.get("is_bpo") and g.get("runs", -1) != -1:
                    g["runs"] = 0
                gruppen[key] = g
                reihenfolge.append(key)
            g["_in_job"] = int(g.get("_in_job", 0) or 0) + int(b.get("quantity", 1) or 1)
            g.setdefault("_in_job_jobs", []).append(dict(b.get("in_job") or {}))
        out = []
        for key in reihenfolge:
            g = gruppen[key]
            if len(g.pop("_orte", ())) > 1:
                g["location_id"] = None      # gemischt -> kein einzelner Ort
                g["_ort_gemischt"] = True
            out.append(g)
        return out

    # ---- HINWEIS IN DER LEEREN TABELLE (Sitzung 17, Nutzer: "leere Tabs
    # sollen sagen, warum sie leer sind") ---------------------------------
    #
    # ANLASS: ein Discord-Nutzer sah leere Listen und hielt das Werkzeug fuer
    # kaputt. Der Grund stand in der kleinen Statuszeile, die niemand liest.
    # AUFBAU (mit dem Nutzer abgestimmt): zentriert in der leeren Flaeche,
    # Kopfzeile 15px in Textfarbe, darunter EIN Knopf, der genau das tut, was
    # fehlt. Kein Symbol, keine Erklaerung, keine Links.
    def _leerhinweis(self, table, titel, knopf_text=None, aktion=None,
                     satz=None, symbol=None, zustand=None):
        """Hinweis in einer leeren Tabelle - mit einem Knopf, der GENAU das
        tut, was fehlt.

        `zustand`: optionale Funktion -> (titel, knopf_text, symbolname,
        aktion). Wird bei jedem Einblenden gefragt. NUTZER-BEFUND 17.09.2026:
        "klickt man auf Market scan unter 'No market data', kommt zwar ein
        Ladebildschirm, aber keine Auflistung". Der Scan LIEF - was fehlte,
        war "Load deals". Ein Hinweis, der immer "Market scan" sagt, ist nach
        dem ersten Scan also falsch. Jetzt sagt er, was WIRKLICH fehlt.
        """
        from PySide6.QtWidgets import QVBoxLayout as _V, QWidget as _W
        _vp = table.viewport()
        box = _W(_vp)
        box.setAttribute(Qt.WA_TransparentForMouseEvents, False)
        box.setStyleSheet("background:transparent;")
        v = _V(box); v.setContentsMargins(0, 0, 0, 0); v.setSpacing(8)
        _t = QLabel(titel)
        _t.setAlignment(Qt.AlignCenter)
        _t.setStyleSheet(f"color:{theme.TEXT}; font-size:15px; background:transparent;")
        v.addWidget(_t)
        if knopf_text:
            _b = QPushButton(knopf_text)
            _b.setObjectName("Primary")
            _b.setCursor(Qt.PointingHandCursor)
            # SYMBOL VOM VORBILD (Sitzung 17): der Knopf oben traegt eines,
            # der hier soll gleich aussehen - und b55 verlangt, dass
            # Bedienelemente ein Symbol haben.
            if symbol is not None and not symbol.isNull():
                _b.setIcon(symbol)
            box._aktion = aktion
            box._knopf = _b
            # Ueber box._aktion, nicht direkt: `zustand` darf die Aktion
            # beim Einblenden austauschen (Scan -> Deals laden).
            _b.clicked.connect(
                lambda _=False, _bx=box: (_bx._aktion() if _bx._aktion else None))
            _bz = QHBoxLayout(); _bz.addStretch(); _bz.addWidget(_b); _bz.addStretch()
            v.addLayout(_bz)
        elif satz:
            _s = QLabel(satz)
            _s.setAlignment(Qt.AlignCenter)
            _s.setStyleSheet(
                f"color:{theme.MUTED}; font-size:13px; background:transparent;")
            v.addWidget(_s)
        box.adjustSize()

        def _stellen():
            try:
                _leer = table.rowCount() == 0
                box.setVisible(_leer)
                if _leer and zustand is not None and getattr(box, "_knopf", None):
                    try:
                        _t2, _k2, _sym2, _a2 = zustand()
                        _t.setText(_t2)
                        # Kein Knopftext = kein Knopf (z. B. "wird geladen").
                        box._knopf.setVisible(bool(_k2))
                        box._knopf.setText(_k2 or "")
                        if _sym2:
                            box._knopf.setIcon(icons.icon(_sym2))
                        box._aktion = _a2
                    except Exception as _ze:
                        self._log_exception("Leerhinweis-Zustand", str(_ze))
                if _leer:
                    box.adjustSize()
                    box.move(max(0, (_vp.width() - box.width()) // 2),
                             max(0, (_vp.height() - box.height()) // 2))
                    box.raise_()
            except RuntimeError:
                pass
        table._leerhinweis_stellen = _stellen
        _vp.installEventFilter(self)
        self._leerhinweise = getattr(self, "_leerhinweise", [])
        self._leerhinweise.append((table, _stellen))
        _m = table.model()
        for _sig in (_m.rowsInserted, _m.rowsRemoved, _m.modelReset,
                     _m.layoutChanged):
            _sig.connect(lambda *_a, _f=_stellen: _f())
        _stellen()
        return box

    def _leerhinweise_anlegen(self):
        """Fuer jede Liste den passenden Hinweis - EINE Stelle, damit kein
        Tab vergessen wird. Der Knopf tut genau das, was fehlt."""
        _scan = getattr(self, "g_scan_btn", None)
        # MEINE BLAUPAUSEN: der Knopf laedt die Blaupausen der Charaktere
        # (bp_refresh_btn) - NICHT die SDE (g_sde_btn). Nutzer-Befund
        # 17.09.2026: "bei Blueprint genauso, keine Wirkung" - der alte
        # Hinweis zeigte auf den SDE-Download, der bei geladener SDE nur
        # zurueckfragt und sonst nichts tut.
        _bp = getattr(self, "bp_refresh_btn", None) or getattr(self, "g_sde_btn", None)

        def _deals_zustand(load_btn):
            """Vor dem ersten Scan: "Market scan". Danach fehlt nur noch
            "Load deals" - und genau den bekommt der Knopf."""
            def _z():
                if store.snapshot_age_seconds() is None:
                    return (t("No market data yet"), t("Market scan"),
                            "satellite",
                            (lambda: _scan.click()) if _scan is not None else None)
                return (t("Market scanned \u2013 now load the deals"),
                        t("Load deals"), "search",
                        (lambda: load_btn.click()) if load_btn is not None else None)
            return _z

        def _portfolio_zustand():
            """Waehrend der Portfolio-Abruf im Hintergrund laeuft: "wird
            geladen" und KEIN Knopf - vorher stand dort "Nothing here yet /
            Market scan", obwohl die Daten gerade kommen."""
            if getattr(self, "_portfolio_laedt", False):
                return (t("Loading your portfolio \u2026") + "\n"
                        + t("Wallet, assets, orders and prices are being "
                            "fetched from ESI."), None, None, None)
            return (t("Nothing here yet"), t("Market scan"), "satellite",
                    (lambda: _scan.click()) if _scan is not None else None)

        # SYMBOL AUSDRUECKLICH (Sitzung 17): das Symbol des Vorbild-Knopfes
        # zu kopieren lieferte ein leeres QIcon - b55 wurde zu Recht rot.
        _fuer = (
            ("deals_table", t("No market data yet"), t("Market scan"),
             _scan, "satellite", _deals_zustand(getattr(self, "deals_btn", None))),
            ("hold_table", t("No market data yet"), t("Market scan"),
             _scan, "satellite", _deals_zustand(getattr(self, "hold_btn", None))),
            ("rg_table", t("No market data yet"), t("Market scan"),
             _scan, "satellite", _deals_zustand(getattr(self, "rg_go", None))),
            ("bp_table", t("No blueprints loaded yet"), t("Load blueprints"),
             _bp, "blueprint", None),
            ("pf_table", t("Nothing here yet"), t("Market scan"),
             _scan, "satellite", _portfolio_zustand),
            ("pr_table", t("No transactions yet"), None, None, None, None),
            ("tx_table", t("No transactions yet"), None, None, None, None),
        )
        for _n, _titel, _btxt, _btn, _sym, _zu in _fuer:
            _tbl = getattr(self, _n, None)
            if _tbl is None:
                continue
            try:
                self._leerhinweis(
                    _tbl, _titel, _btxt,
                    (lambda _b=_btn: _b.click()) if _btn is not None else None,
                    symbol=(icons.icon(_sym) if _sym else None),
                    satz=(None if _btn is not None
                          else t("Link a character under \u201eCharacters\u201c.")),
                    zustand=_zu)
            except Exception as _lh:            # pragma: no cover
                self._log_exception("Leerhinweis " + _n, str(_lh))

    def _leerhinweise_aktualisieren(self):
        """Alle Leer-Hinweise neu stellen - nach einem Scan wechselt ihr
        Knopf von "Market scan" auf "Load deals", ohne dass sich die Tabelle
        geaendert haette (die Signale der Tabelle feuern dann nicht)."""
        for _tbl, _f in getattr(self, "_leerhinweise", []) or []:
            try:
                _f()
            except Exception:
                pass

    def _autosize_once(self, table, key):
        """Size columns to their contents on first fill only, so later manual
        widths the user dragged are preserved across refreshes. A little padding
        is added so headers and values get room to breathe (not cramped)."""
        if key in self._sized:
            return
        if table.rowCount() == 0:
            return   # wait for real data before locking column widths
        table.resizeColumnsToContents()
        h = table.horizontalHeader()
        fm = table.fontMetrics()
        for i in range(table.columnCount()):
            # make sure the full header label fits, plus padding for both
            item = table.horizontalHeaderItem(i)
            head_w = fm.horizontalAdvance(item.text()) + 34 if item else 0
            want = max(table.columnWidth(i) + 22, head_w, 70)
            table.setColumnWidth(i, want)
        self._sized.add(key)

    def _run(self, worker, done_cb, fail_cb=None, err_prefix=None, label=None,
             overlay=True):
        self._workers.append(worker)
        self._spinner_start()
        # the big centered overlay is only for slow, button-triggered work; quick
        # background actions (ladder load, ingame-open) pass overlay=False, and
        # even slow ones only appear after a short delay (no flicker on fast ops)
        if overlay:
            if label:
                self._set_loading(label)
            self._overlay_want += 1
            if not self._overlay.isVisible() and not self._overlay_delay.isActive():
                self._overlay_delay.start()
        # route this worker's progress to the big overlay (X / Y + bar)
        try:
            worker.progress.connect(self._set_loading_progress)
        except Exception:
            pass
        try:
            worker.status.connect(self._set_loading)     # Phasen-Text („was passiert“)
        except Exception:
            pass

        def _guard(cb):
            # ignore a result that arrives after the user hit Abbrechen
            def wrapped(*a, **k):
                if getattr(worker, "_discarded", False) or worker.is_cancelled():
                    return
                if cb:
                    cb(*a, **k)
            return wrapped

        if done_cb:
            worker.done.connect(_guard(done_cb))
        if fail_cb:
            worker.failed.connect(_guard(fail_cb))
        else:
            worker.failed.connect(_guard(
                lambda m: self.statusBar().showMessage(
                    f"{err_prefix or t('Error')}: {m}")))

        def cleanup():
            try:
                worker.wait(5000)
            except Exception:
                pass
            if worker in self._workers:
                self._workers.remove(worker)
            worker.deleteLater()
            if overlay:
                self._overlay_want = max(0, self._overlay_want - 1)
                if self._overlay_want == 0:
                    self._hide_overlay()
            self._spinner_stop()
        worker.finished.connect(cleanup)
        worker.start()

    def _cancel_all(self):
        """Stop every running background job immediately and give control back.
        Cooperative jobs (deals, gold, scan) bail out early; any result that
        still arrives is discarded."""
        workers = list(getattr(self, "_workers", []))
        for w in workers:
            w._discarded = True
            try:
                w.cancel()
            except Exception:
                pass
        # give the UI back right away, don't wait for the threads to unwind
        self._overlay_want = 0
        self._hide_overlay()
        self._spinner_stop()
        # re-enable via the same helpers the workers use, so the GLOBAL scan and
        # SDE buttons (g_scan_btn / g_sde_btn) are covered too — a hardcoded list
        # missed them and left „Markt-Scan“ stuck disabled after a cancel.
        self._set_scan_buttons(True)
        self._set_sde_buttons(True)
        for name in ("deals_btn", "gold_btn", "refresh_btn",
                     "b_compute_btn", "hold_btn", "hold_top_btn", "tx_refresh"):
            wdg = getattr(self, name, None)
            if wdg is not None:
                try:
                    wdg.setEnabled(True)
                except Exception:
                    pass
        if hasattr(self, "deal_status"):
            self.deal_status.setText(t("Cancelled. Nothing was calculated."))
        self.statusBar().showMessage(t("Operation cancelled."))
